def tidy_app_path(raw):
    """The Dock stores 'file:///Users/.../Kite%20by%20Zerodha.app/'.
    Turn that into a plain path macOS can open."""
    p = (raw or "").strip()
    if p.startswith("file://"):
        p = urllib.parse.unquote(p[len("file://"):])
    p = p.rstrip("/")
    return p


def open_kite_browser():
    """Kite saved from Chrome is a bookmark, not an app. Opening the URL in
    Chrome itself reuses the window you are already logged into."""
    import subprocess
    for browser in ("Google Chrome", "Brave Browser", "Microsoft Edge",
                    "Safari"):
        try:
            r = subprocess.run(["open", "-a", browser, KITE_URL], timeout=8,
                               capture_output=True)
            if r.returncode == 0:
                return {"ok": True, "how": "browser", "app": browser}
        except Exception:
            continue
    try:
        subprocess.run(["open", KITE_URL], timeout=8)
        return {"ok": True, "how": "browser", "app": "default browser"}
    except Exception as e:
        return {"ok": False, "how": "failed", "error": str(e)}


def open_kite_old(preferred=None):
    import subprocess
    tried = []
    targets = []
    if preferred:
        targets.append(preferred)
    targets += find_kite_apps()
    targets += ["Kite", "Zerodha Kite", "Kite by Zerodha"]
    for t in targets:
        try:
            # -a brings a running copy forward; it does not relaunch or log out
            r = subprocess.run(["open", "-a", t], timeout=6, capture_output=True)
            tried.append("%s -> %d" % (t, r.returncode))
            if r.returncode == 0:
                return {"ok": True, "how": "app", "used": t, "tried": tried}
        except Exception as e:
            tried.append("%s -> %s" % (t, e))
    try:
        subprocess.run(["open", "https://kite.zerodha.com/chart/web/"], timeout=6)
        return {"ok": True, "how": "browser", "tried": tried,
                "note": "No Kite app found on this Mac. Diagnostics -> Find "
                        "Kite app lists what is installed."}
    except Exception as e:
        return {"ok": False, "how": "failed", "error": str(e), "tried": tried}


KITE_URL = "https://kite.zerodha.com/dashboard"
KITE_HINTS = ("kite", "zerodha")


def find_kite_apps():
    """Spotlight first - it finds Chrome/Edge web apps and odd locations."""
    hits = []
    try:
        for q in ('kMDItemKind == "Application" && kMDItemDisplayName == "*kite*"cd',
                  'kMDItemKind == "Application" && kMDItemDisplayName == "*zerodha*"cd'):
            r = subprocess.run(["mdfind", q], timeout=6, capture_output=True,
                               text=True)
            for line in (r.stdout or "").splitlines():
                if line.strip().endswith(".app"):
                    hits.append(line.strip())
    except Exception:
        pass
    hits += _find_kite_by_folder()
    seen, out = set(), []
    for h in hits:
        if h not in seen:
            seen.add(h)
            out.append(h)
    return out


def _find_kite_by_folder():
    """Look for anything Kite-ish: a normal app, or a Chrome/Edge web app."""
    import glob
    places = [
        "/Applications/*.app",
        os.path.expanduser("~/Applications/*.app"),
        os.path.expanduser("~/Applications/Chrome Apps.localized/*.app"),
        os.path.expanduser("~/Applications/Chrome Apps/*.app"),
        os.path.expanduser("~/Applications/Edge Apps.localized/*.app"),
    ]
    hits = []
    for pat in places:
        for p in glob.glob(pat):
            base = os.path.basename(p).lower()
            if any(h in base for h in KITE_HINTS):
                hits.append(p)
    return hits


def open_kite_v16(preferred=None):
    """One route to Kite. Look where it actually lives - the Dock first,
    then Applications and Chrome Apps - remember what worked, and use
    `open -a` so the app already running is brought forward instead of a
    second window being spawned."""
    st = load_state()
    tried = []
    saved = (st.get("kiteApp") or st.get("kitePath") or "").strip()
    order = ([preferred] if preferred else []) + ([saved] if saved else [])
    order += [p for p in (dock_kite_paths() + find_kite_apps())
              if p not in order]
    for path in order:
        if not path:
            continue
        tried.append(path)
        try:
            r = subprocess.run(["open", "-a", path], timeout=10,
                               capture_output=True)
            if r.returncode == 0:
                if path != saved:
                    with NOTE_LOCK:
                        st = load_state()
                        st["kiteApp"] = path
                        save_state(st)
                return {"ok": True, "how": "app", "kiteApp": path}
        except Exception:
            continue
    try:
        subprocess.run(["open", KITE_URL], timeout=8)
        return {"ok": True, "how": "browser", "tried": tried[:6],
                "note": "No Kite app found, so the website was opened. "
                        "Diagnostics -> Look for Kite in the Dock will "
                        "show what is installed."}
    except Exception as e:
        return {"ok": False, "how": "failed", "note": str(e),
                "tried": tried[:6]}


def dock_kite_paths():
    """Read the Dock's own list and pull out anything Kite-ish."""
    out = []
    try:
        r = subprocess.run(
            ["defaults", "read", "com.apple.dock", "persistent-apps"],
            capture_output=True, timeout=8)
        text = r.stdout.decode("utf-8", "replace")
        for m in re.finditer(r'_CFURLString\s*=\s*"([^"]+)"', text):
            raw = m.group(1)
            if not any(h in raw.lower() for h in KITE_HINTS):
                continue
            p = urllib.parse.unquote(raw)
            if p.startswith("file://"):
                p = p[7:]
            p = p.rstrip("/")
            if p and p not in out:
                out.append(p)
    except Exception:
        pass
    return out


def open_kite():
    import subprocess
    state = load_state()
    manual = (state.get("kitePath") or "").strip()
    tried = []
    candidates = ([manual] if manual else []) + find_kite_apps()
    for path in candidates:
        try:
            tried.append(path)
            # -a on a path brings a running copy forward; it does not relaunch
            r = subprocess.run(["open", "-a", path], timeout=8,
                               capture_output=True)
            if r.returncode == 0:
                return {"ok": True, "how": "app", "app": os.path.basename(path)}
        except Exception:
            continue
    try:
        subprocess.run(["open", "https://kite.zerodha.com/chart/web/"], timeout=8)
        return {"ok": True, "how": "browser", "tried": tried,
                "note": "No Kite app found on this Mac - opened the website. "
                        "If you have it installed under another name, set "
                        "kitePath in Data/cas_state.json."}
    except Exception as e:
        return {"ok": False, "how": "failed", "error": str(e), "tried": tried}


CAL_OVERRIDE = {"working": []}      # days he has marked as trading anyway


def cal_override_save():
    path = os.path.join(DATA_DIR, "holidays.json")
    try:
        with open(path) as f:
            d = json.load(f)
    except Exception:
        d = {"holidays": sorted(NSE_HOLIDAYS), "special": SPECIAL_SESSIONS}
    d["overrides"] = CAL_OVERRIDE["working"]
    try:
        tmp = path + ".tmp"
        with open(tmp, "w") as f:
            json.dump(d, f, indent=2)
        os.replace(tmp, path)
    except Exception:
        pass


def mark_working(day):
    """He can overrule the calendar for a day it has got wrong."""
    day = (day or datetime.date.today().isoformat()).strip()
    if day not in CAL_OVERRIDE["working"]:
        CAL_OVERRIDE["working"].append(day)
    cal_override_save()
    return {"ok": True, "day": day,
            "working": sorted(CAL_OVERRIDE["working"]),
            "note": "Treated as a normal trading day from now on."}


def unmark_working(day):
    day = (day or datetime.date.today().isoformat()).strip()
    CAL_OVERRIDE["working"] = [d for d in CAL_OVERRIDE["working"] if d != day]
    cal_override_save()
    return {"ok": True, "day": day, "working": sorted(CAL_OVERRIDE["working"])}


def load_calendar():
    """Holiday list from NSE, cached on disk so it survives restarts."""
    global NSE_HOLIDAYS, SPECIAL_SESSIONS
    path = os.path.join(DATA_DIR, "holidays.json")
    stale_parser = False
    try:
        with open(path) as f:
            d = json.load(f)
        NSE_HOLIDAYS = set(d.get("holidays") or [])
        SPECIAL_SESSIONS = d.get("special") or {}
        CAL_OVERRIDE["working"] = list(d.get("overrides") or [])
        # a file written before the segment fix contains settlement and
        # commodity dates, so it is refetched once
        stale_parser = d.get("segment") != "CM"
        if stale_parser:
            NSE_HOLIDAYS.discard("2026-08-26")   # the known bad entry
        CAL["source"] = "cached (%d holidays)" % len(NSE_HOLIDAYS)
    except Exception:
        pass
    if stale_parser:
        NSE_HOLIDAYS = NSE_HOLIDAYS or set()
    fresh_enough = (os.path.exists(path)
                    and time.time() - os.path.getmtime(path) < 7 * 86400)
    if NSE_HOLIDAYS and fresh_enough and not stale_parser:
        return
    data, err = SESSION.fetch(
        "https://www.nseindia.com/api/holiday-master?type=trading", LIVE_PAGE)
    if err or not isinstance(data, dict):
        CAL["source"] = CAL["source"] or ("could not fetch (%s)" % err)
        return
    # ONLY the capital market segment. Reading every segment is what put
    # 26 Aug 2026 in the list - a clearing and settlement holiday for
    # Id-e-Milad, on which equity trading ran perfectly normally. That one
    # wrong entry silenced the pressure gauge and the auction machinery for
    # the whole day.
    found = set()
    for seg, rows in data.items():
        if str(seg).strip().upper() not in ("CM", "EQUITIES", "EQUITY"):
            continue
        if not isinstance(rows, list):
            continue
        for r in rows:
            raw = str((r or {}).get("tradingDate") or "").strip()
            for fmt in ("%d-%b-%Y", "%Y-%m-%d", "%d-%B-%Y"):
                try:
                    found.add(datetime.datetime.strptime(raw, fmt)
                              .date().isoformat())
                    break
                except Exception:
                    pass
    if found:
        NSE_HOLIDAYS = found
        CAL["source"] = "NSE (%d holidays)" % len(found)
        try:
            _write_json(path, {"holidays": sorted(found),
                               "special": SPECIAL_SESSIONS,
                               "segment": "CM",
                               "overrides": CAL_OVERRIDE.get("working", [])})
        except Exception:
            pass
    CAL["at"] = time.time()


def is_trading_day(d=None):
    d = d or datetime.date.today()
    iso = d.isoformat()
    if iso in CAL_OVERRIDE["working"]:   # he has overruled the calendar
        return True
    if iso in SPECIAL_SESSIONS:      # Muhurat: a session on an odd day
        return True
    if d.weekday() >= 5:             # Saturday / Sunday
        return False
    return iso not in NSE_HOLIDAYS


def next_trading_day(d):
    d = d + datetime.timedelta(days=1)
    for _ in range(20):
        if is_trading_day(d):
            return d
        d = d + datetime.timedelta(days=1)
    return d


def prev_trading_day(d=None):
    d = (d or datetime.date.today()) - datetime.timedelta(days=1)
    for _ in range(20):
        if is_trading_day(d):
            return d
        d = d - datetime.timedelta(days=1)
    return d

