# ----------------------------------------------------------------------------
# NSE session
# ----------------------------------------------------------------------------

def prime_reason(e):
    """A plain reason for the black window."""
    if isinstance(e, urllib.error.HTTPError):
        return "NSE answered %s" % e.code
    t = str(getattr(e, "reason", "") or e).lower()
    if "timed out" in t or isinstance(e, TimeoutError):
        return "NSE was slow to answer"
    if "nodename" in t or "name or service" in t or "getaddrinfo" in t:
        return "no internet connection"
    return "network error"


class NSESession:
    def __init__(self):
        self.jar = http.cookiejar.CookieJar()
        self.opener = urllib.request.build_opener(
            urllib.request.HTTPCookieProcessor(self.jar))
        self.primed_at = 0
        self.lock = threading.Lock()

    def prime(self, symbol="RELIANCE"):
        """Visit NSE's pages as a browser would, for its cookies. Only the
        home page must answer; the other two are heavy pages that are often
        slow, and a slow one used to fail the whole start ("could not reach
        NSE yet") although the session was fine."""
        self.last_error = ""
        for i, url in enumerate(("https://www.nseindia.com/", LIVE_PAGE,
                                 "https://www.nseindia.com/get-quotes/"
                                 "equity?symbol=" + Q(symbol))):
            req = urllib.request.Request(url, headers={
                **BASE_HEADERS,
                "Accept": ("text/html,application/xhtml+xml,application/xml;"
                           "q=0.9,image/avif,image/webp,*/*;q=0.8"),
                "Sec-Fetch-Dest": "document", "Sec-Fetch-Mode": "navigate",
                "Sec-Fetch-Site": "none", "Upgrade-Insecure-Requests": "1",
            })
            try:
                self.opener.open(req, timeout=12 if i == 0 else 4).read()
            except Exception as e:
                if i == 0:
                    self.last_error = prime_reason(e)
                    return False
            time.sleep(0.4)
        self.primed_at = time.time()
        return True

    def get_json(self, url, referer, timeout=8):
        h = dict(BASE_HEADERS)
        h["Referer"] = referer
        resp = self.opener.open(urllib.request.Request(url, headers=h),
                                timeout=timeout)
        raw = resp.read()
        enc = (resp.headers.get("Content-Encoding") or "").lower()
        if enc == "gzip":
            raw = gzip.GzipFile(fileobj=io.BytesIO(raw)).read()
        elif enc == "deflate":
            try:
                raw = zlib.decompress(raw)
            except Exception:
                raw = zlib.decompress(raw, -zlib.MAX_WBITS)
        self.last_status = getattr(resp, "status", None)
        return json.loads(raw.decode("utf-8", "replace"))

    def get_raw(self, url, referer="https://www.nseindia.com/"):
        """Bytes, not JSON - used for NSE's dated CSV reports."""
        with self.lock:
            if time.time() - self.primed_at > 420:
                self.prime()
        h = dict(BASE_HEADERS)
        h["Referer"] = referer
        h["Accept"] = "text/csv,application/csv,*/*"
        resp = self.opener.open(urllib.request.Request(url, headers=h),
                                timeout=25)
        raw = resp.read()
        if resp.headers.get("Content-Encoding") == "gzip":
            raw = gzip.GzipFile(fileobj=io.BytesIO(raw)).read()
        self.last_headers = {k: v for k, v in resp.headers.items()}
        self.last_status = resp.status
        return raw

    def fetch(self, url, referer, symbol="RELIANCE", timeout=8):
        with self.lock:
            if time.time() - self.primed_at > 420:
                self.prime(symbol)
        try:
            return self.get_json(url, referer, timeout), None
        except Exception as e:
            code = getattr(e, "code", None)
            if code == 404:                 # endpoint simply does not exist
                return None, "HTTP 404"
            with self.lock:
                if time.time() - self.primed_at > 30:
                    ok = self.prime(symbol)
                else:
                    ok = True
            if not ok:
                return None, "no NSE session (%s)" % e
            try:
                return self.get_json(url, referer, timeout), None
            except Exception as e2:
                return None, str(e2)


SESSION = NSESession()
IDX_SESSION = NSESession()   # indices never queue behind the stock sweep
RPT_SESSION = NSESession()   # dated CSV reports (52-week high/low)


def to_number(v):
    try:
        if isinstance(v, str):
            v = v.replace(",", "").strip()
            if v in ("", "-", "--"):
                return None
        return float(v)
    except Exception:
        return None


# ----------------------------------------------------------------------------
# Bulk
# ----------------------------------------------------------------------------

ICP_KEYS = ["indicativeClose", "indicative_close", "iep", "indicativeprice"]
IEQ_KEYS = ["ieq", "finalQuantity", "indicativeQuantity"]


def pick(d, keys):
    low = {k.lower(): k for k in d}
    for want in keys:
        k = low.get(want.lower())
        if k is not None and d[k] not in (None, ""):
            return d[k]
    return None


def parse_bulk(data):
    out = {}
    rows = data.get("data") if isinstance(data, dict) else None
    # marketWatchApi nests it one level deeper: {"data": {"data": [...]}}
    if isinstance(rows, dict):
        rows = rows.get("data")
    if not isinstance(rows, list):
        return out
    for it in rows:
        if not isinstance(it, dict):
            continue
        sym = it.get("symbol") or it.get("Symbol")
        if not sym or str(sym).upper().startswith("NIFTY"):
            continue
        flat = dict(it)
        for sub in ("meta", "metadata"):
            if isinstance(it.get(sub), dict):
                flat.update(it[sub])
        out[str(sym).strip().upper()] = {
            "ltp": to_number(pick(flat, ["lastPrice", "ltP", "last_price"])),
            "pe": to_number(pick(flat, ["pdSymbolPe", "symbolPe", "pe"])),
            "sectorPe": to_number(pick(flat, ["pdSectorPe", "sectorPe"])),
            "eps": to_number(pick(flat, ["eps", "earningsPerShare"])),
            # NSE sends 0 for the auction fields outside the auction. A
            # zero is "nothing yet", not a price - he saw 0s appear at 2am.
            "icp": (to_number(pick(flat, ICP_KEYS))
                    or None) if not in_auction_pressure_window()
                   else to_number(pick(flat, ICP_KEYS)),
            "ieq": (to_number(pick(flat, IEQ_KEYS))
                    or None) if not in_auction_pressure_window()
                   else to_number(pick(flat, IEQ_KEYS)),
            "close": (to_number(pick(flat, ["closePrice"]))
                      or to_number(pick(flat, ["previousClose"]))),
            "open": to_number(pick(flat, ["open"])),
            # the full registered name ("ONE 97 COMMUNICATIONS LIMITED") -
            # the quote's own name is cut short ("Tata Consultancy Serv
            # Ltd"), which is what kept Tickertape from being found
            "name": str(pick(flat, ["companyName"]) or "").strip(),
        }
    return out


BULK_OK = []        # [(name, url, count)]
BULK_TRIED = []     # [(name, status)]
BULK_SEEN = set()


def discover_bulk():
    """Try every candidate once; keep the ones that actually return stocks."""
    global BULK_OK, BULK_TRIED
    ok, tried = [], []
    for name, url in BULK_CANDIDATES:
        data, err = SESSION.fetch(url, LIVE_PAGE)
        if err:
            tried.append((name, "failed: %s" % err))
            continue
        table = parse_bulk(data)
        if table:
            ok.append((name, url, len(table)))
            tried.append((name, "OK - %d stocks" % len(table)))
        else:
            tried.append((name, "no usable rows"))
        time.sleep(0.4)
    BULK_OK, BULK_TRIED = ok, tried
    return ok


def bulk_pass():
    if not BULK_OK:
        return 0
    state = load_state()
    watch = [s.upper() for s in (state.get("watchlist") or [])]
    if not watch:
        return 0
    # Out of list shares get their price from the same lists (the phone
    # shows it); they never hold up the pass
    extra = [x for x in extra_symbols(state) if x not in watch]
    filled = 0
    for name, url, _n in BULK_OK:
        data, err = SESSION.fetch(url, LIVE_PAGE)
        if err or not data:
            STATS["lastError"] = "bulk %s: %s" % (name, err)
            continue
        table = parse_bulk(data)
        if not table:
            continue
        STATS["lastError"] = ""
        now, nowtxt = time.time(), time.strftime("%H:%M:%S")
        with CACHE_LOCK:
            for sym in watch + extra:
                row = table.get(sym)
                if not row:
                    continue
                BULK_SEEN.add(sym)
                q = CACHE.get(sym) or {"symbol": sym}
                if row["ltp"] is not None:
                    q["ltp"] = q["ltpNum"] = row["ltp"]
                    q["qty"] = int(5000 // row["ltp"]) if row["ltp"] > 0 else None
                for k in ("icp", "ieq", "close", "open"):
                    if row.get(k) is not None:
                        q[k] = row[k]
                if row.get("name"):
                    q["companyFull"] = row["name"]
                q["at"], q["atText"], q["src"] = now, nowtxt, name
                q["error"] = None
                q["tried"] = now
                CACHE[sym] = q
                filled += 1
        if all(s in BULK_SEEN for s in watch):
            break
    STATS["lastBulk"] = time.strftime("%H:%M:%S")
    return filled


# ----------------------------------------------------------------------------
# Per symbol
# ----------------------------------------------------------------------------

WANTED = {"indicativeclose": "icp", "iep": "iep", "ieq": "ieq",
          "pchange": "pchange", "dayhigh": "dayHigh", "daylow": "dayLow",
          "casstatus": "casStatus", "caseligible": "casEligible",
          "lastprice": "ltp", "lastupdatetime": "updated",
          "finalquantity": "ieq", "closeprice": "close", "open": "open",
          "previousclose": "prevclose", "prevclose": "prevclose",
          # valuation - NSE's secInfo block. These were never captured,
          # which is why the VALUATION column stayed empty
          # NOTE: pdSectorPe is NOT a sector figure. NSE's own quote page
          # labels it "Adjusted P/E" of the same share (ITC: Symbol P/E 16.50,
          # Adjusted P/E 16.55, checked 9 Oct). Comparing the two is why
          # nearly every row said Fair. The sector comparison now uses the
          # PE of the share's NIFTY sector index instead.
          "pdsymbolpe": "pe", "pdsectorpe": "adjPe",
          "pdsectorind": "sectorInd", "sector": "sector",
          "industryinfo": "industry", "basicindustry": "basicIndustry",
          "issuedesc": "company"}


def _isodate(v):
    """NSE writes dates like '05-Aug-2026'."""
    # "07-Oct-2026 21:56:20" and "2026-10-07 21:56:20" carry a time after
    # the date - only the date part is wanted
    full = str(v or "").strip()
    for t in (full, full.split(" ")[0].split("T")[0]):
        for fmt in ("%d-%b-%Y", "%Y-%m-%d", "%d-%B-%Y", "%d %b %Y",
                    "%d-%m-%Y", "%d/%m/%Y"):
            try:
                return datetime.datetime.strptime(t, fmt).date().isoformat()
            except Exception:
                continue
    return None


def deep_find(obj, out):
    if isinstance(obj, dict):
        for k, v in obj.items():
            lk = k.lower()
            if lk in WANTED and not isinstance(v, (dict, list)):
                key = WANTED[lk]
                if out.get(key) in (None, "", 0, "0"):
                    out[key] = v
            deep_find(v, out)
    elif isinstance(obj, list):
        for v in obj:
            deep_find(v, out)
    return out


def fetch_symbol(symbol, want_raw=False, light=False):
    symbol = symbol.upper().strip()
    ref = "https://www.nseindia.com/get-quotes/equity?symbol=" + Q(symbol)
    res = {"symbol": symbol, "ltp": None, "icp": None, "iep": None, "ieq": None,
           "casStatus": None, "casEligible": None, "close": None,
           "prevclose": None, "open": None,
           "updated": None, "pchange": None, "dayHigh": None, "dayLow": None,
           "yearHigh": None, "yearLow": None, "yearHighDate": None,
           "yearLowDate": None, "source": [], "error": None,
           "tried": time.time()}       # when it was last asked for (20.10)
    raws, errors = {}, []
    getquote = ("GetQuoteApi",
                "https://www.nseindia.com/api/NextApi/apiClient/GetQuoteApi?"
                + urllib.parse.urlencode({"functionName": "getSymbolData",
                                          "marketType": "N", "series": "EQ",
                                          "symbol": symbol}))
    plain = ("quote-equity",
             "https://www.nseindia.com/api/quote-equity?symbol=" + Q(symbol))
    # GetQuoteApi first: it is the endpoint that actually answers.
    plan = [getquote] if light else [getquote, plain]
    for name, url in plan:
        data, err = SESSION.fetch(url, ref, symbol)
        if err:
            errors.append("%s: %s" % (name, err))
            continue
        if want_raw:
            raws[name] = data
        found = deep_find(data, {})
        if name == "GetQuoteApi" and "casEligible" in found:
            # NSE answers casEligible "Eligible in CAS" for a share in the
            # closing auction and null for one that is not (IDBI, 14 Oct) -
            # the null used to be read as "unknown", so no share was ever
            # marked as outside the auction
            res["casKnown"] = True
        try:
            pi = data.get("priceInfo") if isinstance(data, dict) else None
            whl = (pi or {}).get("weekHighLow") if isinstance(pi, dict) else None
            if isinstance(whl, dict):
                found.setdefault("yearHigh", whl.get("max"))
                found.setdefault("yearLow", whl.get("min"))
                found.setdefault("yearHighDate", _isodate(whl.get("maxDate")))
                found.setdefault("yearLowDate", _isodate(whl.get("minDate")))
        except Exception:
            pass
        used = False
        for key in ("ltp", "icp", "iep", "ieq", "casStatus", "casEligible",
                    "close", "prevclose", "open", "updated", "pchange",
                    "dayHigh", "dayLow",
                    "yearHigh", "yearLow", "yearHighDate", "yearLowDate",
                    "pe", "adjPe", "sectorInd", "sector", "industry",
                    "basicIndustry", "company"):
            val = found.get(key)
            if val in (None, ""):
                continue
            if res.get(key) in (None, ""):
                res[key] = val
                used = True
            elif key in ("icp", "iep", "ieq"):
                if to_number(res[key]) in (0, None) and to_number(val) not in (0, None):
                    res[key] = val
                    used = True
        if used:
            res["source"].append(name)
        if to_number(res["ltp"]) is not None and (light or res["icp"] is not None):
            break
    if res["ltp"] is None and errors:
        res["error"] = " | ".join(errors)
    # closePrice reads 0 all through the session; previousClose is the real
    # one until the market shuts
    if not to_number(res.get("close")) and to_number(res.get("prevclose")):
        res["close"] = res["prevclose"]
    elig = res.get("casEligible")
    if elig in (None, ""):
        res["inCas"] = False if res.get("casKnown") else None
    else:
        t = str(elig).strip().lower()
        res["inCas"] = False if ("not" in t or "ineligible" in t) else ("eligible" in t)
    ltp = to_number(res["ltp"])
    res["ltpNum"] = ltp
    res["qty"] = int(5000 // ltp) if ltp and ltp > 0 else None
    if to_number(res["ltp"]) is not None:
        res["at"], res["atText"] = time.time(), time.strftime("%H:%M:%S")
    if "GetQuoteApi" in res["source"]:
        # this reply carries the share's PE and sector, so its valuation
        # can now be judged (or is known to have no PE, e.g. a loss-maker)
        res["valChecked"] = True
        res["peAt"] = time.strftime("%H:%M")
        res["pePrice"] = to_number(res.get("ltp"))   # the price the P/E is at
        res["peDay"] = datetime.date.today().isoformat()
    res["src"] = "symbol"
    if want_raw:
        res["raw"] = raws
    return res


AUCTION_FIELDS = ("icp", "iep", "ieq")
AUCTION_MAX_AGE = 12.0        # seconds - older than this and we show nothing


def merge_symbol(q):
    """Carry forward ordinary fields when a light fetch omits them, but NEVER
    the auction figures. The light 125-symbol sweep does not carry ICP, and
    copying the old one forward - then stamping it with the sweep's fresh
    timestamp - made a stale ICP look current. That is why the dashboard and
    the NSE website disagreed by a few paise during the auction."""
    with CACHE_LOCK:
        old = CACHE.get(q["symbol"]) or {}
        for k in ("ltp", "ltpNum", "qty", "close", "prevclose", "open",
                  "pchange", "dayHigh", "dayLow", "yearHigh", "yearLow",
                  "yearHighDate", "yearLowDate", "at", "atText", "inCas",
                  "pe", "adjPe", "sectorInd", "sector", "industry",
                  "basicIndustry", "company", "companyFull", "valChecked",
                  "peAt", "pePrice", "peDay"):
            if q.get(k) in (None, "") and old.get(k) not in (None, ""):
                q[k] = old[k]

        got_auction = any(to_number(q.get(k)) not in (None,)
                          for k in AUCTION_FIELDS)
        if got_auction:
            now_t = time.time()
            q["icpAt"] = now_t
            q["icpAtText"] = time.strftime("%H:%M:%S")
            # A figure that has not moved for ten minutes and a figure that is
            # not being refreshed look identical on screen. Recording when the
            # value last CHANGED tells the two apart.
            # Before 3:20 the auction figures come back as 0. Treating 0 as a
            # real reading made the hover say "unchanged since 12:46", which
            # is true but useless.
            new_icp, old_icp = to_number(q.get("icp")), to_number(old.get("icp"))
            if not new_icp:
                q["icpChangedAt"] = old.get("icpChangedAt")
                q["icpChangedText"] = old.get("icpChangedText")
                CACHE[q["symbol"]] = q
                return q
            same = (new_icp == old_icp
                    and to_number(q.get("iep")) == to_number(old.get("iep")))
            if same and old.get("icpChangedAt"):
                q["icpChangedAt"] = old["icpChangedAt"]
                q["icpChangedText"] = old.get("icpChangedText")
            else:
                q["icpChangedAt"] = now_t
                q["icpChangedText"] = time.strftime("%H:%M:%S")
        else:
            # this fetch said nothing about the auction - keep the previous
            # figures WITH their own age, so the page can decide to hide them
            for k in AUCTION_FIELDS:
                if q.get(k) in (None, ""):
                    q[k] = old.get(k)
            q["icpAt"] = old.get("icpAt")
            q["icpAtText"] = old.get("icpAtText")
            q["icpChangedAt"] = old.get("icpChangedAt")
            q["icpChangedText"] = old.get("icpChangedText")
        age = time.time() - (q.get("icpAt") or 0)
        q["icpAge"] = round(age, 1) if q.get("icpAt") else None
        q["icpStale"] = bool(q.get("icpAt")) and age > AUCTION_MAX_AGE
        CACHE[q["symbol"]] = q
    return q


# ----------------------------------------------------------------------------
# State / snapshots
# ----------------------------------------------------------------------------

DEFAULT_STATE = {"watchlist": ["RELIANCE", "ITC", "KOTAKBANK", "NTPC",
                               "TATASTEEL"],
                 "notes": {}, "outOfList": "", "onlyActive": False,
                 "notepad": "", "theme": "#1F3864", "paper": "#FFFFFF"}
STATE_LOCK = threading.Lock()
# Every read-change-save of his data holds NOTE_LOCK, so a change made on the
# iPhone can never fall between another path's read and its save.
NOTE_LOCK = threading.RLock()
NOTE_EDITS = {}                 # (symbol, field) -> stamp of the phone edit
PHONE_REV = {"rev": int(time.time() * 1000)}


def load_state():
    try:
        with open(PATHS["state"], "r") as f:
            s = json.load(f)
        for k, v in DEFAULT_STATE.items():
            s.setdefault(k, v)
        return s
    except Exception:
        return json.loads(json.dumps(DEFAULT_STATE))


# The profile a web request was let in for. If another profile is opened
# while the request is under way, its save is refused rather than written
# into the other profile's dashboard.
REQ = threading.local()


class ProfileMoved(Exception):
    pass


def req_pid_ok():
    p = getattr(REQ, "pid", None)
    return p is None or p == ACTIVE["pid"]


def save_state(state):
    with NOTE_LOCK:
        if not req_pid_ok():
            raise ProfileMoved()
        with STATE_LOCK:
            tmp = PATHS["state"] + ".tmp"
            with open(tmp, "w") as f:
                json.dump(state, f, indent=2)
            os.replace(tmp, PATHS["state"])


ACTIVE_KEYS = ("buy", "purchase", "target")


try:
    os.makedirs(PATHS["backups"], exist_ok=True)
except Exception:
    pass
BACKUP_KEEP = 24
BACKUP_LAST = {}                      # backups folder -> hash of the last copy


def make_backup(tag=""):
    """A dated copy of everything you have typed. Runs on its own - there is
    nothing to press and nothing that can be forgotten."""
    with NOTE_LOCK:                   # one profile's two paths, together
        if not req_pid_ok():
            return None
        src, bdir = PATHS["state"], PATHS["backups"]
    if not os.path.exists(src):
        return None
    name = ("cas_state_" + time.strftime("%Y-%m-%d_%H%M")
            + (("_" + tag) if tag else "") + ".json")
    dest = os.path.join(bdir, name)
    try:
        with open(src, "r") as a:
            body = a.read()
        json.loads(body)                    # never back up a broken file
        # nothing changed since the last copy: no new copy - so the copies
        # kept reach back days, not just the last four hours
        h = hashlib.sha1(body.encode("utf-8")).hexdigest()
        if not tag and BACKUP_LAST.get(bdir) == h:
            return None
        BACKUP_LAST[bdir] = h
        tmp = dest + ".tmp"
        with open(tmp, "w") as b:
            b.write(body)
        os.replace(tmp, dest)
    except Exception:
        return None
    try:
        files = sorted(f for f in os.listdir(bdir)
                       if f.startswith("cas_state_") and f.endswith(".json"))
        # the newest 24 (every ten minutes, when something changed), plus
        # the last copy of each of the last 30 days, plus the start-up and
        # before-restore copies - which are never pushed out by the others
        rolling = [f for f in files if not re.search(r"_[a-z]", f[20:])]
        daily = {}
        for f in rolling:
            daily[f[10:20]] = f            # the last copy of each day
        keep = set(rolling[-BACKUP_KEEP:]) | set(sorted(daily.values())[-30:])
        # 20.18: and each day's FULLEST copy (most rows with something
        # typed), so a wipe late in a day can never push out that day's
        # good copy - 1 Nov's survived only because the dashboard was shut
        best = {}
        for f in files:
            if f[10:20] < (datetime.date.today() - datetime.timedelta(
                    days=30)).isoformat():
                continue
            try:
                with open(os.path.join(bdir, f)) as fh:
                    nn = json.load(fh).get("notes") or {}
                typed = sum(1 for v in nn.values() if isinstance(v, dict) and
                            any(str(x or "").strip() for x in v.values()))
            except Exception:
                continue
            if typed > best.get(f[10:20], (-1, ""))[0]:
                best[f[10:20]] = (typed, f)
        keep |= {f for _t, f in best.values()}
        special = [f for f in files if f not in rolling]
        keep |= set(special[-10:])
        for old in files:
            if old not in keep:
                os.remove(os.path.join(bdir, old))
    except Exception:
        pass
    return name


def list_backups():
    out = []
    try:
        for f in sorted(os.listdir(PATHS["backups"]), reverse=True):
            if not (f.startswith("cas_state_") and f.endswith(".json")):
                continue
            p = os.path.join(PATHS["backups"], f)
            try:
                d = json.load(open(p))
                n = len(d.get("watchlist") or [])
                typed = sum(1 for v in (d.get("notes") or {}).values()
                            if any(str(x or "").strip() for x in v.values()))
            except Exception:
                continue
            out.append({"file": f,
                        "when": time.strftime("%d %b %Y, %H:%M",
                                              time.localtime(
                                                  os.path.getmtime(p))),
                        "symbols": n, "rowsWithNotes": typed})
    except Exception:
        pass
    return out


def backup_preview(name):
    """20.18: exactly what putting a backup back would change - every box of
    the table that differs (share, column, now -> in the backup), shares
    added or gone, and which settings differ - before anything is done."""
    if not re.fullmatch(r"cas_state_[0-9_\-]+(_\w+)?\.json", name or ""):
        return {"ok": False, "note": "not a backup file name"}
    try:
        b = json.load(open(os.path.join(PATHS["backups"], name)))
    except Exception as e:
        return {"ok": False, "note": "could not read it (%s)" % str(e)[:60]}
    cur = load_state()
    labels = dict({"buy": "QTY", "purchase": "PRICE", "target": "TARGET",
                   "old": "OLD", "yesterday": "YESTERDAY", "missed": "MISSED"},
                  **{k: v for k, v in (cur.get("headings") or {}).items() if v})
    cn, bn = cur.get("notes") or {}, b.get("notes") or {}
    cells = []
    for sym in sorted(set(cn) | set(bn)):
        a, z = cn.get(sym) or {}, bn.get(sym) or {}
        for f in sorted(set(a) | set(z)):
            va, vz = str(a.get(f) or "").strip(), str(z.get(f) or "").strip()
            if va != vz:
                cells.append({"sym": sym, "col": labels.get(f, f.upper()),
                              "now": va, "backup": vz})
    cw, bw = cur.get("watchlist") or [], b.get("watchlist") or []
    skip = {"notes", "watchlist", "_phoneRev", "_chgRates"}
    settings = sorted(k for k in set(cur) | set(b) if k not in skip and
                      json.dumps(cur.get(k), sort_keys=True) !=
                      json.dumps(b.get(k), sort_keys=True))
    return {"ok": True, "cells": cells[:400], "cellCount": len(cells),
            "added": [s for s in bw if s not in cw],
            "gone": [s for s in cw if s not in bw],
            "settings": settings}


def restore_backup(name):
    """Put a backup back. The current file is itself backed up first, so a
    restore can always be undone."""
    if not re.fullmatch(r"cas_state_[0-9_\-]+(_\w+)?\.json", name or ""):
        return {"ok": False, "note": "not a backup file name"}
    src = os.path.join(PATHS["backups"], name)
    if not os.path.exists(src):
        return {"ok": False, "note": "that backup is no longer there"}
    try:
        body = open(src).read()
        data = json.loads(body)
    except Exception as e:
        return {"ok": False, "note": "backup unreadable: %s" % e}
    make_backup("before_restore")
    with NOTE_LOCK:
        save_state(data)
    return {"ok": True, "note": "restored " + name,
            "symbols": len(data.get("watchlist") or [])}


def backup_watcher():
    last = 0
    while STATS["running"]:
        try:
            if time.time() - last > 600:        # every ten minutes
                if make_backup():
                    last = time.time()
        except Exception:
            pass
        time.sleep(30)


def active_symbols(state):
    """A row is active if it has a quantity, a price OR a target - any one."""
    n = state.get("notes") or {}
    out = []
    for s in (state.get("watchlist") or []):
        note = n.get(s) or {}
        if any(str(note.get(k, "") or "").strip() for k in ACTIVE_KEYS):
            out.append(s)
    return out


def load_snaps():
    try:
        with open(SNAP_FILE, "r") as f:
            return json.load(f)
    except Exception:
        return {}


def save_snaps(s):
    tmp = SNAP_FILE + ".tmp"
    with open(tmp, "w") as f:
        json.dump(s, f, indent=2)
    os.replace(tmp, SNAP_FILE)
    write_csv(s)


def write_csv(snaps):
    """One row per recorded trade. Purchase = the price he bought at."""
    try:
        rows = []
        for day in sorted(snaps.keys()):
            for sym, r in sorted(snaps[day].items()):
                try:
                    dtxt = datetime.date.fromisoformat(day).strftime("%d-%b-%Y")
                except Exception:
                    dtxt = day
                rows.append({
                    "date": dtxt,
                    "symbol": sym,
                    "qty": r.get("buy", ""),
                    "purchase": r.get("purchase", "") or r.get("p1515", ""),
                    "close": r.get("close", ""),
                    "next_morning": r.get("next0930", ""),
                    "next_price_source": r.get("nextSource", ""),
                })
        with open(CSV_FILE, "w", newline="") as f:
            w = csv.DictWriter(f, fieldnames=["date", "symbol", "qty",
                                              "purchase", "close",
                                              "next_morning",
                                              "next_price_source"])
            w.writeheader()
            w.writerows(rows)
    except Exception:
        pass


SNAP_DONE = {}
today_key = lambda: datetime.date.today().isoformat()


def hist_daily(symbol, d_from, d_to):
    """Daily open/close straight from NSE's historical data - works for past
    days, so the dashboard does NOT have to be running at 3:40 or 9:30."""
    url = ("https://www.nseindia.com/api/historical/cm/equity?symbol="
           + Q(symbol) + "&series=[%22EQ%22]"
           + "&from=" + d_from.strftime("%d-%m-%Y")
           + "&to=" + d_to.strftime("%d-%m-%Y"))
    ref = "https://www.nseindia.com/get-quotes/equity?symbol=" + Q(symbol)
    data, err = SESSION.fetch(url, ref, symbol)
    if err or not isinstance(data, dict):
        return {}, err
    out = {}
    for row in (data.get("data") or []):
        if not isinstance(row, dict):
            continue
        ts = row.get("CH_TIMESTAMP") or row.get("mTIMESTAMP") or ""
        day = None
        for fmt in ("%Y-%m-%d", "%d-%b-%Y"):
            try:
                day = datetime.datetime.strptime(str(ts)[:11].strip(),
                                                 fmt).date().isoformat()
                break
            except Exception:
                pass
        if not day:
            continue
        out[day] = {
            "open": to_number(row.get("CH_OPENING_PRICE")),
            "close": to_number(row.get("CH_CLOSING_PRICE")),
            "high": to_number(row.get("CH_TRADE_HIGH_PRICE")),
            "low": to_number(row.get("CH_TRADE_LOW_PRICE")),
        }
    return out, None


# NSE's intraday chart of the day. NSE moved it (found 28 Oct 2026, when the
# old chart-databyindex started answering with an empty list all day): the
# "-dynamic" address gives one price a minute for a share (with a flag: PO
# pre-open, NM normal market, IC the closing session) and one a second for
# an index, India's clock time written as if it were UTC.
NSE_CHART = "https://www.nseindia.com/api/chart-databyindex-dynamic?index="


def intraday_price_at(symbol, hhmm="09:30"):
    """Today's traded price at a given clock time, from NSE's intraday chart.
    Only works for the CURRENT day - which is exactly what we need: at 3 pm
    we can still read this morning's 9:30 price."""
    url = (NSE_CHART + Q(symbol.upper() + "EQN") + "&type=symbol")
    ref = "https://www.nseindia.com/get-quotes/equity?symbol=" + Q(symbol)
    data, err = SESSION.fetch(url, ref, symbol)
    if err or not isinstance(data, dict):
        return None, err or "no data"
    pts = data.get("grapthData") or data.get("graphData") or []
    if not pts:
        return None, "empty chart"
    want_h, want_m = int(hhmm[:2]), int(hhmm[3:5])
    best, best_gap = None, None
    for p in pts:
        try:
            ts, price = p[0], p[1]
            dt = datetime.datetime.fromtimestamp(ts / 1000.0)
            gap = abs((dt.hour * 60 + dt.minute) - (want_h * 60 + want_m))
            if best_gap is None or gap < best_gap:
                best, best_gap = to_number(price), gap
        except Exception:
            continue
    if best is None or best_gap is None or best_gap > 20:
        return None, "no tick near %s" % hhmm
    return best, None


def intraday_0930(symbol, want="09:30"):
    """NSE's intraday chart for TODAY. Lets us read back this morning's 9:30
    price during the afternoon - no need to be awake at 9:30."""
    url = (NSE_CHART + Q(symbol.upper() + "EQN") + "&type=symbol")
    ref = "https://www.nseindia.com/get-quotes/equity?symbol=" + Q(symbol)
    data, err = SESSION.fetch(url, ref, symbol)
    if err or not isinstance(data, dict):
        return None, err
    pts = data.get("grapthData") or data.get("graphData") or []
    hh, mm = int(want[:2]), int(want[3:5])
    best, bestgap = None, 10 ** 9
    # NSE is reported to send India's clock time written as if it were UTC:
    # whichever reading puts the points inside market hours is the right one
    conv = datetime.datetime.fromtimestamp
    if nse_clock_is_utc([p[0] / 1000.0 for p in pts
                         if isinstance(p, (list, tuple)) and p]):
        conv = datetime.datetime.utcfromtimestamp
    for p in pts:
        try:
            ts, price = p[0], p[1]
            t = conv(ts / 1000.0)
            gap = abs((t.hour * 60 + t.minute) - (hh * 60 + mm))
            if gap < bestgap:
                best, bestgap = to_number(price), gap
        except Exception:
            continue
    if best is None or bestgap > 12:
        return None, "no 09:30 point in today's chart"
    return best, None


def fill_today_0930():
    """For the previous TRADING day's positions, fetch this morning's 9:30
    price. Never reads a weekend or holiday, where no 9:30 exists."""
    if not is_trading_day():
        return {"filled": 0, "note": "today is not a trading day"}
    snaps = load_snaps()
    prev = [k for k in sorted(snaps.keys()) if k < today_key()]
    if not prev:
        return {"filled": 0, "note": "nothing pending"}
    day = prev[-1]
    try:
        if next_trading_day(datetime.date.fromisoformat(day)) \
                != datetime.date.today():
            return {"filled": 0,
                    "note": "today is not the next trading day after " + day}
    except Exception:
        pass
    filled, errs = 0, []
    for sym, rec in snaps[day].items():
        if rec.get("next0930") and rec.get("nextSource") == "live 9:30":
            continue
        px, err = intraday_0930(sym)
        if px:
            rec["next0930"] = px
            rec["nextSource"] = "live 9:30"
            rec["nextOpenDate"] = today_key()
            filled += 1
        elif err:
            errs.append("%s: %s" % (sym, err))
        time.sleep(0.5)
    save_snaps(snaps)
    return {"day": day, "filled": filled, "errors": errs[:4]}


LT_CACHE = {}          # symbol -> {"day": iso, "points": [...]}

# ---------------------------------------------------------------------------
# LT chart - built from NSE's own daily 52-week high/low report
#
#   https://nsearchives.nseindia.com/content/CM_52_wk_High_low_DDMMYYYY.csv
#
# Each dated file carries, for every listed symbol, the 52-week high and low
# AND the date each was set.  The two lines are then, for any day d:
#
#   Green = (365 - days since that day's 52-week HIGH) / 365 x 100
#   Red   = (365 - days since that day's 52-week LOW ) / 365 x 100
#
# Because every file states its own high/low dates, the reset is automatic:
# when an old extreme drops out of the window NSE names a new one, and the
# line jumps back up on that day.  Nothing is ever negative.
# ---------------------------------------------------------------------------

WK52_DIR = os.path.join(DATA_DIR, "wk52")
try:
    os.makedirs(WK52_DIR, exist_ok=True)
except Exception:
    pass

WK52_MEM = {}                       # "DDMMYYYY" -> {SYM: (hi, hid, lo, lod)}
WK52_MISS = set()                   # dates known to have no file
WK52_LOCK = threading.Lock()

_MON = {"JAN": 1, "FEB": 2, "MAR": 3, "APR": 4, "MAY": 5, "JUN": 6,
        "JUL": 7, "AUG": 8, "SEP": 9, "OCT": 10, "NOV": 11, "DEC": 12}


def _nse_day(d):
    return d.strftime("%d%m%Y")


def _wk52_date(text):
    """'19-AUG-2025' -> date, or None."""
    try:
        p = str(text).strip().upper().split("-")
        return datetime.date(int(p[2]), _MON[p[1][:3]], int(p[0]))
    except Exception:
        return None


def wk52_parse(text):
    out = {}
    for line in text.splitlines():
        if not line.startswith('"') or line.startswith('"SYMBOL"'):
            continue
        cols = [c.strip().strip('"').strip() for c in line.split('","')]
        if len(cols) < 6:
            continue
        sym = re.sub(r"[^A-Z0-9]", "", cols[0].upper())
        hi, hid, lo, lod = cols[2], cols[3], cols[4], cols[5].rstrip('"')
        if hi in ("-", "") or lo in ("-", ""):
            continue
        out[sym] = (to_number(hi), hid, to_number(lo), lod)
    return out


def wk52_for(d, allow_download=True):
    """That day's report: memory, then disk, then NSE.  {} if no file."""
    key = _nse_day(d)
    with WK52_LOCK:
        if key in WK52_MEM:
            return WK52_MEM[key]
        if key in WK52_MISS:
            return {}
    path = os.path.join(WK52_DIR, key + ".csv.gz")
    text = None
    if os.path.exists(path):
        try:
            import gzip
            with gzip.open(path, "rt", encoding="utf-8", errors="replace") as f:
                text = f.read()
        except Exception:
            text = None
    if text is None and allow_download:
        url = ("https://nsearchives.nseindia.com/content/CM_52_wk_High_low_"
               + key + ".csv")
        try:
            raw = RPT_SESSION.get_raw(url,
                "https://www.nseindia.com/report-detail/eq_security")
            text = raw.decode("utf-8", "replace")
            if "SYMBOL" not in text[:400]:
                text = None
        except Exception:
            text = None
        if text:
            try:
                import gzip
                with gzip.open(path + ".tmp", "wt", encoding="utf-8") as f:
                    f.write(text)
                os.replace(path + ".tmp", path)
            except Exception:
                pass
    if not text:
        with WK52_LOCK:
            WK52_MISS.add(key)
        return {}
    table = wk52_parse(text)
    with WK52_LOCK:
        WK52_MEM[key] = table
        if len(WK52_MEM) > 60:
            WK52_MEM.pop(next(iter(WK52_MEM)))
    return table


def wk52_available_days(limit=400):
    """Dates we already hold on disk, newest last."""
    days = []
    try:
        for name in os.listdir(WK52_DIR):
            if not name.endswith(".csv.gz"):
                continue
            k = name[:-7]
            try:
                days.append(datetime.date(int(k[4:8]), int(k[2:4]), int(k[:2])))
            except Exception:
                continue
    except Exception:
        pass
    days.sort()
    return days[-limit:]


def lt_point(day, row):
    """One chart point from one day's (hi, hidate, lo, lodate)."""
    hi, hid, lo, lod = row
    dh, dl = _wk52_date(hid), _wk52_date(lod)
    if not (dh and dl):
        return None
    since_hi = max(0, (day - dh).days)
    since_lo = max(0, (day - dl).days)
    return {"d": day.isoformat(),
            "green": round(max(0.0, (365 - since_hi) / 365 * 100), 2),
            "red": round(max(0.0, (365 - since_lo) / 365 * 100), 2),
            "high52": hi, "low52": lo,
            "highOn": dh.isoformat(), "lowOn": dl.isoformat(),
            "sinceHigh": since_hi, "sinceLow": since_lo}


def wk52_fetch_latest(back=6):
    """Today's file if NSE has published it, else the most recent one."""
    today = datetime.date.today()
    for i in range(back):
        d = today - datetime.timedelta(days=i)
        if not is_trading_day(d):
            continue
        if wk52_for(d):
            return d
    return None


def lt_series(symbol, lookback_days=520):
    """Every day we hold a report for, as two 0-100 lines."""
    sym = re.sub(r"[^A-Z0-9]", "", (symbol or "").upper())
    today = datetime.date.today()
    hit = LT_CACHE.get(sym)
    if hit and hit.get("day") == today.isoformat():
        return hit["points"], None

    days = wk52_available_days()
    if not days:
        d = wk52_fetch_latest()
        days = [d] if d else []
    cut = today - datetime.timedelta(days=lookback_days)
    points = []
    for d in days:
        if d < cut:
            continue
        row = (wk52_for(d, allow_download=False) or {}).get(sym)
        if row:
            p = lt_point(d, row)
            if p:
                points.append(p)
    if not points:
        return [], ("no 52-week reading for this share yet - press Backfill "
                    "history in Diagnostics to fetch NSE's report")
    LT_CACHE[sym] = {"day": today.isoformat(), "points": points}
    return points, None


def lt_record_today():
    """Called after the close - pull today's report so the chart extends.
    20.14: the charts made today are kept unless a newer report arrived
    (it used to throw them all away on every opening, so every LT chart was
    worked out afresh from a year of files - the 10-15 second wait)."""
    now = time.time()
    if now - LT_WARM.get("checked", 0) < 600 and LT_WARM.get("latest"):
        return LT_WARM.get("n", 0)
    LT_WARM["checked"] = now
    d = wk52_fetch_latest()
    if not d:
        return 0
    if LT_WARM.get("latest") != d.isoformat():
        LT_WARM["latest"] = d.isoformat()
        LT_CACHE.clear()
    LT_WARM["n"] = len(wk52_for(d) or {})
    return LT_WARM["n"]


LT_WARM = {"latest": "", "checked": 0, "n": 0, "busy": False, "done": ""}


def lt_warm(symbols=None):
    """20.14: every LT chart of the table made ready in one pass over the
    year of NSE reports (each file read once for all the shares, not once per
    share), so the LT hover box shows the chart at once."""
    if LT_WARM["busy"]:
        return
    LT_WARM["busy"] = True
    try:
        import gzip
        lt_record_today()
        today = datetime.date.today()
        if symbols is None:
            st = load_state()
            symbols = list(dict.fromkeys((st.get("watchlist") or []) +
                                         extra_symbols(st)))
        want = {re.sub(r"[^A-Z0-9]", "", s.upper()) for s in symbols}
        want = {s for s in want if s and not (
            (LT_CACHE.get(s) or {}).get("day") == today.isoformat())}
        if not want:
            return
        cut = today - datetime.timedelta(days=520)
        got = {s: [] for s in want}
        for d in wk52_available_days():
            if d < cut:
                continue
            key = _nse_day(d)
            with WK52_LOCK:
                table = WK52_MEM.get(key)
            if table is None:
                path = os.path.join(WK52_DIR, key + ".csv.gz")
                try:
                    with gzip.open(path, "rt", encoding="utf-8",
                                   errors="replace") as f:
                        table = wk52_parse(f.read())
                except Exception:
                    continue
            for s in want:
                row = table.get(s)
                if row:
                    pt = lt_point(d, row)
                    if pt:
                        got[s].append(pt)
            time.sleep(0.002)               # never hog the computer
        for s, pts in got.items():
            if pts:
                LT_CACHE[s] = {"day": today.isoformat(), "points": pts}
        LT_WARM["done"] = time.strftime("%H:%M")
    except Exception:
        pass
    finally:
        LT_WARM["busy"] = False


def lt_warm_loop():
    time.sleep(40)
    while STATS["running"]:
        lt_warm()
        time.sleep(1800)


def lt_backfill(days_back=45):
    """Download past dated copies of NSE's 52-week report."""
    today = datetime.date.today()
    got, missing = 0, 0
    for i in range(days_back + 1):
        d = today - datetime.timedelta(days=i)
        if not is_trading_day(d):
            continue
        if os.path.exists(os.path.join(WK52_DIR, _nse_day(d) + ".csv.gz")):
            got += 1
            continue
        with WK52_LOCK:
            WK52_MISS.discard(_nse_day(d))
        if wk52_for(d):
            got += 1
        else:
            missing += 1
        time.sleep(0.6)
    LT_CACHE.clear()
    return {"days": got, "missing": missing,
            "note": "each day held is one point on every LT chart"}


def wk52_catch_up(days=10):
    """Collect any recent trading days we do not already hold. Runs at
    startup, so the dashboard does NOT have to be open at any particular
    hour - open it the next morning and yesterday's report is picked up."""
    today = datetime.date.today()
    got = 0
    for i in range(1, days + 1):
        d = today - datetime.timedelta(days=i)
        if not is_trading_day(d):
            continue
        if os.path.exists(os.path.join(WK52_DIR, _nse_day(d) + ".csv.gz")):
            continue
        with WK52_LOCK:
            WK52_MISS.discard(_nse_day(d))
        if wk52_for(d):
            got += 1
        time.sleep(0.5)
    if got:
        LT_CACHE.clear()
    return got


def wk52_watcher():
    """Catch up on anything missed, then look for today's report from 4pm on.
    Nothing depends on the machine being awake at a set time."""
    try:
        wk52_catch_up()
    except Exception:
        pass
    done = None
    while STATS["running"]:
        try:
            now = datetime.datetime.now()
            today = now.date()
            if done != today and now.hour >= 16 and is_trading_day(today):
                with WK52_LOCK:
                    WK52_MISS.discard(_nse_day(today))
                if wk52_for(today):
                    LT_CACHE.clear()
                    done = today
        except Exception:
            pass
        time.sleep(900)


def backfill(days_back=30):
    """Fill in any missing close / next-day-open for days already recorded."""
    snaps = load_snaps()
    if not snaps:
        return {"filled": 0, "symbols": 0, "note": "no snapshot days yet"}
    today = datetime.date.today()
    start = today - datetime.timedelta(days=days_back + 7)
    syms = sorted({s for day in snaps for s in snaps[day]})
    filled, errs = 0, []
    for sym in syms:
        table, err = hist_daily(sym, start, today)
        if err:
            errs.append("%s: %s" % (sym, err))
            time.sleep(0.6)
            continue
        days = sorted(table.keys())
        for day in snaps:
            rec = snaps[day].get(sym)
            if rec is None:
                continue
            if not rec.get("close") and day in table and table[day]["close"]:
                rec["close"] = table[day]["close"]
                filled += 1
            if not rec.get("next0930"):
                try:
                    want = next_trading_day(
                        datetime.date.fromisoformat(day)).isoformat()
                except Exception:
                    want = None
                later = [d for d in days if d > day]
                pick_day = want if (want and want in table) else \
                    (later[0] if later else None)
                if pick_day and table[pick_day]["open"]:
                    rec["next0930"] = table[pick_day]["open"]
                    rec["nextSource"] = "9:15 open (approx)"
                    rec["nextOpenDate"] = pick_day
                    filled += 1
        time.sleep(0.6)
    save_snaps(snaps)
    return {"filled": filled, "symbols": len(syms),
            "errors": errs[:5]}


# ----------------------------------------------------------------------------
# Banners
# ----------------------------------------------------------------------------

EVENTS, EVENT_DONE = [], {}
CAS_WAS_ON = {"v": False}

# ---------------------------------------------------------------------------
# THE CLOSING AUCTION'S CLOCK (20.11)
#
# SEBI's circular of 15 October 2026 moves the closing auction to 3:30-3:40
# from Monday 7 December 2026: normal trading for every share until 3:30;
# 3:30-3:31 the reference price; 3:31-3:36 market and limit orders;
# 3:36-3:40 limit orders only, the window shutting at a random moment
# between 3:38 and 3:40; then matching and the closing price; post-close
# session 3:50-4:00 at the closing price; F&O until 3:45. Every time in the
# dashboard that depends on the auction comes from cas_times(), so it
# switches by itself that morning. If NSE moves the date, one line in
# Data/cas_times.json ({"newFrom": "2026-12-14"}) moves it here too.
# ---------------------------------------------------------------------------

CAS_NEW_FROM = datetime.date(2026, 12, 7)
CAS_TIMES_FILE = os.path.join(DATA_DIR, "cas_times.json")
CAS_FROM_CACHE = {"at": 0, "v": CAS_NEW_FROM}
# minutes after midnight. warn = 5 minutes before normal trading ends;
# ctsEnd = normal trading ends for the auction's shares; entry = auction
# orders open; limitOnly = market orders frozen; mayShut = the "any moment"
# alert; shutFrom-shut = the random close; note = today's buys are noted;
# late = the closing prices are final
CAS_CLOCKS = {
    False: {"warn": 910, "ctsEnd": 915, "entry": 920, "limitOnly": 925,
            "mayShut": 927, "shutFrom": 928, "shut": 930, "matched": 935,
            "note": 931, "late": 945},
    True: {"warn": 925, "ctsEnd": 930, "entry": 931, "limitOnly": 936,
           "mayShut": 937, "shutFrom": 938, "shut": 940, "matched": 941,
           "note": 941, "late": 955},
}
SCHEDULE_OLD = [("15:10", "warn", "BUYING TIME — 5 minutes left of normal trading"),
                ("15:15", "stop", "ORDERS STOPPED — continuous trading closed"),
                ("15:20", "go", "ORDERS OPEN — auction order entry"),
                ("15:25", "warn", "LIMIT ORDERS ONLY — market orders frozen"),
                ("15:27", "stop", "WINDOW MAY SHUT ANY MOMENT — random 3:28-3:30"),
                ("15:35", "info", "Matching over — closing price published")]
SCHEDULE_NEW = [("15:25", "warn", "BUYING TIME — 5 minutes left of normal trading"),
                ("15:30", "stop", "ORDERS STOPPED — continuous trading closed, "
                 "auction orders from 3:31"),
                ("15:31", "go", "ORDERS OPEN — auction order entry"),
                ("15:36", "warn", "LIMIT ORDERS ONLY — market orders frozen"),
                ("15:37", "stop", "WINDOW MAY SHUT ANY MOMENT — random 3:38-3:40"),
                ("15:41", "info", "Auction closed — closing price being published")]
SCHEDULE = SCHEDULE_OLD          # the list as it stood (tests, old callers)


def cas_new_from():
    """The day the new auction times start (the override file, if any)."""
    if time.time() - CAS_FROM_CACHE["at"] > 60:
        v = CAS_NEW_FROM
        try:
            raw = _read_json(CAS_TIMES_FILE, {}).get("newFrom")
            if raw:
                v = datetime.date.fromisoformat(str(raw)[:10])
        except (ValueError, TypeError, AttributeError):
            pass
        CAS_FROM_CACHE.update(at=time.time(), v=v)
    return CAS_FROM_CACHE["v"]


def cas_times(day=None):
    """The auction's clock for that day: minutes after midnight, and "new"
    once SEBI's 3:30-3:40 auction applies."""
    if isinstance(day, datetime.datetime):
        day = day.date()
    day = day or datetime.date.today()
    new = day >= cas_new_from()
    t = dict(CAS_CLOCKS[new])
    t["new"] = new
    return t


def cas_schedule(day=None):
    return SCHEDULE_NEW if cas_times(day)["new"] else SCHEDULE_OLD


def hm_text(mins, dot=False):
    """915 -> "15:15", or with dot "3:15" (as he writes it)."""
    h, m = divmod(int(mins), 60)
    return ("%d:%02d" % (h - 12 if h > 12 else h, m)) if dot else \
        "%02d:%02d" % (h, m)


def cas_public(day=None):
    """What the pages need: the times as "15:31", and from 1 December a
    notice that the new times are coming."""
    t = cas_times(day)
    out = {k: hm_text(v) for k, v in t.items() if k != "new"}
    out["new"] = t["new"]
    nf = cas_new_from()
    out["newFrom"] = nf.isoformat()
    today = day or datetime.date.today()
    left = (nf - today).days
    out["notice"] = ("From %s the closing auction moves to 3:30-3:40: "
                     "normal trading until 3:30, auction orders 3:31-3:40 "
                     "(limit orders only after 3:36), the window shutting at "
                     "a random moment between 3:38 and 3:40. The dashboard "
                     "switches by itself that morning." % (
                         "tomorrow" if left == 1 else
                         nf.strftime("%A %-d %B") if os.name != "nt" else
                         nf.strftime("%A %d %B"))) if 0 < left <= 6 else ""
    return out



# ---------------------------------------------------------------------------
# ALERTS
#
# The schedule above is only the starting point. Everything about it is his:
# which ones fire, what they say, when, and whether they make a sound. He can
# add his own and delete any of them, and undo covers the lot.
# ---------------------------------------------------------------------------

ALERT_FILE = os.path.join(DATA_DIR, "alerts.json")
SOUND_DIR = os.path.join(os.path.dirname(DATA_DIR), "Sounds")
ALERTS = {"items": [], "sound": "chime", "volume": 0.6}


def alerts_default():
    out = []
    for i, (hhmm, level, text) in enumerate(cas_schedule()):
        out.append({"id": "s%d" % i, "at": hhmm, "level": level,
                    "text": text, "on": True, "sound": True})
    return out


def alerts_load():
    try:
        with open(ALERT_FILE) as f:
            d = json.load(f)
        ALERTS["items"] = d.get("items") or alerts_default()
        ALERTS["sound"] = d.get("sound") or "chime"
        ALERTS["volume"] = d.get("volume", 0.6)
        ALERTS["casNew"] = bool(d.get("casNew")) if d.get("items") \
            else cas_times()["new"]
    except Exception:
        ALERTS["items"] = alerts_default()
        ALERTS["casNew"] = cas_times()["new"]
    alerts_cas_switch()


def alerts_cas_switch():
    """On the first day of the new auction times, the standard alerts move
    with them: one still at its old standard time goes to the new one (and
    its standard words to the new words). One he moved or wrote himself is
    left as he made it. Done once; the box then shows the new times."""
    if ALERTS.get("casNew") or not cas_times()["new"]:
        return False
    out = []
    for it in ALERTS["items"]:
        it = dict(it)
        m = re.fullmatch(r"s(\d)", str(it.get("id") or ""))
        i = int(m.group(1)) if m else -1
        if 0 <= i < len(SCHEDULE_OLD) and it.get("at") == SCHEDULE_OLD[i][0]:
            it["at"] = SCHEDULE_NEW[i][0]
            if it.get("text") == SCHEDULE_OLD[i][2]:
                it["text"] = SCHEDULE_NEW[i][2]
        out.append(it)
    out.sort(key=lambda x: str(x.get("at") or ""))
    ALERTS["items"] = out
    ALERTS["casNew"] = True
    alerts_save()
    return True


def alerts_save(payload=None):
    if payload:
        if "items" in payload:
            ALERTS["items"] = payload["items"]
        if "sound" in payload:
            ALERTS["sound"] = payload["sound"]
        if "volume" in payload:
            ALERTS["volume"] = payload["volume"]
    try:
        tmp = ALERT_FILE + ".tmp"
        with open(tmp, "w") as f:
            json.dump({"items": ALERTS["items"], "sound": ALERTS["sound"],
                       "volume": ALERTS["volume"],
                       "casNew": bool(ALERTS.get("casNew"))}, f, indent=1)
        os.replace(tmp, ALERT_FILE)
    except Exception:
        pass
    return {"ok": True}


def alerts_sounds():
    """The built-in tones, plus any mp3 he has dropped in Backend/Sounds."""
    built = ["chime", "ping", "bell", "buzz", "rise", "none"]
    files = []
    try:
        os.makedirs(SOUND_DIR, exist_ok=True)
        for f in sorted(os.listdir(SOUND_DIR)):
            if f.lower().endswith((".mp3", ".wav", ".m4a", ".aiff")):
                files.append(f)
    except Exception:
        pass
    return {"built": built, "files": files, "folder": SOUND_DIR}


def event_watcher():
    while STATS["running"]:
        if not is_trading_day():
            time.sleep(60)
            continue
        hm = datetime.datetime.now().strftime("%H:%M")
        try:
            alerts_cas_switch()
        except Exception:
            pass
        # 20.11: his own list from the Alerts box (before, the standard list
        # fired whatever he had changed there)
        for it in list(ALERTS["items"] or alerts_default()):
            when = str(it.get("at") or "")
            if not it.get("on", True) or not re.fullmatch(r"\d\d:\d\d", when):
                continue
            key = today_key() + str(it.get("id")) + when
            if hm == when and not EVENT_DONE.get(key):
                EVENT_DONE[key] = True
                push_event(it.get("level") or "info", str(it.get("text") or ""),
                           sound=it.get("sound", True) is not False)
        time.sleep(5)


def push_event(level, text, gap=180, sound=True):
    """One banner per thing. Anything identical inside `gap` seconds is
    dropped, whichever code path raised it."""
    now = time.time()
    for e in EVENTS[-12:]:
        if e.get("text") == text and now - e.get("at", 0) < gap:
            return
    EVENTS.append({"at": now, "level": level, "text": text, "sound": sound})
    if len(EVENTS) > 400:
        del EVENTS[:-300]


def note_cas(on):
    """Called once per share, and different shares report the auction as open
    or closed at slightly different moments - which used to flip this flag
    back and forth and fire the banner several times in a few seconds. The
    window itself decides now, and the flag only moves once."""
    if on:
        if not CAS_WAS_ON["v"]:
            CAS_WAS_ON["v"] = True
        return
    if CAS_WAS_ON["v"] and not in_auction_window():
        CAS_WAS_ON["v"] = False
        push_event("stop", "AUCTION CLOSED at " + time.strftime("%H:%M:%S"))


