# News
# ----------------------------------------------------------------------------

NEWS = {"items": [], "global": [], "at": 0, "error": ""}


def _iso_norm(v):
    """ISO dates as older Pythons (his Mac may have 3.9) can read them:
    "Z" -> +00:00, "+0530" -> +05:30, fractions of a second dropped, and a
    bare date given a time."""
    v = (v or "").strip().replace("Z", "+00:00")
    v = re.sub(r"\.\d+(?=[+-]\d\d:?\d\d$|$)", "", v)
    v = re.sub(r"([+-]\d\d)(\d\d)$", r"\1:\2", v)
    if re.fullmatch(r"\d{4}-\d\d-\d\d", v):
        v += "T00:00:00+05:30"
    return v


def age_hours(pub):
    """Hours since a feed's date. RFC-822 dates ("Fri, 09 Oct 2026 05:10:00
    +0530") and ISO ones ("2026-10-09T05:10:00+05:30") are both read. An
    item with no date at all is not thrown away - see undated_verdict."""
    pub = (pub or "").strip()
    if not pub:
        return None
    dt = None
    try:
        dt = email.utils.parsedate_to_datetime(pub)
    except Exception:
        dt = None
    if dt is None:
        try:
            dt = datetime.datetime.fromisoformat(_iso_norm(pub))
        except Exception:
            dt = None
    if dt is None:
        for fmt in ("%Y-%m-%d %H:%M:%S", "%d %b %Y %H:%M:%S",
                    "%a, %d %b %Y %H:%M:%S", "%B %d, %Y %H:%M"):
            try:
                dt = datetime.datetime.strptime(pub[:len(pub)], fmt)
                # no zone given: these Indian feeds write Indian time
                dt = dt.replace(tzinfo=datetime.timezone(
                    datetime.timedelta(hours=5, minutes=30)))
                break
            except Exception:
                continue
    if dt is None:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    now = datetime.datetime.now(datetime.timezone.utc)
    return max(0.0, (now - dt).total_seconds() / 3600.0)


# ---------------------------------------------------------------------------
# FEEDS AND DATES
#
# 19.17 dropped every story without a date, so nothing old could slip in.
# He pointed out that this can lose important news - plenty of articles
# carry no date in the feed. So an undated story is now looked into, one by
# one, and kept unless it is shown to be old:
#   1. the feed's other date fields (dc:date, Atom updated/published),
#   2. a date in the article's own address (/2026/10/09/),
#   3. the article page's published date (the meta tags and the structured
#      data every news site writes for Google),
#   4. dates written in the story itself - a recent one dates it; one in
#      the future, or a later year ("the 2027 election"), means it is about
#      something still to come, so it stays, marked UPCOMING,
#   5. nothing at all: if the paper's feed is current (its dated stories
#      are from today), the story is in today's edition - kept and marked.
# Only a story whose page or text proves it is older than the limit is
# left out. Each article is looked at once and the answer remembered.
# ---------------------------------------------------------------------------

DC_DATE = "{http://purl.org/dc/elements/1.1/}date"
ATOM = "{http://www.w3.org/2005/Atom}"


def _feed_text(v):
    v = (v or "").strip()
    v = re.sub(r"^<!\[CDATA\[|\]\]>$", "", v).strip()
    return html_lib.unescape(v).strip()


def feed_items(raw):
    """[{title, link, pub, desc}] from RSS or Atom. A feed with one broken
    character (Financial Express sends one) used to be lost entirely; it is
    now read with a forgiving fallback instead."""
    if raw[:2] == b"\x1f\x8b":
        raw = gzip.GzipFile(fileobj=io.BytesIO(raw)).read()
    out = []
    try:
        root = ET.fromstring(raw)
        for it in root.iter("item"):
            pub = ""
            for tag in ("pubDate", DC_DATE, ATOM + "updated",
                        ATOM + "published", "published", "updated", "date"):
                pub = (it.findtext(tag) or "").strip()
                if pub:
                    break
            out.append({"title": _feed_text(it.findtext("title")),
                        "link": _feed_text(it.findtext("link")),
                        "pub": pub,
                        "desc": _feed_text(it.findtext("description"))[:800]})
        for it in root.iter(ATOM + "entry"):
            ln = it.find(ATOM + "link")
            out.append({"title": _feed_text(it.findtext(ATOM + "title")),
                        "link": (ln.get("href") if ln is not None else ""),
                        "pub": (it.findtext(ATOM + "published") or
                                it.findtext(ATOM + "updated") or "").strip(),
                        "desc": _feed_text(it.findtext(ATOM + "summary"))[:800]})
        return out
    except ET.ParseError:
        pass
    txt = raw.decode("utf-8", "replace")
    for blk in re.findall(r"<item\b.*?</item>", txt, re.S | re.I):
        def tag(*names):
            for n in names:
                m = re.search(r"<%s\b[^>]*>(.*?)</%s>" % (n, n), blk,
                              re.S | re.I)
                if m and m.group(1).strip():
                    return _feed_text(m.group(1))
            return ""
        out.append({"title": tag("title"), "link": tag("link", "guid"),
                    "pub": tag("pubDate", "dc:date", "published", "updated"),
                    "desc": tag("description")[:800]})
    return out


def read_feed(url, timeout=10):
    raw = urllib.request.urlopen(
        urllib.request.Request(url, headers={"User-Agent": UA}),
        timeout=timeout).read()
    return feed_items(raw)


MONTHS = {"jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
          "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12}
# Bengali and Hindi papers write the same months in their own script
INDIC_MONTHS = {
    "জানুয়ারি": "Jan", "ফেব্রুয়ারি": "Feb", "মার্চ": "Mar", "এপ্রিল": "Apr",
    "মে": "May", "জুন": "Jun", "জুলাই": "Jul", "আগস্ট": "Aug",
    "সেপ্টেম্বর": "Sep", "অক্টোবর": "Oct", "নভেম্বর": "Nov",
    "ডিসেম্বর": "Dec",
    "जनवरी": "Jan", "फ़रवरी": "Feb", "फरवरी": "Feb", "मार्च": "Mar",
    "अप्रैल": "Apr", "मई": "May", "जून": "Jun", "जुलाई": "Jul",
    "अगस्त": "Aug", "सितंबर": "Sep", "सितम्बर": "Sep", "अक्टूबर": "Oct",
    "नवंबर": "Nov", "नवम्बर": "Nov", "दिसंबर": "Dec", "दिसम्बर": "Dec"}
INDIC_DIGITS = str.maketrans("০১২৩৪৫৬৭৮৯०१२३४५६७८९", "01234567890123456789")
_MON_RX = r"(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?"


def dates_in_text(text):
    """Every full calendar date written out in a piece of text."""
    t = (text or "").translate(INDIC_DIGITS)
    for k, v in INDIC_MONTHS.items():
        # only as a word on its own - "মে" (May) is also inside other words
        t = re.sub(r"(?<![^\s\d,.])" + re.escape(k) + r"(?![^\s\d,.])",
                   " " + v + " ", t)
    t = t.lower()
    out = []

    def add(y, m, d):
        try:
            out.append(datetime.date(int(y), int(m), int(d)))
        except Exception:
            pass
    for d, m, y in re.findall(r"\b(\d{1,2})(?:st|nd|rd|th)?\s+" + _MON_RX +
                              r",?\s+(20\d\d)\b", t):
        add(y, MONTHS[m], d)
    for m, d, y in re.findall(r"\b" + _MON_RX + r"\s+(\d{1,2})(?:st|nd|rd|th)?,?"
                              r"\s+(20\d\d)\b", t):
        add(y, MONTHS[m], d)
    for y, m, d in re.findall(r"\b(20\d\d)-(\d\d)-(\d\d)\b", t):
        add(y, m, d)
    return out


def future_years(text):
    """Years written as something still to come - "in 2027", "by 2028",
    "the 2027 election" - but not "2040 MW" or "Rs 2045 crore"."""
    t = (text or "").translate(INDIC_DIGITS)
    out = re.findall(
        r"\b(?:in|by|till|until|before|from|for|during|ahead of)\s+"
        r"(?:the\s+|early\s+|mid[- ]|late\s+|fy\s*)?(20\d\d)\b"
        r"(?!\s*(?:mw|gw|kw|crore|cr\b|lakh|units|tonnes|km|%|rs))", t, re.I)
    out += re.findall(
        r"\b(20\d\d)\s+(?:assembly\s+|lok sabha\s+|general\s+|state\s+)?"
        r"(?:election|elections|polls|budget|world cup|olympics|census"
        r"|deadline)\b", t, re.I)
    return out


def date_from_link(link):
    """/2026/10/09/, /2026-10-09-, -20261009 in the article's address."""
    m = (re.search(r"[/-](20\d\d)[/-](\d{1,2})[/-](\d{1,2})(?=[/?.#_-]|$)",
                   link)
         or re.search(r"(?<!\d)(20\d\d)(\d\d)(\d\d)(?!\d)", link))
    if not m:
        return None
    try:
        d = datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except Exception:
        return None
    return d if d <= datetime.date.today() else None


PAGE_DATE_RES = [
    r'<meta[^>]+(?:property|name|itemprop)=["\'](?:article:published_time|'
    r'og:article:published_time|publish-date|pubdate|publishdate|'
    r'datePublished|date|dc\.date|dc\.date\.issued|sailthru\.date|'
    r'parsely-pub-date|article\.published|publish_date)["\'][^>]*?'
    r'content=["\']([^"\']+)',
    r'<meta[^>]+content=["\']([^"\']+)["\'][^>]*(?:property|name|itemprop)='
    r'["\'](?:article:published_time|datePublished|pubdate|publish-date)["\']',
    r'"datePublished"\s*:\s*"([^"]+)"',
    r'<time[^>]+datetime=["\']([^"\']+)',
    r'"dateModified"\s*:\s*"([^"]+)"',
    r'<meta[^>]+(?:property|name)=["\'](?:article:modified_time|'
    r'og:updated_time)["\'][^>]*content=["\']([^"\']+)',
]
UNDATED = {}            # link -> verdict, so each article is read once


def article_date(link, title=""):
    """What can be found out about an undated story's date. Returns
    {"how": "link"|"page"|"text"|"upcoming"|"old"|"none", "pub", "note"}."""
    if link in UNDATED:
        return UNDATED[link]
    today = datetime.date.today()
    res = {"how": "none", "pub": "", "note": ""}
    d = date_from_link(link)
    if d:
        res = {"how": "link", "pub": d.isoformat(), "note": ""}
    else:
        html = ""
        try:
            html = urllib.request.urlopen(
                urllib.request.Request(link, headers={"User-Agent": UA}),
                timeout=8).read(500000)
            if html[:2] == b"\x1f\x8b":
                html = gzip.GzipFile(fileobj=io.BytesIO(html)).read()
            html = html.decode("utf-8", "replace")
        except Exception:
            html = ""
        for rx in PAGE_DATE_RES:
            m = re.search(rx, html, re.I)
            if m and age_hours(m.group(1)) is not None:
                res = {"how": "page", "pub": m.group(1).strip(), "note": ""}
                break
        if res["how"] == "none":
            body = html
            m = re.search(r"<article[^>]*>(.*?)</article>", html, re.S | re.I)
            if m:
                body = m.group(1)
            paras = re.findall(r"<p[^>]*>(.*?)</p>", body, re.S | re.I)
            text = (title or "") + " " + " ".join(
                re.sub(r"<[^>]+>", " ", x) for x in paras[:25])
            ds = dates_in_text(text)
            past = [x for x in ds if x <= today]
            fresh = [x for x in past
                     if (today - x).days <= NEWS_MAX_AGE_HOURS / 24]
            future = sorted(x for x in ds if x > today)
            years = sorted({int(y) for y in future_years(text)
                            if today.year < int(y) <= today.year + 3})
            if fresh:
                res = {"how": "text", "pub": max(fresh).isoformat(),
                       "note": ""}
            elif past:
                # its newest written date is older than the limit: an old
                # story, whatever later year it also mentions
                res = {"how": "old", "pub": "", "note": ""}
            elif future or years:
                when = (future[0].strftime("%d %b %Y").upper() if future
                        else str(years[0]))
                res = {"how": "upcoming", "pub": "",
                       "note": "UPCOMING · " + when}
    UNDATED[link] = res
    if len(UNDATED) > 4000:
        UNDATED.pop(next(iter(UNDATED)))
    return res


def undated_verdict(link, title, feed_current, budget):
    """Decide one undated story. Returns (keep, pub, note). `budget` is a
    one-item list counting how many article pages may still be opened in
    this pass, so a feed full of undated items cannot stall the refresh -
    the rest are decided on the next pass (and kept meanwhile if the feed
    is current)."""
    if link not in UNDATED and budget[0] <= 0:
        return (feed_current, "", "UNDATED · IN TODAY'S EDITION")
    if link not in UNDATED:
        budget[0] -= 1
    r = article_date(link, title)
    if r["how"] in ("link", "page", "text"):
        return (True, r["pub"], "")
    if r["how"] == "upcoming":
        return (True, "", r["note"])
    if r["how"] == "old":
        return (False, "", "")
    return (feed_current, "", "UNDATED · IN TODAY'S EDITION")


def feed_is_current(items, hours=24):
    """A feed is today's edition if any of its dated stories is from the
    last day - or if it dates none of them (then what it lists now IS its
    latest edition)."""
    ages = [age_hours(x.get("pub")) for x in items]
    ages = [a for a in ages if a is not None]
    return (not ages) or min(ages) <= hours


def dated_items(items, max_age, budget, current=None):
    """The feed's stories that are recent enough, with every undated one
    looked into rather than thrown away. Adds "age", and "dateNote" for
    the ones still without a date."""
    cur = feed_is_current(items) if current is None else current
    out = []
    for x in items:
        if not (x.get("title") and x.get("link")):
            continue
        a = age_hours(x.get("pub"))
        note = ""
        if a is None:
            keep, pub, note = undated_verdict(x["link"], x["title"], cur,
                                              budget)
            if not keep:
                continue
            if pub:
                x["pub"] = pub
                a = age_hours(pub)
                if re.fullmatch(r"\d{4}-\d\d-\d\d", pub):
                    # only the day is known - say so rather than a precise
                    # "1 min ago"
                    try:
                        note = "DATED " + datetime.date.fromisoformat(
                            pub).strftime("%d %b").upper()
                    except Exception:
                        note = ""
        if a is not None and a > max_age:
            continue
        y = dict(x)
        y["age"] = a
        if note:
            y["dateNote"] = note
        out.append(y)
    return out


# Things happening abroad that move Indian shares. He wants the Houthis and
# the Strait of Hormuz because they move crude, and crude moves his oil and
# paint and tyre names - but he does not want general world news. So an item
# has to name something with a route into this market.
INDIA_IMPACT = (
    "crude", "brent", "wti", "oil price", "opec", "hormuz", "houthi", "red sea",
    "tanker", "iran", "israel", "russia oil", "gas price", "lng",
    "federal reserve", "fed rate", "fomc", "us inflation", "treasury yield",
    "dollar index", "rupee", "gold price", "tariff", "trade deal",
    "supply chain", "semiconductor", "chip export", "china stimulus",
    "china exports", "monsoon", "fertiliser", "fertilizer", "palm oil",
    "sugar", "ethanol", "e20", "coal", "steel price", "copper",
    "pharma export", "us fda", "h-1b", "remittance", "sanction",
)


def impact_score(title):
    t = (title or "").lower()
    return sum(1 for w in INDIA_IMPACT if w in t)


def title_key(t):
    """Two papers writing the same story should not both appear."""
    t = re.sub(r"[^a-z0-9 ]", " ", (t or "").lower())
    words = [w for w in t.split() if len(w) > 3][:7]
    return " ".join(sorted(words))


def fetch_news():
    items, err = [], ""
    budget = [25]           # article pages that may be opened this pass
    for source, url in NEWS_FEEDS:
        try:
            # English papers only here; Business Today's main feed also
            # carries its Hindi stories, which do not belong in these boxes
            feed = [x for x in read_feed(url)
                    if not is_indic(x.get("title") or "")]
            for x in dated_items(feed, NEWS_MAX_AGE_HOURS, budget):
                row = {"title": x["title"], "link": x["link"],
                       "source": source, "pub": x["pub"], "age": x["age"]}
                if x.get("dateNote"):
                    row["dateNote"] = x["dateNote"]
                items.append(row)
        except Exception as e:
            err = str(e)
    seen, out = set(), []
    for it in sorted(items, key=lambda x: (x["age"] is None, x["age"] or 0)):
        k = title_key(it["title"])
        if k in seen or it["title"] in seen:
            continue
        seen.add(k)
        seen.add(it["title"])
        out.append(it)
    if out:
        NEWS["items"], NEWS["error"] = out[:300], ""
        portfolio_rate_news(out[:300])     # 20.15: his bank's FD rates
    else:
        NEWS["error"] = err
    NEWS["at"] = time.time()



# ---------------------------------------------------------------------------
# WHY THE MARKET IS MOVING
#
# The dashboard cannot reason about cause. What it can do is take the day's
# headlines, keep the ones naming something that genuinely reaches this
# market, and put them next to Nifty's actual direction. So it reports what
# is in the news rather than claiming to know why - and on a quiet day it
# says there is no dominant theme instead of inventing one.
#
# Deliberately terse: a theme word and a clipped headline, nothing more.
# ---------------------------------------------------------------------------

