# ---------------------------------------------------------------------------
# WHAT WAS EXPECTED, AND WHAT ACTUALLY HAPPENED
#
# When a headline says the market EXPECTS something - a repo rate move, a GDP
# print - it is written down with whatever number it names. When the decision
# itself arrives days later, the expectation is pulled back out and shown
# beside it, so the gap between the two is visible at a glance:
#
#     RBI raises repo rate by 25 bps        expected 50 bps
#
# The pairing is done on topic and is not infallible; where nothing was
# recorded beforehand the outcome simply shows on its own.
# ---------------------------------------------------------------------------

EXPECT_FILE = os.path.join(DATA_DIR, "expectations.json")
EXPECT = {"items": []}

EXPECT_WORDS = ("expect", "expected", "expects", "likely to", "seen at",
                "forecast", "poll", "estimate", "estimates", "anticipate",
                "projected", "may hike", "may cut", "may hold", "set to",
                "ahead of", "preview", "street sees", "economists")

OUTCOME_WORDS = ("announces", "announced", "raises", "hikes", "cuts", "holds",
                 "keeps", "decides", "unchanged", "slashes", "lifts",
                 "rose to", "fell to", "came in at", "grows", "printed at",
                 "delivers", "verdict", "decision")

EXPECT_TOPICS = {
    "repo rate": "REPO RATE", "policy rate": "REPO RATE",
    "rbi": "REPO RATE", "mpc": "REPO RATE", "monetary policy": "REPO RATE",
    "gdp": "GDP", "growth rate": "GDP",
    "inflation": "INFLATION", "cpi": "INFLATION", "wpi": "INFLATION",
    "gst": "GST", "fiscal deficit": "FISCAL DEFICIT",
    "iip": "IIP", "trade deficit": "TRADE DEFICIT",
    "fed": "US FED", "fomc": "US FED",
}


def expect_load():
    global EXPECT
    try:
        with open(EXPECT_FILE) as f:
            EXPECT = json.load(f)
    except Exception:
        EXPECT = {"items": []}
    return EXPECT


def expect_save():
    try:
        tmp = EXPECT_FILE + ".tmp"
        with open(tmp, "w") as f:
            json.dump(EXPECT, f, indent=1)
        os.replace(tmp, EXPECT_FILE)
    except Exception:
        pass


def topic_of(title):
    low = (title or "").lower()
    for word, name in EXPECT_TOPICS.items():
        if re.search(r"(?<![a-z])" + re.escape(word) + r"(?![a-z])", low):
            return name
    return ""


def number_in(title):
    """The figure a headline is talking about - 25 bps, 6.4%, and so on."""
    t = (title or "").lower()
    m = re.search(r"(\d+(?:\.\d+)?)\s*(?:basis points|bps|bp\b)", t)
    if m:
        return m.group(1) + " bps"
    m = re.search(r"(\d+(?:\.\d+)?)\s*(?:per cent|percent|%)", t)
    if m:
        return m.group(1) + "%"
    return ""


def is_expectation(title):
    low = (title or "").lower()
    return any(re.search(r"(?<![a-z])" + re.escape(w) + r"(?![a-z])", low)
               for w in EXPECT_WORDS)


def is_outcome(title):
    low = (title or "").lower()
    return any(re.search(r"(?<![a-z])" + re.escape(w) + r"(?![a-z])", low)
               for w in OUTCOME_WORDS)


def note_expectations(pool):
    """Record what was being expected, and clear out anything stale."""
    changed = False
    have = {x["title"] for x in EXPECT["items"]}
    for it in pool:
        t = it.get("title") or ""
        if t in have or not is_expectation(t):
            continue
        topic = topic_of(t)
        if not topic:
            continue
        EXPECT["items"].append({
            "topic": topic, "number": number_in(t), "title": t,
            "source": it.get("source", ""), "link": it.get("link", ""),
            "at": time.strftime("%Y-%m-%d %H:%M"), "epoch": time.time()})
        changed = True
    cut = time.time() - 45 * 86400
    keep = [x for x in EXPECT["items"] if x.get("epoch", 0) > cut]
    if len(keep) != len(EXPECT["items"]):
        EXPECT["items"] = keep
        changed = True
    if changed:
        EXPECT["items"] = EXPECT["items"][-400:]
        expect_save()


def expectation_for(title):
    """The most recent thing said beforehand about this same subject."""
    topic = topic_of(title)
    if not topic:
        return None
    best = None
    for x in EXPECT["items"]:
        if x["topic"] != topic or not x.get("number"):
            continue
        if x["title"] == title:
            continue
        if best is None or x.get("epoch", 0) > best.get("epoch", 0):
            best = x
    return best



# ---------------------------------------------------------------------------
# BUYING AND SELLING PRESSURE
#
# Not whether the market is up or down - which way it is being pushed right
# now. The index can be 800 points down and still be under heavy buying, and
# that is the day it closes 300 down. The gauge measures the DIRECTION OF
# TRAVEL over the last few minutes, not the level.
#
# It works off the 125 shares already being polled: how far the average has
# moved over the last ten minutes, and how many are rising against falling
# in that window. No extra data is fetched.
#
# It reports pressure as it happens. It does not predict - anyone who says
# they can tell you where the market goes next is selling something.
# ---------------------------------------------------------------------------

PULSE = []                 # (epoch, nifty level) - the market gauge
SHARE_PULSE = {}           # symbol -> [(epoch, ltp), ...]
PULSE_LOCK = threading.Lock()
PULSE_LAST = {"market": None, "shares": {}, "at": "", "frozen": False}
PULSE_FILE = os.path.join(DATA_DIR, "pressure.json")


def pulse_load():
    """Bring back the last readings so the gauge and the column are not blank
    after a restart outside market hours. If the file is not there yet, one is
    written straight away so it always exists."""
    try:
        with open(PULSE_FILE) as f:
            d = json.load(f)
        PULSE_LAST["market"] = d.get("market")
        PULSE_LAST["shares"] = d.get("shares") or {}
        PULSE_LAST["savedAt"] = d.get("savedAt", "")
        PULSE_LAST["auction"] = d.get("auction")
        PULSE_LAST["auctionShares"] = d.get("auctionShares") or {}
    except Exception:
        pass
    if not os.path.exists(PULSE_FILE):
        pulse_save()


def pulse_save():
    try:
        tmp = PULSE_FILE + ".tmp"
        with open(tmp, "w") as f:
            json.dump({"market": PULSE_LAST.get("market"),
                       "shares": PULSE_LAST.get("shares") or {},
                       "auction": PULSE_LAST.get("auction"),
                       "auctionShares": PULSE_LAST.get("auctionShares") or {},
                       "savedAt": time.strftime("%d %b %H:%M")}, f)
        os.replace(tmp, PULSE_FILE)
    except Exception:
        pass


def in_auction_pressure_window(now=None):
    """The auction itself, once it is actually running: 15:20 to 15:32
    (from 7 Dec 2026, 15:31 to 15:42)."""
    now = now or datetime.datetime.now()
    if not is_trading_day(now.date()):
        return False
    t = cas_times(now)
    mins = now.hour * 60 + now.minute
    return t["entry"] <= mins <= t["shut"] + 2


def in_pressure_pause(now=None):
    """Continuous trading has stopped and the auction has not begun (15:15
    to 15:20; from 7 Dec 2026 15:30 to 15:31). Nothing meaningful to
    measure, so nothing is measured."""
    now = now or datetime.datetime.now()
    if not is_trading_day(now.date()):
        return False
    t = cas_times(now)
    mins = now.hour * 60 + now.minute
    return t["ctsEnd"] <= mins < t["entry"]


def watchlist_level():
    """A stand-in index: the average of the watchlist against yesterday's
    closes, so one expensive share cannot dominate."""
    st = load_state()
    vals = []
    with CACHE_LOCK:
        for sym in (st.get("watchlist") or []):
            q = CACHE.get(sym) or {}
            ltp = to_number(q.get("ltpNum") or q.get("ltp"))
            prev = to_number(q.get("close"))
            if ltp and prev:
                vals.append(ltp / prev)
    if len(vals) < 5:
        return None
    return sum(vals) / len(vals) * 1000.0


AUCTION_BASE = {}


def auction_level():
    """Where the auction prices are going, measured against where each one
    STARTED, not against its last traded price.

    The old version divided ICP by LTP. The last traded price moves as well,
    so that ratio could fall while every indicative price was climbing -
    which is exactly what he saw: his chart showed the ICP rising while the
    gauge read heavy selling. Only the ICP's own drift matters here.
    """
    st = load_state()
    syms = active_symbols(st) or (st.get("watchlist") or [])
    vals = []
    with CACHE_LOCK:
        trust = cas_outside([CACHE.get(x) or {} for x in
                             (st.get("watchlist") or [])]) is not None
        for sym in syms:
            q = CACHE.get(sym) or {}
            if trust and q.get("inCas") is False:
                continue        # not in the auction - its "ICP" is an average
            icp = to_number(q.get("icp")) or to_number(q.get("iep"))
            if not icp:
                continue
            base = AUCTION_BASE.get(sym)
            if not base:
                AUCTION_BASE[sym] = icp      # first reading of this auction
                base = icp
            vals.append(icp / base)
    if not vals:
        return None
    return sum(vals) / len(vals) * 1000.0     # a level the drift maths can use


def auction_reset():
    """A fresh auction starts from a clean set of opening prices - for the
    gauge and for every share's own reading, which switch from traded
    prices to indicative ones (mixing the two would read as a jump)."""
    AUCTION_BASE.clear()
    with PULSE_LOCK:
        SHARE_PULSE.clear()


def in_continuous_session(now=None):
    """9:00 to 15:15 (from 7 Dec 2026, 15:30) - pre-open and normal
    trading."""
    now = now or datetime.datetime.now()
    if not is_trading_day(now.date()):
        return False
    mins = now.hour * 60 + now.minute
    return 9 * 60 <= mins < cas_times(now)["ctsEnd"]


def pulse_sample():
    """One reading of Nifty - or, during the auction, of the auction itself -
    and of every share on the list."""
    now_dt = datetime.datetime.now()
    if in_auction_pressure_window(now_dt):
        nif = auction_level()
        PULSE_LAST["source"] = "auction"
    else:
        nif = to_number((TICKER["last"].get("NIFTY 50") or {}).get("last"))
        PULSE_LAST["source"] = "nifty"
        if not nif:
            # no index reading - a failed or slow index fetch. The shares are
            # fetched separately, so stand in with their own average rather
            # than showing nothing at all.
            nif = watchlist_level()
            if nif:
                PULSE_LAST["source"] = "watchlist"
    now = time.time()
    with PULSE_LOCK:
        if nif:
            # switching source resets the series, or the jump between two
            # different scales would read as an enormous move
            if PULSE and PULSE_LAST.get("series") != PULSE_LAST.get("source"):
                PULSE.clear()
            PULSE_LAST["series"] = PULSE_LAST.get("source")
            PULSE.append((now, nif))
            cut = now - 3 * 3600
            while PULSE and PULSE[0][0] < cut:
                PULSE.pop(0)
    st = load_state()
    auction = PULSE_LAST.get("source") == "auction"
    with CACHE_LOCK:
        if auction:
            # In the auction nothing trades, so the last traded price stands
            # still and every share read "balanced". Each share's pressure
            # now follows its own indicative closing price instead.
            snap = {}
            trust = cas_outside([CACHE.get(x) or {} for x in
                                 (st.get("watchlist") or [])]) is not None
            for s in (st.get("watchlist") or []):
                q = CACHE.get(s) or {}
                if trust and q.get("inCas") is False:
                    # not in the auction: it keeps trading until 3:30
                    snap[s] = to_number(q.get("ltpNum") or q.get("ltp"))
                else:
                    snap[s] = (to_number(q.get("icp"))
                               or to_number(q.get("iep")))
        else:
            snap = {s: to_number((CACHE.get(s) or {}).get("ltpNum")
                                 or (CACHE.get(s) or {}).get("ltp"))
                    for s in (st.get("watchlist") or [])}
    with PULSE_LOCK:
        for sym, ltp in snap.items():
            if not ltp:
                continue
            row = SHARE_PULSE.setdefault(sym, [])
            row.append((now, ltp))
            cut = now - 3 * 3600
            while row and row[0][0] < cut:
                row.pop(0)



# ---------------------------------------------------------------------------
# WHEN THE CONNECTION IS REALLY STRUGGLING
#
# Not a grumble about a slow minute. This only speaks up when the dashboard
# is genuinely failing to do its job: NSE refusing most requests, or the
# prices barely arriving minutes after opening. One notice, not a stream.
# ---------------------------------------------------------------------------

def connection_watcher():
    warned_at = 0.0
    started = time.time()
    while STATS["running"]:
        try:
            time.sleep(30)
            if not is_trading_day():
                continue
            fails = recent_fail_count()
            st = load_state()
            want = len(st.get("watchlist") or []) or 1
            with CACHE_LOCK:
                have = sum(1 for x in (st.get("watchlist") or [])
                           if (CACHE.get(x) or {}).get("ltpNum"))
            up = time.time() - started
            bad = ""
            if fails >= 30:
                bad = ("NSE is refusing most requests \u2014 %d failures in "
                       "the last few minutes" % fails)
            elif up > 240 and have < want * 0.4:
                bad = ("Prices are barely arriving \u2014 only %d of %d after "
                       "%d minutes. The connection may be the problem."
                       % (have, want, int(up / 60)))
            elif up > 600 and have < want * 0.75:
                bad = ("Still only %d of %d prices after %d minutes."
                       % (have, want, int(up / 60)))
            if bad and time.time() - warned_at > 900:
                warned_at = time.time()
                push_event("warn", bad, gap=900)
        except Exception:
            pass


def pulse_watcher():
    while STATS["running"]:
        try:
            # samples only while the market is open; the last reading is kept
            # afterwards so the gauge and the column never go blank
            auction = in_auction_pressure_window()
            if auction and PULSE_LAST.get("source") != "auction":
                auction_reset()          # new auction, fresh starting prices
            if in_pressure_pause():
                PULSE_LAST["frozen"] = False      # holding, not finished
            elif in_continuous_session() or auction:
                pulse_sample()
                PULSE_LAST["frozen"] = False
            else:
                # after 15:32 the auction's closing picture is held. Before,
                # sampling ran on until 16:00 and a flat, closed Nifty
                # replaced it with "Balanced" for half an hour.
                PULSE_LAST["frozen"] = True
            market_pulse()              # refresh the held readings
            if PULSE_LAST.get("market") or PULSE_LAST.get("shares"):
                pulse_save()            # keep them for the next start
        except Exception:
            pass
        # ten seconds through the auction, where a minute is a long time
        time.sleep(10 if in_auction_pressure_window() else 45)


def _drift(rows, minutes, min_minutes=2):
    """How far a series has moved, as a percentage, over N minutes - or over
    whatever span exists, provided it is at least a couple of minutes."""
    if len(rows) < 2:
        return None
    now_t, now_v = rows[-1]
    target = now_t - minutes * 60
    old = None
    for r in rows:
        if r[0] <= target:
            old = r
        else:
            break
    if old is None:
        span = now_t - rows[0][0]
        if span < min_minutes * 60:
            return None
        old = rows[0]
    if not old[1]:
        return None
    return (now_v - old[1]) / old[1] * 100.0


def _needle(pct, full):
    """Turn a percentage move into a needle between -100 and +100."""
    if pct is None:
        return None
    return round(max(-100.0, min(100.0, (pct / full) * 100.0)), 1)


def pressure_label(v):
    if v is None:
        return ""
    return ("Heavy buying" if v >= 55 else "Buying" if v >= 20 else
            "Heavy selling" if v <= -55 else "Selling" if v <= -20 else
            "Balanced")



# ---------------------------------------------------------------------------
# HOW LONG STARTUP ACTUALLY TAKES
#
# The old estimate guessed from how fast prices were arriving and ignored the
# news, which is the slowest part - so it read 25% and "2 min left" while the
# real wait was longer. This times each stage on every start and keeps the
# last few runs, so the estimate is built from what this machine actually
# does rather than from a guess.
# ---------------------------------------------------------------------------

LOAD_FILE = os.path.join(DATA_DIR, "loadstats.json")
LOAD = {"started": time.time(), "done": {}, "past": {}}
LOAD_STAGES = ("prices", "news", "global", "local", "recos")
# The Kolkata news is the last thing to finish - every item is checked and
# some are translated - so by the time it is in, everything else already is.
# The estimate follows that one stage rather than juggling five.
LOAD_ANCHOR = "local"
LOAD_DEFAULT = {"prices": 95.0, "news": 45.0, "global": 60.0,
                "local": 150.0, "recos": 70.0}


def market_phase(now=None):
    """What the market is doing right this minute."""
    now = now or datetime.datetime.now()
    if not is_trading_day(now.date()):
        return "closed"
    m = now.hour * 60 + now.minute
    t = cas_times(now)
    if m < 9 * 60:
        return "closed"
    if m < 9 * 60 + 15:
        return "preopen"
    if m < t["ctsEnd"] or (not t["new"] and m == t["ctsEnd"]):
        return "open"
    if m < t["entry"]:
        return "preauction"      # continuous trading over, auction not begun
    if m <= t["shut"]:
        return "auction"
    return "closed"


def in_market_hours(now=None):
    """Indian continuous trading, 09:15 to 15:30 on a trading day."""
    now = now or datetime.datetime.now()
    if not is_trading_day(now.date()):
        return False
    mins = now.hour * 60 + now.minute
    return (9 * 60 + 15) <= mins <= (15 * 60 + 30)


def load_stats_read():
    try:
        with open(LOAD_FILE) as f:
            LOAD["past"] = json.load(f)
    except Exception:
        LOAD["past"] = {}


def load_anchor_timeout():
    """Deliberately does nothing now. It used to mark the Kolkata news as
    finished after six minutes even when nothing had arrived, so the bar
    said everything was ready while the strip was still empty. It waits."""
    return


def load_stats_note(stage):
    """Record how long a stage took, keeping the last five runs."""
    if stage in LOAD["done"]:
        return
    took = round(time.time() - LOAD["started"], 1)
    LOAD["done"][stage] = took
    hist = LOAD["past"].setdefault(stage, [])
    hist.append(took)
    del hist[:-9]
    try:
        tmp = LOAD_FILE + ".tmp"
        with open(tmp, "w") as f:
            json.dump(LOAD["past"], f)
        os.replace(tmp, LOAD_FILE)
    except Exception:
        pass


def load_expect(stage):
    """How long this stage usually takes on this machine. Implausibly quick
    entries are thrown away - they came from the bug where a failed pass was
    counted as a finished one."""
    hist = sorted(x for x in ((LOAD["past"] or {}).get(stage) or [])
                  if 30 <= x <= 1800)
    if hist:
        return hist[len(hist) // 2]     # the middle run, not the average
    return LOAD_DEFAULT.get(stage, 60.0)


def load_progress():
    """What has actually finished, and what is still running.

    Every attempt at a countdown has been wrong, because how long the Kolkata
    news takes varies enormously and nothing predicts it. So this reports
    fact instead of forecast: which stages are done, which are still going,
    and how long it has been. Where there is a settled history it mentions
    what it usually takes - as a note, not a promise.
    """
    st = load_state()
    total = len(st.get("watchlist") or []) or 1
    with CACHE_LOCK:
        priced = sum(1 for x in (st.get("watchlist") or [])
                     if (CACHE.get(x) or {}).get("ltpNum"))
        # a share NSE does not answer for (renamed, suspended, a typing
        # slip) must not hold the whole page up: after three minutes it is
        # named on the loading line and counted as done
        stuck = [x for x in (st.get("watchlist") or [])
                 if not (CACHE.get(x) or {}).get("ltpNum")
                 and time.time() - LOAD["started"] > 180
                 and ((CACHE.get(x) or {}).get("error") or
                      time.time() - LOAD["started"] > 600)]
    priced = min(total, priced + len(stuck))

    if priced >= total:
        load_stats_note("prices")
    if NEWS.get("at") and NEWS.get("items"):
        load_stats_note("news")
    if NEWS.get("global"):
        load_stats_note("global")
    if NEWS.get("local"):
        load_stats_note("local")
    if RECO.get("at"):
        load_stats_note("recos")

    load_anchor_timeout()
    elapsed = time.time() - LOAD["started"]
    done = all(k in LOAD["done"] for k in LOAD_STAGES)

    # the bar is how much has genuinely finished; prices count part-way
    # because they arrive steadily and you can watch them do it
    weight = {"prices": 30, "news": 15, "global": 15, "local": 30, "recos": 10}
    got = 0.0
    for k in LOAD_STAGES:
        if k in LOAD["done"]:
            got += weight[k]
        elif k == "prices":
            got += weight[k] * min(1.0, priced / total)

    waiting = [k for k in LOAD_STAGES if k not in LOAD["done"]]
    # beta and valuation are part of the page too, so they are on the bar
    bdone, btotal = beta_status(st.get("watchlist") or [])
    with CACHE_LOCK:
        vdone = sum(1 for x in (st.get("watchlist") or [])
                    if (CACHE.get(x) or {}).get("valChecked") or x in stuck)
    hist = sorted(x for x in ((LOAD["past"] or {}).get(LOAD_ANCHOR) or [])
                  if 30 <= x <= 1800)
    usual = int(hist[len(hist) // 2]) if len(hist) >= 3 else 0
    return {"pct": 100 if done else int(round(min(100, got))),
            "done": done, "elapsed": int(elapsed),
            "priced": priced, "total": total,
            "waiting": waiting,
            "doneCount": len(LOAD_STAGES) - len(waiting),
            "stageCount": len(LOAD_STAGES),
            "usual": usual,
            "betaDone": bdone, "betaTotal": btotal,
            "valDone": vdone, "valTotal": total, "stuck": stuck[:6],
            "stages": {k: (k in LOAD["done"]) for k in LOAD_STAGES}}


GEMINI_FILE = os.path.join(DATA_DIR, "gemini.json")
GEMINI = {"key": "", "model": "gemini-flash-lite-latest"}
GEMINI_SHIPPED = ""


def gemini_load():
    GEMINI["key"] = GEMINI_SHIPPED      # replaced by the saved file if present
    try:
        with open(GEMINI_FILE) as f:
            d = json.load(f)
        GEMINI["key"] = (d.get("key") or GEMINI_SHIPPED).strip()
        GEMINI["model"] = d.get("model") or "gemini-flash-lite-latest"
    except Exception:
        pass


GEMINI_SAVE_LOCK = threading.Lock()


def gemini_save(key=None, model=None):
    if key is not None:
        GEMINI["key"] = key.strip()
    if model:
        GEMINI["model"] = model
    try:
        with GEMINI_SAVE_LOCK:            # several readers may switch at once
            tmp = GEMINI_FILE + ".tmp"
            with open(tmp, "w") as f:
                json.dump({"key": GEMINI["key"], "model": GEMINI["model"]}, f)
            os.replace(tmp, GEMINI_FILE)
    except Exception:
        pass
    return {"ok": True, "hasKey": bool(GEMINI["key"]),
            "model": GEMINI["model"]}


# ---------------------------------------------------------------------------
# THE GEMINI LOG (20.14): everything a person asks Gemini for - the
# assistant, Ask, the AI view and its replies - one line each in
# Data/gemini_log.csv (that profile's own). On the administrator's computer
# it is also written to "Gemini log.csv" in the folder above Backend (the
# Capital Compass Backend folder), and a copy that uses his key (the one shipped) sends its
# lines to him there through a quiet ntfy channel - each user was told so
# when the profile was made (and can use a key of his own instead).
# ---------------------------------------------------------------------------
GEMINI_LOG_LOCK = threading.Lock()
GEMINI_RELAY = {"queue": [], "seen": set(), "polled": 0}


def gemini_relay_topic():
    t = admin_read().get("topic") or ""
    return (t + "-gemini") if t else ""


def _log_csv(path, row):
    new = not os.path.exists(path)
    try:
        if not new and os.path.getsize(path) > 3 * 1024 * 1024:
            os.replace(path, path + ".old")
            new = True
        with open(path, "a", newline="", encoding="utf-8") as f:
            w = csv.writer(f)
            if new:
                w.writerow(["When", "Who", "What", "Asked", "Answer"])
            w.writerow(row)
    except OSError:
        pass


def gemini_log(what, asked, answer):
    try:
        who = profile_read().get("name") or ""
    except Exception:
        who = ""
    row = [time.strftime("%Y-%m-%d %H:%M:%S"), who, str(what)[:40],
           re.sub(r"\s+", " ", str(asked or ""))[:400],
           re.sub(r"\s+", " ", str(answer or ""))[:400]]
    with GEMINI_LOG_LOCK:
        _log_csv(os.path.join(os.path.dirname(PATHS["state"]),
                              "gemini_log.csv"), row)
        try:
            admin = is_admin_copy()
        except Exception:
            admin = False
        if admin:
            _log_csv(os.path.join(os.path.dirname(HERE), "Gemini log.csv"),
                     row)
        elif GEMINI.get("key") == GEMINI_SHIPPED and gemini_relay_topic():
            GEMINI_RELAY["queue"].append(row)
            del GEMINI_RELAY["queue"][:-200]


def gemini_relay_loop():
    time.sleep(90)
    while STATS["running"]:
        gemini_relay()
        time.sleep(600)


def gemini_relay():
    """Every ten minutes: a friend's copy sends its queued lines; the
    administrator's copy collects them into his log."""
    try:
        topic = gemini_relay_topic()
        if not topic:
            return
        if is_admin_copy():
            url = NTFY + topic + "/json?poll=1&since=" + (
                "%d" % int(GEMINI_RELAY["polled"]) if GEMINI_RELAY["polled"]
                else "24h")
            with urllib.request.urlopen(url, timeout=20) as r:
                lines = r.read().decode("utf-8", "replace").splitlines()
            GEMINI_RELAY["polled"] = int(time.time()) - 60
            for raw in lines:
                try:
                    m = json.loads(raw)
                except Exception:
                    continue
                if m.get("event") != "message" or m.get("id") in \
                        GEMINI_RELAY["seen"]:
                    continue
                GEMINI_RELAY["seen"].add(m.get("id"))
                msg = str(m.get("message") or "")
                if not msg.startswith("#casgem|"):
                    continue
                try:
                    rows = json.loads(unb64u(msg.split("|", 1)[1]))
                except Exception:
                    continue
                with GEMINI_LOG_LOCK:
                    for row in rows[:200]:
                        if isinstance(row, list) and len(row) == 5:
                            _log_csv(os.path.join(os.path.dirname(HERE),
                                                  "Gemini log.csv"),
                                     [str(x)[:400] for x in row])
        elif GEMINI_RELAY["queue"]:
            rows, GEMINI_RELAY["queue"] = GEMINI_RELAY["queue"][:60], \
                GEMINI_RELAY["queue"][60:]
            body = "#casgem|" + base64.urlsafe_b64encode(json.dumps(
                rows).encode("utf-8")).decode("ascii").rstrip("=")
            req = urllib.request.Request(NTFY + topic, data=body.encode(),
                                         method="POST",
                                         headers={"Title": "log",
                                                  "Priority": "1"})
            urllib.request.urlopen(req, timeout=20).read()
    except Exception:
        pass


ASK_STYLE = ("You are helping someone read Indian financial news quickly. "
             "Answer in at most three short sentences, plain English, no "
             "preamble and no bullet points. If it is a place, say where it "
             "is. If it is a term, define it simply. If you are unsure, say "
             "so in one line.\n\nQuestion: ")


# 20.17: tested on his key on 6 Nov 2026 - the 2.5 models answer 404 ("no
# longer available"), which is the "Gemini error 404" he saw on every
# fallback. Lite models first: they answer fastest and have the most free
# use. Models Google adds later are found by themselves (gem_discover), and
# a model that answers 404 is set aside for a day (GEM_DEAD).
GEMINI_MODELS = ["gemini-flash-lite-latest", "gemini-3.5-flash-lite",
                 "gemini-3.1-flash-lite", "gemini-3.5-flash",
                 "gemini-flash-latest"]
GEM_DEAD = {}       # model -> until when it is not tried (404: gone)
GEM_BUSY = {}       # model -> until when it is tried last (503, too slow)
GEM_FOUND = {"at": 0, "models": []}
GEM_LAST = {"src": "gemini"}


def gem_discover():
    """Once a day: the text models Google offers now (flash and flash-lite,
    no voice/image/preview ones), so a renamed model never stops it."""
    if time.time() - GEM_FOUND["at"] < 86400 or not GEMINI["key"]:
        return
    GEM_FOUND["at"] = time.time()
    try:
        req = urllib.request.Request(
            "https://generativelanguage.googleapis.com/v1beta/models"
            "?pageSize=200", headers={"X-goog-api-key": GEMINI["key"]})
        d = json.loads(urllib.request.urlopen(req, timeout=8).read()
                       .decode("utf-8", "replace"))
    except Exception:
        return
    names = []
    for m in d.get("models") or []:
        n = str(m.get("name") or "").replace("models/", "")
        if "generateContent" not in (m.get("supportedGenerationMethods")
                                     or []):
            continue
        if re.fullmatch(r"gemini-\d+(\.\d+)?-flash(-lite)?", n):
            names.append(n)

    def rank(n):
        v = re.match(r"gemini-(\d+(?:\.\d+)?)", n)
        return (0 if n.endswith("-lite") else 1, -float(v.group(1)))
    GEM_FOUND["models"] = sorted(names, key=rank)[:6]


def gem_order():
    """The models to try, in order: his saved one, the tested list, then
    the ones found today. Busy ones go last, gone ones not at all."""
    gem_discover()
    now, seen = time.time(), []
    for m in [GEMINI["model"]] + GEMINI_MODELS + GEM_FOUND["models"]:
        if m and m not in seen and GEM_DEAD.get(m, 0) < now:
            seen.append(m)
    ok = [m for m in seen if GEM_BUSY.get(m, 0) < now]
    return ok + [m for m in seen if m not in ok]


def gem_mark(model, why):
    why = str(why or "")
    if "404" in why:
        GEM_DEAD[model] = time.time() + 86400
    elif "503" in why or "overloaded" in why or "timed out" in why:
        GEM_BUSY[model] = time.time() + 120


# ---------------------------------------------------------------------------
# THE BACKUP AI (20.17) - Ollama, free, running on this Mac. Used only when
# every Gemini model has failed. Nothing goes to the internet. Once he has
# installed the Ollama app, the dashboard fetches a small model by itself.
# ---------------------------------------------------------------------------
OLLAMA = {"url": "http://127.0.0.1:11434", "model": "", "at": 0, "up": False,
          "pulling": False, "error": ""}
OLLAMA_DEFAULT = "gemma3:4b"
OLLAMA_LIKE = ("gemma", "qwen", "llama", "mistral", "phi")


def _ollama_pull():
    OLLAMA["pulling"] = True
    try:
        req = urllib.request.Request(
            OLLAMA["url"] + "/api/pull", method="POST",
            data=json.dumps({"model": OLLAMA_DEFAULT,
                             "stream": False}).encode(),
            headers={"Content-Type": "application/json"})
        urllib.request.urlopen(req, timeout=3600).read()
        OLLAMA["error"] = ""
    except Exception as e:
        OLLAMA["error"] = "fetching %s: %s" % (OLLAMA_DEFAULT, str(e)[:80])
    finally:
        OLLAMA["pulling"] = False
        OLLAMA["at"] = 0


def ollama_model():
    """The backup model ready on this Mac, or "" (checked once a minute)."""
    if time.time() - OLLAMA["at"] < 60:
        return OLLAMA["model"] if OLLAMA["up"] else ""
    OLLAMA["at"] = time.time()
    try:
        d = json.loads(urllib.request.urlopen(
            OLLAMA["url"] + "/api/tags", timeout=2).read().decode())
        OLLAMA["up"] = True
    except Exception:
        OLLAMA["up"], OLLAMA["model"] = False, ""
        return ""
    names = [str(m.get("name") or "") for m in d.get("models") or []]
    pick = next((n for k in OLLAMA_LIKE for n in names
                 if n.lower().startswith(k)), names[0] if names else "")
    OLLAMA["model"] = pick
    if not pick and not OLLAMA["pulling"]:
        threading.Thread(target=_ollama_pull, daemon=True).start()
    return pick


def ask_ollama(prompt, timeout=120):
    m = ollama_model()
    if not m:
        return None, ("backup AI: fetching its model" if OLLAMA["pulling"]
                      else "backup AI not installed")
    try:
        req = urllib.request.Request(
            OLLAMA["url"] + "/api/generate", method="POST",
            data=json.dumps({"model": m, "prompt": prompt, "stream": False,
                             "options": {"temperature": 0.2}}).encode(),
            headers={"Content-Type": "application/json"})
        d = json.loads(urllib.request.urlopen(req, timeout=timeout).read()
                       .decode("utf-8", "replace"))
        text = re.sub(r"(?s)<think>.*?</think>", "",
                      str(d.get("response") or "")).strip()
        return (text or None), ("" if text else "backup AI: empty answer")
    except Exception as e:
        return None, "backup AI: %s" % str(e)[:60]


def ollama_status():
    m = ollama_model()
    return {"installed": OLLAMA["up"], "model": m,
            "pulling": OLLAMA["pulling"], "error": OLLAMA["error"],
            "want": OLLAMA_DEFAULT}


# 20.15: every question to Gemini goes into the Gemini log - including
# what the dashboard asks by itself (the AI view for each chart, the
# recommendations, the reasons for index moves, result previews, rule
# changes, broker calls in the news). The few that log with their own words
# are left to do so.
GEM_LABELS = {"tm_scenario": "Time Machine (your question into conditions)",
              "tax_classify": "Taxes (where an entry goes)",
              "tax_ask": "Taxes (your question)",
              "style_plan": "Setting the dashboard to his trading style",
              "rules_explain": "Rule change explained",
              "_gemini_translate": "Translation (Google Translate was busy)",
              "voice_transcribe": "Voice (writing out a recording)",
              "voice_command": "Voice command", "result_preview":
              "Result preview (automatic)", "index_reason":
              "Why an index moved (automatic)", "_call_parse":
              "Broker calls in the news (automatic)",
              "_pick_markets": "Ideas in your other markets (automatic)",
              "_pick_outside":
              "Opportunities (automatic)", "_pick_fno": "F&O ideas (automatic)",
              "picks_run": "Recommendations (automatic)", "_rule_screen":
              "Rule-change check (automatic)", "_rule_match":
              "Rule-change check (automatic)", "accounts_ai_summary":
              "Accounts summary"}
GEM_SELF_LOGGED = {"assistant_answer", "chart_opinion", "ask"}


def _gem_logged(fn):
    def wrap(*a, **k):
        text, why = fn(*a, **k)
        try:
            caller = sys._getframe(1).f_code.co_name
            if caller not in GEM_SELF_LOGGED:
                q = a[0] if a else ""
                if isinstance(q, list):
                    q = " ".join(str(x.get("text") or "[recording]")
                                 for x in q if isinstance(x, dict))
                gemini_log(GEM_LABELS.get(caller, caller.strip("_")
                                          .replace("_", " ")),
                           str(q)[-400:], text or ("failed: %s" % why))
        except Exception:
            pass
        return text, why
    return wrap


def ask_gemini(q, style=None, timeout=12):
    """A 503 from Google means that model is overloaded, NOT that the key is
    bad - his key authenticated fine. So work down the list of models and
    give each one a second try before moving on."""
    tried = []
    if GEMINI["key"]:
        for n, model in enumerate(gem_order()[:5]):
            # 20.17: a slow model costs at most 15 s after the first
            text, why = _gemini_once(q, model, style,
                                     timeout if n == 0 else min(timeout, 15))
            if text:
                GEM_LAST["src"] = "gemini"
                if model != GEMINI["model"]:
                    GEMINI["model"] = model          # remember what worked
                    gemini_save()
                return text, ""
            gem_mark(model, why)
            tried.append("%s: %s" % (model, why))
            if "key refused" in why or "no key" in why:
                break
    else:
        tried.append("no Gemini key")
    # 20.17: every Gemini model failed - the backup AI on this Mac
    text, why = ask_ollama((style or ASK_STYLE) + q)
    if text:
        GEM_LAST["src"] = "ollama"
        return text, ""
    tried.append(why)
    return None, " | ".join(tried)


ask_gemini = _gem_logged(ask_gemini)


def _gemini_once(q, model, style=None, timeout=12):
    url = ("https://generativelanguage.googleapis.com/v1beta/models/%s"
           ":generateContent" % model)
    body = json.dumps({"contents": [{"parts": [{"text": (style or ASK_STYLE)
                                                + q}]}]})
    req = urllib.request.Request(
        url, data=body.encode("utf-8"), method="POST",
        headers={"Content-Type": "application/json",
                 "X-goog-api-key": GEMINI["key"]})
    try:
        raw = urllib.request.urlopen(req, timeout=timeout).read()
        d = json.loads(raw.decode("utf-8", "replace"))
        cands = d.get("candidates") or []
        if not cands:
            return None, "no answer"
        parts = ((cands[0].get("content") or {}).get("parts") or [])
        text = " ".join(p.get("text", "") for p in parts).strip()
        return (text or None), ("" if text else "empty answer")
    except urllib.error.HTTPError as e:
        try:
            msg = json.loads(e.read().decode("utf-8", "replace"))
            msg = (msg.get("error") or {}).get("message", "")[:120]
        except Exception:
            msg = ""
        if e.code == 429:
            return None, "quota used up for now"
        if e.code in (400, 401, 403):
            return None, "key refused" + (" - " + msg if msg else "")
        if e.code in (500, 503):
            return None, "overloaded (503)"
        return None, "Gemini error %s" % e.code
    except Exception as e:
        return None, str(e)[:80]


# ---------------------------------------------------------------------------
# VOICE COMMANDS (20.12) - what was said (or the sound itself, when the
# browser cannot listen) is turned into the dashboard's few actions by
# Gemini with the Ask key. Nothing is done here: the page does it, after
# checking each action.
# ---------------------------------------------------------------------------
VOICE_STYLE = (
    "You turn one spoken command for an Indian share-trading dashboard into "
    "JSON. The only things it can do:\n"
    ' {"do":"set","sym":SYMBOL,"col":COLUMN_KEY,"value":"text"} - write in '
    'the table (value "" clears the cell; numbers without commas)\n'
    ' {"do":"open","box":BOX_KEY} and {"do":"close","box":BOX_KEY} - '
    'box "all" closes every box\n'
    ' {"do":"chart","sym":SYMBOL_OR_INDEX,"kind":"share"|"index"}\n'
    ' {"do":"linecolour","value":"#rrggbb"} - the chart line colour\n'
    ' {"do":"size","box":BOX_KEY,"dir":"bigger"|"smaller"}\n'
    "Use only the keys listed below. A share named by its company (\"Reliance\""
    ", \"HDFC Bank\") is its SYMBOL from the list. Indian English; "
    "numbers may be said as words (\"nineteen hundred\" = 1900, \"one "
    "thousand nine hundred and fifty point five\" = 1950.5).\n"
    "If the recording has no clear spoken words, or you are not sure what "
    "was said, do NOTHING: heard \"\" and no actions - never guess.\n"
    'Reply with JSON only: {"heard": "<the words heard>", "actions": [...], '
    '"say": "<one short line, only if nothing can be done>"}\n')


def voice_transcribe(data):
    """The words in a recording (for a browser that cannot listen itself)."""
    audio = str(data.get("audio") or "")
    if not audio:
        return {"ok": False, "error": "Nothing was heard."}
    if not GEMINI["key"]:
        return {"ok": False, "error": "That needs Gemini: set the Ask key in "
                "Diagnostics (it is free)."}
    if len(audio) > 4000000:
        return {"ok": False, "error": "Too long - ten minutes at most."}
    mime = str(data.get("mime") or "audio/webm")
    if not re.fullmatch(r"audio/[a-z0-9.+-]+", mime):
        mime = "audio/webm"
    raw, why = gemini_parts([
        {"text": "Write out exactly what is said in this recording, in "
                 "English (Indian English; names of Indian companies and "
                 "shares as they are written, numbers as figures). Only the "
                 "words, nothing else. If nothing clear is said, answer with "
                 "an empty line."},
        {"inline_data": {"mime_type": mime, "data": audio}}], timeout=60)
    if raw is None:
        return {"ok": False, "error": "Gemini did not answer (%s)." % why}
    return {"ok": True, "text": raw.strip().strip('"')[:2000]}


# ---------------------------------------------------------------------------
# THE ASSISTANT (20.13) - a conversation with Gemini that knows the
# dashboard: with every question it is given the parts of the manual that
# match it best, and the same short list of things it may do as the voice
# commands. It answers "where is ...", "how do I ...", explains figures,
# and carries out simple commands; it never changes the program.
# ---------------------------------------------------------------------------
MANUAL_PARTS = {"mtime": 0, "parts": []}
ASSIST_STOP = set("the a an and or of to in on for is it i my me do does how what where "
                  "when which can with this that be are was there please you your "
                  "from at by as if not no yes want need show find".split())


def manual_parts():
    path = os.path.join(HERE, "USER_MANUAL.html")
    try:
        mt = os.path.getmtime(path)
    except OSError:
        return []
    if MANUAL_PARTS["mtime"] == mt:
        return MANUAL_PARTS["parts"]
    raw = open(path, encoding="utf-8").read()
    raw = re.sub(r"(?is)<(script|style)[^>]*>.*?</\1>", " ", raw)
    parts, h2, h3 = [], "", ""
    for m in re.finditer(r"(?is)<(h2|h3)[^>]*>(.*?)</\1>|(<p|<li|<tr|<div class=\"box\")(.*?)(?=<p|<li|<tr|<h2|<h3|<div class=\"box\"|$)", raw):
        if m.group(1):
            t = html_lib.unescape(re.sub(r"<[^>]+>", "", m.group(2))).strip()
            if m.group(1).lower() == "h2":
                h2, h3 = t, ""
            else:
                h3 = t
            continue
        t = html_lib.unescape(re.sub(r"<[^>]+>", " ", m.group(4) or ""))
        t = re.sub(r"\s+", " ", t).strip(" >")
        if len(t) > 25:
            parts.append((h2, h3, t[:1500]))
    MANUAL_PARTS.update(mtime=mt, parts=parts)
    return parts


def manual_snippets(q, limit=9000):
    words = [w for w in re.findall(r"[a-z0-9&]+", q.lower())
             if w not in ASSIST_STOP and len(w) > 1]
    if not words:
        return ""
    scored = []
    for h2, h3, t in manual_parts():
        low = (h2 + " " + h3 + " " + t).lower()
        sc = sum(low.count(w) for w in words) + \
            3 * sum(1 for w in words if w in (h2 + " " + h3).lower())
        if sc:
            scored.append((sc, h2, h3, t))
    scored.sort(key=lambda x: -x[0])
    out, n = [], 0
    for _sc, h2, h3, t in scored[:14]:
        piece = "[%s%s] %s" % (h2, (" > " + h3) if h3 else "", t)
        if n + len(piece) > limit:
            break
        out.append(piece)
        n += len(piece)
    return "\n".join(out)


