def assistant_answer(data):
    msgs = [m for m in (data.get("messages") or []) if isinstance(m, dict)
            and m.get("role") in ("user", "model") and m.get("text")][-12:]
    if not msgs or msgs[-1]["role"] != "user":
        return {"ok": False, "error": "Nothing to answer."}
    if not GEMINI["key"]:
        return {"ok": False, "error": "The assistant needs Gemini: set the Ask "
                "key in Diagnostics (it is free)."}
    ctx = data.get("context") if isinstance(data.get("context"), dict) else {}

    def pairs(k, n):
        return "; ".join("%s: %s" % (str(x[0])[:30], str(x[1] if len(x) > 1
                                                       else "")[:50])
                         for x in (ctx.get(k) or [])[:n]
                         if isinstance(x, list) and x)
    q = " ".join(m["text"] for m in msgs[-3:] if m["role"] == "user")[-600:]
    # 20.14: the accounts are read only with his yes (Accounts -> ... ->
    # Let the assistant read the accounts); a question about them without it
    # is answered with the offer instead of being sent
    about_acc = re.search(
        r"(?i)\b(my )?(accounts?|reconcil\w*|p ?& ?l|profit|loss(es)?|charges|"
        r"intraday|delivery trades?|capital gains?|stcg|ltcg|dividends?|"
        r"cash balance|holdings?|my trad(es|ing)|how am i doing|net worth)\b",
        msgs[-1]["text"])
    acc_text = accounts_ai_summary() if about_acc else ""
    if about_acc and not acc_text and acc_load() is not None and \
            not data.get("noAccounts"):
        return {"ok": True, "needAccounts": True,
                "reply": "To answer from your accounts I need to read them. "
                "That sends a short summary of them (no bank or account "
                "numbers) to Google Gemini with your question. Allow it? "
                "You can stop it at any time in Accounts -> ... ."}
    system = (ASSIST_STYLE + ASSIST_MAP + (
              "\n" + acc_text + "\nUse these figures when he asks about his "
              "accounts or trading; be frank and specific, and say so when "
              "the figures do not answer the question.\n" if acc_text else
              "") +
              "COLUMNS (key: name): " + pairs("columns", 20) +
              "\nBOXES (key: name): " + pairs("boxes", 30) +
              "\nSHARES (SYMBOL: company): " + pairs("shares", 260) +
              "\nVERSION: " + VERSION + "\n\nMANUAL EXCERPTS:\n" +
              (manual_snippets(q) or "(none matched)"))
    contents = [{"role": m["role"], "parts": [{"text": str(m["text"])[:2000]}]}
                for m in msgs]
    raw, why = gemini_parts(None, timeout=40, contents=contents,
                            system=system)
    gemini_log("Assistant" + (" (with the accounts)" if acc_text else ""),
               msgs[-1]["text"], raw or ("failed: %s" % why))
    if not raw:
        return {"ok": False, "error": "Gemini did not answer (%s)." % why}
    m = re.search(r"\{.*\}", raw, re.S)
    try:
        d = json.loads(m.group(0)) if m else {"reply": raw}
    except ValueError:
        d = {"reply": raw}
    acts = [a for a in (d.get("actions") or []) if isinstance(a, dict)
            and a.get("do") in ("set", "open", "close", "chart", "linecolour",
                                "size", "colwidth")][:6]
    return {"ok": True, "reply": str(d.get("reply") or "")[:3000],
            "actions": acts}


