def ai_calls_path():
    return os.path.join(os.path.dirname(PATHS["state"]), "ai_calls.json")


def _rsi14(closes):
    if len(closes) < 16:
        return None
    gains = losses = 0.0
    for i in range(1, 15):
        d = closes[i] - closes[i - 1]
        gains += max(d, 0)
        losses += max(-d, 0)
    ag, al = gains / 14, losses / 14
    for i in range(15, len(closes)):
        d = closes[i] - closes[i - 1]
        ag = (ag * 13 + max(d, 0)) / 14
        al = (al * 13 + max(-d, 0)) / 14
    return 100.0 if al == 0 else round(100 - 100 / (1 + ag / al), 1)


def candle_patterns(bars):
    """20.15: the candlestick patterns of the last three daily candles, by
    the textbook rules, each with the trend it comes after (a reversal
    pattern only means something after a move the other way)."""
    b = [x for x in bars if x[1] and x[2] and x[3] and x[4]]
    if len(b) < 8:
        return []
    out = []

    def body(x):
        return abs(x[4] - x[1])

    def rng(x):
        return max(x[2] - x[3], 1e-9)

    def upper(x):
        return x[2] - max(x[1], x[4])

    def lower(x):
        return min(x[1], x[4]) - x[3]
    avgb = sum(body(x) for x in b[-15:-1]) / max(1, len(b[-15:-1]))
    c0, c1, c2 = b[-1], b[-2], b[-3]
    before = (c1[4] / b[-7][4] - 1) * 100 if len(b) >= 7 else 0
    trend = "after a fall" if before < -2 else "after a rise" if before > 2 \
        else "with no clear move before it"
    down, up = before < -2, before > 2
    # doji: open and close almost the same - indecision; long legs either
    # side make the "plus sign" doji
    if body(c0) <= 0.1 * rng(c0):
        if upper(c0) > 0.3 * rng(c0) and lower(c0) > 0.3 * rng(c0):
            nm = "long-legged doji (a plus-sign candle)"
        elif lower(c0) > 0.6 * rng(c0):
            nm = "dragonfly doji"
        elif upper(c0) > 0.6 * rng(c0):
            nm = "gravestone doji"
        else:
            nm = "doji"
        sig = 1 if down else -1 if up else 0
        out.append({"name": nm, "when": "today", "trend": trend, "dir": sig,
                    "meaning": "indecision; " + ("a possible turn up - "
                    "confirmed only if the next candle closes higher" if down
                    else "a possible turn down - confirmed only if the next "
                    "candle closes lower" if up else "no signal on its own")})
    elif lower(c0) >= 2 * body(c0) and upper(c0) <= 0.3 * body(c0) + 1e-9:
        if down:
            out.append({"name": "hammer", "when": "today", "trend": trend,
                        "dir": 1, "meaning": "buyers pushed back from the "
                        "low - a possible turn up"})
        elif up:
            out.append({"name": "hanging man", "when": "today", "trend": trend,
                        "dir": -1, "meaning": "selling appeared at the top - "
                        "a possible turn down"})
    elif upper(c0) >= 2 * body(c0) and lower(c0) <= 0.3 * body(c0) + 1e-9:
        if up:
            out.append({"name": "shooting star", "when": "today",
                        "trend": trend, "dir": -1, "meaning": "rejected from "
                        "higher prices - a possible turn down"})
        elif down:
            out.append({"name": "inverted hammer", "when": "today",
                        "trend": trend, "dir": 1, "meaning": "buyers tried to "
                        "lift it - a possible turn up if confirmed"})
    # two-candle patterns
    g0, g1 = c0[4] > c0[1], c1[4] > c1[1]
    if g0 and not g1 and c0[4] >= c1[1] and c0[1] <= c1[4] and \
            body(c0) > body(c1):
        out.append({"name": "bullish engulfing", "when": "today",
                    "trend": trend, "dir": 1 if not up else 0,
                    "meaning": "today's rise swallowed yesterday's fall"})
    if not g0 and g1 and c0[1] >= c1[4] and c0[4] <= c1[1] and \
            body(c0) > body(c1):
        out.append({"name": "bearish engulfing", "when": "today",
                    "trend": trend, "dir": -1 if not down else 0,
                    "meaning": "today's fall swallowed yesterday's rise"})
    if body(c1) > avgb and body(c0) < 0.5 * body(c1) and \
            max(c0[1], c0[4]) < max(c1[1], c1[4]) and \
            min(c0[1], c0[4]) > min(c1[1], c1[4]):
        out.append({"name": "bullish harami" if not g1 else "bearish harami",
                    "when": "today", "trend": trend,
                    "dir": 1 if (not g1 and down) else -1 if (g1 and up) else 0,
                    "meaning": "a small candle inside yesterday's big one - "
                    "the move is losing strength"})
    if g0 and not g1 and c0[1] < c1[4] and c0[4] > (c1[1] + c1[4]) / 2 and \
            c0[4] < c1[1] and down:
        out.append({"name": "piercing line", "when": "today", "trend": trend,
                    "dir": 1, "meaning": "opened lower but closed above the "
                    "middle of yesterday's fall"})
    if not g0 and g1 and c0[1] > c1[4] and c0[4] < (c1[1] + c1[4]) / 2 and \
            c0[4] > c1[1] and up:
        out.append({"name": "dark cloud cover", "when": "today",
                    "trend": trend, "dir": -1, "meaning": "opened higher but "
                    "closed below the middle of yesterday's rise"})
    # three-candle patterns
    small1 = body(c1) < 0.4 * max(body(c2), 1e-9)
    if c2[4] < c2[1] and body(c2) > avgb and small1 and g0 and \
            c0[4] > (c2[1] + c2[4]) / 2:
        out.append({"name": "morning star", "when": "last three days",
                    "trend": trend, "dir": 1, "meaning": "a fall, a pause, "
                    "then a strong rise - a turn up"})
    if c2[4] > c2[1] and body(c2) > avgb and small1 and not g0 and \
            c0[4] < (c2[1] + c2[4]) / 2:
        out.append({"name": "evening star", "when": "last three days",
                    "trend": trend, "dir": -1, "meaning": "a rise, a pause, "
                    "then a strong fall - a turn down"})
    if all(x[4] > x[1] for x in (c2, c1, c0)) and c2[4] < c1[4] < c0[4] and \
            min(body(x) for x in (c2, c1, c0)) > 0.6 * avgb:
        out.append({"name": "three white soldiers", "when": "last three days",
                    "trend": trend, "dir": 1, "meaning": "three strong rising "
                    "days in a row"})
    if all(x[4] < x[1] for x in (c2, c1, c0)) and c2[4] > c1[4] > c0[4] and \
            min(body(x) for x in (c2, c1, c0)) > 0.6 * avgb:
        out.append({"name": "three black crows", "when": "last three days",
                    "trend": trend, "dir": -1, "meaning": "three strong "
                    "falling days in a row"})
    # yesterday's single-candle reversal signs, confirmed or not today
    if body(c1) <= 0.1 * rng(c1) and len(b) >= 8:
        pre = (c2[4] / b[-8][4] - 1) * 100
        if pre < -2:
            conf = c0[4] > c1[2]
            out.append({"name": "doji yesterday after a fall", "when":
                        "yesterday", "trend": "after a fall",
                        "dir": 1 if conf else 0, "meaning": "today " +
                        ("closed above it - the turn up is confirmed" if conf
                         else "did not confirm it yet")})
        elif pre > 2:
            conf = c0[4] < c1[3]
            out.append({"name": "doji yesterday after a rise", "when":
                        "yesterday", "trend": "after a rise",
                        "dir": -1 if conf else 0, "meaning": "today " +
                        ("closed below it - the turn down is confirmed" if conf
                         else "did not confirm it yet")})
    return out


def chart_signals(bars):
    """20.15: what each common indicator says by its textbook reading, worked
    out here from the daily bars - so the AI view weighs them all and he can
    see them: RSI zones, Bollinger bands, MACD crossing, the averages,
    volume, and the candles."""
    b = [x for x in bars if x[4]]
    cl = [x[4] for x in b]
    if len(cl) < 35:
        return []
    sig = []

    def add(name, value, d, meaning):
        sig.append({"name": name, "value": value, "dir": d,
                    "meaning": meaning})
    last = cl[-1]
    r = _rsi14(cl[-120:])
    if r is not None:
        add("RSI 14", round(r, 1), 1 if r < 30 else -1 if r > 70 else 0,
            "oversold (below 30) - a buy-side sign" if r < 30 else
            "overbought (above 70) - a sell-side sign" if r > 70 else
            "between 30 and 70 - neutral" + (", leaning weak" if r < 45 else
                                             ", leaning strong" if r > 55
                                             else ""))
    n = 20
    win = cl[-n:]
    mid = sum(win) / n
    sd = (sum((x - mid) ** 2 for x in win) / n) ** 0.5
    upb, lob = mid + 2 * sd, mid - 2 * sd
    pos = (last - lob) / (upb - lob) if upb > lob else 0.5
    add("Bollinger 20, 2", "lower %.2f / middle %.2f / upper %.2f" % (
        lob, mid, upb), 1 if last <= lob * 1.005 else -1
        if last >= upb * 0.995 else 0,
        "at or below the lower band - stretched down, a buy-side sign" if
        last <= lob * 1.005 else "at or above the upper band - stretched "
        "up, a sell-side sign" if last >= upb * 0.995 else
        "inside the bands (%d%% of the way from lower to upper)" % round(
            pos * 100))

    def ema(vals, k):
        a = 2 / (k + 1)
        e = vals[0]
        out = []
        for v in vals:
            e = v * a + e * (1 - a)
            out.append(e)
        return out
    e12, e26 = ema(cl, 12), ema(cl, 26)
    macd = [x - y for x, y in zip(e12, e26)]
    sigl = ema(macd, 9)
    hist = [x - y for x, y in zip(macd, sigl)]
    cross = None
    for i in range(1, 4):
        if hist[-i] > 0 >= hist[-i - 1]:
            cross = ("crossed above its signal line %d day(s) ago" % (i - 1)
                     if i > 1 else "crossed above its signal line today", 1)
            break
        if hist[-i] < 0 <= hist[-i - 1]:
            cross = ("crossed below its signal line %d day(s) ago" % (i - 1)
                     if i > 1 else "crossed below its signal line today", -1)
            break
    if cross:
        add("MACD 12, 26, 9", round(macd[-1], 2), cross[1], cross[0])
    else:
        add("MACD 12, 26, 9", round(macd[-1], 2), 0,
            "above its signal line (momentum up)" if hist[-1] > 0 else
            "below its signal line (momentum down)")
    for k in (20, 50, 200):
        if len(cl) >= k:
            m = sum(cl[-k:]) / k
            add("%d-day average" % k, round(m, 2), 1 if last > m else -1,
                "price above it" if last > m else "price below it")
    vols = [x[5] for x in b if len(x) > 5 and x[5]]
    if len(vols) >= 21:
        av = sum(vols[-21:-1]) / 20
        rv = vols[-1] / av if av else 0
        mv = "up" if cl[-1] > cl[-2] else "down"
        add("Volume vs 20-day average", "%.1fx" % rv, (1 if mv == "up" else -1)
            if rv >= 1.5 else 0, ("heavy volume on a day the price went %s - "
                                  "it backs the move" % mv) if rv >= 1.5 else
            "light volume - the day's move is not strongly backed" if rv < 0.7
            else "normal volume")
    for p in candle_patterns(b):
        add("Candles: " + p["name"], p["when"] + ", " + p["trend"],
            p["dir"], p["meaning"])
    return sig


def daily_context(sym):
    """The daily picture whatever bar size the chart is on (20.14): where the
    price is against its 20/50/200-day averages, RSI 14, the 52-week range."""
    try:
        d = chart_candles("share", sym, "1d")
    except Exception:
        return {}
    bars = d.get("bars") or []
    cl = [b[4] for b in bars if b[4]]
    if len(cl) < 30:
        return {}
    last = cl[-1]

    def sma(n):
        return round(sum(cl[-n:]) / n, 2) if len(cl) >= n else None
    out = {"close": round(last, 2)}
    for n in (20, 50, 200):
        m = sma(n)
        if m:
            out["sma%d" % n] = m
            out["vsSma%dPct" % n] = round((last / m - 1) * 100, 2)
    if len(cl) >= 26:
        m20, m20b = sma(20), round(sum(cl[-25:-5]) / 20, 2)
        out["sma20Slope5dPct"] = round((m20 / m20b - 1) * 100, 2)
    out["rsi14"] = _rsi14(cl[-120:])
    try:
        out["signals"] = chart_signals(bars)
    except Exception:
        out["signals"] = []
    yr = bars[-250:]
    hi, lo = max(b[2] for b in yr), min(b[3] for b in yr)
    out["fromHigh52wPct"] = round((last / hi - 1) * 100, 2)
    out["fromLow52wPct"] = round((last / lo - 1) * 100, 2)
    for k, n in (("ret1m", 21), ("ret3m", 63), ("ret6m", 126)):
        if len(cl) > n:
            out[k + "Pct"] = round((last / cl[-1 - n] - 1) * 100, 2)
    return out


def ai_call_record(sym, mode, call, price, tf):
    """Each day's first call on a share, for the accuracy report."""
    if not price:
        return
    day = datetime.date.today().isoformat()
    with AI_CALLS_LOCK:
        d = _read_json(ai_calls_path(), {})
        calls = d.setdefault("calls", [])
        if any(c.get("d") == day and c.get("sym") == sym and
               c.get("mode") == mode for c in calls[-400:]):
            return
        calls.append({"d": day, "sym": sym, "mode": mode, "call": call,
                      "price": round(float(price), 2), "tf": tf,
                      "at": int(time.time())})
        d["calls"] = calls[-3000:]
        _write_json(ai_calls_path(), d)


def ai_accuracy():
    """How often the AI view was right: each call against the share's close
    on the next trading day (BUY right if it closed higher, NO BUY if not
    higher, SELL if lower, HOLD if not lower). All shares, all days so far."""
    with AI_CALLS_LOCK:
        d = _read_json(ai_calls_path(), {})
    calls = d.get("calls") or []
    today = datetime.date.today().isoformat()
    changed = False
    closes = {}
    for c in calls:
        if "ok" in c or c.get("d", today) >= today:
            continue
        sym = c["sym"]
        if sym not in closes:
            try:
                hit = CHART_CACHE.get(("share", sym, "1d"))
                bars = hit["bars"] if hit else (chart_candles(
                    "share", sym, "1d").get("bars") or [])
            except Exception:
                bars = []
            closes[sym] = [(datetime.datetime.utcfromtimestamp(b[0]).date()
                            .isoformat(), b[4]) for b in bars]
        nxt = next((cl for day, cl in closes[sym] if day > c["d"]), None)
        if nxt is None:
            continue
        up = nxt > c["price"]
        c["next"] = nxt
        c["ok"] = {"BUY": up, "NO BUY": not up, "SELL": nxt < c["price"],
                   "HOLD": nxt >= c["price"]}.get(c["call"])
        changed = True
    if changed:
        with AI_CALLS_LOCK:
            cur = _read_json(ai_calls_path(), {})
            by = {(c["d"], c["sym"], c["mode"]): c for c in calls}
            cur["calls"] = [by.get((c.get("d"), c.get("sym"), c.get("mode")),
                                   c) for c in cur.get("calls") or []]
            _write_json(ai_calls_path(), cur)
    done = [c for c in calls if isinstance(c.get("ok"), bool)]
    right = sum(1 for c in done if c["ok"])
    by_call = {}
    for c in done:
        x = by_call.setdefault(c["call"], [0, 0])
        x[0] += 1
        x[1] += 1 if c["ok"] else 0
    return {"n": len(done), "right": right,
            "pct": round(right * 100.0 / len(done), 1) if done else None,
            "since": done[0]["d"] if done else "",
            "waiting": sum(1 for c in calls if "ok" not in c),
            "byCall": {k: {"n": v[0], "pct": round(v[1] * 100.0 / v[0], 1)}
                       for k, v in by_call.items()}}


def chart_opinion(data):
    """20.13: BUY / NO BUY (or SELL / HOLD for a share he holds) from the
    chart's own indicators, by Gemini. Kept ten minutes per share. 20.14:
    with the daily context whatever the bar size, a balanced instruction,
    each day's first call kept for the accuracy report, and a follow-up
    conversation in which Gemini is told to hold its ground unless the
    figures say otherwise."""
    sym = re.sub(r"[^A-Z0-9&. -]", "", str(data.get("sym") or "").upper())[:30]
    mode = "sell" if data.get("mode") == "sell" else "buy"
    snap = data.get("snap") if isinstance(data.get("snap"), dict) else {}
    if data.get("accuracy"):
        return dict(ai_accuracy(), ok=True)
    if not sym or not snap:
        return {"ok": False, "error": "Nothing to judge."}
    if not GEMINI["key"]:
        return {"ok": False, "error": "This needs Gemini: set the Ask key in "
                "Diagnostics (it is free)."}
    calls = "\"SELL\" or \"HOLD\"" if mode == "sell" else \
        "\"BUY\" or \"NO BUY\""
    ok_calls = ("SELL", "HOLD") if mode == "sell" else ("BUY", "NO BUY")
    ctx = daily_context(sym)
    facts = json.dumps(dict(dailyContext=ctx, **snap), ensure_ascii=False)[:14000]
    fu = data.get("followup") if isinstance(data.get("followup"), dict) else None
    if fu:
        prior = fu.get("prior") if isinstance(fu.get("prior"), dict) else {}
        hist = [x for x in (fu.get("history") or []) if isinstance(x, dict)][-8:]
        convo = "\n".join("%s: %s" % ("HE" if x.get("role") == "user" else
                                      "YOU", str(x.get("text") or "")[:600])
                          for x in hist)
        raw, why = gemini_parts([{"text": (CHART_FOLLOW_STYLE % calls) +
                                  "SHARE: " + sym + "\nCHART: " + facts +
                                  "\nYOUR CALL: " + json.dumps(prior)[:1500] +
                                  "\nTHE TALK SO FAR:\n" + convo +
                                  "\nHE NOW SAYS: " +
                                  str(fu.get("text") or "")[:800]}],
                                timeout=40)
        gemini_log("AI view reply", sym + ": " + str(fu.get("text"))[:200],
                   raw)
        if not raw:
            return {"ok": False, "error": "Gemini did not answer (%s)." % why}
        m = re.search(r"\{.*\}", raw, re.S)
        try:
            d = json.loads(m.group(0)) if m else {"reply": raw}
        except ValueError:
            d = {"reply": raw}
        call = str(d.get("call") or prior.get("call") or "").upper().strip()
        if call not in ok_calls:
            call = prior.get("call") or ""
        return {"ok": True, "reply": str(d.get("reply") or "")[:1500],
                "call": call, "changed": bool(d.get("changed")) and
                call != prior.get("call")}
    key = sym + "|" + mode + "|" + str(data.get("tf") or "")
    hit = CHART_OPINION.get(key)
    if hit and time.time() - hit["at"] < 600 and not data.get("fresh"):
        return dict(hit["data"], cached=True, accuracy=ai_accuracy())
    if mode == "sell":
        task = ("He ALREADY HOLDS this share. Say SELL if the chart says "
                "the up-move is over or the trend has turned down, otherwise "
                "HOLD.")
    else:
        task = ("He does NOT hold this share and is deciding whether to buy "
                "now. Say BUY when the balance of the chart is favourable "
                "for a rise over the next days to weeks; otherwise NO BUY.")
    raw, why = gemini_parts([{"text": (CHART_OPINION_STYLE % (task, calls)) +
                              "SHARE: " + sym + "\nCHART: " + facts}],
                            timeout=40)
    if not raw:
        return {"ok": False, "error": "Gemini did not answer (%s)." % why}
    m = re.search(r"\{.*\}", raw, re.S)
    try:
        d = json.loads(m.group(0)) if m else {}
    except ValueError:
        d = {}
    call = str(d.get("call") or "").upper().strip()
    if call not in ok_calls:
        return {"ok": False, "error": "Gemini's answer was unclear - try "
                "again."}
    gemini_log("AI view", sym, call)
    out = {"ok": True, "sym": sym, "mode": mode, "call": call,
           "signals": (ctx or {}).get("signals") or [],
           "confidence": str(d.get("confidence") or "")[:10],
           "why": [str(x)[:200] for x in (d.get("why") or [])
                   if isinstance(x, (str, int, float))][:5],
           "watch": str(d.get("watch") or "")[:200],
           "at": int(time.time())}
    try:
        ai_call_record(sym, mode, call, snap.get("last") or ctx.get("close"),
                       str(data.get("tf") or ""))
    except Exception:
        pass
    CHART_OPINION[key] = {"at": time.time(), "data": out}
    if len(CHART_OPINION) > 100:
        for k in sorted(CHART_OPINION,
                        key=lambda x: CHART_OPINION[x]["at"])[:40]:
            CHART_OPINION.pop(k, None)
    return dict(out, accuracy=ai_accuracy())


def voice_command(data):
    if data.get("mode") == "transcribe":
        return voice_transcribe(data)
    ctx = data.get("context") if isinstance(data.get("context"), dict) else {}

    def pairs(k, n):
        out = []
        for x in (ctx.get(k) or [])[:n]:
            if isinstance(x, list) and x:
                out.append("%s: %s" % (str(x[0])[:30], str(x[1] if len(x) > 1
                                                            else "")[:50]))
        return "; ".join(out)
    prompt = (VOICE_STYLE + "COLUMNS (key: name): " + pairs("columns", 20) +
              "\nBOXES (key: name): " + pairs("boxes", 30) +
              "\nSHARES (SYMBOL: company): " + pairs("shares", 260) +
              "\nIndices for charts: NIFTY 50, NIFTY BANK, SENSEX, INDIA VIX, "
              "NIFTY IT, NIFTY AUTO, NIFTY PHARMA, NIFTY FMCG, NIFTY METAL.\n")
    text = str(data.get("text") or "").strip()[:300]
    audio = str(data.get("audio") or "")
    if not text and not audio:
        return {"ok": False, "error": "Nothing was heard."}
    if not GEMINI["key"]:
        return {"ok": False, "error": "That needs Gemini: set the Ask key in "
                "Diagnostics (it is free)."}
    if audio:
        if len(audio) > 3000000:
            return {"ok": False, "error": "Too long - say it in one short "
                    "sentence."}
        mime = str(data.get("mime") or "audio/webm")
        if not re.fullmatch(r"audio/[a-z0-9.+-]+", mime):
            mime = "audio/webm"
        parts = [{"text": prompt + "The command is in this recording:"},
                 {"inline_data": {"mime_type": mime, "data": audio}}]
    else:
        parts = [{"text": prompt + "The command: " + text}]
    raw, why = gemini_parts(parts, timeout=25)
    if not raw:
        return {"ok": False, "error": "Gemini did not answer (%s)." % why}
    m = re.search(r"\{.*\}", raw, re.S)
    try:
        d = json.loads(m.group(0)) if m else {}
    except ValueError:
        d = {}
    acts = [a for a in (d.get("actions") or []) if isinstance(a, dict)
            and a.get("do") in ("set", "open", "close", "chart", "linecolour",
                                "size", "colwidth")][:6]
    return {"ok": True, "heard": str(d.get("heard") or text)[:200],
            "actions": acts, "say": str(d.get("say") or "")[:200]}


def gemini_parts(parts, timeout=25, contents=None, system=None):
    """Like ask_gemini, for a request made of several parts (a recording),
    or a whole conversation (contents) with standing instructions."""
    order = gem_order()
    why = ""
    for model in order[:4]:
        url = ("https://generativelanguage.googleapis.com/v1beta/models/%s"
               ":generateContent" % model)
        req_body = {"contents": contents or [{"parts": parts}],
                    "generationConfig": {"temperature": 0}}
        if system:
            req_body["systemInstruction"] = {"parts": [{"text": system}]}
        body = json.dumps(req_body)
        req = urllib.request.Request(
            url, data=body.encode("utf-8"), method="POST",
            headers={"Content-Type": "application/json",
                     "X-goog-api-key": GEMINI["key"]})
        try:
            d = json.loads(urllib.request.urlopen(req, timeout=timeout).read()
                           .decode("utf-8", "replace"))
            cand = (d.get("candidates") or [{}])[0]
            text = " ".join(p.get("text", "") for p in
                            (cand.get("content") or {}).get("parts") or [])
            if text.strip():
                return text.strip(), ""
            why = "empty answer"
        except urllib.error.HTTPError as e:
            why = "Gemini error %s" % e.code
            gem_mark(model, why)
            if e.code in (400, 401, 403):
                break
        except Exception as e:
            why = str(e)[:60]
            gem_mark(model, why)
    # 20.17: a request of plain text only can go to the backup AI as well
    try:
        texts = [str(p.get("text") or "") for c in (contents or [{"parts": parts}])
                 for p in (c.get("parts") or [])]
        plain = all("inline_data" not in p for c in (contents or [{"parts": parts}])
                    for p in (c.get("parts") or []))
    except Exception:
        texts, plain = [], False
    if plain and any(texts):
        t2, w2 = ask_ollama(((system or "") + "\n\n" if system else "")
                            + "\n\n".join(texts))
        if t2:
            GEM_LAST["src"] = "ollama"
            return t2, ""
        why = why + " | " + w2
    return None, why


gemini_parts = _gem_logged(gemini_parts)


def ask_wikipedia(q):
    """Fallback: the opening lines of the closest article."""
    try:
        srch = ("https://en.wikipedia.org/w/api.php?action=opensearch&search=%s"
                "&limit=1&namespace=0&format=json" % urllib.parse.quote(q))
        raw = urllib.request.urlopen(
            urllib.request.Request(srch, headers={"User-Agent": UA}),
            timeout=25).read()
        d = json.loads(raw.decode("utf-8", "replace"))
        titles = d[1] if len(d) > 1 else []
        if not titles:
            return None, "nothing on Wikipedia for that"
        title = titles[0]
        sm = ("https://en.wikipedia.org/api/rest_v1/page/summary/%s"
              % urllib.parse.quote(title.replace(" ", "_")))
        raw = urllib.request.urlopen(
            urllib.request.Request(sm, headers={"User-Agent": UA}),
            timeout=25).read()
        p = json.loads(raw.decode("utf-8", "replace"))
        text = (p.get("extract") or "").strip()
        if not text:
            return None, "no summary"
        # keep it to the first couple of sentences
        bits = re.split(r"(?<=[.!?])\s+", text)
        return " ".join(bits[:3]), title
    except Exception as e:
        return None, str(e)[:80]


def ask(q):
    q = (q or "").strip()
    if not q:
        return {"ok": False, "note": "Type something first."}
    t0 = time.time()
    text, why = ask_gemini(q)
    gsec = round(time.time() - t0, 1)
    gemini_log("Ask", q, text or ("failed: %s" % why))
    if text:
        return {"ok": True, "answer": text,
                "source": "Backup AI on this Mac" if GEM_LAST["src"] ==
                "ollama" else "Gemini", "gemini": "ok in %ss" % gsec}
    t1 = time.time()
    text, title = ask_wikipedia(q)
    wsec = round(time.time() - t1, 1)
    if text:
        return {"ok": True, "answer": text,
                "source": "Wikipedia \u2014 " + str(title),
                "gemini": "%s (after %ss)" % (why, gsec),
                "note": "Gemini could not answer, so this is Wikipedia."}
    # both failed: say exactly what EACH of them did, separately
    return {"ok": False, "gemini": "%s (after %ss)" % (why, gsec),
            "wiki": "%s (after %ss)" % (title, wsec),
            "note": "Gemini: %s.  Wikipedia: %s." % (why, title)}



# ---------------------------------------------------------------------------
# IPOs AND CORPORATE ACTIONS
#
# The IPO list comes from NSE, which is authoritative for dates, price band
# and lot size. The grey market premium is not official and cannot be - it is
# an unregulated market - so it is read from the IPO blogs and ALWAYS shown
# with the name of the site it came from. Treat it as gossip with a number
# attached, which is exactly what it is.
# ---------------------------------------------------------------------------

IPO_CACHE = {"at": 0, "rows": [], "gmpSource": ""}
# The GMP tables are built by JavaScript after the page loads, which is why
# reading the page source returned plenty of bytes and zero rows. These are
# the data feeds behind them. Several shapes are tried because the exact
# path changes with the year and the site version.
IPO_LIST_URL = "https://www.investorgain.com/report/ipo-gmp-live/331/"
GMP_LINKS = {}          # filled from the feed when it gives us real links

def gmp_sources():
    """The feeds' addresses carry the year: worked out on every reading, so
    a dashboard left running past 1 April moves on by itself."""
    _YR = datetime.date.today().year
    _FY = "%d-%d" % ((_YR - 1, _YR % 100) if datetime.date.today().month < 4
                     else (_YR, (_YR + 1) % 100))
    return [
        ("InvestorGain feed",
         "https://webnodejs.investorgain.com/cloud/report/data-read/331/1/1/%d/%s/0/all"
         % (_YR, _FY)),
        ("InvestorGain feed b",
         "https://webnodejs.investorgain.com/cloud/report/data-read/331/1/5/%d/%s/0/all"
         % (_YR, _FY)),
        ("Chittorgarh feed",
         "https://webnodejs.chittorgarh.com/cloud/report/data-read/82/1/1/%d/%s/0/0"
         % (_YR, _FY)),
        ("Chittorgarh feed b",
         "https://nodejs.chittorgarh.com/cloud/report/data-read/82/1/1/%d/%s/0/0"
         % (_YR, _FY)),
        ("IPO Watch",
         "https://ipowatch.in/ipo-grey-market-premium-latest-ipo-gmp/"),
    ]


def _gmp_num(t):
    m = re.search(r"-?\d+(?:\.\d+)?", str(t or "").replace(",", ""))
    return float(m.group()) if m else None


def fetch_gmp_from(name, raw):
    """Parse one site's reply. Separate so the probe can reuse it."""
    out = {}
    try:
        if raw.lstrip().startswith(("{", "[")):
            d = json.loads(raw)
            rows = d.get("reportTableData") if isinstance(d, dict) else d
            for r in (rows or []):
                nm = re.sub(r"<[^>]+>", "", str(r.get("~IPO_Name")
                                                or r.get("IPO") or "")).strip()
                g = _gmp_num(r.get("GMP") or r.get("~GMP"))
                if nm and g is not None:
                    key = nm.lower()[:28]
                    out[key] = g
                    # some feeds carry the IPO's own page - use it if so
                    for lk in ("~urlrewrite_folder_name", "url", "link",
                               "~url", "ipo_url"):
                        v = r.get(lk)
                        if v and isinstance(v, str) and len(v) > 3:
                            GMP_LINKS[key] = (v if v.startswith("http") else
                                              "https://www.investorgain.com/"
                                              + v.lstrip("/"))
                            break
        else:
            # by ROW, not by line - the whole page is one long line
            for tr in re.findall(r"<tr[^>]*>(.*?)</tr>", raw,
                                 re.I | re.S):
                cells = [re.sub(r"<[^>]+>", " ", c)
                         for c in re.findall(r"<t[dh][^>]*>(.*?)</t[dh]>",
                                             tr, re.I | re.S)]
                cells = [re.sub(r"\s+", " ", c).strip() for c in cells]
                cells = [c for c in cells if c]
                if len(cells) < 2:
                    continue
                nm = cells[0]
                if len(nm) < 4 or not re.search(r"[A-Za-z]", nm):
                    continue
                for c in cells[1:6]:
                    if re.fullmatch(r"[\u20b9]?\s*-?\d+(?:\.\d+)?", c):
                        out[nm.lower()[:28]] = _gmp_num(c)
                        break
    except Exception:
        pass
    return out


def gmp_probe():
    """What each grey-market site actually returned. He runs this once and
    sends me the output, so the next fix is based on fact, not a guess."""
    res = []
    for name, url in gmp_sources():
        row = {"source": name, "url": url}
        t0 = time.time()
        try:
            raw = urllib.request.urlopen(
                urllib.request.Request(url, headers={"User-Agent": UA}),
                timeout=15).read()
            row["ms"] = int((time.time() - t0) * 1000)
            row["bytes"] = len(raw)
            body = raw.decode("utf-8", "replace")
            row["looksLike"] = "json" if body.lstrip()[:1] in "[{" else "html"
            row["first300"] = body[:300]
            hits = fetch_gmp_from(name, body)
            row["parsed"] = len(hits)
            row["sample"] = list(hits.items())[:5]
            # the first table rows as they actually are, so the structure is
            # visible even when nothing parses
            rows3 = []
            for tr in re.findall(r"<tr[^>]*>(.*?)</tr>", body,
                                 re.I | re.S)[:3]:
                cells = [re.sub(r"\s+", " ",
                                re.sub(r"<[^>]+>", " ", c)).strip()
                         for c in re.findall(r"<t[dh][^>]*>(.*?)</t[dh]>",
                                             tr, re.I | re.S)]
                rows3.append([c for c in cells if c][:8])
            row["firstRows"] = rows3
            row["trCount"] = len(re.findall(r"<tr[^>]*>", body, re.I))
        except Exception as e:
            row["ms"] = int((time.time() - t0) * 1000)
            row["error"] = str(e)[:160]
        res.append(row)
    return {"sources": res}


def fetch_gmp():
    """Best effort. Whichever site answers first wins, and is named."""
    out, src = {}, ""
    for name, url in gmp_sources():
        try:
            raw = urllib.request.urlopen(
                urllib.request.Request(url, headers={"User-Agent": UA}),
                timeout=25).read().decode("utf-8", "replace")
        except Exception:
            continue
        out.update(fetch_gmp_from(name, raw))
        if out:
            src = name
            break
    return out, src



# ---------------------------------------------------------------------------
# IPO WATCH
#
# His probe settled this: IPO Watch's grey-market table returns 322 rows and
# parses cleanly, while InvestorGain's and Chittorgarh's feeds answer "API not
# found". So the table gives name, GMP, price band, estimated listing and
# dates; the lot size, minimum investment and subscription are not on that
# page at all, so each current issue's own page is read for those.
# ---------------------------------------------------------------------------

IPOW_URL = "https://ipowatch.in/ipo-grey-market-premium-latest-ipo-gmp/"
IPOW_DETAIL = {}          # link -> {lot, minAmount, subscription}


def _ipow_clean(t):
    t = re.sub(r"<[^>]+>", " ", t or "")
    t = t.replace("&nbsp;", " ").replace("&amp;", "&")
    return re.sub(r"\s+", " ", t).strip()


def investorgain_table():
    """IPO Watch's layout has changed again - his probe returned 0 rows. This
    reads InvestorGain's live GMP report instead, the page he already uses."""
    rows = []
    try:
        raw = urllib.request.urlopen(
            urllib.request.Request(
                "https://www.investorgain.com/report/live-ipo-gmp/331/",
                headers={"User-Agent": UA}), timeout=20).read().decode(
                    "utf-8", "replace")
    except Exception:
        return rows, "investorgain did not answer"
    for tr in re.findall(r"<tr[^>]*>(.*?)</tr>", raw, re.I | re.S):
        cells = [_ipow_clean(c) for c in
                 re.findall(r"<t[dh][^>]*>(.*?)</t[dh]>", tr, re.I | re.S)]
        cells = [c for c in cells if c is not None]
        if len(cells) < 6:
            continue
        name = cells[0]
        if not name or re.search(r"ipo\s*name|^name$", name, re.I):
            continue
        link = ""
        m = re.search(r'href="([^"]+)"', tr)
        if m:
            link = m.group(1)
            if link.startswith("/"):
                link = "https://www.investorgain.com" + link
        rows.append({"name": re.sub(r"\s+(IPO|SME)$", "", name).strip(),
                     "gmp": cells[1] if len(cells) > 1 else "",
                     "band": cells[3] if len(cells) > 3 else "",
                     "listing": cells[4] if len(cells) > 4 else "",
                     "dates": cells[5] if len(cells) > 5 else "",
                     "status": cells[6] if len(cells) > 6 else "",
                     "updated": cells[-1] if cells else "",
                     "link": link, "src": "InvestorGain"})
    return rows, ("" if rows else "investorgain returned no rows")


def ipowatch_table():
    """Every row of IPO Watch's grey-market tables.

    The layout changed again (checked in a browser on 9 Oct 2026): the
    heading is now "Company | GMP* | Trend | Price Band | Est. Gain | Date",
    the status ("Upcoming", "Open", "Closed") sits under the name in the
    same cell, and there are two tables - Mainboard first, then SME. The
    parser looked for an "IPO Name" heading, never found one, and returned
    nothing; that is why GMP, lot size, minimum and listing were all blank.
    Columns are now found by their heading words, whatever order they are in.
    """
    try:
        raw = urllib.request.urlopen(
            urllib.request.Request(IPOW_URL, headers={"User-Agent": UA}),
            timeout=20).read().decode("utf-8", "replace")
    except Exception as e:
        return [], str(e)[:120]

    rows = []
    tables = re.findall(r"<table[^>]*>(.*?)</table>", raw, re.I | re.S)
    for ti, tbl in enumerate(tables):
        # the words just before the table say which board it is
        at = raw.find(tbl)
        heads = re.findall(r"<h\d[^>]*>(.*?)</h\d>", raw[max(0, at - 3000):at],
                           re.I | re.S)
        before = _ipow_clean(heads[-1]).lower() if heads else ""
        board = ("SME" if "sme" in before else
                 "Mainboard" if "mainboard" in before else
                 ("Mainboard" if ti == 0 else "SME"))
        head = []
        for tr in re.findall(r"<tr[^>]*>(.*?)</tr>", tbl, re.I | re.S):
            cells_raw = re.findall(r"<t[dh][^>]*>(.*?)</t[dh]>", tr,
                                   re.I | re.S)
            cells = [_ipow_clean(c) for c in cells_raw]
            if not cells:
                continue
            low = [c.lower() for c in cells]
            if re.search(r"^(company|ipo\s*name|ipo)\b", low[0]) and \
                    any("gmp" in c for c in low):
                head = low
                continue
            if not head or len(cells) < 3:
                continue

            def col(*names):
                for n in names:
                    for i, h in enumerate(head):
                        if n in h and i < len(cells):
                            return cells[i]
                return ""

            first = cells_raw[0]
            status = ""
            ms = re.search(r"<span[^>]*>(.*?)</span>", first, re.I | re.S)
            if ms:
                status = _ipow_clean(ms.group(1))
            name = _ipow_clean(re.sub(r"<span[^>]*>.*?</span>", "", first,
                                      flags=re.I | re.S))
            name = re.sub(r"\s+(IPO|SME IPO)$", "", name).strip()
            if len(name) < 3:
                continue
            link = ""
            m = re.search(r'href="([^"]+)"', first)
            if m:
                link = m.group(1)
                if link.startswith("/"):
                    link = "https://ipowatch.in" + link
            est = col("est. gain", "est. listing", "listing", "gain")
            pct = ""
            mp = re.search(r"\(([-\d.]+)%\)", est)
            if mp:
                pct = mp.group(1) + "%"
            listing = re.sub(r"\s*\([^)]*\)", "", est).strip()
            if listing in ("\u20b9-", "-", ""):
                listing, pct = "", ""     # "Rs - (0.00%)" means not known yet
            band = col("price band", "price", "issue price")
            rows.append({
                "name": name, "link": link, "board": board,
                "gmp": col("gmp"),
                "band": "" if band.strip() in ("₹-", "-", "") else band,
                "listing": "" if listing.strip() in ("₹-", "-") else
                           listing,
                "gainPct": pct,
                "dates": col("date"),
                "status": status or col("status"),
                "updated": col("last updated", "updated"),
            })
    return rows, ("" if rows else "IPO Watch table had no rows")


def ipowatch_detail_url(link):
    """The table links to an issue's GMP page; lot size and dates are on the
    issue's own page. /hd-fire-protect-ipo-gmp-grey-market-premium/ ->
    /hd-fire-protect-ipo/ - checked by hand for HD Fire Protect."""
    m = re.search(r"ipowatch\.in/([a-z0-9-]+?)-ipo-gmp-grey-market-premium/?",
                  link or "")
    if m:
        return "https://ipowatch.in/%s-ipo/" % m.group(1)
    return link or ""


IPOW_FAILED = {}


def ipowatch_detail(link):
    """Lot size, minimum investment and the key dates from an issue's own
    page: the "Retail Minimum" row (Lots | Shares | Amount, e.g. 1 | 55 |
    Rs 14,905) and the date rows (Basis of Allotment, IPO Listing Date)."""
    if not link:
        return {}
    hit = IPOW_DETAIL.get(link)
    # a page that gave nothing (timeout, 503) is tried again ten minutes on
    if hit is not None and (hit or time.time() - IPOW_FAILED.get(link, 0)
                            < 600):
        return hit
    out = {}
    for url in (ipowatch_detail_url(link), link):
        if not url or out.get("lot"):
            continue
        try:
            raw = urllib.request.urlopen(
                urllib.request.Request(url, headers={"User-Agent": UA}),
                timeout=15).read().decode("utf-8", "replace")
        except Exception:
            continue
        for tr in re.findall(r"<tr[^>]*>(.*?)</tr>", raw, re.I | re.S):
            cells = [_ipow_clean(c) for c in
                     re.findall(r"<t[dh][^>]*>(.*?)</t[dh]>", tr, re.I | re.S)]
            cells = [c for c in cells if c]
            if len(cells) < 2:
                continue
            c0 = cells[0].lower()
            if re.search(r"retail\s*min", c0) and len(cells) >= 3:
                nums = [re.sub(r"[^\d.]", "", c) for c in cells[1:]]
                nums = [n for n in nums if n]
                if len(nums) >= 2:
                    out["lot"] = nums[-2]          # shares in one lot
                    out["minAmount"] = nums[-1]
                elif nums:
                    out["lot"] = nums[0]
            elif "basis of allotment" in c0 and "allotment" not in out:
                out["allotment"] = cells[1]
            elif re.search(r"ipo listing date|listing date", c0) \
                    and "listDate" not in out:
                out["listDate"] = cells[1]
            elif re.search(r"^ipo price band", c0) and "band" not in out:
                out["band"] = re.sub(r"\s*per\s+(equity\s+)?share.*$", "",
                                     cells[1], flags=re.I).strip()
        if not out.get("lot"):
            text = _ipow_clean(raw)
            m = re.search(r"minimum\s+bid\s+is\s+([\d,]+)\s*shares?"
                          r"[^\d]{0,30}([\d,]{3,12})?", text, re.I)
            if m:
                out["lot"] = m.group(1).replace(",", "")
                if m.group(2):
                    out["minAmount"] = m.group(2).replace(",", "")
    # short dates read better in a table: "October 16, 2026" -> "16 Oct"
    for k in ("allotment", "listDate"):
        try:
            out[k] = datetime.datetime.strptime(out[k].strip(), "%B %d, %Y") \
                .strftime("%d %b")
        except Exception:
            pass
    IPOW_DETAIL[link] = out
    if not out:
        IPOW_FAILED[link] = time.time()
    if len(IPOW_DETAIL) > 200:
        IPOW_DETAIL.pop(next(iter(IPOW_DETAIL)))
    return out


def nse_ipo_subscription(name):
    """His NSE screenshot showed it: Offered 25,43,000, Bids 48,42,000,
    Subscription 1.90 - simply bids divided by offered. Computing it beats
    guessing at a field name that may not exist."""
    """Subscription from NSE's own issue-information feed, as he asked."""
    try:
        data, _e = SESSION.fetch(
            "https://www.nseindia.com/api/ipo-current-issue",
            "https://www.nseindia.com/market-data/all-upcoming-issues-ipo")
        if not isinstance(data, list):
            return ""
        key = re.sub(r"[^a-z]", "", (name or "").lower())[:12]
        for r in data:
            nm = re.sub(r"[^a-z]", "",
                        str(r.get("companyName") or "").lower())[:12]
            if key and nm and (key in nm or nm in key):
                for f in ("noOfTimesIssueSubscribed", "issueSubscribed",
                          "subscriptionTimes", "sub"):
                    v = to_number(r.get(f))
                    if v:
                        return ("%.2fx" % v)
                bids = to_number(r.get("noOfSharesBid")
                                 or r.get("bids") or r.get("totalBids"))
                offered = to_number(r.get("noOfSharesOffered")
                                    or r.get("offered")
                                    or r.get("sharesOffered"))
                if bids and offered:
                    return ("%.2fx" % (bids / offered))
        return ""
    except Exception:
        return ""


def _ipo_key(nm):
    """Company names match on their full squashed form, never a prefix -
    two issues sharing their first few letters must not swap figures."""
    t = re.sub(r"\b(limited|ltd|private|pvt|ipo|sme|india)\b", "",
               (nm or "").lower())
    return re.sub(r"[^a-z0-9]", "", t)


# A slow source never holds up the page: once there is a list, a stale one
# is answered at once and the fresh one is read in the background.
BG_RUN = {}
BG_LOCK = threading.Lock()


def stale_ok(name, has, fresh, refresh, too_old=False):
    """Return True when the caller may answer with what it has now.
    20.19: never once it is too old - then it is read again now, and what
    that reading gives (or its failure) is what is shown."""
    if fresh:
        return True
    if not has or too_old:
        return False                     # nothing usable: read it now
    with BG_LOCK:
        if BG_RUN.get(name):
            return True
        BG_RUN[name] = True

    def run():
        try:
            refresh()
        except Exception:
            pass
        finally:
            BG_RUN[name] = False
    threading.Thread(target=run, daemon=True).start()
    return True


IPO_READ_LOCK = threading.Lock()


def fetch_ipos(force=False):
    """Open, upcoming and just-closed issues, everything in one table."""
    # GMP and subscription move through the day - five minutes at most
    if not force and stale_ok("ipo", bool(IPO_CACHE["rows"]),
                              time.time() - IPO_CACHE["at"] < 300,
                              lambda: fetch_ipos(True),
                              time.time() - IPO_CACHE["at"] > 900):
        return IPO_CACHE
    with IPO_READ_LOCK:                  # one reading at a time
        if not force and IPO_CACHE["rows"] and \
                time.time() - IPO_CACHE["at"] < 300:
            return IPO_CACHE
        # every source failed a moment ago: not tried again for a minute
        if not force and not IPO_CACHE["rows"] and \
                time.time() - IPO_CACHE["at"] < 60:
            return IPO_CACHE
        return _fetch_ipos_now()


def _fetch_ipos_now():
    table, err = ipowatch_table()
    src = "IPO Watch"
    if not table:
        table, err2 = investorgain_table()
        err = err or err2
        src = "InvestorGain"

    # NSE: what is actually open today, with its subscription. Checked on
    # 9 Oct: the reply carries noOfTime (times subscribed), noOfsharesBid
    # and noOfSharesOffered - and it also lists bond issues (series DEBT),
    # which are not IPOs and are now left out.
    nse = {}
    for url, ref in (("https://www.nseindia.com/api/ipo-current-issue",
                      "https://www.nseindia.com/market-data/all-upcoming-"
                      "issues-ipo"),
                     ("https://www.nseindia.com/api/all-upcoming-issues"
                      "?category=ipo",
                      "https://www.nseindia.com/market-data/all-upcoming-"
                      "issues-ipo")):
        try:
            data, _e = SESSION.fetch(url, ref)
        except Exception:
            data = None
        for r in (data if isinstance(data, list) else []):
            if str(r.get("series") or "EQ").upper() not in ("EQ", "SM", "ST",
                                                            "SME", "BE"):
                continue
            nm = str(r.get("companyName") or "").strip()
            key = _ipo_key(nm)
            if not key:
                continue
            cur = nse.setdefault(key, {"name": nm})
            times = to_number(r.get("noOfTime"))
            bids = to_number(r.get("noOfsharesBid") or r.get("noOfSharesBid"))
            offered = to_number(r.get("noOfSharesOffered"))
            if times:
                cur["sub"] = "%.2fx" % times
            elif bids and offered and "sub" not in cur:
                cur["sub"] = "%.2fx" % (bids / offered)
            cur.setdefault("symbol", str(r.get("symbol") or "").strip())
            cur.setdefault("status", str(r.get("status") or "").strip())
            cur.setdefault("open", str(r.get("issueStartDate") or ""))
            cur.setdefault("close", str(r.get("issueEndDate") or ""))
            cur.setdefault("band", str(r.get("issuePrice") or "")
                           .replace("Rs.", "₹"))

    order = {"open": 0, "active": 0, "closing": 0, "upcoming": 1,
             "forthcoming": 1}

    def is_over(st):
        return bool(re.search(r"closed|listed|allotted|withdrawn", st or "",
                              re.I))

    def same(a, b):
        # "Ravita Engineering" (IPO Watch) is "Ravita Engineering Services
        # Limited" at NSE - one issue, not two
        # a short name ("Tata Capital") must not swallow a longer one
        # ("Tata Capital Housing Finance"): only a long first part counts
        return a == b or (min(len(a), len(b)) >= 12
                          and (a.startswith(b) or b.startswith(a)))

    seen, live = [], []
    for r in table:
        k = _ipo_key(r["name"])
        if any(same(k, x) for x in seen):
            continue
        seen.append(k)
        if is_over(r.get("status")):
            continue                     # he has no use for closed issues
        live.append(r)
    # NSE's figures are attached to the matching IPO Watch row
    for k, n in list(nse.items()):
        for x in seen:
            if same(k, x) and k != x:
                nse[x] = dict(n, **{kk: vv for kk, vv in nse.get(x, {}).items()
                                    if vv})
    # anything NSE lists that IPO Watch has not got yet still goes in
    for k, n in nse.items():
        if any(same(k, x) for x in seen) or is_over(n.get("status")):
            continue
        live.append({"name": n["name"], "link": "", "gmp": "",
                     "band": n.get("band", ""), "listing": "", "gainPct": "",
                     "board": "", "dates": (n.get("open", "") + " to " +
                                            n.get("close", "")),
                     "status": n.get("status") or "Open", "updated": ""})
    # NSE knows first when an issue opens: its "Active" wins over a blog
    # still saying Upcoming
    for r in live:
        n = nse.get(_ipo_key(r["name"])) or {}
        if re.match(r"\s*(active|open)\b", n.get("status") or "", re.I):
            r["status"] = "Open"
    live.sort(key=lambda r: order.get((r.get("status") or "").split()[0]
                                      .lower() if r.get("status") else "",
                                      1))

    rows = []
    for r in live[:24]:
        d = ipowatch_detail(r["link"])
        lot = d.get("lot") or ""
        band = r["band"] or d.get("band", "")
        nums = re.findall(r"\d+(?:\.\d+)?", band.replace(",", ""))
        if not nums:
            # price not announced yet ("Rs [.] to Rs [.]") - any lot or
            # amount on the page is a placeholder, not a figure
            band, lot, d = "Not announced", "", dict(d, minAmount=None)
        top = max(float(x) for x in nums) if nums else None
        lotn = _gmp_num(lot)
        minamt = d.get("minAmount")
        if not minamt and top and lotn:
            minamt = str(round(top * lotn))
        gmpn = _gmp_num(r["gmp"])
        listing = r["listing"]
        if not listing and top and gmpn is not None:
            listing = "₹" + str(round(top + gmpn))
        gain = r["gainPct"]
        if not gain and top and gmpn is not None:
            gain = "%.2f%%" % (gmpn / top * 100)
        n = nse.get(_ipo_key(r["name"]), {})
        rows.append({
            "name": r["name"], "gmp": gmpn, "gmpText": r["gmp"],
            "board": r.get("board", ""), "symbol": n.get("symbol", ""),
            "band": band, "listing": listing, "gainPct": gain,
            "dates": r["dates"], "status": r["status"] or n.get("status", ""),
            "lot": lot, "minAmount": (int(float(minamt)) if minamt and
                                      re.fullmatch(r"[\d.]+", str(minamt))
                                      else None),
            "allotment": d.get("allotment", ""),
            "listDate": d.get("listDate", ""),
            "subscription": n.get("sub", ""),
            "updated": r["updated"],
            "readUrl": ipowatch_detail_url(r["link"]) or IPO_LIST_URL,
        })
    IPO_CACHE.update({"at": time.time(), "rows": rows,
                      "gmpSource": src, "error": err})
    return IPO_CACHE


# ---------------------------------------------------------------------------
# PAST IPOs (20.12) - issues allotted in the last few days (three unless he
# picks longer): the issue price, the price it listed at, how many times it
# was subscribed, the price now and the change since listing.
#  * which issues and when: NSE's list of past issues (it gives the closing
#    day and the listing day; the allotment is the next trading day after
#    closing, as SEBI's T+3 timetable has it)
#  * times subscribed: NSE's own page of the issue (the "Total" line)
#  * the listing price: the first day's opening price; the price now: the
#    latest close or live price (Yahoo Finance, NSE when Yahoo has none)
# ---------------------------------------------------------------------------
IPO_PAST = {}
IPO_SUBS = {}


def _ipo_subscribed(sym, series):
    hit = IPO_SUBS.get(sym)
    if hit is not None:
        return hit
    data, _e = SESSION.fetch(
        "https://www.nseindia.com/api/ipo-detail?symbol=%s&series=%s"
        % (Q(sym), Q(series)),
        "https://www.nseindia.com/market-data/all-upcoming-issues-ipo")
    out = ""
    for r in ((data or {}).get("bidDetails") or []) \
            if isinstance(data, dict) else []:
        if str(r.get("category") or "").strip().lower() == "total":
            t = to_number(r.get("noOfTime"))
            if t:
                out = "%.2f" % t
    if out:
        IPO_SUBS[sym] = out
    return out


IPO_PAST_ONE = {}


def _ipo_past_one(x, today):
    """Subscription, listing price and price now for one past issue. What
    cannot change any more (subscription, listing price) is kept."""
    keep = IPO_PAST_ONE.get(x["symbol"]) or {}
    x.update(listPrice=keep.get("listPrice"), price=None, sinceList=None,
             sinceIssue=None, subscribed=keep.get("subscribed", ""))
    if not x["subscribed"]:
        try:
            x["subscribed"] = _ipo_subscribed(x["symbol"], x["series"])
        except Exception:
            x["subscribed"] = ""
    if x["listed"] and x["listed"] <= today.isoformat():
        hit = keep.get("px")
        if hit and time.time() - hit[0] < 600:
            x["price"] = hit[1]
        else:
            try:
                bars, meta, _ev = yahoo_ohlc(x["symbol"] + ".NS", "5y", "1d")
                first = [b for b in bars if datetime.datetime.fromtimestamp(
                    b[0] + IST_SHIFT, datetime.timezone.utc).date()
                    .isoformat() >= x["listed"]]
                if first:
                    x["listPrice"] = x["listPrice"] or round(first[0][1], 2)
                    x["price"] = round(meta.get("regularMarketPrice") or
                                       first[-1][4], 2)
            except Exception:
                pass
            if x["price"] is None:
                try:
                    f = fetch_symbol(x["symbol"], light=True)
                    x["price"] = to_number(f.get("ltp"))
                    if not x["listPrice"] and x["listed"] == today.isoformat():
                        x["listPrice"] = to_number(f.get("open"))
                except Exception:
                    pass
    if x["price"] and x["listPrice"]:
        x["sinceList"] = round((x["price"] / x["listPrice"] - 1) * 100, 2)
    if x["price"] and x["issue"]:
        x["sinceIssue"] = round((x["price"] / x["issue"] - 1) * 100, 2)
    IPO_PAST_ONE[x["symbol"]] = {
        "subscribed": x["subscribed"],
        "listPrice": x["listPrice"] if x["listed"] and x["listed"] <
        today.isoformat() else None,
        "px": [time.time(), x["price"]] if x["price"] else None}


def ipo_past(days=3):
    days = max(1, min(400, int(days or 3)))
    hit = IPO_PAST.get(days)
    if hit and time.time() - hit["at"] < 1800:
        return hit["data"]
    data, err = SESSION.fetch(
        "https://www.nseindia.com/api/public-past-issues",
        "https://www.nseindia.com/market-data/all-upcoming-issues-ipo",
        timeout=30)
    today = datetime.date.today()
    rows = []
    for r in (data if isinstance(data, list) else []):
        series = str(r.get("securityType") or "").upper()
        if series not in ("EQ", "SME", "BE"):
            continue                       # bonds and the like
        end = _isodate(r.get("ipoEndDate") or "")
        if not end:
            continue
        allot = next_trading_day(datetime.date.fromisoformat(end))
        if allot > today or (today - allot).days > days:
            continue
        sym = str(r.get("symbol") or "").strip().upper()
        lst = _isodate(r.get("listingDate") or "")
        issue = to_number(str(r.get("issuePrice") or "").strip())
        rows.append({"symbol": sym, "name": str(r.get("company") or
                                                r.get("companyName") or sym),
                     "board": "SME" if series == "SME" else "Mainboard",
                     "series": "SME" if series == "SME" else "EQ",
                     "allotted": allot.isoformat(), "listed": lst or "",
                     "issue": issue, "band": str(r.get("priceRange") or "")
                     .replace("Rs.", "₹")})
    rows.sort(key=lambda x: x["allotted"], reverse=True)
    rows = rows[:40]
    # each issue's figures are read side by side (eight at a time): a
    # month's 30-odd issues take seconds, not minutes
    ts = []
    for x in rows:
        t = threading.Thread(target=_ipo_past_one, args=(x, today),
                             daemon=True)
        t.start()
        ts.append(t)
        if len(ts) >= 8:
            ts.pop(0).join(40)
    for t in ts:
        t.join(40)
    out = {"ok": isinstance(data, list), "rows": rows, "days": days,
           "error": "" if isinstance(data, list) else (err or "no answer"),
           "at": time.strftime("%H:%M")}
    IPO_PAST[days] = {"at": time.time() - (0 if out["ok"] else 1700),
                      "data": out}
    return out


CORP_CACHE = {"at": 0, "rows": [], "seen": {}}
CORP_FILE = os.path.join(DATA_DIR, "corpactions.json")
CORP_WANTED = ("dividend", "bonus", "rights", "buy back", "buyback",
               "split", "sub-division", "offer for sale", "open offer")


def corp_labels(state):
    """Whatever those two columns are called today. He can rename them, and
    the panel must say the name he is actually looking at."""
    heads = state.get("headings") or {}
    return (str(heads.get("old") or "OLD").strip() or "OLD",
            str(heads.get("yesterday") or "YESTERDAY").strip() or "YESTERDAY")


def corp_symbols(state):
    """Watchlist shares with something typed in the OLD or YESTERDAY column,
    plus everything in Out of list. No cap - on a busy day every one of the
    125 could have a note in those columns."""
    n = state.get("notes") or {}
    out = []
    for sym in (state.get("watchlist") or []):
        note = n.get(sym) or {}
        if str(note.get("old", "") or "").strip() or \
           str(note.get("yesterday", "") or "").strip():
            out.append(sym)
    for sym in extra_symbols(state):
        if sym not in out:
            out.append(sym)
    return out


CORP_SEEN_LOCK = threading.Lock()


def corp_seen_load():
    """What he has already seen: {id: when first seen}. (Until 20.7 a list
    cut alphabetically, so the newest could be dropped and shown again.)"""
    try:
        with open(CORP_FILE) as f:
            s = json.load(f).get("seen") or {}
        if isinstance(s, list):
            s = {k: 0 for k in s}
        CORP_CACHE["seen"] = dict(s)
    except Exception:
        CORP_CACHE["seen"] = {}


def corp_seen_save():
    try:
        with CORP_SEEN_LOCK:
            keep = dict(sorted(CORP_CACHE["seen"].items(),
                               key=lambda kv: kv[1])[-1500:])
            CORP_CACHE["seen"] = keep
            _write_json(CORP_FILE, {"seen": keep})
    except Exception:
        pass


# Only the events that change what a share is worth to a holder. Board
# meetings, press releases, investor calls and general filings are noise.
CORP_ANN_WANTED = ("dividend", "bonus", "rights issue", "rights entitlement",
                   "buy back", "buyback", "buy-back", "stock split",
                   "sub-division", "subdivision", "offer for sale", "ofs",
                   "open offer")
CORP_ANN_BLOCK = ("record date update", "general update", "updates",
                  "board meeting", "outcome of board", "press release",
                  "investor presentation", "analyst", "earnings call",
                  "trading window", "newspaper publication", "certificate",
                  "compliance", "disclosure under regulation", "intimation of",
                  "loss of share", "duplicate share", "sub-committee")


PDF_VALUES = {}


def value_from_text(txt):
    """Pull the number a holder actually cares about out of the wording."""
    t = re.sub(r"\s+", " ", txt or "")
    m = re.search(r"buy[\s-]?back[^.]{0,120}?(?:price|per equity share|per "
                  r"share)[^\d]{0,20}(?:rs\.?|inr|\u20b9)?\s*([\d,]+"
                  r"(?:\.\d+)?)", t, re.I)
    if m:
        return "Rs " + m.group(1) + " per share"
    m = re.search(r"dividend[^.]{0,90}?(?:rs\.?|inr|\u20b9)\s*([\d,]+"
                  r"(?:\.\d+)?)\s*(?:per\s+(?:equity\s+)?share)?",
                  t, re.I)
    if m:
        return "Rs " + m.group(1) + " per share"
    m = re.search(r"(?:split|sub[\s-]?division)[^.]{0,90}?from\s*(?:rs\.?"
                  r"|\u20b9)?\s*([\d.]+)[^\d]{1,20}(?:rs\.?|\u20b9)?\s*"
                  r"([\d.]+)", t, re.I)
    if m:
        return "Split from Rs %s to Rs %s" % (m.group(1), m.group(2))
    m = re.search(r"(?:bonus|rights)[^.]{0,60}?(\d+\s*[:\u2236]\s*\d+)",
                  t, re.I)
    if m:
        return "Ratio " + m.group(1)
    return ""


def value_from_pdf(url):
    """Open the filing itself when the headline does not carry the number.
    Slow, so each one is read once and remembered."""
    if not url:
        return ""
    if url in PDF_VALUES:
        return PDF_VALUES[url]
    out = ""
    try:
        raw = urllib.request.urlopen(
            urllib.request.Request(url, headers={"User-Agent": UA}),
            timeout=25).read()
        if raw[:4] == b"%PDF":
            txt = ""
            for chunk in re.findall(rb"stream\r?\n(.*?)endstream", raw,
                                    re.S)[:60]:
                try:
                    txt += zlib.decompress(chunk).decode("latin-1", "replace")
                except Exception:
                    continue
            words = " ".join(re.findall(r"\((.*?)\)", txt))
            out = value_from_text(words)
        else:
            out = value_from_text(raw.decode("utf-8", "replace"))
    except Exception:
        out = ""
    PDF_VALUES[url] = out
    if len(PDF_VALUES) > 300:
        PDF_VALUES.pop(next(iter(PDF_VALUES)))
    return out


def _strip_boiler(t):
    """NSE prefixes everything with wording like "Public Announcement - ",
    which ate the whole column and pushed the real announcement out of
    sight."""
    t = re.sub(r"^(public\s+)?announcement\s*[-\u2013:]+\s*", "", t or "",
               flags=re.I)
    t = re.sub(r"^(intimation|disclosure|submission)\s+(of|under)\s+"
               r"[^-\u2013:]{0,40}[-\u2013:]+\s*", "", t, flags=re.I)
    return t.strip()


# NSE's own category names for the filings that matter, read off the live
# feed on 9 Oct 2026 (113 categories in 45 days). Matching the CATEGORY
# exactly replaced word-matching across the whole filing text, which is
# what put wrong rows in the panel: "rights" matched "voting rights",
# "ofs" matched inside other words, and a symbol-in-text fallback tagged
# other companies' filings to his shares.
CORP_ANN_CATEGORIES = {
    "dividend": "Dividend",
    "buyback": "Buyback",
    "public announcement - buyback of shares": "Buyback",
    "bonus": "Bonus",
    "rights issue": "Rights",
    "public announcement-open offer": "Open offer",
    "public announcement - open offer": "Open offer",
    "offer for sale": "Offer for sale",
    "stock split": "Split",
    "sub-division": "Split",
}
# these say the event is finished - the buyback is over, nothing to watch
CORP_ANN_DONE = ("closure of buy back", "post buyback public announcement",
                 "post buy back public announcement")


def _corp_kind(text):
    t = (text or "").lower()
    for w, k in (("buy back", "Buyback"), ("buyback", "Buyback"),
                 ("buy-back", "Buyback"), ("dividend", "Dividend"),
                 ("bonus", "Bonus"), ("rights", "Rights"),
                 ("sub-division", "Split"), ("split", "Split"),
                 ("offer for sale", "Offer for sale"),
                 ("open offer", "Open offer")):
        if w in t:
            return k
    return ""


def _corp_day(iso):
    """2026-10-09 -> 09-Oct-2026, the way NSE and he both write it."""
    try:
        return datetime.date.fromisoformat(iso).strftime("%d-%b-%Y")
    except Exception:
        return iso or ""


RECORD_DATE_RX = re.compile(
    r"record\s*date[^.]{0,90}?\b(\d{1,2}[-/ ](?:[A-Za-z]{3,9}|\d{1,2})[-/ ,]*"
    r"\d{4})", re.I)


def record_dates_in(text):
    """'Record date for the purpose of Dividend is 14-Oct-2026' ->
    [("Dividend", "2026-10-14")]. Every record date in the text is read,
    each with the event named just before it; one naming no event we
    follow (an AGM, interest on bonds) is ignored."""
    out = []
    t = text or ""
    for m in RECORD_DATE_RX.finditer(t):
        raw = re.sub(r"[ ,/]+", "-", m.group(1).strip())
        iso = ""
        for fmt in ("%d-%b-%Y", "%d-%B-%Y", "%d-%m-%Y"):
            try:
                iso = datetime.datetime.strptime(raw, fmt).date().isoformat()
                break
            except Exception:
                continue
        kind = _corp_kind(t[max(0, m.start() - 60):m.end()])
        if iso and kind:
            out.append((kind, iso))
    return out


def fetch_announcements(symbols):
    """Filings as they are made, before any ex-date exists - a buyback
    announced today has no dated corporate action yet.

    A company's own "Record Date" filing (Vedanta, 5 Oct: "Record date for
    the purpose of Dividend is 14-Oct-2026"), or a record date written in
    the dividend filing itself, is kept in CORP_CACHE["recDates"] so the
    row can show it before NSE's dated list catches up."""
    rows, done = [], set()
    recs = {}
    want = {s.upper() for s in symbols}
    d2 = datetime.date.today()
    d1 = d2 - datetime.timedelta(days=45)
    url = ("https://www.nseindia.com/api/corporate-announcements"
           "?index=equities&from_date=%s&to_date=%s"
           % (d1.strftime("%d-%m-%Y"), d2.strftime("%d-%m-%Y")))
    data, err = SESSION.fetch(url, "https://www.nseindia.com/companies-"
                                   "listing/corporate-filings-announcements",
                              timeout=40)
    CORP_CACHE["annErr"] = "" if isinstance(data, list) else (err or "empty")
    if not isinstance(data, list):
        return rows, done
    for r in data:
        sym = str(r.get("symbol") or "").upper().strip()
        if sym not in want:
            continue                       # exact symbol only - no guessing
        cat = str(r.get("desc") or "").strip().lower()
        when = _isodate(r.get("an_dt") or r.get("sort_date") or "")
        if any(cat.startswith(x) for x in CORP_ANN_DONE):
            done.add((sym, "Buyback"))
            continue
        raw_text = str(r.get("attchmntText") or "")
        for rkind, rec in record_dates_in(raw_text):
            rk = (sym, rkind)
            if rk not in recs or (when or "") > recs[rk][1]:
                recs[rk] = (rec, when or "")
        kind = CORP_ANN_CATEGORIES.get(cat)
        if not kind:
            continue
        text = raw_text.strip()
        # "X Limited has informed the Exchange that ..." - the company's
        # own name adds nothing in a row that already says the share
        text = re.sub(r"^.{0,90}?has informed (the )?exchange\s*(that|about|"
                      r"regarding)?\s*", "", text, flags=re.I)
        text = re.sub(r"^.{0,90}?has filed\s+", "Filed ", text, flags=re.I)
        val = value_from_text(text)
        if not val and kind in ("Dividend", "Buyback", "Bonus", "Split",
                                "Rights"):
            val = value_from_pdf(r.get("attchmntFile") or "")
        rows.append({"symbol": sym, "kind": kind,
                     "purpose": (text[:220] or kind),
                     "value": val,
                     "exDate": "", "recDate": "",
                     "filed": _corp_day(when) if when else "",
                     "announced": when or "",
                     "source": "filing",
                     "link": r.get("attchmntFile") or "",
                     "id": sym + "|ann|" + kind + "|" + (when or "")})
    CORP_CACHE["recDates"] = recs
    return rows, done


def fetch_results(symbols):
    """Board meetings that will consider financial results, from NSE's
    board-meetings list (checked 10 Oct 2026: HCLTECH 12-Oct "Financial
    Results/Dividend", HDFCBANK 17-Oct "Financial Results"). NSE lists each
    meeting twice - the intimation and the results entry - so one row is
    kept per share per date."""
    today = datetime.date.today()
    url = ("https://www.nseindia.com/api/corporate-board-meetings"
           "?index=equities&from_date=%s&to_date=%s"
           % (today.strftime("%d-%m-%Y"),
              (today + datetime.timedelta(days=30)).strftime("%d-%m-%Y")))
    data, err = SESSION.fetch(url, "https://www.nseindia.com/companies-"
                                   "listing/corporate-filings-board-meetings",
                              timeout=40)
    CORP_CACHE["resErr"] = "" if isinstance(data, list) else (err or "empty")
    best = {}
    for r in (data if isinstance(data, list) else []):
        sym = str(r.get("bm_symbol") or "").upper().strip()
        if sym not in symbols:
            continue
        purpose = str(r.get("bm_purpose") or "")
        desc = str(r.get("bm_desc") or "")
        if "financial result" not in (purpose + " " + desc).lower():
            continue
        iso = _isodate(r.get("bm_date") or "")
        if not iso or iso < today.isoformat():
            continue
        div = "dividend" in (purpose + " " + desc).lower()
        per = re.search(r"(quarter|half[- ]year|year|nine months)[^.]{0,40}?"
                        r"ended\s+(?:on\s+|as on\s+)?([A-Za-z]+)[ ,0-9]*?"
                        r"(\d{4})", desc, re.I)
        if per:
            what = "%s ended %s %s" % (per.group(1).title(),
                                       per.group(2)[:3].title(), per.group(3))
        else:
            # the last quarter-end before the meeting is the one reported
            md = datetime.date.fromisoformat(iso)
            qm = ((md.month - 1) // 3) * 3 or 12
            qy = md.year if qm != 12 else md.year - 1
            what = "Quarter ended %s %d" % (
                datetime.date(2000, qm, 1).strftime("%b"), qy)
        key = (sym, iso)
        row = {"symbol": sym, "kind": "Results",
               "purpose": "Board meeting to approve the results" +
                          (" - and a dividend" if div else ""),
               "value": what, "exDate": r.get("bm_date") or "",
               "recDate": "", "meeting": True,
               "filed": _corp_day(_isodate(r.get("bm_timestamp") or "")
                                  or ""),
               "announced": _isodate(r.get("bm_timestamp") or "") or "",
               "exIso": iso, "source": "meeting",
               "daysTo": (datetime.date.fromisoformat(iso) - today).days,
               "link": r.get("attachment") or "",
               "id": sym + "|Results|" + iso}
        # the "Financial Results" entry wins over the bare intimation
        if key not in best or "result" in purpose.lower():
            best[key] = row
    return list(best.values())


def fetch_corp_actions(force=False):
    """Two NSE feeds, merged per share and per event.

    1. The dated corporate-actions list - ONE call for every company from a
       week ago to six months ahead. Every row carries its ex-date and
       record date, and the value is in the wording ("Dividend - Rs 1.50
       Per Share"). This is what the panel was missing: rows came from the
       filings feed, which has no ex-date, so the date column showed a dash.
    2. Filings (announcements) - for an event that is declared but not yet
       dated. Kept until the dated row appears, then the dated row wins.
    """
    if not force and stale_ok("corp", bool(CORP_CACHE["rows"]),
                              time.time() - CORP_CACHE["at"] < 1800,
                              lambda: fetch_corp_actions(True),
                              time.time() - CORP_CACHE["at"] > 5400):
        return CORP_CACHE["rows"]
    with CORP_READ_LOCK:                 # one reading at a time
        if not force and CORP_CACHE["rows"] and \
                time.time() - CORP_CACHE["at"] < 1800:
            return CORP_CACHE["rows"]
        return _fetch_corp_now()


CORP_READ_LOCK = threading.Lock()


def _fetch_corp_now():
    st = load_state()
    want = {s.upper() for s in corp_symbols(st)}
    today = datetime.date.today()
    rows = []
    url = ("https://www.nseindia.com/api/corporates-corporateActions"
           "?index=equities&from_date=%s&to_date=%s"
           % ((today - datetime.timedelta(days=7)).strftime("%d-%m-%Y"),
              (today + datetime.timedelta(days=180)).strftime("%d-%m-%Y")))
    data, err = SESSION.fetch(url, "https://www.nseindia.com/companies-"
                                   "listing/corporate-filings-actions",
                              timeout=30)
    CORP_CACHE["actErr"] = "" if isinstance(data, list) else (err or "empty")
    for r in (data if isinstance(data, list) else []):
        sym = str(r.get("symbol") or "").upper().strip()
        if sym not in want:
            continue
        subj = re.sub(r"\s+", " ", str(r.get("subject") or "")).strip()
        kind = _corp_kind(subj)
        if not kind:
            continue                     # AGMs, demergers etc are not wanted
        exd = _isodate(r.get("exDate") or "")
        if not exd or exd < today.isoformat():
            continue                     # already gone ex - over
        rec = r.get("recDate") or ""
        rows.append({"symbol": sym, "kind": kind, "purpose": subj,
                     "value": value_from_text(subj),
                     "exDate": r.get("exDate") or "",
                     "recDate": "" if rec in ("-", None) else rec,
                     "filed": "", "announced": "",
                     "exIso": exd, "source": "dated",
                     "daysTo": (datetime.date.fromisoformat(exd)
                                - today).days,
                     "id": sym + "|" + kind + "|" + (r.get("exDate") or "")})
    try:
        ann, finished = fetch_announcements(want)
    except Exception:
        ann, finished = [], set()
    dated_kinds = {(r["symbol"], r["kind"]) for r in rows}
    newest = {}
    for r in ann:
        key = (r["symbol"], r["kind"])
        if key in dated_kinds:
            # the dated row is the real thing; borrow the filing's date and
            # its figure if the dated wording lacks one
            for d in rows:
                if (d["symbol"], d["kind"]) == key:
                    d["filed"] = d["filed"] or r["filed"]
                    d["announced"] = d["announced"] or r["announced"]
                    d["link"] = d.get("link") or r["link"]
                    d["value"] = d["value"] or r["value"]
            continue
        if key in finished:
            continue                     # buyback closed - nothing to watch
        if key not in newest or r["announced"] > newest[key]["announced"]:
            newest[key] = r
    # RESULTS: the board meetings NSE lists for the next 30 days. Shown for
    # every share he holds or follows (the corporate-actions scope) and for
    # the rows he is buying today - a result the morning after a 3:20 buy
    # is exactly what he needs to see before buying
    try:
        rows += fetch_results(want | {s.upper()
                                      for s in active_symbols(st)})
    except Exception:
        CORP_CACHE["resErr"] = "results: failed"
    # a record date the company itself has filed, ahead of NSE's dated list
    recs = CORP_CACHE.get("recDates") or {}
    for key, r in list(newest.items()):
        rec = recs.get(key)
        # a company often files the record date a few days BEFORE the board
        # declares the dividend (Vedanta: 5 Oct and 8 Oct), so the test is
        # that the record date itself falls after the declaration
        if not rec or (r["announced"] and rec[0] < r["announced"][:10]):
            continue                     # none, or belongs to an older event
        if rec[0] < today.isoformat():
            newest.pop(key)              # record date passed - over
            continue
        day = _corp_day(rec[0])
        # T+1 settlement: the ex-date is the record date itself
        r.update({"recDate": day, "exDate": day, "exIso": rec[0],
                  "daysTo": (datetime.date.fromisoformat(rec[0])
                             - today).days,
                  "recFrom": "the company's filing"})
    rows += list(newest.values())
    # Grouped, as he asked once results made the list crowded: buybacks,
    # then dividends, then bonuses, then everything else, and results last.
    # Inside each group the soonest date first, then the ones not yet dated,
    # newest filing first.
    group = {"Buyback": 0, "Dividend": 1, "Bonus": 2, "Results": 9}

    def order(r):
        g = group.get(r.get("kind"), 5)
        return (g, 0 if r.get("exIso") else 1, r.get("exIso") or "",
                "" if r.get("exIso") else
                "".join(chr(255 - ord(c)) for c in (r.get("announced") or "")))
    rows.sort(key=order)
    CORP_CACHE.update({"at": time.time(), "rows": rows})
    return rows


# ---------------------------------------------------------------------------
# WHAT THE MARKET EXPECTS FROM THE RESULTS
#
# Before a company reports, brokerages publish previews ("PAT may rise 13%",
# "muted quarter seen"). For each RESULTS row due in the next two weeks the
# dashboard reads the preview headlines from Google News, and Gemini (his
# Ask key) sums them up in one word and one line: STRONG, MODERATE, WEAK or
# MIXED, with the figures quoted. Without Gemini a simple word count of the
# headlines is used. Read again every six hours (two, in the last two days).
# ---------------------------------------------------------------------------

PREVIEW_FILE = os.path.join(DATA_DIR, "result_previews.json")
PREVIEWS = {"data": None, "lock": threading.Lock()}
PREVIEW_WORDS = ("preview", "expect", "estimate", "likely", " may ", "seen ",
                 "ahead of", "what to watch", "to report", "forecast", "poll",
                 "brokerages", "could ", "set to", "things to watch")
PREVIEW_STYLE = (
    "You read Indian business-news headlines about a company's quarterly "
    "results that are still to come. From ONLY these headlines, say what "
    "analysts and brokerages expect for this company. Reply with one line of "
    "JSON and nothing else: {\"verdict\": \"STRONG\" or \"MODERATE\" or "
    "\"WEAK\" or \"MIXED\" or \"UNCLEAR\", \"why\": \"at most 22 words, "
    "with any figures the headlines give, e.g. profit seen up 13% YoY\"}. "
    "Use UNCLEAR if the headlines do not say what is expected.\n\n")


def previews():
    with PREVIEWS["lock"]:
        if PREVIEWS["data"] is None:
            PREVIEWS["data"] = _read_json(PREVIEW_FILE, {})
        return PREVIEWS["data"]


def quarter_of(value, iso):
    """'Quarter ended Sep 2026' -> ('Q2', 'FY27'). India's year runs April
    to March."""
    m = re.search(r"(Jun|Sep|Dec|Mar)[a-z]* (\d{4})", value or "")
    if not m:
        d = datetime.date.fromisoformat(iso)
        qm = ((d.month - 1) // 3) * 3 or 12
        mon, yr = datetime.date(2000, qm, 1).strftime("%b"), \
            (d.year if qm != 12 else d.year - 1)
    else:
        mon, yr = m.group(1), int(m.group(2))
    q = {"Jun": "Q1", "Sep": "Q2", "Dec": "Q3", "Mar": "Q4"}[mon]
    fy = yr + 1 if mon != "Mar" else yr
    return q, "FY%02d" % (fy % 100)


def short_company(sym):
    with CACHE_LOCK:
        q = CACHE.get(sym) or {}
    name = q.get("company") or q.get("companyFull") or sym
    name = re.sub(r"\b(limited|ltd\.?|the)\b", "", name, flags=re.I)
    name = re.sub(r"\s+", " ", name).strip(" .,")
    if name.isupper():
        name = " ".join(w if len(w) <= 4 else w.title() for w in name.split())
    return name or sym


def result_preview(sym, iso, value):
    name = short_company(sym)
    q, fy = quarter_of(value, iso)
    others = {"Q1", "Q2", "Q3", "Q4"} - {q}
    key_words = [w for w in re.findall(r"[A-Za-z&]{3,}", name)[:2]]
    seen, heads = set(), []
    for term in ("%s %s results preview" % (name, q),
                 "%s %s %s earnings estimates" % (name, q, fy),
                 "%s %s results expectations brokerages" % (name, q)):
        for h in google_news(term, 15):
            t = h["title"]
            low = " " + t.lower() + " "
            if t in seen or (h.get("age") or 9999) > 24 * 35:
                continue
            if not (all(w.lower() in low for w in key_words) or
                    sym.lower() in low):
                continue
            if not any(w in low for w in PREVIEW_WORDS):
                continue
            if any(o.lower() in low for o in others) and q.lower() not in low:
                continue                         # another quarter's preview
            seen.add(t)
            heads.append({"title": t, "source": h.get("source", ""),
                          "age": h.get("age"), "link": h.get("link", "")})
        time.sleep(0.6)
    heads.sort(key=lambda h: h.get("age") or 9999)
    heads = heads[:8]
    out = {"verdict": "NONE", "why": "No preview found yet for %s %s." %
           (q, fy), "heads": heads, "at": time.time(), "q": "%s %s" % (q, fy),
           "by": ""}
    if not heads:
        return out
    text, _err = ask_gemini("Company: %s (%s). Results: %s %s.\nHeadlines:\n"
                            % (name, sym, q, fy) +
                            "\n".join("- " + h["title"] for h in heads),
                            style=PREVIEW_STYLE)
    m = re.search(r"\{.*\}", text or "", re.S)
    if m:
        try:
            j = json.loads(m.group(0))
            v = str(j.get("verdict") or "").upper()
            if v in ("STRONG", "MODERATE", "WEAK", "MIXED", "UNCLEAR"):
                out.update(verdict=v, why=str(j.get("why") or "")[:200],
                           by="gemini")
                return out
        except Exception:
            pass
    # no Gemini: count the tone of the headlines
    good = bad = 0
    for h in heads:
        low = h["title"].lower()
        good += len(re.findall(r"strong|robust|healthy|rise|jump|grow|beat|"
                               r"surge|double-digit|up \d", low))
        bad += len(re.findall(r"weak|muted|decline|fall|drop|pressure|soft|"
                              r"subdued|slow|miss|dip|down \d", low))
    v = ("STRONG" if good > bad * 2 and good >= 2 else
         "WEAK" if bad > good * 2 and bad >= 2 else
         "MIXED" if good and bad else "MODERATE" if good or bad else "UNCLEAR")
    out.update(verdict=v, why="From the tone of %d preview headline%s."
               % (len(heads), "" if len(heads) == 1 else "s"), by="headlines")
    return out


def preview_watcher():
    """Results due soonest first, four at a time, so the verdicts are there
    within a few minutes of starting rather than an hour."""
    from concurrent.futures import ThreadPoolExecutor
    time.sleep(25)
    pool = ThreadPoolExecutor(max_workers=4)
    while STATS["running"]:
        try:
            if not CORP_CACHE.get("rows"):
                try:
                    fetch_corp_actions()
                except Exception:
                    pass
            rows = [r for r in (CORP_CACHE.get("rows") or [])
                    if r.get("kind") == "Results"
                    and 0 <= (r.get("daysTo") if r.get("daysTo") is not None
                              else 99) <= 14]
            data = previews()
            due = []
            for r in sorted(rows, key=lambda r: r.get("daysTo") or 0):
                k = r["symbol"] + "|" + r["exIso"]
                old = data.get(k) or {}
                # nothing found yet: tried again sooner
                every = (2 * 3600 if (r.get("daysTo") or 0) <= 2 or
                         old.get("verdict") in (None, "NONE", "UNCLEAR")
                         else 6 * 3600)
                if time.time() - (old.get("at") or 0) >= every:
                    due.append(r)

            def one(r):
                res = result_preview(r["symbol"], r["exIso"], r.get("value"))
                with PREVIEWS["lock"]:
                    data[r["symbol"] + "|" + r["exIso"]] = res
            list(pool.map(one, due))
            if due:
                with PREVIEWS["lock"]:
                    cut = (datetime.date.today() -
                           datetime.timedelta(days=3)).isoformat()
                    for kk in [x for x in data if x.split("|")[-1] < cut]:
                        data.pop(kk, None)
                    _write_json(PREVIEW_FILE, data)
        except Exception:
            pass
        for _ in range(600):
            if not STATS["running"]:
                return
            time.sleep(1)


def corp_payload(mark=False):
    rows = fetch_corp_actions()
    fresh = [r for r in rows if r["id"] not in CORP_CACHE["seen"]]
    if mark:
        now = time.time()
        with CORP_SEEN_LOCK:
            for r in rows:
                CORP_CACHE["seen"].setdefault(r["id"], now)
        corp_seen_save()
    st = load_state()
    oldlbl, ylbl = corp_labels(st)
    pv = previews()
    rows = [dict(r, preview=pv.get(r["symbol"] + "|" + r.get("exIso", "")))
            if r.get("kind") == "Results" else r for r in rows]
    return {"rows": rows, "new": len(fresh),
            "newIds": [r["id"] for r in fresh],
            "symbols": len(set(r["symbol"] for r in rows)),
            "watching": len(corp_symbols(st)),
            "watchlist": len(st.get("watchlist") or []),
            "outOfList": len(extra_symbols(st)),
            "feedErrors": [x for x in (CORP_CACHE.get("actErr"),
                                       CORP_CACHE.get("annErr"),
                                       CORP_CACHE.get("resErr")) if x],
            "active": len(active_symbols(st)),
            "oldLabel": oldlbl, "yesterdayLabel": ylbl}



# ---------------------------------------------------------------------------
# FUTURES AND OPTIONS
#
# Everything NSE publishes free. Whatever cannot be fetched is returned with
# a reason rather than left blank, so the panel can say plainly what is
# missing instead of pretending it has nothing to show.
# ---------------------------------------------------------------------------

FNO_CACHE = {"at": 0, "data": {}}
FNO_REF = "https://www.nseindia.com/option-chain"


OC_INDICES = ("NIFTY", "BANKNIFTY", "FINNIFTY", "MIDCPNIFTY", "NIFTYNXT50")



FNO_SYMS = {"at": 0, "list": []}


def fno_symbol_list():
    """Every share that has F&O contracts, so a company name can be turned
    into the ticker NSE expects. He should not have to remember that State
    Bank of India is SBIN."""
    if time.time() - FNO_SYMS["at"] < 86400 and FNO_SYMS["list"]:
        return FNO_SYMS["list"]
    try:
        data, _e = SESSION.fetch(
            "https://www.nseindia.com/api/master-quote", FNO_REF)
        if isinstance(data, list) and data:
            FNO_SYMS.update({"at": time.time(),
                             "list": [str(x).upper() for x in data]})
    except Exception:
        pass
    return FNO_SYMS["list"]


# Names that must never be guessed at. "State Bank of India" resolving to
# SBICARD could have had him trading the wrong company on the wrong numbers.
NAME_ALIASES = {
    "STATEBANKOFINDIA": "SBIN", "STATEBANK": "SBIN", "SBI": "SBIN",
    "SBIBANK": "SBIN", "SBICARDS": "SBICARD", "SBILIFEINSURANCE": "SBILIFE",
    "HDFC": "HDFCBANK", "ICICI": "ICICIBANK", "AXIS": "AXISBANK",
    "KOTAK": "KOTAKBANK", "KOTAKMAHINDRABANK": "KOTAKBANK",
    "INFOSYS": "INFY", "LARSENANDTOUBRO": "LT", "LARSENTOUBRO": "LT",
    "RELIANCEINDUSTRIES": "RELIANCE", "TATACONSULTANCYSERVICES": "TCS",
    "BAJAJFINANCE": "BAJFINANCE", "BAJAJFINSERV": "BAJAJFINSV",
    "MARUTISUZUKI": "MARUTI", "HINDUSTANUNILEVER": "HINDUNILVR",
    "BHARTIAIRTEL": "BHARTIARTL", "MAHINDRAANDMAHINDRA": "M&M",
    "LIFEINSURANCECORPORATION": "LICI", "POWERGRIDCORPORATION": "POWERGRID",
    "ULTRATECHCEMENT": "ULTRACEMCO", "ASIANPAINTS": "ASIANPAINT",
}


def resolve_fno_symbol(text):
    """Turn what he typed into a ticker, and say how sure we are.

    Returns (symbol, exact). "State Bank of India" used to become SBICARD:
    the initials SB matched SBICARD, SBILIFE and SBIN equally and whichever
    NSE listed first won. That is wrong-company data with nothing on screen
    to show it. Exactness is now returned so the panel can display the
    ticker it actually resolved to.
    """
    t = re.sub(r"[^A-Za-z0-9 &]", " ", str(text or "NIFTY")).strip().upper()
    if not t:
        return "NIFTY", True
    flat = t.replace(" ", "")

    if flat in NAME_ALIASES:
        return NAME_ALIASES[flat], True
    if flat in OC_INDICES:
        return flat, True

    syms = fno_symbol_list()
    if flat in syms:
        return flat, True                  # he typed the ticker itself
    st = load_state()
    for sym in (st.get("watchlist") or []):
        if sym.upper() == flat:
            return flat, True
    if not syms:
        return flat, True

    stop = {"OF", "THE", "AND", "LTD", "LIMITED", "INDIA", "CO", "CORP",
            "INDUSTRIES", "COMPANY"}
    words = [w for w in t.split() if w not in stop and len(w) > 1]
    initials = "".join(w[0] for w in words)

    scored = []
    for sym in syms:
        sc = 0
        if sym == flat:
            sc = 100
        elif flat.startswith(sym) or sym.startswith(flat):
            sc = 80 - abs(len(sym) - len(flat))
        elif initials and len(initials) > 1 and sym.startswith(initials):
            sc = 70
        elif words and sym.startswith(words[0][:4]):
            sc = 60 + (10 if len(words) == 1 else 0)
        elif words and len(words[0]) > 3 and words[0][:5] in sym:
            sc = 40
        if sc:
            scored.append((sc, len(sym), sym))
    if not scored:
        return flat, False
    # highest score, then the SHORTEST symbol - SBIN beats SBICARD instead
    # of losing to whichever NSE happened to list first
    scored.sort(key=lambda x: (-x[0], x[1], x[2]))
    best = scored[0]
    tied = [x for x in scored if x[0] == best[0]]
    exact = (best[0] >= 100) or (len(tied) == 1 and best[0] >= 80)
    return best[2], exact


def oc_expiries(sym):
    """NSE serves the expiry list separately now, and the chain call needs
    one of these dates. Found from his own developer-tab capture."""
    url = ("https://www.nseindia.com/api/option-chain-contract-info?symbol="
           + urllib.parse.quote(sym))
    try:
        data, err = SESSION.fetch(url, FNO_REF)
        if isinstance(data, dict):
            for k in ("expiryDates", "expiry", "expiryDatesByInstrument"):
                v = data.get(k)
                if isinstance(v, list) and v:
                    return [str(x) for x in v], ""
                if isinstance(v, dict):
                    for vv in v.values():
                        if isinstance(vv, list) and vv:
                            return [str(x) for x in vv], ""
        return [], err or "no expiry list"
    except Exception as e:
        return [], str(e)[:100]


def _oc_url(sym, expiry):
    """The v3 endpoint. The old option-chain-indices / -equities paths no
    longer return anything, which is why every F&O request came back empty."""
    sym = (sym or "NIFTY").upper()
    kind = "Indices" if sym in OC_INDICES else "Equity"
    return ("https://www.nseindia.com/api/option-chain-v3?type=%s&symbol=%s"
            "&expiry=%s" % (kind, urllib.parse.quote(sym),
                            urllib.parse.quote(expiry)))


def fno_chain(sym="NIFTY", force=False, want_expiry=""):
    """The option chain, and everything that can be worked out from it."""
    sym, exact = resolve_fno_symbol(sym)
    out = {"symbol": sym, "exact": exact, "ok": False}
    exps, eerr = oc_expiries(sym)
    if not exps:
        out["error"] = "no expiries for %s (%s)" % (sym, eerr)
        return out
    out["expiries"] = exps[:8]
    use = want_expiry if want_expiry in exps else exps[0]
    try:
        data, err = SESSION.fetch(_oc_url(sym, use), FNO_REF)
        if not isinstance(data, dict) or not (data.get("records")
                                              or data.get("data")):
            out["error"] = err or "no chain returned"
            return out
    except Exception as e:
        out["error"] = str(e)[:120]
        return out

    rec = data.get("records") or {}
    fil = data.get("filtered") or {}
    rows = (fil.get("data") or rec.get("data") or data.get("data") or [])
    spot = (to_number(rec.get("underlyingValue"))
            or to_number(data.get("underlyingValue")))
    out["spot"] = spot
    out["expiry"] = use

    ce_oi = to_number((fil.get("CE") or {}).get("totOI"))
    pe_oi = to_number((fil.get("PE") or {}).get("totOI"))
    if not (ce_oi and pe_oi):
        ce_oi = sum(to_number((r.get("CE") or {}).get("openInterest")) or 0
                    for r in rows)
        pe_oi = sum(to_number((r.get("PE") or {}).get("openInterest")) or 0
                    for r in rows)
    out["callOI"], out["putOI"] = ce_oi, pe_oi
    out["pcr"] = round(pe_oi / ce_oi, 2) if ce_oi else None

    # max pain: the strike where option writers lose least
    strikes = sorted({to_number(r.get("strikePrice")) for r in rows
                      if r.get("strikePrice")})
    pain, best = None, None
    for k in strikes:
        loss = 0.0
        for r in rows:
            sp = to_number(r.get("strikePrice"))
            if sp is None:
                continue
            c = to_number((r.get("CE") or {}).get("openInterest")) or 0
            p = to_number((r.get("PE") or {}).get("openInterest")) or 0
            if k > sp:
                loss += (k - sp) * c
            if k < sp:
                loss += (sp - k) * p
        if best is None or loss < best:
            best, pain = loss, k
    out["maxPain"] = pain

    # the walls: biggest open interest either side
    tops = []
    for side in ("CE", "PE"):
        rr = sorted(rows, key=lambda r: to_number(
            (r.get(side) or {}).get("openInterest")) or 0, reverse=True)[:3]
        for r in rr:
            d = r.get(side) or {}
            tops.append({"side": side, "strike": to_number(r.get("strikePrice")),
                         "oi": to_number(d.get("openInterest")),
                         "chg": to_number(d.get("changeinOpenInterest")),
                         "iv": to_number(d.get("impliedVolatility"))})
    out["topOI"] = tops

    # the at-the-money straddle - what the market expects the move to be
    if spot and strikes:
        atm = min(strikes, key=lambda k: abs(k - spot))
        out["atm"] = atm
        for r in rows:
            if to_number(r.get("strikePrice")) == atm:
                c = to_number((r.get("CE") or {}).get("lastPrice")) or 0
                p = to_number((r.get("PE") or {}).get("lastPrice")) or 0
                out["straddle"] = round(c + p, 2)
                out["atmIV"] = to_number((r.get("CE") or {}).get(
                    "impliedVolatility"))
                break

    # what the day's open interest change is saying
    dc = sum(to_number((r.get("CE") or {}).get("changeinOpenInterest")) or 0
             for r in rows)
    dp = sum(to_number((r.get("PE") or {}).get("changeinOpenInterest")) or 0
             for r in rows)
    out["callOIChg"], out["putOIChg"] = dc, dp
    out["bias"] = ("Puts being written - supportive" if dp > dc * 1.15 else
                   "Calls being written - capped" if dc > dp * 1.15 else
                   "Balanced")

    # days to expiry, and what the straddle implies as a daily move
    try:
        ed = datetime.datetime.strptime(use, "%d-%b-%Y").date()
        out["daysToExpiry"] = (ed - datetime.date.today()).days
    except Exception:
        out["daysToExpiry"] = None
    if out.get("straddle") and spot:
        out["expectedMovePct"] = round(out["straddle"] / spot * 100, 2)
        out["expectedMove"] = out["straddle"]

    # the support and resistance the option writers have drawn
    puts = [r for r in rows if (r.get("PE") or {}).get("openInterest")]
    calls = [r for r in rows if (r.get("CE") or {}).get("openInterest")]
    if puts:
        out["support"] = to_number(max(puts, key=lambda r: to_number(
            (r.get("PE") or {}).get("openInterest")) or 0).get("strikePrice"))
    if calls:
        out["resistance"] = to_number(max(calls, key=lambda r: to_number(
            (r.get("CE") or {}).get("openInterest")) or 0).get("strikePrice"))

    try:
        ed = datetime.datetime.strptime(use, "%d-%b-%Y").date()
        out["daysToExpiry"] = (ed - datetime.date.today()).days
    except Exception:
        pass

    # the whole visible chain, so he can read it strike by strike.
    # Field names checked against NSE's live v3 reply on 9 Oct: the best bid
    # and offer are buyPrice1/sellPrice1 with buyQuantity1/sellQuantity1.
    # The old bidprice/askPrice names do not exist, which is why BID and ASK
    # were blank in every row.
    def leg_num(leg, *names):
        for nm in names:
            v = to_number(leg.get(nm))
            if v is not None:
                return v
        return None

    def buildup(price_chg, oi_chg):
        if price_chg is None or oi_chg is None or (not price_chg
                                                   and not oi_chg):
            return ""
        if price_chg >= 0 and oi_chg > 0:
            return "Long build-up"
        if price_chg < 0 and oi_chg > 0:
            return "Short build-up"
        if price_chg > 0 and oi_chg < 0:
            return "Short covering"
        if price_chg < 0 and oi_chg < 0:
            return "Long unwinding"
        return ""

    chain = []
    for r in sorted(rows, key=lambda r: to_number(r.get("strikePrice")) or 0):
        ce, pe = r.get("CE") or {}, r.get("PE") or {}
        k = to_number(r.get("strikePrice"))
        if spot and k and abs(k - spot) > spot * 0.06:
            continue                       # keep it near the money
        g_ce = black_scholes_greeks(spot, k, out.get("daysToExpiry") or 1,
                                    to_number(ce.get("impliedVolatility")),
                                    True)
        g_pe = black_scholes_greeks(spot, k, out.get("daysToExpiry") or 1,
                                    to_number(pe.get("impliedVolatility")),
                                    False)
        chain.append({
            "strike": k,
            "ceDelta": g_ce.get("delta"), "peDelta": g_pe.get("delta"),
            "ceTheta": g_ce.get("theta"), "peTheta": g_pe.get("theta"),
            "gamma": g_ce.get("gamma"), "vega": g_ce.get("vega"),
            "ceOI": to_number(ce.get("openInterest")),
            "ceChg": to_number(ce.get("changeinOpenInterest")),
            "ceIV": to_number(ce.get("impliedVolatility")),
            "ceLtp": to_number(ce.get("lastPrice")),
            "ceVol": to_number(ce.get("totalTradedVolume")),
            "ceBid": leg_num(ce, "buyPrice1", "bidprice", "bidPrice"),
            "ceAsk": leg_num(ce, "sellPrice1", "askPrice", "askprice"),
            "ceBidQty": leg_num(ce, "buyQuantity1", "bidQty"),
            "ceAskQty": leg_num(ce, "sellQuantity1", "askQty"),
            "ceLtpChg": leg_num(ce, "change"),
            "ceLtpPct": leg_num(ce, "pChange", "PChange"),
            "ceTotBuy": leg_num(ce, "totalBuyQuantity"),
            "ceTotSell": leg_num(ce, "totalSellQuantity"),
            "ceBuild": buildup(leg_num(ce, "change"),
                               leg_num(ce, "changeinOpenInterest")),
            "ceOIPct": (round(leg_num(ce, "pchangeinOpenInterest"), 1)
                        if leg_num(ce, "pchangeinOpenInterest") is not None
                        else None),
            "ceGamma": g_ce.get("gamma"), "ceVega": g_ce.get("vega"),
            "peOI": to_number(pe.get("openInterest")),
            "peChg": to_number(pe.get("changeinOpenInterest")),
            "peIV": to_number(pe.get("impliedVolatility")),
            "peLtp": to_number(pe.get("lastPrice")),
            "peVol": to_number(pe.get("totalTradedVolume")),
            "peBid": leg_num(pe, "buyPrice1", "bidprice", "bidPrice"),
            "peAsk": leg_num(pe, "sellPrice1", "askPrice", "askprice"),
            "peBidQty": leg_num(pe, "buyQuantity1", "bidQty"),
            "peAskQty": leg_num(pe, "sellQuantity1", "askQty"),
            "peLtpChg": leg_num(pe, "change"),
            "peLtpPct": leg_num(pe, "pChange", "PChange"),
            "peTotBuy": leg_num(pe, "totalBuyQuantity"),
            "peTotSell": leg_num(pe, "totalSellQuantity"),
            "peBuild": buildup(leg_num(pe, "change"),
                               leg_num(pe, "changeinOpenInterest")),
            "peOIPct": (round(leg_num(pe, "pchangeinOpenInterest"), 1)
                        if leg_num(pe, "pchangeinOpenInterest") is not None
                        else None),
            "peGamma": g_pe.get("gamma"), "peVega": g_pe.get("vega"),
        })
    out["chainRows"] = chain[:24]

    # cost of carry: the futures premium annualised, which tells him whether
    # the roll is cheap or dear
    if out.get("spot") and out.get("daysToExpiry"):
        out["carryReady"] = True

    # the option-interest picture as bars, for the charts
    # where an at-the-money straddle stops losing money
    if out.get("atm") and out.get("straddle"):
        out["breakEvenUp"] = round(out["atm"] + out["straddle"], 1)
        out["breakEvenDn"] = round(out["atm"] - out["straddle"], 1)
    # where today's implied volatility sits against the rest of the chain
    ivs = sorted(x for x in (to_number((r.get("CE") or {})
                 .get("impliedVolatility")) for r in rows) if x)
    atm_iv = to_number(out.get("atmIV"))
    if ivs and atm_iv:
        below = sum(1 for x in ivs if x <= atm_iv)
        out["ivPercentile"] = int(round(below / len(ivs) * 100))

    # what is sitting in the money against out of the money, both sides
    agg = {"itmOI": 0, "itmChg": 0, "itmVol": 0,
           "otmOI": 0, "otmChg": 0, "otmVol": 0}
    for r in rows:
        k = to_number(r.get("strikePrice"))
        if not (k and spot):
            continue
        for side, itm in (("CE", k < spot), ("PE", k > spot)):
            leg = r.get(side) or {}
            tag = "itm" if itm else "otm"
            agg[tag + "OI"] += to_number(leg.get("openInterest")) or 0
            agg[tag + "Chg"] += to_number(leg.get("changeinOpenInterest")) or 0
            agg[tag + "Vol"] += to_number(leg.get("totalTradedVolume")) or 0
    for tag in ("itm", "otm"):
        base = agg[tag + "OI"] - agg[tag + "Chg"]
        agg[tag + "Pct"] = (round(agg[tag + "Chg"] / base * 100, 1)
                            if base else None)
    out["aggregates"] = agg

    # ATM implied volatility, taken as the mean of the call and the put
    # rather than silently using the call alone
    for r in rows:
        if to_number(r.get("strikePrice")) == out.get("atm"):
            civ = to_number((r.get("CE") or {}).get("impliedVolatility"))
            piv = to_number((r.get("PE") or {}).get("impliedVolatility"))
            both = [x for x in (civ, piv) if x]
            if both:
                out["atmIV"] = round(sum(both) / len(both), 2)
                out["atmIVCall"] = civ
                out["atmIVPut"] = piv
            break

    # the change since the last time this chain was read, and since the
    # first reading today - PCR and ATM IV on their own say little without
    # the direction they are moving in
    key = sym + "|" + use
    hist = FNO_HIST.setdefault(key, {})
    day = datetime.date.today().isoformat()
    if hist.get("day") != day:
        hist.clear()
        hist.update({"day": day, "firstPcr": out.get("pcr"),
                     "firstIv": out.get("atmIV"),
                     "firstAt": time.strftime("%H:%M")})
    prev = hist.get("last") or {}
    if prev:
        if prev.get("pcr") is not None and out.get("pcr") is not None:
            out["pcrChg"] = round(out["pcr"] - prev["pcr"], 2)
        if prev.get("iv") and out.get("atmIV"):
            out["ivChg"] = round(out["atmIV"] - prev["iv"], 2)
            out["ivChgPct"] = round((out["atmIV"] - prev["iv"]) /
                                    prev["iv"] * 100, 1)
        out["prevAt"] = prev.get("at")
    if hist.get("firstPcr") is not None and out.get("pcr") is not None:
        out["pcrDayChg"] = round(out["pcr"] - hist["firstPcr"], 2)
    if hist.get("firstIv") and out.get("atmIV"):
        out["ivDayChg"] = round(out["atmIV"] - hist["firstIv"], 2)
    out["firstAt"] = hist.get("firstAt")
    if not prev or time.time() - prev.get("t", 0) > 60:
        hist["last"] = {"pcr": out.get("pcr"), "iv": out.get("atmIV"),
                        "at": time.strftime("%H:%M"), "t": time.time()}
    # a PCR the day can be read by
    pcr = out.get("pcr")
    if pcr is not None:
        out["pcrRead"] = ("Bullish - puts heavily written" if pcr >= 1.3 else
                          "Mildly bullish" if pcr >= 1.0 else
                          "Mildly bearish" if pcr >= 0.7 else
                          "Bearish - calls heavily written")

    out["oiBars"] = [{"strike": r["strike"], "ce": r["ceOI"] or 0,
                      "pe": r["peOI"] or 0, "ceChg": r["ceChg"] or 0,
                      "peChg": r["peChg"] or 0} for r in chain]
    out["ok"] = True
    return out


FUT_CACHE = {"at": 0, "rows": {}}
FNO_HIST = {}          # symbol|expiry -> first and last PCR / ATM IV today



LOTS = {"at": 0, "map": {}}


def lot_sizes():
    """Every F&O lot size, from NSE's own market-lots file. The derivatives
    quote does not carry it, which is why the margin stayed blank: margin is
    price x lot, and the lot was missing."""
    if time.time() - LOTS["at"] < 6 * 3600 and LOTS["map"]:
        return LOTS["map"]
    out = {}
    for url in ("https://nsearchives.nseindia.com/content/fo/fo_mktlots.csv",
                "https://www1.nseindia.com/content/fo/fo_mktlots.csv"):
        try:
            raw = RPT_SESSION.get_raw(url, "https://www.nseindia.com/")
            txt = raw.decode("utf-8", "replace")
            for ln in txt.splitlines()[1:]:
                cells = [c.strip() for c in ln.split(",")]
                if len(cells) < 3 or not cells[1]:
                    continue
                sym = cells[1].upper()
                for c in cells[2:]:
                    n = to_number(c)
                    if n:
                        out[sym] = int(n)      # the nearest month with a lot
                        break
            if out:
                LOTS.update({"at": time.time(), "map": out})
                break
        except Exception:
            continue
    return LOTS["map"]


def black_scholes_greeks(spot, strike, days, iv, is_call):
    """Delta, gamma, theta and vega. NSE publishes none of them, but they
    follow from the chain's own implied volatility."""
    try:
        if not (spot and strike and iv and days) or days <= 0:
            return {}
        t = days / 365.0
        v = iv / 100.0
        r = 0.065                       # a reasonable Indian risk-free rate
        if v <= 0 or t <= 0:
            return {}
        d1 = ((math.log(spot / strike) + (r + v * v / 2) * t) /
              (v * math.sqrt(t)))
        d2 = d1 - v * math.sqrt(t)
        nd1 = math.exp(-d1 * d1 / 2) / math.sqrt(2 * math.pi)
        cdf = lambda x: 0.5 * (1 + math.erf(x / math.sqrt(2)))
        delta = cdf(d1) if is_call else cdf(d1) - 1
        gamma = nd1 / (spot * v * math.sqrt(t))
        vega = spot * nd1 * math.sqrt(t) / 100.0
        theta = (-(spot * nd1 * v) / (2 * math.sqrt(t))
                 - (r * strike * math.exp(-r * t) *
                    (cdf(d2) if is_call else cdf(-d2))
                    * (1 if is_call else -1))) / 365.0
        return {"delta": round(delta, 3), "gamma": round(gamma, 5),
                "theta": round(theta, 2), "vega": round(vega, 3)}
    except Exception:
        return {}


def fno_quote(sym):
    """The derivatives quote, from the path his developer tab revealed:
    NextApi/apiClient/GetQuoteApi?functionName=getSymbolDerivativesData.
    The plain quote-derivative path answers 404."""
    url = ("https://www.nseindia.com/api/NextApi/apiClient/GetQuoteApi"
           "?functionName=getSymbolDerivativesData&symbol="
           + urllib.parse.quote(sym))
    try:
        data, err = SESSION.fetch(url, "https://www.nseindia.com/get-quotes/"
                                       "derivatives?symbol=" + sym)
        return data, err
    except Exception as e:
        return None, str(e)[:110]


def _deep_rows(node, out, depth=0):
    """The reply nests the contract list differently for indices and shares,
    so every list of dicts is collected and the futures picked out."""
    if depth > 6:
        return
    if isinstance(node, list):
        if node and isinstance(node[0], dict):
            out.append(node)
        for v in node[:40]:
            _deep_rows(v, out, depth + 1)
    elif isinstance(node, dict):
        for v in node.values():
            _deep_rows(v, out, depth + 1)


def fut_all():
    """Every stock and index future in one call - the per-symbol
    quote-derivative path was answering 404."""
    if time.time() - FUT_CACHE["at"] < 180 and FUT_CACHE["rows"]:
        return FUT_CACHE["rows"]
    out = {}
    for idx in ("stock_fut", "index_fut"):
        try:
            data, _e = SESSION.fetch(
                "https://www.nseindia.com/api/liveEquity-derivatives?index="
                + idx, FNO_REF)
            for r in ((data or {}).get("data") or []):
                sym = str(r.get("underlying") or r.get("symbol") or "").upper()
                if not sym or sym in out:
                    continue
                out[sym] = r
        except Exception:
            continue
    if out:
        FUT_CACHE.update({"at": time.time(), "rows": out})
    return FUT_CACHE["rows"]


def fno_futures(sym):
    """Futures price, basis, open interest, lot size and what the day's
    price-against-OI move is saying."""
    out = {"ok": False}
    data, err = fno_quote(sym)
    if not data:
        rows = fut_all()
        r = rows.get(sym.upper())
        if not r:
            out["error"] = err or "no futures data"
            return out
        data = {"stocks": [{"metadata": r}]}

    lists = []
    _deep_rows(data, lists)
    futs = []
    for lst in lists:
        for r in lst:
            m = r.get("metadata") if isinstance(r.get("metadata"), dict) else r
            it = str(m.get("instrumentType") or m.get("instrument") or "")
            if "FUT" not in it.upper():
                continue
            ltp = to_number(m.get("lastPrice") or m.get("ltp"))
            if not ltp:
                continue
            futs.append((_isodate(m.get("expiryDate") or "") or "9999", m, r))
    if not futs:
        out["error"] = "no futures contract in the reply"
        return out
    futs.sort(key=lambda x: x[0])
    # every month on offer - near, next and far - for the roll
    out["contracts"] = [{
        "expiry": m.get("expiryDate"),
        "ltp": to_number(m.get("lastPrice")),
        "chg": to_number(m.get("change")),
        "pct": to_number(m.get("pChange") or m.get("pchange")),
        "oi": to_number(m.get("openInterest")),
        "oiChg": to_number(m.get("changeinOpenInterest")),
        "vol": to_number(m.get("totalTradedVolume"))}
        for _d, m, _r in futs[:3]]
    _d, m, r = futs[0]
    depth = r.get("marketDeptOrderBook") or {}
    trade = depth.get("tradeInfo") or {}
    ltp = to_number(m.get("lastPrice") or m.get("ltp"))
    oi = (to_number(trade.get("openInterest"))
          or to_number(m.get("openInterest")))
    chg = (to_number(trade.get("changeinOpenInterest"))
           or to_number(m.get("changeinOpenInterest")))
    # NSE spells it "pchange" in this reply - reading "pChange" only is why
    # the build-up line never appeared
    pchg = to_number(m.get("pChange") if m.get("pChange") is not None
                     else m.get("pchange"))
    lot = (to_number(m.get("marketLot")) or to_number(m.get("lotSize"))
           or to_number((data or {}).get("marketLot"))
           or lot_sizes().get(sym.upper()))
    spot = (to_number((data or {}).get("underlyingValue"))
            or to_number(m.get("underlyingValue")))
    build = ""
    if pchg is not None and chg is not None:
        build = ("Long buildup" if pchg > 0 and chg > 0 else
                 "Short buildup" if pchg < 0 and chg > 0 else
                 "Short covering" if pchg > 0 and chg < 0 else
                 "Long unwinding" if pchg < 0 and chg < 0 else "")
    out.update({"ok": True, "expiry": m.get("expiryDate"), "ltp": ltp,
                "pChange": (round(pchg, 2) if pchg is not None else None),
                "change": to_number(m.get("change")),
                "open": to_number(m.get("openPrice")),
                "high": to_number(m.get("highPrice")),
                "low": to_number(m.get("lowPrice")),
                "prevClose": to_number(m.get("prevClose")),
                "volume": to_number(m.get("totalTradedVolume")),
                "turnoverCr": (round(to_number(m.get("totalTurnover")) / 1e7,
                                     1) if to_number(m.get("totalTurnover"))
                               else None),
                "oiPct": (round(to_number(m.get("pchangeinOpenInterest")), 2)
                          if to_number(m.get("pchangeinOpenInterest"))
                          is not None else None),
                "oi": oi, "oiChg": chg, "buildup": build,
                "spot": spot, "lotSize": lot,
                "basis": (round(ltp - spot, 2) if (ltp and spot) else None)})
    # cost of carry: the premium annualised, so he can see if the roll is dear
    if ltp and spot and spot:
        try:
            ed = datetime.datetime.strptime(str(m.get("expiryDate")),
                                            "%d-%b-%Y").date()
            days = max(1, (ed - datetime.date.today()).days)
            out["carryPct"] = round((ltp - spot) / spot * (365.0 / days) * 100,
                                    2)
            out["daysToExpiry"] = days
            # rollover only means anything in the last week of a series
            if days <= 7 and oi:
                nxt = None
                for lst in lists:
                    for rr in lst:
                        mm = (rr.get("metadata")
                              if isinstance(rr.get("metadata"), dict) else rr)
                        if "FUT" not in str(mm.get("instrumentType")
                                            or "").upper():
                            continue
                        if str(mm.get("expiryDate")) == str(m.get("expiryDate")):
                            continue
                        o2 = to_number((rr.get("marketDeptOrderBook") or {})
                                       .get("tradeInfo", {})
                                       .get("openInterest")) \
                            or to_number(mm.get("openInterest"))
                        if o2:
                            nxt = (nxt or 0) + o2
                if nxt:
                    out["rolloverPct"] = round(nxt / (oi + nxt) * 100, 1)
        except Exception:
            pass
    return out


def fno_margin(sym, price, lot):
    """Approximate only, and labelled as such. NSE does not publish the
    figure a broker will actually charge - SPAN plus exposure is computed by
    the clearing corporation - so this uses NSE's own applicable margin rate
    where it can, and a conventional rate where it cannot."""
    out = {"ok": False, "approx": True}
    if not (price and lot):
        out["error"] = "need the futures price and lot size first"
        return out
    contract = price * lot
    rate = None
    try:
        data, _e = SESSION.fetch(
            "https://www.nseindia.com/api/quote-equity?symbol="
            + urllib.parse.quote(sym), "https://www.nseindia.com/")
        sec = (data or {}).get("securityInfo") or {}
        rate = to_number(sec.get("applicableMargin"))
    except Exception:
        pass
    src = "NSE applicable margin"
    if not rate:
        # the usual span+exposure band for an index or a large stock future
        rate = 12.0 if sym.upper() in OC_INDICES else 20.0
        src = "typical SPAN + exposure band"
    out.update({"ok": True, "contractValue": round(contract),
                "ratePct": rate, "margin": round(contract * rate / 100.0),
                "source": src,
                "note": "Approximate. Your broker's own calculator is the "
                        "figure that will actually be charged."})
    return out


def fno_ban():
    """Securities barred from fresh F&O positions. His uploaded copy shows
    the file is UNDATED - I was asking for fo_secban_04092026.csv, which
    never exists, so this said "not published" every single day."""
    urls = ["https://nsearchives.nseindia.com/content/fo/fo_secban.csv",
            "https://www1.nseindia.com/content/fo/fo_secban.csv"]
    for url in urls:
        try:
            raw = RPT_SESSION.get_raw(url, "https://www.nseindia.com/")
            txt = raw.decode("utf-8", "replace")
            day, names = "", []
            for ln in txt.splitlines():
                ln = ln.strip()
                if not ln:
                    continue
                m = re.search(r"Trade Date\s*[:\-]?\s*([\d]{1,2}-[A-Za-z]{3}"
                              r"-[\d]{4})", ln, re.I)
                if m:
                    day = m.group(1)
                    continue
                parts = [p.strip() for p in ln.split(",") if p.strip()]
                if len(parts) >= 2 and re.fullmatch(r"\d+", parts[0]):
                    names.append(parts[-1].upper())
                elif len(parts) == 1 and parts[0].isupper() \
                        and parts[0] != "SECURITIES":
                    names.append(parts[0])
            if names:
                return {"ok": True, "day": day, "names": names}
        except Exception:
            continue
    return {"ok": False, "error": "ban file did not answer"}


def fno_participants():
    """Who is holding what in derivatives - FII, DII, pro and retail."""
    d = datetime.date.today()
    # a weekend plus a holiday can put the last file five days back
    for back in range(0, 7):
        day = d - datetime.timedelta(days=back)
        if day.weekday() >= 5:
            continue
        url = ("https://nsearchives.nseindia.com/content/nsccl/"
               "fao_participant_oi_%s.csv" % day.strftime("%d%m%Y"))
        try:
            raw = RPT_SESSION.get_raw(url, "https://www.nseindia.com/")
            txt = raw.decode("utf-8", "replace")
            lines = [l for l in txt.splitlines() if l.strip()]
            head, rows = None, []
            for ln in lines:
                cells = [c.strip() for c in ln.split(",")]
                if not head and any("client type" in c.lower() for c in cells):
                    head = cells
                    continue
                if head and len(cells) >= 4 and cells[0]:
                    rows.append(dict(zip(head, cells)))
            if rows:
                return {"ok": True, "day": day.isoformat(),
                        "head": head, "rows": rows}
        except Exception:
            continue
    return {"ok": False, "error": "participant file not published yet"}


# 20.16: the slow F&O columns of the main table (PCR, max pain, ATM IV) -
# one option chain every few seconds in the background, each kept 4 minutes,
# so the table shows what is known at once and never waits on NSE
FNO_COLS = {"data": {}, "want": [], "busy": False}
FNO_COLS_LOCK = threading.Lock()


def fno_cols(syms):
    now = time.time()
    out = {}
    with FNO_COLS_LOCK:
        for s in syms:
            hit = FNO_COLS["data"].get(s)
            if hit:
                out[s] = hit[1]
            if not hit or now - hit[0] > 240:
                if s not in FNO_COLS["want"]:
                    FNO_COLS["want"].append(s)
        go = FNO_COLS["want"] and not FNO_COLS["busy"]
        if go:
            FNO_COLS["busy"] = True
    if go:
        threading.Thread(target=_fno_cols_fill, daemon=True).start()
    return {"ok": True, "cols": out}


def _fno_cols_fill():
    try:
        while True:
            with FNO_COLS_LOCK:
                if not FNO_COLS["want"]:
                    break
                s = FNO_COLS["want"].pop(0)
            try:
                c = fno_chain(s)
                v = {"pcr": c.get("pcr"), "maxPain": c.get("maxPain"),
                     "iv": c.get("atmIV"), "exp": (c.get("expiries") or
                                                   [""])[0]} \
                    if c.get("ok") else {"err": c.get("error") or "no chain"}
            except Exception as e:
                v = {"err": str(e)[:80]}
            with FNO_COLS_LOCK:
                FNO_COLS["data"][s] = (time.time(), v)
            time.sleep(2)
    finally:
        with FNO_COLS_LOCK:
            FNO_COLS["busy"] = False


def fno_snapshot(sym="NIFTY", force=False, want_expiry=""):
    # the panel re-reads every minute while it is open, so the chain is at
    # most 45 seconds old; the key includes the expiry he picked
    key = (sym.upper(), want_expiry or "")
    if not force and time.time() - FNO_CACHE["at"] < 45 and FNO_CACHE["data"] \
            and FNO_CACHE.get("key") == key:
        return FNO_CACHE["data"]
    vix = TICKER["last"].get("INDIA VIX") or {}
    if not vix.get("last"):
        try:
            data, _e = SESSION.fetch(
                "https://www.nseindia.com/api/allIndices",
                "https://www.nseindia.com/")
            for row in ((data or {}).get("data") or []):
                if str(row.get("index", "")).upper().startswith("INDIA VIX"):
                    vix = {"last": to_number(row.get("last")),
                           "pct": to_number(row.get("percentChange"))}
                    break
        except Exception:
            pass
    sym, exact = resolve_fno_symbol(sym)
    chain = fno_chain(sym, force, want_expiry)
    chain["exact"] = exact
    fut = fno_futures(sym)
    out = {
        "chain": chain,
        "futures": fut,
        "margin": fno_margin(sym, fut.get("ltp") or chain.get("spot"),
                             fut.get("lotSize")),
        "ban": _daily_cached("ban", fno_ban, 1800),
        "participants": _daily_cached("participants", fno_participants, 3600),
        "vix": {"ok": bool(vix.get("last")), "last": vix.get("last"),
                "pct": vix.get("pct"),
                "error": "" if vix.get("last") else "India VIX not in the "
                                                    "index feed"},
        "at": time.strftime("%H:%M:%S"),
    }
    missing = []
    if not out["chain"].get("ok"):
        missing.append("option chain (%s)" % out["chain"].get("error", ""))
    if not out["ban"].get("ok"):
        missing.append("ban list (%s)" % out["ban"].get("error", ""))
    if not out["participants"].get("ok"):
        missing.append("FII/DII positions (%s)"
                       % out["participants"].get("error", ""))
    if not out["vix"]["ok"]:
        missing.append("India VIX")
    if not out["futures"].get("ok"):
        missing.append("futures (%s)" % out["futures"].get("error", ""))
    if not out["margin"].get("ok"):
        missing.append("approx margin (%s)" % out["margin"].get("error", ""))
    out["missing"] = missing
    FNO_CACHE.update({"at": time.time(), "data": out, "key": key})
    return out


DAILY_FILES = {}


def _daily_cached(name, fn, secs):
    """The ban list and the participant file are published once a day -
    no need to download them on every one-minute refresh."""
    hit = DAILY_FILES.get(name)
    if hit and time.time() - hit[0] < secs and hit[1].get("ok"):
        return hit[1]
    val = fn()
    DAILY_FILES[name] = (time.time(), val)
    return val



# ---------------------------------------------------------------------------
# THE PRE-OPEN CALL
#
# GIFT Nifty trades from early morning and is what those 8:30 notifications
# are built on. Comparing it with yesterday's Nifty close gives the likely
# gap, in points, rather than someone else's adjective.
# ---------------------------------------------------------------------------

PREOPEN = {"at": 0, "data": {}}


def in_preopen_window(now=None):
    now = now or datetime.datetime.now()
    if not is_trading_day(now.date()):
        return False
    m = now.hour * 60 + now.minute
    return (8 * 60) <= m <= (9 * 60 + 30)


def gift_nifty():
    """GIFT Nifty, from whichever source answers."""
    for url, ref in (
        ("https://www.nseindia.com/api/allIndices", "https://www.nseindia.com/"),
        ("https://www.nseindia.com/api/marketStatus", "https://www.nseindia.com/"),
    ):
        try:
            data, _e = SESSION.fetch(url, ref)
        except Exception:
            continue
        rows = []
        if isinstance(data, dict):
            rows = (data.get("data") or data.get("marketState") or [])
        for r in (rows or []):
            nm = str(r.get("index") or r.get("market") or "").upper()
            if "GIFT" in nm or "SGX" in nm:
                v = to_number(r.get("last") or r.get("indexValue"))
                if v:
                    return v, nm
    return None, ""


def preopen_call():
    """How the market is likely to open, in points."""
    if time.time() - PREOPEN["at"] < 120 and PREOPEN["data"]:
        return PREOPEN["data"]
    out = {"ok": False, "window": in_preopen_window()}
    gift, src = gift_nifty()
    prev = None
    nif = TICKER["last"].get("NIFTY 50") or {}
    prev = to_number(nif.get("prevClose")) or to_number(nif.get("last"))
    if gift and prev:
        gap = gift - prev
        pct = gap / prev * 100
        strength = ("flat" if abs(pct) < 0.15 else
                    "slightly higher" if 0.15 <= pct < 0.4 else
                    "higher" if 0.4 <= pct < 0.9 else
                    "sharply higher" if pct >= 0.9 else
                    "slightly lower" if -0.4 < pct <= -0.15 else
                    "lower" if -0.9 < pct <= -0.4 else "sharply lower")
        out.update({"ok": True, "gift": round(gift, 2), "prev": round(prev, 2),
                    "gap": round(gap, 1), "pct": round(pct, 2),
                    "source": src or "GIFT Nifty",
                    "text": ("GIFT Nifty %s \u2014 Nifty seen opening %s"
                             % (round(gift, 2), strength)
                             + ("" if strength == "flat"
                                else ", about %d points" % abs(round(gap))))})
    else:
        out["error"] = "GIFT Nifty not available just now"
    PREOPEN.update({"at": time.time(), "data": out})
    return out


def corp_probe():
    """Runs the real pipeline once and says what each feed gave - rows in
    total, how many are his, and the first few as they will be shown."""
    st = load_state()
    syms = corp_symbols(st)
    t0 = time.time()
    rows = fetch_corp_actions(force=True)
    return {"watching": len(syms), "sample": syms[:8],
            "ms": int((time.time() - t0) * 1000),
            "datedFeedError": CORP_CACHE.get("actErr") or "",
            "filingsFeedError": CORP_CACHE.get("annErr") or "",
            "rowsShown": len(rows),
            "withExDate": len([r for r in rows if r.get("exDate")]),
            "awaitingDate": len([r for r in rows if not r.get("exDate")]),
            "first": [{k: r.get(k) for k in ("symbol", "kind", "value",
                                               "exDate", "recDate", "filed")}
                      for r in rows[:6]]}


# ---------------------------------------------------------------------------
# BETA, computed here rather than copied
#
# Sites disagree on beta because each picks its own window, frequency and
# index without saying so. This uses one year of daily returns against
# Nifty 50, and says so in the hover, so the number always means one thing.
# ---------------------------------------------------------------------------

BETA_FILE = os.path.join(DATA_DIR, "beta.json")
BETA = {"at": 0, "map": {}, "nifty": {}}
BETA_LOCK = threading.Lock()


def _hist_chunks(days=365, step=98):
    """NSE's history endpoints return at most about 70 rows a call, so a year
    is asked for in quarter-year pieces. Asking for 400 days at once - what
    the earlier version did - quietly returned only the latest ~70 rows."""
    out = []
    end = datetime.date.today()
    start = end - datetime.timedelta(days=days)
    while end > start:
        fr = max(start, end - datetime.timedelta(days=step))
        out.append((fr.strftime("%d-%m-%Y"), end.strftime("%d-%m-%Y")))
        end = fr - datetime.timedelta(days=1)
    return out


BETA_ERR = {}          # last reason each fetch came back empty, for the probe


def nifty_daily():
    """Nifty 50's own closes, the yardstick everything is measured against.

    NSE's own index history (historicalOR/indicesHistory) first - checked
    in the browser on 9 Oct: 63 rows a quarter, EOD_CLOSE_INDEX_VAL. The
    niftyindices page is kept only as a fallback."""
    if len(BETA["nifty"]) >= 200 and time.time() - BETA.get("niftyAt", 0) \
            < 86400:
        return BETA["nifty"]
    out = {}
    errs = []
    for fr, to in _hist_chunks():
        url = ("https://www.nseindia.com/api/historicalOR/indicesHistory"
               "?indexType=NIFTY%%2050&from=%s&to=%s" % (fr, to))
        try:
            data, err = SESSION.fetch(
                url, "https://www.nseindia.com/reports-indices-historical-"
                     "index-data", timeout=20)
            rows = (data or {}).get("data") if isinstance(data, dict) else None
            if not rows:
                errs.append(err or "no rows")
            for r in (rows or []):
                d = _isodate(r.get("EOD_TIMESTAMP") or "")
                v = to_number(r.get("EOD_CLOSE_INDEX_VAL"))
                if d and v:
                    out[d] = v
        except Exception as e:
            errs.append(str(e)[:80])
        time.sleep(0.3)
    if len(out) < 150:
        # fallback: niftyindices wants a POST with a JSON "cinfo" body
        try:
            fr, to = (datetime.date.today() - datetime.timedelta(days=365)
                      ).strftime("%d-%b-%Y"), \
                datetime.date.today().strftime("%d-%b-%Y")
            body = json.dumps({"cinfo": json.dumps(
                {"name": "NIFTY 50", "startDate": fr, "endDate": to,
                 "indexName": "NIFTY 50"})})
            req = urllib.request.Request(
                "https://www.niftyindices.com/Backpage.aspx/"
                "getHistoricaldatatabletoString", data=body.encode(),
                headers={"User-Agent": UA,
                         "Content-Type": "application/json; charset=utf-8",
                         "X-Requested-With": "XMLHttpRequest",
                         "Referer": "https://www.niftyindices.com/reports/"
                                    "historical-data"})
            raw = urllib.request.urlopen(req, timeout=25).read().decode(
                "utf-8", "replace").replace('\\"', '"')
            for m in re.finditer(r'"HistoricalDate":"([^"]+)"[^}]*?"CLOSE":'
                                 r'"?([\d.,]+)"?', raw):
                d = _isodate(m.group(1))
                v = to_number(m.group(2))
                if d and v:
                    out.setdefault(d, v)
        except Exception as e:
            errs.append("niftyindices: " + str(e)[:80])
    BETA_ERR["nifty"] = "; ".join(errs[:3])
    if out:
        BETA["nifty"] = out
        BETA["niftyAt"] = time.time()
    return BETA["nifty"]


BETA_SESSION = NSESession()   # its own connection, so it never waits on
                              # the price sweep and the sweep never waits on it


def _share_chunk(sym, fr, to):
    url = ("https://www.nseindia.com/api/historicalOR/"
           "generateSecurityWiseHistoricalData?from=%s&to=%s&symbol=%s"
           "&type=priceVolumeDeliverable&series=EQ"
           % (fr, to, urllib.parse.quote(sym)))
    out, err = {}, ""
    try:
        data, err = BETA_SESSION.fetch(
            url, "https://www.nseindia.com/report-detail/eq_security",
            sym, timeout=20)
        rows = (data or {}).get("data") if isinstance(data, dict) else None
        if not rows:
            err = err or "no rows"
        for r in (rows or []):
            if str(r.get("CH_SERIES") or "EQ").strip() != "EQ":
                continue
            # mTIMESTAMP ("08-Oct-2026") is the trading day. CH_TIMESTAMP is
            # the same day written as UTC ("2026-10-07T18:30:00Z") - reading
            # that put every close one day early, so the share's moves never
            # lined up with Nifty's and every beta came out near zero
            d = _isodate(r.get("mTIMESTAMP") or "")
            if not d and r.get("CH_TIMESTAMP"):
                try:
                    d = (datetime.datetime.fromisoformat(
                        str(r["CH_TIMESTAMP"]).replace("Z", "+00:00"))
                         + datetime.timedelta(hours=5, minutes=30)
                         ).date().isoformat()
                except Exception:
                    d = None
            v = to_number(r.get("CH_CLOSING_PRICE")
                          or r.get("CH_LAST_TRADED_PRICE"))
            if d and v:
                out[d] = v
    except Exception as e:
        err = str(e)[:80]
    return out, err


def share_daily(sym):
    """A year of daily closes for one share, EQ series only - the four
    quarter-year pieces asked for at the same time (about a second a share
    instead of five)."""
    out, errs = {}, []
    chunks = _hist_chunks()
    res = [None] * len(chunks)

    def work(i, fr, to):
        res[i] = _share_chunk(sym, fr, to)

    ts = [threading.Thread(target=work, args=(i, fr, to), daemon=True)
          for i, (fr, to) in enumerate(chunks)]
    for t in ts:
        t.start()
    for t in ts:
        t.join(30)
    for r in res:
        if not r:
            errs.append("timed out")
            continue
        out.update(r[0])
        if r[1]:
            errs.append(r[1])
    BETA_ERR[sym] = "; ".join(errs[:3])
    return out


def compute_beta(sym):
    """One year of daily returns against Nifty 50."""
    idx = nifty_daily()
    shr = share_daily(sym)
    if len(idx) < 60 or len(shr) < 60:
        return None
    days = sorted(set(idx) & set(shr))
    if len(days) < 60:
        return None
    sr, ir = [], []
    for i in range(1, len(days)):
        a, b = days[i - 1], days[i]
        if not (idx[a] and shr[a]):
            continue
        ir.append(idx[b] / idx[a] - 1)
        sr.append(shr[b] / shr[a] - 1)
    n = len(ir)
    if n < 60:
        return None
    mi = sum(ir) / n
    ms = sum(sr) / n
    cov = sum((ir[i] - mi) * (sr[i] - ms) for i in range(n)) / n
    var = sum((x - mi) ** 2 for x in ir) / n
    if not var:
        return None
    return {"beta": round(cov / var, 2), "days": n, "v": BETA_METHOD,
            "at": datetime.date.today().isoformat()}


def beta_load():
    if BETA["map"]:
        return BETA["map"]
    try:
        with open(BETA_FILE) as f:
            BETA["map"] = json.load(f) or {}
    except Exception:
        BETA["map"] = {}
    return BETA["map"]


def beta_save():
    try:
        tmp = BETA_FILE + ".tmp"
        with open(tmp, "w") as f:
            json.dump(BETA["map"], f)
        os.replace(tmp, BETA_FILE)
    except Exception:
        pass


BETA_PROGRESS = {"done": 0, "total": 0, "running": False}
# 2 = dates read from mTIMESTAMP. Anything worked out before that used
# dates a day early and is thrown away, not shown.
BETA_METHOD = 2


def beta_good(h):
    return bool(h) and h.get("beta") is not None and h.get("v") == BETA_METHOD


def beta_status(syms=None):
    """How many of his shares have a beta (or a settled failure) - for the
    loading bar and Diagnostics."""
    if syms is None:
        st = load_state()
        syms = list(st.get("watchlist") or [])
    have = beta_load()
    now = time.time()
    done = 0
    for s in syms:
        h = have.get(s) or {}
        if beta_good(h) or (h.get("v") == BETA_METHOD
                            and now - (h.get("tried") or 0) < 7200):
            done += 1
    return done, len(syms)


def beta_refresh_loop():
    """Works through the watchlist as fast as NSE comfortably allows -
    roughly two seconds a share, so all 125 in about five minutes the first
    time. After that every figure is kept on disk for a week, so a restart
    shows them at once; only new shares, failures (after two hours) and
    week-old figures are fetched again, quietly, and an old figure stays on
    screen until its replacement is ready."""
    time.sleep(8)
    while True:
        try:
            st = load_state()
            syms = list(st.get("watchlist") or [])
            syms += [x for x in extra_symbols(st) if x not in syms]
            have = beta_load()
            cut = (datetime.date.today() -
                   datetime.timedelta(days=7)).isoformat()
            now = time.time()
            new = [x for x in syms if not have.get(x)
                   or have[x].get("v") != BETA_METHOD]
            retry = [x for x in syms if have.get(x)
                     and have[x].get("v") == BETA_METHOD
                     and have[x].get("beta") is None
                     and now - (have[x].get("tried") or 0) > 7200]
            stale = [x for x in syms if beta_good(have.get(x))
                     and (have[x].get("at") or "") < cut
                     and now - (have[x].get("tried") or 0) > 7200]
            todo = new + retry + stale
            BETA_PROGRESS["running"] = bool(todo)
            for i, sym in enumerate(todo):
                r = compute_beta(sym)
                with BETA_LOCK:
                    old = have.get(sym) or {}
                    if r:
                        have[sym] = r
                    elif beta_good(old):
                        # keep showing last week's figure rather than a dash
                        old["tried"] = time.time()
                        have[sym] = old
                    else:
                        have[sym] = {"beta": None, "tried": time.time(),
                                     "v": BETA_METHOD,
                                     "why": BETA_ERR.get(sym, "")[:120],
                                     "at": datetime.date.today().isoformat()}
                if i % 10 == 9:
                    beta_save()
                time.sleep(0.15)
            if todo:
                beta_save()
            BETA_PROGRESS["running"] = False
        except Exception:
            pass
        time.sleep(60)


INDEX_PE = {}        # index name -> {pe, last, prev, at} from allIndices
INDEX_PE_AT = {"t": 0}


def index_pe_table():
    """Every NSE index's PE. Filled by the ticker's allIndices call; fetched
    here only if that has not run for ten minutes."""
    fresh = [v for v in INDEX_PE.values() if time.time() - v["at"] < 600]
    if not fresh:
        try:
            nse_indices()
        except Exception:
            pass
    return INDEX_PE


# NSE's own classification of each share (sector / industry / basic
# industry, from the quote) -> the NIFTY index that best represents its
# peers. Checked against real replies: CIPLA Healthcare/Pharmaceuticals,
# SBIN Public Sector Bank, BSE Capital Markets, HAL Aerospace & Defense.
SECTOR_INDEX_RULES = [
    ("basic", "public sector bank", "NIFTY PSU BANK"),
    ("basic", "private sector bank", "NIFTY PRIVATE BANK"),
    ("industry", "banks", "NIFTY BANK"),
    ("industry", "capital markets", "NIFTY CAPITAL MARKETS"),
    ("sector", "financial services", "NIFTY FINANCIAL SERVICES"),
    ("industry", "aerospace & defense", "NIFTY INDIA DEFENCE"),
    ("sector", "information technology", "NIFTY IT"),
    ("industry", "pharmaceuticals", "NIFTY PHARMA"),
    ("sector", "healthcare", "NIFTY HEALTHCARE INDEX"),
    ("sector", "fast moving consumer goods", "NIFTY FMCG"),
    ("sector", "automobile", "NIFTY AUTO"),
    ("sector", "metals & mining", "NIFTY METAL"),
    ("sector", "oil gas & consumable fuels", "NIFTY OIL & GAS"),
    ("sector", "power", "NIFTY ENERGY"),
    ("sector", "realty", "NIFTY REALTY"),
    ("sector", "media", "NIFTY MEDIA"),
    ("sector", "consumer durables", "NIFTY CONSUMER DURABLES"),
    ("sector", "chemicals", "NIFTY CHEMICALS"),
    ("sector", "construction materials", "NIFTY CEMENT"),
    ("sector", "construction", "NIFTY INFRASTRUCTURE"),
    ("sector", "capital goods", "NIFTY INDIA MANUFACTURING"),
    ("sector", "consumer services", "NIFTY INDIA CONSUMPTION"),
    ("sector", "services", "NIFTY SERVICES SECTOR"),
    ("sector", "telecommunication", "NIFTY INDIA DIGITAL"),
]


def sector_index_for(q):
    sec = str(q.get("sector") or "").lower()
    ind = str(q.get("industry") or "").lower()
    bas = str(q.get("basicIndustry") or "").lower()
    # never fetches - this runs while /api/quotes holds the cache lock; the
    # ticker thread keeps INDEX_PE filled
    table = INDEX_PE
    for field, word, name in SECTOR_INDEX_RULES:
        val = {"sector": sec, "industry": ind, "basic": bas}[field]
        if word in val and name in table:
            return name
    return "NIFTY 500" if "NIFTY 500" in table else ""


# How far from its sector a share's P/E must be before it is flagged.
# At 12% (19.17) about 110 of his 125 shares were flagged. A P/E cannot go
# below zero but can run to 10x or 20x the sector (ETERNAL, NYKAA, PAYTM),
# so the two sides are set as multiples of the sector P/E, not as one
# percentage: on 9 Oct 2026 this flags 7 cheap and 12 expensive shares.
# At +/-35% it would have flagged 70.
VAL_CHEAP = 0.5      # P/E at half the sector's or less -> UNDERVALUED
VAL_DEAR = 4.0       # P/E at four times the sector's or more -> OVERVALUED


def valuation_of(sym, q=None):
    """The share's PE against the PE of its own sector index, both live.

    - The share's earnings per share are fixed once a day from NSE's P/E
      (EPS = previous close / P/E), and its PE is then worked out from the
      LIVE price every time the price updates - so a share that was
      undervalued at 10:00 and has since run up shows Fair or Overvalued
      straight away.
    - The sector index's PE comes from NSE allIndices, re-read with the
      ticker every 10 seconds; NSE works it out from closing prices.
    - The quote is passed in by the caller (/api/quotes already holds
      CACHE_LOCK - a plain Lock is not reentrant)."""
    if q is None:
        with CACHE_LOCK:
            q = dict(CACHE.get(sym) or {})
    pe_nse = to_number(q.get("pe"))
    ltp = to_number(q.get("ltpNum") or q.get("ltp"))
    if not (pe_nse and pe_nse > 0 and ltp):
        return {}
    # NSE's "Symbol P/E" is worked out from the CURRENT price (ITC at 255
    # with P/E 16.50 on 9 Oct), so EPS = the price it was read with / P/E.
    # That price is kept with the P/E, and the PE is then redone from the
    # live price every time the price moves.
    ref = to_number(q.get("pePrice")) or ltp
    eps = ref / pe_nse
    if not eps or eps <= 0:
        return {}
    pe_live = ltp / eps
    name = sector_index_for(q)
    row = INDEX_PE.get(name) if name else None
    if not row:
        return {}
    # NSE publishes index PEs from closing prices, so this is at most a day
    # old - sector PEs move by a percent or two a day, the share's own PE
    # (above) is the part that moves and it is live
    spe = row["pe"]
    gap = (pe_live - spe) / spe * 100
    ratio = pe_live / spe
    verdict = ("UNDERVALUED" if ratio <= VAL_CHEAP else
               "OVERVALUED" if ratio >= VAL_DEAR else "FAIR")
    return {"pe": round(pe_live, 2), "peNse": pe_nse,
            "ratio": round(ratio, 2), "cheapAt": VAL_CHEAP,
            "dearAt": VAL_DEAR,
            "sectorPe": round(spe, 2), "sectorIndex": name,
            "verdict": verdict, "gapPct": round(gap, 1),
            "eps": round(eps, 2), "implied": round(spe * eps, 2),
            "price": ltp, "at": time.strftime("%H:%M:%S"),
            "industry": q.get("basicIndustry") or q.get("industry") or ""}


TT_PAGES = {"at": 0, "slugs": []}
TT_FILE = os.path.join(DATA_DIR, "tickertape_links.json")
TT_LOCK = threading.Lock()
TT_MAP = {}          # NSE symbol -> {"url", "how", "at"}
TT_MISS = {}         # NSE symbol -> when a full search last found nothing
TT_MAP_READ = {"done": False}
TT_BASE = "https://www.tickertape.in/stocks/"
TT_STOP = {"ltd", "limited", "the", "of", "and", "co", "company", "l", "india",
           "corp", "corporation", "inc", "pvt", "private"}


def _tt_tokens(name):
    t = (name or "").lower().replace("&", " and ")
    t = re.sub(r"\([^)]*\)", " ", t)
    return [w for w in re.split(r"[^a-z0-9]+", t) if w and w not in TT_STOP]


def _tt_load():
    with TT_LOCK:
        if TT_MAP_READ["done"]:
            return
        TT_MAP_READ["done"] = True
        try:
            with open(TT_FILE, encoding="utf-8") as f:
                d = json.load(f)
            if isinstance(d, dict):
                TT_MAP.update({k: v for k, v in d.items()
                               if isinstance(v, dict) and v.get("url")})
        except Exception:
            pass


def _tt_save():
    # the whole write happens under the lock, so the background search and
    # a link he pastes can never interleave in the file and spoil it
    try:
        with TT_LOCK:
            tmp = TT_FILE + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(TT_MAP, f, indent=0)
            os.replace(tmp, TT_FILE)
    except Exception:
        pass


def _tt_get(url, limit=None, timeout=15):
    req = urllib.request.Request(url, headers={
        "User-Agent": UA, "Accept": "application/json,text/html,*/*",
        "Accept-Language": "en-IN,en;q=0.9"})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        raw = r.read(limit) if limit else r.read()
    if raw[:2] == b"\x1f\x8b" and not limit:
        raw = gzip.GzipFile(fileobj=io.BytesIO(raw)).read()
    return raw.decode("utf-8", "replace")


def _tt_sitemap():
    """Every Tickertape stock page, from the public sitemap their
    robots.txt points search engines to. Re-read once a week."""
    if time.time() - TT_PAGES["at"] > 7 * 86400 or not TT_PAGES["slugs"]:
        try:
            raw = _tt_get("https://www.tickertape.in/sitemaps/stocks/"
                          "sitemap.xml", timeout=25)
            slugs = re.findall(r"/stocks/([^<\s]+)</loc>", raw)
            if slugs:
                TT_PAGES.update({"at": time.time(), "slugs": slugs})
        except Exception:
            pass
    return TT_PAGES["slugs"]


def _tt_page_symbol(slug):
    """The NSE symbol a Tickertape page belongs to - its title always
    starts with it ("TMPV Share Price Today: Tata Motors Passenger
    Vehicles"). Only the first 24 KB is read (half a second)."""
    try:
        html = _tt_get(TT_BASE + slug, limit=24000)
    except Exception:
        return ""
    m = re.search(r"<title>\s*([^<\s]+)\s+Share Price", html)
    return html_lib.unescape(m.group(1)).upper() if m else ""


def _tt_search(text):
    """Tickertape's own search box. It answers with the NSE ticker of each
    match, so a hit is only accepted when that ticker IS the share."""
    text = (text or "").strip()
    if len(text) < 3:
        return []
    try:
        d = json.loads(_tt_get("https://api.tickertape.in/search?" +
                               urllib.parse.urlencode({"text": text,
                                                       "types": "stock"}),
                               timeout=10))
        rows = ((d.get("data") or {}).get("stocks")) or []
    except Exception:
        return []
    return [(str(x.get("ticker") or "").upper(),
             str(x.get("slug") or "").replace("/stocks/", "").strip("/"))
            for x in rows if isinstance(x, dict)]


def _tt_like(a, b):
    """Does word a (NSE often abbreviates: "Mthrsn", "Samvrdhna") stand for
    word b? Same first letter and a's letters appear in b in order."""
    if a == b:
        return True
    if len(a) < 3 or len(b) < 3 or a[0] != b[0]:
        return False
    if b.startswith(a) or a.startswith(b):
        return True
    it = iter(b)
    return all(ch in it for ch in a)


def _tt_rank(sym, names, slugs):
    """Sitemap pages ordered by how well their name fits the share's
    names. Renamed companies keep their old page name there (Eternal is
    still zomato-ZOM, PVR INOX is pvr-PVRL), which is why the page itself
    is then opened and checked before it is trusted."""
    want = []
    for n in names:
        for w in _tt_tokens(n):
            if w not in want:
                want.append(w)
    s = sym.lower()
    out = []
    for slug in slugs:
        bits = slug.split("-")
        code = bits[-1].lower()
        words = [w for w in bits[:-1] if w and w not in TT_STOP]
        hit = sum(1 for w in words if any(_tt_like(x, w) for x in want))
        score = hit / (len(words) or 1) + hit * 0.5
        if code == s:
            score += 2
        elif len(code) >= 3 and (s.startswith(code) or code.startswith(s[:4])):
            score += 0.6
        if words and s.startswith(words[0][:4]):
            score += 0.4
        if score > 0.5:
            out.append((score, slug))
    out.sort(reverse=True)
    return [x for _s, x in out]


NSE_RENAMES = {"at": 0, "names": {}}


def nse_old_names(sym):
    """A renamed company's earlier names, from NSE's own name-change and
    symbol-change files (ETERNAL was Zomato Limited, INDUSTOWER was Bharti
    Infratel). Tickertape still files those pages under the old name."""
    if time.time() - NSE_RENAMES["at"] > 7 * 86400:
        found = {}
        for f, si, oi in (("namechange", 0, 1), ("symbolchange", 2, 0),
                          ("symbolchange", 2, 1)):
            try:
                raw = RPT_SESSION.get_raw(
                    "https://nsearchives.nseindia.com/content/equities/%s.csv"
                    % f, "https://www.nseindia.com/")
                for row in csv.reader(io.StringIO(
                        raw.decode("utf-8", "replace"))):
                    if len(row) > max(si, oi):
                        k = row[si].strip().upper()
                        v = row[oi].strip()
                        if k and v and not k.startswith("NCH_"):
                            found.setdefault(k, [])
                            if v not in found[k]:
                                found[k].append(v)
            except Exception:
                continue
        if found:
            NSE_RENAMES.update({"at": time.time(), "names": found})
        else:
            NSE_RENAMES["at"] = time.time() - 6 * 86400   # retry in a day
    return list(NSE_RENAMES["names"].get(sym, []))


# ---------------------------------------------------------------------------
# RENAMED SHARES (20.9). When a company changes its NSE symbol (ICICIPRULI
# became ICICILIFE on 23 Oct 2026) the old symbol simply stops answering,
# and one row never gets a price. NSE's own symbol-change list is read once
# a day; a share in his table that has been renamed is renamed in the table
# too - its typed figures go with it - and a banner says so.
# ---------------------------------------------------------------------------

RENAMES = {"at": 0, "map": {}, "done": {}}
# known before NSE's own list carried them
KNOWN_RENAMES = {"ICICIPRULI": ("ICICILIFE", "2026-10-23")}
RENAME_LOCK = threading.Lock()


def nse_symbol_changes():
    """{old symbol: (new symbol, 'YYYY-MM-DD')} from NSE's list."""
    if time.time() - RENAMES["at"] < 20 * 3600 and RENAMES["map"]:
        return RENAMES["map"]
    out = {}
    try:
        raw = RPT_SESSION.get_raw(
            "https://nsearchives.nseindia.com/content/equities/"
            "symbolchange.csv", "https://www.nseindia.com/")
        for row in csv.reader(io.StringIO(raw.decode("utf-8", "replace"))):
            if len(row) < 4:
                continue
            old, new = row[1].strip().upper(), row[2].strip().upper()
            try:
                d = datetime.datetime.strptime(row[3].strip().title(),
                                               "%d-%b-%Y").date().isoformat()
            except ValueError:
                continue
            if old and new and old != new and re.fullmatch(r"[A-Z0-9&-]+",
                                                          new):
                if old not in out or out[old][1] < d:
                    out[old] = (new, d)
    except Exception as e:
        STATS["lastError"] = "symbol changes: %s" % str(e)[:80]
    for old, v in KNOWN_RENAMES.items():
        out.setdefault(old, v)
    if len(out) > len(KNOWN_RENAMES):
        RENAMES.update(at=time.time(), map=out)
    else:
        RENAMES["at"] = time.time() - 18 * 3600       # again in two hours
        RENAMES["map"] = out
    return RENAMES["map"]


def _rename_in(state, old, new):
    """Moves one share's row, figures and size to its new symbol."""
    wl = state.get("watchlist") or []
    if old not in wl:
        return False
    if new in wl:
        state["watchlist"] = [x for x in wl if x != old]
    else:
        state["watchlist"] = [new if x == old else x for x in wl]
    notes = state.get("notes") or {}
    if old in notes:
        row = notes.pop(old)
        if not any(str(v or "").strip() for v in (notes.get(new) or {}).values()):
            notes[new] = row
    for k in ("rowHeights", "cellFormat"):
        m = state.get(k)
        if isinstance(m, dict):
            for key in [x for x in m if x == old or x.startswith(old + "|")]:
                m[new + key[len(old):]] = m.pop(key)
    if isinstance(state.get("outOfList"), str):
        state["outOfList"] = re.sub(r"(?<![A-Z0-9&-])" + re.escape(old) +
                                    r"(?![A-Z0-9&-])", new, state["outOfList"])
    return True


def rename_check():
    """Renames in his table what NSE has renamed (from its date on)."""
    ch = nse_symbol_changes()
    if not ch:
        return []
    today = datetime.date.today().isoformat()
    st = load_state()
    todo = [(o, ch[o][0], ch[o][1]) for o in (st.get("watchlist") or [])
            if o in ch and ch[o][1] <= today]
    if not todo:
        return []
    with NOTE_LOCK:
        st = load_state()
        done = []
        for old, new, d in todo:
            if _rename_in(st, old, new):
                done.append((old, new, d))
        if done:
            save_state(st)
            PHONE_REV["rev"] += 1
    with RENAME_LOCK:
        for old, new, d in done:
            RENAMES["done"][old] = new
    for old, new, d in done:
        push_event("info", "%s is now %s on NSE (from %s) - renamed in your "
                   "table, with its figures." % (
                       old, new, datetime.date.fromisoformat(d)
                       .strftime("%d %b %Y")), gap=86400)
    return done


def renamed_payload(payload):
    """A page opened before a rename still sends the old symbol: it is
    turned into the new one on the way in."""
    with RENAME_LOCK:
        done = dict(RENAMES["done"])
    for old, new in done.items():
        _rename_in(payload, old, new)


def tickertape_names(sym):
    with CACHE_LOCK:
        q = dict(CACHE.get(sym) or {})
    names = [q.get("companyFull") or "", q.get("company") or ""]
    if not any(names):
        try:
            names.append(fetch_symbol(sym, light=True).get("company") or "")
        except Exception:
            pass
    return [n for n in names if n]


def tickertape_url(sym, names=None, deep=True):
    """Tickertape addresses a share by its name plus its own code
    (/stocks/lupin-LUPN), which the NSE symbol alone cannot give. In order:
      1. a link he pasted himself for this share,
      2. the link found before (kept on disk for 30 days),
      3. Tickertape's own search, accepted only when it names this exact
         NSE symbol,
      4. the best-fitting pages in their sitemap, each opened and accepted
         only if the page's title starts with this NSE symbol.
    Never falls back to another site: if nothing is certain it returns
    None and the dashboard asks him for the link once."""
    _tt_load()
    sym = (sym or "").upper().strip()
    if not sym:
        return None, ""
    with TT_LOCK:
        got = dict(TT_MAP.get(sym) or {})
    if got.get("how") == "you":
        return got["url"], "you"
    if got.get("url") and time.time() - (got.get("at") or 0) < 30 * 86400:
        return got["url"], got.get("how") or "saved"
    if not got.get("url") and time.time() - TT_MISS.get(sym, 0) < 6 * 3600:
        return None, ""          # searched in the last six hours, not found
    names = names if names is not None else tickertape_names(sym)
    found = None
    tries = ([sym] + names +
             [" ".join(_tt_tokens(n)[:2]) for n in names])
    seen = set()
    for t in tries:
        if not t or t.lower() in seen:
            continue
        seen.add(t.lower())
        for ticker, slug in _tt_search(t):
            if ticker == sym and slug:
                found = (TT_BASE + slug, "search")
                break
        if found:
            break
    if not found and deep:
        for slug in _tt_rank(sym, names, _tt_sitemap())[:8]:
            if _tt_page_symbol(slug) == sym:
                found = (TT_BASE + slug, "page")
                break
    if not found and deep:
        # renamed: try each earlier name / symbol the same careful way
        old = nse_old_names(sym)
        for t in old:
            for ticker, slug in _tt_search(t):
                if ticker == sym and slug:
                    found = (TT_BASE + slug, "search")
                    break
            if found:
                break
        if not found and old:
            for slug in _tt_rank(sym, old, _tt_sitemap())[:6]:
                if _tt_page_symbol(slug) == sym:
                    found = (TT_BASE + slug, "page")
                    break
    if not found:
        if deep:
            TT_MISS[sym] = time.time()
        return (got.get("url"), "old") if got.get("url") else (None, "")
    with TT_LOCK:
        now = TT_MAP.get(sym) or {}
        if now.get("how") == "you":        # he pasted one while we searched
            return now["url"], "you"
        TT_MAP[sym] = {"url": found[0], "how": found[1], "at": time.time()}
    TT_MISS.pop(sym, None)
    _tt_save()
    return found


def tickertape_set(sym, url):
    """A link he pasted. Only a Tickertape stock page is accepted."""
    _tt_load()
    sym = (sym or "").upper().strip()
    url = (url or "").strip()
    m = re.match(r"^(?:https?://)?(?:www\.)?tickertape\.in/stocks/"
                 r"([A-Za-z0-9&._%-]+)", url)
    if not sym or not m:
        return False
    with TT_LOCK:
        TT_MAP[sym] = {"url": TT_BASE + m.group(1), "how": "you",
                       "at": time.time()}
    TT_MISS.pop(sym, None)
    _tt_save()
    return True


