def tickertape_warm_loop():
    """Finds every share's Tickertape page in the background, gently, so a
    BETA click opens at once instead of searching first."""
    time.sleep(40)
    while True:
        try:
            st = load_state()
            syms = [s.upper() for s in (st.get("watchlist") or [])]
            syms += [x for x in extra_symbols(st) if x not in syms]
            _tt_load()
            for sym in syms:
                with TT_LOCK:
                    got = TT_MAP.get(sym) or {}
                if got.get("how") == "you" or (
                        got.get("url") and
                        time.time() - (got.get("at") or 0) < 30 * 86400):
                    continue
                tickertape_url(sym)
                time.sleep(1.5)
        except Exception:
            pass
        time.sleep(6 * 3600)


def market_pulse():
    """Nifty's direction of travel over the last ten minutes, plus one
    reading per share for the table column."""
    with PULSE_LOCK:
        rows = list(PULSE)
        shares = {k: list(v) for k, v in SHARE_PULSE.items()}
    out = {"at": time.strftime("%H:%M:%S"),
           "frozen": bool(PULSE_LAST.get("frozen")),
           "source": PULSE_LAST.get("source", "nifty"), "shares": {}}

    auction_now = PULSE_LAST.get("source") == "auction"
    win = 1.5 if auction_now else 10          # minutes
    d10 = _drift(rows, win, min_minutes=(0.5 if auction_now else 2))
    if d10 is None and PULSE_LAST.get("market") is not None:
        out.update(PULSE_LAST["market"])          # hold the last known reading
        out["ready"] = True
        out["held"] = True
    elif d10 is None:
        out["ready"] = False
        out["note"] = "building up readings"
    else:
        # a tenth of a per cent on Nifty inside ten minutes is a strong shove
        full = 0.05 if auction_now else 0.10
        v = _needle(d10, full)
        out.update({"ready": True, "value": v, "drift10": round(d10, 3),
                    "windowMin": win, "label": pressure_label(v),
                    "level": rows[-1][1] if rows else None})
        PULSE_LAST["market"] = {"value": v, "drift10": round(d10, 3),
                                "label": pressure_label(v),
                                "level": rows[-1][1] if rows else None}

    for sym, rr in shares.items():
        d = _drift(rr, win, min_minutes=(0.5 if auction_now else 2))
        if d is None:
            keep = PULSE_LAST["shares"].get(sym)
            if keep:
                out["shares"][sym] = keep
            continue
        # a single share moves further than the index; in the auction an
        # indicative price moves far less than a traded one, so 0.15% over a
        # minute and a half already counts as a strong push
        v = _needle(d, 0.15 if auction_now else 0.35)
        cell = {"v": v, "d": round(d, 3), "l": pressure_label(v)}
        out["shares"][sym] = cell
        PULSE_LAST["shares"][sym] = cell
    if not out["shares"] and PULSE_LAST["shares"]:
        out["shares"] = PULSE_LAST["shares"]

    # Keep the auction reading aside as the day's closing picture. After
    # hours that is what the gauge shows, rather than going blank.
    # only while the auction is really on (a reading loaded from the file at
    # a later start used to be stamped with that start's time - "AUCTION
    # 17:35")
    if auction_now and in_auction_window() and out.get("value") is not None:
        PULSE_LAST["auction"] = {"value": out["value"], "label": out["label"],
                                 "drift10": out.get("drift10"),
                                 "at": time.strftime("%H:%M"),
                                 "day": datetime.date.today().isoformat()}
        PULSE_LAST["auctionShares"] = dict(out.get("shares") or {})
    if PULSE_LAST.get("frozen") and PULSE_LAST.get("auction"):
        a = PULSE_LAST["auction"]
        out.update({"ready": True, "value": a["value"], "label": a["label"],
                    "drift10": a.get("drift10"), "held": True,
                    "source": "auctionClose", "auctionAt": a.get("at")})
        if PULSE_LAST.get("auctionShares"):
            out["shares"] = PULSE_LAST["auctionShares"]
    out["savedAt"] = PULSE_LAST.get("savedAt", "")
    return out


def mover_pick(pool, used):
    """The few genuinely market-moving stories, split home and abroad."""
    ind, wor, seen = [], [], set()
    seen_theme = set()          # one story per theme - three papers running
                                # the same GDP piece is one story, not three
    # 20.14: the newest story of each theme wins, and yesterday's are left
    # out (the rupee "falls 7 paise" of yesterday beside today's "rises 4
    # paise" said two opposite things at once)
    pool = sorted(pool, key=lambda it: (it.get("age") is None,
                                        it.get("age") or 0))
    for it in pool:
        title = it.get("title") or ""
        low = title.lower()
        theme = side = None
        if re.search(r"(?<![a-z])rupee(?![a-z])", low) and re.search(
                r"paise|dollar|\$|record|low|high|rises|falls|gains|slips|"
                r"settles|opens|closes", low):
            theme, side = "RUPEE", "in"
        for word, (name, sd) in ([] if theme else MOVER_BIG.items()):
            if re.search(r"(?<![a-z])" + re.escape(word) + r"(?![a-z])", low):
                theme, side = name, sd
                break
        if not theme or theme in seen_theme:
            continue
        k = title_key(title)
        if k in seen or k in used:
            continue
        age = it.get("age")
        # undated stories that were looked into and kept (today's edition,
        # or about something still to come) count too
        if (age is None and not it.get("dateNote")) or (age or 0) > 18:
            continue
        if it.get("source") in INDIAN_SOURCES and side == "wo":
            side = "wo"          # an Indian paper reporting a world event
        row = {"theme": theme, "text": title, "link": it.get("link", ""),
               "source": it.get("source", ""), "age": age,
               "dateNote": it.get("dateNote", ""),
               "side": "India" if side == "in" else "World"}
        seen.add(k)
        seen_theme.add(theme)
        (ind if side == "in" else wor).append(row)
        if len(ind) >= 4 and len(wor) >= 4:
            break
    return ind[:4] + wor[:4], seen


def market_mover():
    nif = TICKER["last"].get("NIFTY 50") or {}
    out = {"pct": nif.get("pct"), "last": nif.get("last"),
           "at": time.strftime("%H:%M"), "drivers": []}
    pool = ((NEWS.get("items") or [])
            + (NEWS.get("globalAll") or NEWS.get("global") or []))
    try:
        note_expectations(pool)
    except Exception:
        pass
    picked, keys = mover_pick(pool, set())
    # anything saying what is expected goes to the front - that is the part
    # he can act on before the announcement
    for d in picked:
        d["kind"] = ("expected" if is_expectation(d["text"])
                     else ("outcome" if is_outcome(d["text"]) else ""))
        if d["kind"] == "expected" and not d.get("number"):
            d["number"] = number_in(d["text"])
        if d["kind"] == "outcome":
            e = expectation_for(d["text"])
            if e:
                d["expected"] = e.get("number") or ""
                d["expectedWhen"] = e.get("at", "")
                d["expectedTitle"] = e.get("title", "")
    picked.sort(key=lambda d: 0 if d.get("expected") else
                             (1 if d.get("kind") == "expected" else 2))
    out["drivers"] = picked
    # whatever the strip takes is left out of the Global column, so the two
    # never show the same story
    NEWS["moverKeys"] = keys
    return out



# ---------------------------------------------------------------------------
# TRANSLATION
# An article written in Bengali is written FOR Bengal - most of the country
# cannot read it - so the Bengali papers are the strongest signal of genuinely
# local news. They are only useful here if the headlines can be read in
# English, so each is translated once and cached. MyMemory first (documented,
# free, no key), Google's public endpoint as fallback. If both fail the
# headline is dropped rather than shown in a script he cannot read.
# ---------------------------------------------------------------------------

TRANS_CACHE = {}
TRANS_LOCK = threading.Lock()
TRANS_FAILS = {"n": 0, "at": 0.0}


def _tr_mymemory(text, src):
    url = ("https://api.mymemory.translated.net/get?q=%s&langpair=%s%%7Cen"
           % (urllib.parse.quote(text[:480]), src))
    raw = urllib.request.urlopen(
        urllib.request.Request(url, headers={"User-Agent": UA}),
        timeout=8).read()
    d = json.loads(raw.decode("utf-8", "replace"))
    out = ((d.get("responseData") or {}).get("translatedText") or "").strip()
    return "" if out.upper().startswith("MYMEMORY WARNING") else out


def _tr_google(text, src):
    url = ("https://translate.googleapis.com/translate_a/single?client=gtx"
           "&sl=%s&tl=en&dt=t&q=%s" % (src, urllib.parse.quote(text[:480])))
    raw = urllib.request.urlopen(
        urllib.request.Request(url, headers={"User-Agent": UA}),
        timeout=8).read()
    d = json.loads(raw.decode("utf-8", "replace"))
    return "".join(p[0] for p in (d[0] or []) if p and p[0]).strip()


def looks_translated(t):
    letters = [c for c in t if c.isalpha()]
    if not letters:
        return False
    return sum(1 for c in letters if ord(c) < 0x250) / len(letters) > 0.8


def is_indic(t):
    return any(0x0900 <= ord(c) <= 0x0DFF for c in (t or ""))


def translate(text, src="bn"):
    text = (text or "").strip()
    if not text:
        return ""
    key = src + "|" + text
    with TRANS_LOCK:
        if key in TRANS_CACHE:
            return TRANS_CACHE[key]
        if TRANS_FAILS["n"] >= 6 and time.time() - TRANS_FAILS["at"] < 900:
            return ""
    out = ""
    for fn in (_tr_mymemory, _tr_google):
        try:
            out = fn(text, src)
            if out and looks_translated(out):
                break
            out = ""
        except Exception:
            out = ""
    with TRANS_LOCK:
        if out:
            TRANS_CACHE[key] = out
            TRANS_FAILS["n"] = 0
            if len(TRANS_CACHE) > 4000:
                TRANS_CACHE.pop(next(iter(TRANS_CACHE)))
        else:
            TRANS_FAILS["n"] += 1
            TRANS_FAILS["at"] = time.time()
    return out


