def _gn_site(site, words, lang):
    """Google News, limited to one paper's own site: works when the paper's
    own feed refuses or has moved (20.9)."""
    hl = {"bn": ("bn", "IN:bn"), "hi": ("hi", "IN:hi")}.get(lang, ("en-IN",
                                                                 "IN:en"))
    q = "site:%s%s when:2d" % (site, (" " + words) if words else "")
    return ("https://news.google.com/rss/search?q=" + Q(q) + "&hl=%s&gl=IN"
            "&ceid=%s" % hl)


# the last address tried for each paper - its headlines through Google News
