def cnbc_batch(labels):
    """Every index in a single request. CNBC needs no session and has not
    rate-limited us, unlike Yahoo."""
    syms = [CNBC_SYMBOL[l] for l in labels if l in CNBC_SYMBOL]
    if not syms:
        return {}
    url = ("https://quote.cnbc.com/quote-html-webservice/quote.htm?symbols="
           + urllib.parse.quote("|".join(syms), safe="|")
           + "&requestMethod=itv&noform=1&partnerId=2&fund=1&exthrs=1"
             "&output=json")
    raw = urllib.request.urlopen(
        urllib.request.Request(url, headers={"User-Agent": UA}),
        timeout=10).read()
    d = json.loads(raw.decode("utf-8", "replace"))
    rows = (((d.get("ITVQuoteResult") or {}).get("ITVQuote")) or [])
    if isinstance(rows, dict):
        rows = [rows]
    back = {}
    for r in rows:
        sym = r.get("symbol")
        last = _n(r.get("last"))
        if last is None:
            continue                       # code "3" = CNBC has no data
        for lab, cs in CNBC_SYMBOL.items():
            if cs == sym:
                back[lab] = {
                    "name": lab, "last": round(last, 2),
                    "chg": round(_n(r.get("change")) or 0, 2),
                    "pct": round(_n(r.get("change_pct")) or 0, 2),
                    "src": "CNBC",
                    "mktOpen": str(r.get("curmktstatus", "")).upper() == "REG_MKT",
                }
    return back


BRENT_PICK = {"symbol": None, "name": "", "at": 0}


def brent_quote():
    """CNBC's @LCO.1 turned out to be a deferred contract, several dollars
    away from spot. Ask for a few candidates and keep whichever calls itself
    Brent and sits closest to the front month."""
    cands = ["@LCO.1", "@LCO.2", "UK-BRENT-CRUDE-OIL", "@CL.1"]
    url = ("https://quote.cnbc.com/quote-html-webservice/quote.htm?symbols="
           + urllib.parse.quote("|".join(cands), safe="|")
           + "&requestMethod=itv&noform=1&partnerId=2&fund=1&exthrs=1"
             "&output=json")
    try:
        raw = urllib.request.urlopen(
            urllib.request.Request(url, headers={"User-Agent": UA}),
            timeout=10).read()
        rows = (((json.loads(raw.decode("utf-8", "replace"))
                  .get("ITVQuoteResult") or {}).get("ITVQuote")) or [])
        if isinstance(rows, dict):
            rows = [rows]
        best = None
        for r in rows:
            nm = str(r.get("name") or r.get("shortName") or "")
            if "brent" not in nm.lower():
                continue
            last = _n(r.get("last"))
            if last is None:
                continue
            cand = {"name": "BRENT", "last": round(last, 2),
                    "chg": round(_n(r.get("change")) or 0, 2),
                    "pct": round(_n(r.get("change_pct")) or 0, 2),
                    "src": "CNBC " + str(r.get("symbol")),
                    "instrument": nm,
                    "mktOpen": str(r.get("curmktstatus", "")).upper() == "REG_MKT"}
            if best is None or cand["last"] < best["last"]:
                best = cand      # front month trades below deferred contracts
        if best:
            BRENT_PICK.update({"symbol": best["src"], "name": best["instrument"],
                               "at": time.time()})
            return best
    except Exception:
        pass
    # Moneycontrol commodity feed as the backstop
    try:
        raw = urllib.request.urlopen(
            urllib.request.Request(
                "https://priceapi.moneycontrol.com/pricefeed/mcx/commodity/"
                "crudeoil", headers={"User-Agent": UA,
                                     "Referer": "https://www.moneycontrol.com/"}),
            timeout=10).read()
        d = (json.loads(raw.decode("utf-8", "replace")) or {}).get("data") or {}
        last = to_number(d.get("pricecurrent"))
        if last:
            return {"name": "BRENT", "last": round(last, 2),
                    "chg": round(to_number(d.get("pricechange")) or 0, 2),
                    "pct": round(to_number(d.get("pricepercentchange")) or 0, 2),
                    "src": "Moneycontrol", "instrument": "Crude oil"}
    except Exception:
        pass
    return None


BRENT_MC_URLS = (
    "https://priceapi.moneycontrol.com/pricefeed/mcx/commodityfuture/BRENTCRUDEOIL",
    "https://priceapi.moneycontrol.com/pricefeed/nse/commodity/brentcrude",
    "https://priceapi.moneycontrol.com/pricefeed/notapplicable/commodity/"
    "in%3Bbrentcrude",
    "https://api.moneycontrol.com/mcapi/v1/commodity/getCommodityPrice"
    "?commodity=brentcrude",
)


def brent_spot():
    """Whatever Moneycontrol quotes for Brent - always shown in US dollars.
    If their figure comes in rupees (their MCX feed does), it is converted at
    the live USD/INR already on the ticker, and the row says so."""
    for url in BRENT_MC_URLS:
        try:
            raw = urllib.request.urlopen(
                urllib.request.Request(url, headers={
                    "User-Agent": UA, "Accept": "application/json",
                    "Referer": "https://www.moneycontrol.com/"}),
                timeout=8).read()
            d = json.loads(raw.decode("utf-8", "replace"))
            d = d.get("data") or d
            if isinstance(d, list) and d:
                d = d[0]
            if not isinstance(d, dict):
                continue
            last = to_number(d.get("pricecurrent") or d.get("lastvalue")
                             or d.get("lastprice") or d.get("price"))
            if not last:
                continue
            chg = to_number(d.get("pricechange") or d.get("change")) or 0
            pct = to_number(d.get("pricepercentchange")
                            or d.get("percentchange")) or 0
            note = "Moneycontrol"
            cur = str(d.get("currency") or "").upper()
            looks_rupee = cur in ("INR", "RS") or last > 1000
            if looks_rupee:
                fx = (TICKER["last"].get("USD/INR") or {}).get("last")
                if not fx:
                    continue                 # never show a rupee number as USD
                last, chg = last / fx, chg / fx
                note = "Moneycontrol, converted at %.2f" % fx
            return {"name": "BRENT", "last": round(last, 2),
                    "chg": round(chg, 2), "pct": round(pct, 2),
                    "unit": "USD", "src": note}
        except Exception:
            continue
    return None


def mc_quote(label):
    """Moneycontrol price feed - the source he trusts most."""
    key = MC_SYMBOL.get(label)
    if not key:
        return None
    url = ("https://priceapi.moneycontrol.com/pricefeed/notapplicable/"
           "inidicesindia/" + key)
    raw = urllib.request.urlopen(
        urllib.request.Request(url, headers={
            "User-Agent": UA, "Referer": "https://www.moneycontrol.com/"}),
        timeout=10).read()
    d = (json.loads(raw.decode("utf-8", "replace")) or {}).get("data") or {}
    last = to_number(d.get("pricecurrent"))
    if last is None:
        return None
    return {"name": label, "last": round(last, 2),
            "chg": round(to_number(d.get("pricechange")) or 0, 2),
            "pct": round(to_number(d.get("pricepercentchange")) or 0, 2),
            "src": "Moneycontrol",
            "mktOpen": str(d.get("market_state", "")).upper() != "CLOSED"}


def nse_indices():
    """Nifty (and any other NSE index) straight from NSE."""
    out = {}
    data, err = IDX_SESSION.fetch("https://www.nseindia.com/api/allIndices",
                              LIVE_PAGE)
    if err or not isinstance(data, dict):
        return out
    want = {"NIFTY 50": "NIFTY 50"}
    for row in (data.get("data") or []):
        name = str(row.get("index") or row.get("indexSymbol") or "").upper()
        # every sector index's PE comes in this same reply - kept for the
        # VALUATION column, so it costs no extra request
        ipe = to_number(row.get("pe"))
        if ipe:
            INDEX_PE[name] = {"pe": ipe, "last": to_number(row.get("last")),
                              "prev": to_number(row.get("previousClose")),
                              "at": time.time()}
        label = want.get(name)
        if not label:
            continue
        last = to_number(row.get("last"))
        prev = to_number(row.get("previousClose"))
        if last is None:
            continue
        out[label] = {"name": label, "last": round(last, 2),
                      "chg": round(last - prev, 2) if prev else 0,
                      "pct": round((last - prev) / prev * 100, 2) if prev else 0,
                      "src": "NSE"}
    return out


def bse_sensex():
    """Sensex from BSE's own site."""
    for url, ref in (
        ("https://api.bseindia.com/BseIndiaAPI/api/SensexData/w?",
         "https://www.bseindia.com/"),
        ("https://api.bseindia.com/BseIndiaAPI/api/DefaultData/w?"
         "type=index&scripcode=SENSEX", "https://www.bseindia.com/"),
    ):
        try:
            req = urllib.request.Request(url, headers={
                "User-Agent": UA, "Referer": ref, "Origin":
                "https://www.bseindia.com", "Accept": "application/json"})
            raw = urllib.request.urlopen(req, timeout=5).read()
            d = json.loads(raw.decode("utf-8", "replace"))
            rows = d.get("Table") or d.get("Table1") or []
            if isinstance(rows, dict):
                rows = [rows]
            for r in rows:
                name = str(r.get("Index_Name") or r.get("INDEX_NAME") or
                           r.get("scrip_name") or "").upper()
                if "SENSEX" not in name and rows.index(r) != 0:
                    continue
                last = to_number(r.get("CurrValue") or r.get("LTP")
                                 or r.get("Value"))
                chg = to_number(r.get("Chg") or r.get("Change"))
                pct = to_number(r.get("ChgPer") or r.get("PerChg"))
                if last is None:
                    continue
                return {"name": "SENSEX", "last": round(last, 2),
                        "chg": round(chg or 0, 2), "pct": round(pct or 0, 2),
                        "src": "BSE"}
        except Exception:
            continue
    return None


