def hist_record(rows):
    """Every figure of the strip, a point each five minutes per index,
    one file a day, kept 200 days."""
    now = time.time()
    day = time.strftime("%Y-%m-%d")
    path = os.path.join(HIST_DIR, day + ".json")
    with HIST_LOCK:
        due = [r for r in rows if r.get("last") is not None and not
               r.get("stale") and now - HIST_LAST.get(r.get("name"), 0) >= 290]
        if not due:
            return
        os.makedirs(HIST_DIR, exist_ok=True)
        d = _read_json(path, {})
        for r in due:
            d.setdefault(r["name"], []).append([int(now), r["last"]])
            HIST_LAST[r["name"]] = now
        _write_json(path, d)
        if time.localtime().tm_hour == 0:
            cut = (datetime.date.today() - datetime.timedelta(days=200)) \
                .isoformat()
            for f in os.listdir(HIST_DIR):
                if f.endswith(".json") and f[:10] < cut:
                    try:
                        os.remove(os.path.join(HIST_DIR, f))
                    except OSError:
                        pass


def hist_local(name, hours):
    """The dashboard's own readings of one index over the last hours."""
    out = []
    cut = time.time() - hours * 3600
    first = (datetime.date.today() -
             datetime.timedelta(days=int(hours // 24) + 2)).isoformat()
    try:
        files = sorted(f for f in os.listdir(HIST_DIR)
                       if f.endswith(".json") and f[:10] >= first)
    except OSError:
        files = []
    long_ = hours > 40 * 24
    for f in files:
        d = _read_json(os.path.join(HIST_DIR, f), {})
        pts = [p for p in (d.get(name) or []) if p[0] >= cut]
        if long_ and pts:
            pts = pts[-1:]          # one reading a day is enough for months
        out += pts
    return out


def chart_check(syms, day=None):
    """The charts' prices against NSE's own closing prices for the last
    trading day (NSE's daily price file): (ok, words). 20.11 - checked by
    hand on 25 Oct 2026: 840 closes of 60 shares over three weeks matched to
    the paisa, and Nifty 50 and India VIX too."""
    day = day or prior_trading_day(datetime.date.today())
    url = ("https://nsearchives.nseindia.com/products/content/"
           "sec_bhavdata_full_%s.csv" % day.strftime("%d%m%Y"))
    raw = urllib.request.urlopen(urllib.request.Request(
        url, headers={"User-Agent": "Mozilla/5.0"}), timeout=20).read()
    rows = {}
    lines = raw.decode("utf-8", "replace").splitlines()
    head = [h.strip() for h in lines[0].split(",")]
    for ln in lines[1:]:
        m = dict(zip(head, [x.strip() for x in ln.split(",")]))
        if m.get("SERIES") in ("EQ", "BE", "BZ"):
            try:
                rows[m["SYMBOL"]] = float(m["CLOSE_PRICE"])
            except (KeyError, ValueError):
                pass
    checked, off = 0, []
    for sym in syms:
        if sym not in rows:
            continue
        pts, _c = yahoo_history(sym + ".NS", "5d", "1d")
        got = [v for t, v in pts if datetime.datetime.fromtimestamp(t)
               .date() == day]
        if not got:
            continue
        checked += 1
        if abs(got[-1] - rows[sym]) > max(0.06, rows[sym] * 0.0005):
            off.append("%s %.2f vs NSE %.2f" % (sym, got[-1], rows[sym]))
        if checked >= 3:
            break
    if not checked:
        return False, "nothing to compare for %s" % day.isoformat()
    return not off, ("%d shares' closing prices for %s match NSE exactly" % (
        checked, day.strftime("%d %b")) if not off else "; ".join(off))


def yahoo_history(ysym, rng, step):
    # Yahoo turns some browser names away with "too many requests"; a plain
    # "Mozilla/5.0" is let through, and the second server is tried too
    raw, err = None, None
    for host in ("query1", "query2", "query1"):
        url = ("https://%s.finance.yahoo.com/v8/finance/chart/" % host +
               urllib.parse.quote(ysym) + "?range=%s&interval=%s" % (rng, step))
        try:
            raw = urllib.request.urlopen(urllib.request.Request(
                url, headers={"User-Agent": "Mozilla/5.0",
                              "Accept": "application/json"}), timeout=12).read()
            break
        except urllib.error.HTTPError as e:
            err = e
            if e.code not in (429, 500, 502, 503):
                raise
            time.sleep(0.6)
    if raw is None:
        raise err
    r = json.loads(raw.decode("utf-8", "replace"))["chart"]["result"][0]
    ts = r.get("timestamp") or []
    cl = ((r.get("indicators") or {}).get("quote") or [{}])[0].get("close") \
        or []
    pts = [[int(t), round(float(c), 4)] for t, c in zip(ts, cl)
           if c is not None]
    return pts, (r.get("meta") or {}).get("currency") or ""


def price_history(kind, name, rng):
    """[[epoch, value], ...] for an index of the strip or a share, over the
    chosen range, with where it came from."""
    if rng not in HIST_RANGES:
        rng = "1m"
    name = str(name or "").strip()
    key = (kind, name.upper(), rng)
    hit = HIST_CACHE.get(key)
    life = 300 if rng in ("today", "1d", "2d") else \
        6 * 3600 if rng in ("1y", "3y", "5y", "10y", "max") else 3600
    if hit and time.time() - hit["at"] < life:
        return hit["data"]
    yr, step, keep = HIST_RANGES[rng]
    if kind == "share":
        sym = re.sub(r"[^A-Z0-9&-]", "", name.upper())
        ysym = sym + ".NS"
    else:
        sym = name
        ysym = YAHOO_SYM.get(name)
    out = {"ok": False, "points": [], "src": "", "name": name, "range": rng}
    if ysym:
        try:
            pts, cur = yahoo_history(ysym, yr, step)
            span = {"1mo": 31, "6mo": 183, "1y": 366, "5y": 1827,
                    "10y": 3653, "max": 3653}.get(yr)
            if kind == "share" and span and pts and pts[0][0] > \
                    time.time() - span * 86400 * 0.92:
                # 20.14: a renamed share's NSE history on Yahoo starts at
                # the rename; its BSE history is whole
                try:
                    alt, _c = yahoo_history(sym + ".BO", yr, step)
                    first = pts[0][0]
                    if alt and alt[0][0] < first - 5 * 86400:
                        pts = [p for p in alt if p[0] < first - 3600] + pts
                except Exception:
                    pass
            if kind == "share" and step in ("1d", "1wk", "1mo") and \
                    len(pts) < 6:
                # a share listed only days ago (Past IPOs): its first days
                # in 15-minute steps say more than two or three dots
                pts, cur = yahoo_history(ysym, "5d", "15m")
                keep = None
            if keep and pts:
                cut = pts[-1][0] - keep * 3600
                pts = [p for p in pts if p[0] >= cut]
            if rng == "today" and pts:
                # only the latest session (a market closed today shows its
                # last day)
                last_day = time.localtime(pts[-1][0])[:3]
                pts = [p for p in pts if time.localtime(p[0])[:3] == last_day]
            scale = INDEX_SCALE.get(name) if kind != "share" and \
                ysym != "JPYINR=X" else None
            if scale:
                pts = [[t, round(v * scale, 6)] for t, v in pts]
            if len(pts) >= 2:
                out.update(ok=True, points=pts, src="Yahoo Finance",
                           currency=cur)
        except Exception as e:
            out["error"] = "Yahoo: %s" % str(e)[:80]
    if not out["ok"] and kind != "share":
        hours = {"today": 16, "1d": 24, "2d": 48, "1w": 7 * 24,
                 "2w": 14 * 24, "1m": 31 * 24, "6m": 183 * 24,
                 "1y": 366 * 24, "5y": 5 * 366 * 24, "10y": 10 * 366 * 24,
                 "max": 50 * 366 * 24, "3y": 3 * 366 * 24}[rng]
        pts = hist_local(sym, hours)
        if len(pts) >= 2:
            out.update(ok=True, points=pts, src="the dashboard's own "
                       "readings (kept since 24 Oct 2026)")
        else:
            out["error"] = (out.get("error", "") + " - no history yet: "
                            "the dashboard keeps its own readings from now "
                            "on, so this fills in by itself").strip(" -")
    # a failure is tried again after a minute, not after the full life
    HIST_CACHE[key] = {"at": time.time() - (0 if out["ok"] else life - 60),
                       "data": out}
    if len(HIST_CACHE) > 400:
        for k in sorted(HIST_CACHE, key=lambda k: HIST_CACHE[k]["at"])[:200]:
            HIST_CACHE.pop(k, None)
    return out


# ---------------------------------------------------------------------------
# THE FULL CHART (20.12) - candles, the live price, the shares and indices
# to search, and the marks on the chart (dividends, bonuses, splits,
# buybacks, mergers, results, the week's news).
#
# Where the prices come from - checked by hand, 23-25 Oct 2026:
#  * every day's open/high/low/close: Yahoo Finance; its closes matched NSE's
#    own closing-price file to the paisa (840 closes of 60 shares)
#  * TODAY, minute by minute: NSE's own intraday chart (the one on nseindia
#    .com), through the dashboard's NSE session - Yahoo's minute bars agreed
#    with Moneycontrol's on only 55% of minutes, so neither is used for today
#    when NSE answers
#  * the last price: the dashboard's own NSE reading, a few seconds old
#  * earlier days' minute bars: Yahoo (NSE keeps only today) - marked as
#    approximate in the chart
# ---------------------------------------------------------------------------

