def chart_index_ysym(name):
    n = str(name or "").strip().upper()
    hit = CHART_NSE_INDICES.get(n) or YAHOO_SYM.get(n) or \
        YAHOO_SYM.get(str(name or "").strip())
    if hit:
        return hit
    # 20.15: a row from another market (BTC, GOLD, AAPL...) charts its own
    # Yahoo symbol
    try:
        for a in load_state().get("assets") or []:
            if str(a.get("key") or "").upper() == n and a.get("y"):
                return a["y"]
    except Exception:
        pass
    for key, ys, _n, _t, _c in ASSET_CATALOG:
        if key == n:
            return ys
    return None


def yahoo_ohlc(ysym, rng, step, events=False):
    """Yahoo's bars: [[epoch, open, high, low, close, volume]], the currency,
    and the dividends and splits when asked."""
    raw, err = None, None
    q = "?range=%s&interval=%s" % (rng, step) + \
        ("&events=div%7Csplit" if events else "")
    for host in ("query1", "query2", "query1"):
        url = ("https://%s.finance.yahoo.com/v8/finance/chart/" % host +
               urllib.parse.quote(ysym) + q)
        try:
            raw = urllib.request.urlopen(urllib.request.Request(
                url, headers={"User-Agent": "Mozilla/5.0",
                              "Accept": "application/json"}), timeout=15).read()
            break
        except urllib.error.HTTPError as e:
            err = e
            if e.code not in (429, 500, 502, 503):
                raise
            time.sleep(0.6)
    if raw is None:
        raise err
    r = json.loads(raw.decode("utf-8", "replace"))["chart"]["result"][0]
    ts = r.get("timestamp") or []
    qd = ((r.get("indicators") or {}).get("quote") or [{}])[0]
    o, h, lo, c, v = (qd.get(k) or [] for k in
                      ("open", "high", "low", "close", "volume"))
    bars = []
    for i, t in enumerate(ts):
        cl = c[i] if i < len(c) else None
        if cl is None:
            continue
        op = o[i] if i < len(o) and o[i] is not None else cl
        hi = h[i] if i < len(h) and h[i] is not None else max(op, cl)
        lw = lo[i] if i < len(lo) and lo[i] is not None else min(op, cl)
        vol = v[i] if i < len(v) and v[i] is not None else 0
        bars.append([int(t), round(op, 4), round(hi, 4), round(lw, 4),
                     round(cl, 4), int(vol)])
    return bars, (r.get("meta") or {}), (r.get("events") or {})


def _ist_day_start(t_disp):
    return t_disp - t_disp % 86400


def _bucket(t_disp, secs):
    """The start of the bar a moment belongs to - bars start at 9:15, as on
    NSE and Kite (9:15, 9:18, 9:21 ... for three minutes)."""
    if secs >= 86400:
        return _ist_day_start(t_disp)
    day = _ist_day_start(t_disp)
    off = t_disp - day - 33300          # seconds since 9:15
    return day + 33300 + (off // secs) * secs


def _agg(bars, secs):
    """Minute bars into longer ones (three minutes, ten minutes)."""
    out = []
    for t, o, h, lo, c, v in bars:
        b = _bucket(t, secs)
        if out and out[-1][0] == b:
            x = out[-1]
            x[2] = max(x[2], h)
            x[3] = min(x[3], lo)
            x[4] = c
            x[5] += v
        else:
            out.append([b, o, h, lo, c, v])
    return out


def nse_clock_is_utc(ts):
    """True when NSE's chart times are India's clock written as UTC (as on
    28 Oct 2026). Every point of the day is looked at, not the first few:
    an hour of points sits inside market hours either way."""
    if not ts:
        return True
    step = max(1, len(ts) // 200)
    sample = ts[::step]

    def inside(shift):
        return sum(1 for t in sample
                   if 535 <= ((t + shift) % 86400) // 60 <= 965)
    return inside(0) >= inside(IST_SHIFT)


def _nse_points_today(kind, name):
    """NSE's own intraday chart for today: [[epoch (true), price]]."""
    key = (kind, name)
    hit = CHART_NSE_TODAY.get(key)
    if hit and time.time() - hit["at"] < 20:
        return hit["pts"]
    if kind == "share":
        url = NSE_CHART + Q(name.upper() + "EQN") + "&type=symbol"
        ref = "https://www.nseindia.com/get-quotes/equity?symbol=" + Q(name)
    else:
        url = NSE_CHART + Q(name.upper()) + "&type=index"
        ref = "https://www.nseindia.com/market-data/live-market-indices"
    pts = []
    try:
        data, err = SESSION.fetch(url, ref, name if kind == "share"
                                  else "RELIANCE")
        raw = (data.get("grapthData") or data.get("graphData") or []) \
            if isinstance(data, dict) else []
        good = [(float(p[0]) / 1000.0, float(p[1])) for p in raw
                if isinstance(p, (list, tuple)) and len(p) >= 2 and
                p[1] not in (None, "") and
                (len(p) < 3 or p[2] in ("NM", "", None))]

        # NSE writes India's clock time as if it were UTC: whichever reading
        # puts the day's points (sampled across the WHOLE day) inside market
        # hours wins
        shift = -IST_SHIFT if nse_clock_is_utc([t for t, _p in good]) else 0
        pts = [[t + shift, p] for t, p in good
               if 555 <= ((t + shift + IST_SHIFT) % 86400) // 60 < 930]
        today = datetime.date.today()
        pts = [p for p in pts if datetime.datetime.fromtimestamp(
            p[0], datetime.timezone(datetime.timedelta(seconds=IST_SHIFT)))
            .date() == today]
    except Exception:
        pts = []
    CHART_NSE_TODAY[key] = {"at": time.time(), "pts": pts}
    if len(CHART_NSE_TODAY) > 60:
        for k in sorted(CHART_NSE_TODAY,
                        key=lambda k: CHART_NSE_TODAY[k]["at"])[:30]:
            CHART_NSE_TODAY.pop(k, None)
    return pts


def chart_live(kind, name):
    """The latest price: {ltp, open, high, low, prev, at, src}."""
    name = str(name or "").strip()
    out = {"ok": False, "open": market_hours()}
    if kind == "share":
        sym = re.sub(r"[^A-Z0-9&-]", "", name.upper())
        with CACHE_LOCK:
            q = dict(CACHE.get(sym) or {})
        if not q.get("ltpNum") or time.time() - (q.get("at") or 0) > 30:
            hit = CHART_LIVE.get(sym)
            if hit and time.time() - hit["at"] < 4:
                q = hit["q"]
            elif not (hit and time.time() - hit["at"] < 4):
                try:
                    f = fetch_symbol(sym, light=True)
                    q = {"ltpNum": to_number(f.get("ltp")),
                         "open": f.get("open"), "dayHigh": f.get("dayHigh"),
                         "dayLow": f.get("dayLow"),
                         "prevclose": f.get("prevclose"),
                         "at": time.time() if f.get("ltp") else 0}
                except Exception:
                    q = {}
                CHART_LIVE[sym] = {"at": time.time(), "q": q}
                if len(CHART_LIVE) > 80:
                    for k in sorted(CHART_LIVE,
                                    key=lambda k: CHART_LIVE[k]["at"])[:40]:
                        CHART_LIVE.pop(k, None)
        if q.get("ltpNum"):
            out.update(ok=True, ltp=q.get("ltpNum"),
                       o=to_number(q.get("open")),
                       h=to_number(q.get("dayHigh")),
                       l=to_number(q.get("dayLow")),
                       prev=to_number(q.get("prevclose")),
                       at=int(q.get("at") or 0), src="NSE")
        return out
    up = name.upper()
    for r in TICKER.get("rows") or []:
        if str(r.get("name") or "").upper() == up and \
                r.get("last") is not None and not r.get("stale"):
            out.update(ok=True, ltp=r.get("last"), prev=r.get("prev"),
                       at=int(TICKER.get("at") or 0),
                       src=r.get("src") or "the strip")
            break
    return out


CHART_SPAN = {"5d": 5, "1mo": 31, "1y": 366, "10y": 3653, "20y": 3653,
              "max": 3653}
CHART_TOL = {"5d": 4, "1mo": 6, "1y": 25, "10y": 90, "20y": 90, "max": 90}


def _bse_splice(name, raw, rng, step):
    """20.14: Yahoo's NSE history of a renamed share starts at the rename
    (ICICILIFE.NS: 10 days; ICICIPRULI.NS: 71) while its BSE history is
    whole (ICICILIFE.BO: ten years). When the NSE bars start well after the
    period asked for, the days before them come from BSE, with BSE's volume
    scaled to NSE's on the days both have. Returns (bars, note)."""
    span = CHART_SPAN.get(rng)
    if not span:
        return raw, ""
    want = time.time() - span * 86400
    first = raw[0][0] if raw else time.time()
    if first <= want + CHART_TOL.get(rng, 30) * 86400:
        return raw, ""
    names = [name] + [o for o, v in (nse_symbol_changes() or {}).items()
                      if v and v[0] == name]
    best = []
    for n in names:
        try:
            alt, _m, _e = yahoo_ohlc(n + ".BO", rng, step)
        except Exception:
            continue
        if alt and alt[0][0] < first - 3 * 86400 and len(alt) > len(best):
            best = alt
            break
    if not best:
        return raw, ""
    nse_day = {b[0] // 86400: b[5] for b in raw if b[5]}
    ratios = sorted(nse_day[b[0] // 86400] / b[5] for b in best
                    if b[5] and b[0] // 86400 in nse_day)
    k = ratios[len(ratios) // 2] if ratios else 1.0
    before = [[b[0], b[1], b[2], b[3], b[4], int((b[5] or 0) * k)]
              for b in best if b[0] < first - 3600]
    return before + list(raw), "BSE before %s" % datetime.datetime.fromtimestamp(
        first).strftime("%d %b %Y")


def _icp_bars(sym, bars, secs, today_disp):
    """Today's bars after continuous trading closes: Yahoo's are dropped and
    the ICP readings of the auction (kept while the dashboard was open) are
    put in their place, ending at the closing price once it is out."""
    if not is_trading_day():
        return bars, None
    ct = cas_times()
    now = datetime.datetime.now()
    if now.hour * 60 + now.minute < ct["ctsEnd"]:
        return bars, None
    with SERIES_LOCK:
        pts = list(SERIES.get(sym) or [])
    t_end = today_disp + ct["ctsEnd"] * 60
    t_in = today_disp + ct["entry"] * 60
    t_shut = today_disp + ct["shut"] * 60
    icp = [(int(p[0]) + IST_SHIFT, p[1]) for p in pts
           if p[1] and t_in <= int(p[0]) + IST_SHIFT <= t_shut + 120]
    if not icp:
        return bars, None
    keep = [b for b in bars if b[0] < t_end]
    mine = []
    for t, v in icp:
        bk = _bucket(t, secs)
        if mine and mine[-1][0] == bk:
            x = mine[-1]
            x[2], x[3], x[4] = max(x[2], v), min(x[3], v), v
        else:
            mine.append([bk, v, v, v, v, 0, 1])
    with CACHE_LOCK:
        q = dict(CACHE.get(sym) or {})
    close = to_number(q.get("close"))
    if close and now.hour * 60 + now.minute >= ct["matched"]:
        bk = _bucket(t_shut, secs)
        if mine and mine[-1][0] >= bk:
            mine[-1][4] = close
            mine[-1][2] = max(mine[-1][2], close)
            mine[-1][3] = min(mine[-1][3], close)
        else:
            mine.append([bk, close, close, close, close, 0, 1])
    return keep + mine, {"from": t_in, "end": t_end, "shut": t_shut,
                         "ctsText": hm_text(ct["ctsEnd"])}


def chart_candles(kind, name, tf):
    """Bars for the full chart, with times written the way the chart
    library shows them (India's clock), and where each part came from."""
    tf = tf if tf in CHART_TF else "1d"
    name = str(name or "").strip()
    step, rng, secs = CHART_TF[tf]
    if kind == "share":
        name = re.sub(r"[^A-Z0-9&-]", "", name.upper())
        ysym = name + ".NS"
    else:
        ysym = chart_index_ysym(name)
    out = {"ok": False, "bars": [], "tf": tf, "name": name, "kind": kind,
           "daily": secs is None}
    if not ysym:
        out["error"] = "no chart is known for %s" % name
        return out
    key = (kind, name.upper(), tf)
    hit = CHART_CACHE.get(key)
    life = (120 if secs and secs < 3600 else 600) if secs else 1800
    if hit and time.time() - hit["at"] < life:
        bars, meta = hit["bars"], hit["meta"]
    else:
        try:
            raw, meta, _ev = yahoo_ohlc(ysym, rng, step)
        except Exception as e:
            out["error"] = "Yahoo: %s" % str(e)[:90]
            return out
        if kind == "share":
            raw, spliced = _bse_splice(name, raw, rng, step)
            if spliced:
                meta = dict(meta or {}, spliced=spliced)
        if secs:
            bars = [[t + IST_SHIFT] + b[1:] for b in raw for t in (b[0],)]
            if secs in (180, 600):
                bars = _agg(bars, secs)
        else:
            bars, seen = [], {}
            for b in raw:
                d = _ist_day_start(b[0] + IST_SHIFT)
                if d in seen:                 # Yahoo repeats today's bar
                    bars[seen[d]] = [d] + b[1:]
                else:
                    seen[d] = len(bars)
                    bars.append([d] + b[1:])
        scale = INDEX_SCALE.get(name) if kind != "share" else None
        if scale:
            bars = [[b[0]] + [round(x * scale, 6) for x in b[1:5]] + [b[5]]
                    for b in bars]
        meta = {"currency": meta.get("currency") or "",
                "tz": meta.get("exchangeTimezoneName") or "",
                "spliced": meta.get("spliced") or ""}
        CHART_CACHE[key] = {"at": time.time(), "bars": bars, "meta": meta}
        if len(CHART_CACHE) > 120:
            for k in sorted(CHART_CACHE,
                            key=lambda k: CHART_CACHE[k]["at"])[:60]:
                CHART_CACHE.pop(k, None)
    bars = [list(b) for b in bars]
    src = "Yahoo Finance"
    today_disp = _ist_day_start(int(time.time()) + IST_SHIFT)
    # 28 Oct 2026: NSE's chart gives a share only one price a minute (no
    # highs and lows), while Yahoo's minute bars matched NSE's minute prices
    # to the paisa 88-93% of the time and always within 0.05% (Tuesday 27
    # Oct, four shares, 361 minutes each) - so a share's bars come from
    # Yahoo, with the last price from NSE live; an index's from NSE's own
    # second-by-second chart
    nse_ok = kind != "share" and (name.upper().startswith("NIFTY") or
                                  name.upper() == "INDIA VIX")
    opened = datetime.datetime.now().strftime("%H:%M") >= "09:00"
    if secs and nse_ok and is_trading_day() and opened:
        pts = _nse_points_today(kind, name)
        if len(pts) >= 3:
            vol = {}
            for b in bars:
                if b[0] >= today_disp:
                    vol[_bucket(b[0], secs)] = vol.get(
                        _bucket(b[0], secs), 0) + b[5]
            mine = []
            for t, p in pts:
                b = _bucket(int(t) + IST_SHIFT, secs)
                if mine and mine[-1][0] == b:
                    x = mine[-1]
                    x[2], x[3], x[4] = max(x[2], p), min(x[3], p), p
                else:
                    mine.append([b, p, p, p, p, vol.get(b, 0)])
            bars = [b for b in bars if b[0] < today_disp] + mine
            src = "today: NSE (second by second) · earlier days: Yahoo " \
                  "Finance"
        else:
            src = "Yahoo Finance (NSE's own chart did not answer)"
    elif secs and kind == "share":
        src = "Yahoo Finance minute bars (checked against NSE: within " \
              "0.05%, mostly to the paisa) · last price: NSE live"
        # 20.14: the closing auction on today's chart - the normal price
        # until continuous trading ends, nothing while orders are only being
        # taken, then the ICP as it moved, and last the closing price
        try:
            bars, auc = _icp_bars(name, bars, secs, today_disp)
            if auc:
                out["auction"] = auc
                src += " · after %s: the auction's ICP" % auc["ctsText"]
        except Exception:
            pass
    elif secs:
        src = "Yahoo Finance"
    if not secs and kind == "share" and is_trading_day() and bars:
        live = chart_live(kind, name)
        if live.get("ok") and live.get("ltp"):
            last = bars[-1]
            if last[0] < today_disp and market_hours():
                last = [today_disp, live.get("o") or live["ltp"],
                        live.get("h") or live["ltp"],
                        live.get("l") or live["ltp"], live["ltp"], 0]
                bars.append(last)
            if last[0] == today_disp:
                last[4] = live["ltp"]
                if live.get("h"):
                    last[2] = max(live["h"], live["ltp"])
                if live.get("l"):
                    last[3] = min(live["l"], live["ltp"])
                if live.get("o"):
                    last[1] = live["o"]
            src = "Yahoo Finance (closes match NSE to the paisa) · today: NSE"
    if bars:
        clean = {}
        for b in bars:
            clean[b[0]] = b                  # one bar per time, the latest
        bars = [clean[t] for t in sorted(clean)]
    if meta.get("spliced"):
        src += " · %s (NSE's own history on Yahoo starts at the rename)" \
            % meta["spliced"]
    if len(bars) >= 1:
        out.update(ok=True, bars=bars, src=src, currency=meta.get("currency"))
    else:
        out["error"] = "no prices for %s" % name
    return out


def equity_list():
    """Every share listed on NSE (NSE's own list, read once a week)."""
    if EQUITY_LIST["rows"] and time.time() - EQUITY_LIST["at"] < 7 * 86400:
        return EQUITY_LIST["rows"]
    raw = None
    try:
        if time.time() - os.path.getmtime(EQUITY_FILE) < 7 * 86400:
            with open(EQUITY_FILE, "rb") as f:
                raw = f.read()
    except OSError:
        pass
    if raw is None:
        try:
            raw = urllib.request.urlopen(urllib.request.Request(
                "https://nsearchives.nseindia.com/content/equities/"
                "EQUITY_L.csv", headers={"User-Agent": "Mozilla/5.0"}),
                timeout=20).read()
            if raw.count(b"\n") > 500:
                os.makedirs(DATA_DIR, exist_ok=True)
                with open(EQUITY_FILE, "wb") as f:
                    f.write(raw)
        except Exception:
            try:
                with open(EQUITY_FILE, "rb") as f:
                    raw = f.read()           # an older copy beats nothing
            except OSError:
                raw = b""
    rows = []
    lines = raw.decode("utf-8", "replace").splitlines()
    if lines:
        head = [h.strip().upper() for h in lines[0].split(",")]
        for ln in csv.reader(lines[1:]):
            m = dict(zip(head, [x.strip() for x in ln]))
            if m.get("SYMBOL") and m.get("SERIES", "EQ") in ("EQ", "BE", "BZ",
                                                              "SM", "ST"):
                rows.append((m["SYMBOL"].upper(),
                             m.get("NAME OF COMPANY", "")))
    EQUITY_LIST.update(at=time.time(), rows=rows)
    return rows


def chart_search(q, limit=12):
    """Shares and indices by symbol or by name, the watchlist first."""
    q = re.sub(r"\s+", " ", str(q or "").strip().upper())[:40]
    if not q:
        return []
    watch = [s.upper() for s in (load_state().get("watchlist") or [])]
    names = dict(equity_list())
    scored = []
    for n in list(CHART_NSE_INDICES) + [k for k in YAHOO_SYM
                                        if k not in CHART_NSE_INDICES]:
        u = n.upper()
        if u.startswith(q) or (" " + q) in (" " + u) or \
                u.replace(" ", "").startswith(q.replace(" ", "")):
            scored.append((1 if u.startswith(q) else 3, n,
                           {"sym": n, "name": "Index" if n in
                            CHART_NSE_INDICES else "On the strip",
                            "kind": "index"}))
    for s, nm in names.items():
        nu = nm.upper()
        if s.startswith(q):
            sc = 0 if s == q else 1
        elif (" " + q) in (" " + nu):
            sc = 2
        else:
            continue
        if s in watch:
            sc -= 0.5
        scored.append((sc, s, {"sym": s, "name": nm, "kind": "share",
                               "watch": s in watch}))
    for s in watch:
        if s not in names and s.startswith(q):
            scored.append((0.5, s, {"sym": s, "name": "", "kind": "share",
                                    "watch": True}))
    scored.sort(key=lambda x: (x[0], len(x[1]), x[1]))
    out, seen = [], set()
    for _sc, _k, r in scored:
        if (r["kind"], r["sym"]) not in seen:
            seen.add((r["kind"], r["sym"]))
            out.append(r)
        if len(out) >= limit:
            break
    return out


SCREENER_Q = {}         # sym -> {"at": time, "q": {quarter end: figures}}


def _scr_num(t):
    t = re.sub(r"<[^>]+>", "", t).replace("&nbsp;", " ").replace(",", "")
    t = t.replace("%", "").strip()
    try:
        return float(t)
    except ValueError:
        return None


def screener_quarters(sym):
    """The company's quarterly results from Screener.in (in Rs crore):
    {"2026-09-30": {"sales": 6788, "np": 912, "eps": 9.5}, ...}.
    Consolidated first, the company's own figures when there are none.
    Read once every 12 hours per share; {} when Screener does not answer."""
    sym = re.sub(r"[^A-Z0-9]", "", str(sym or "").upper())
    hit = SCREENER_Q.get(sym)
    if hit and time.time() - hit["at"] < 12 * 3600:
        return hit["q"]
    out = {}
    for tail in ("consolidated/", ""):
        try:
            raw = _tt_get("https://www.screener.in/company/" + sym + "/" +
                          tail, timeout=15)
        except Exception:
            continue
        a = raw.find('id="quarters"')
        if a < 0:
            continue
        seg = raw[a:]
        seg = seg[:seg.find("</table>")]
        keys = re.findall(r'data-date-key="(\d{4}-\d\d-\d\d)"', seg)
        if not keys:
            continue
        rows = {}
        for tr in re.findall(r"<tr[^>]*>(.*?)</tr>", seg, re.S):
            cells = re.findall(r"<td[^>]*>(.*?)</td>", tr, re.S)
            if len(cells) < 2:
                continue
            name = re.sub(r"<[^>]+>|&nbsp;|\+", " ", cells[0])
            name = re.sub(r"\s+", " ", name).strip().lower()
            rows[name] = [_scr_num(c) for c in cells[1:]]
        sales = rows.get("sales") or rows.get("revenue") or []
        np_ = rows.get("net profit") or []
        eps = rows.get("eps in rs") or []
        for i, k in enumerate(keys):
            f = {"sales": sales[i] if i < len(sales) else None,
                 "np": np_[i] if i < len(np_) else None,
                 "eps": eps[i] if i < len(eps) else None}
            if f["np"] is not None or f["sales"] is not None:
                out[k] = f
        if any(v.get("np") is not None for v in out.values()):
            break
        out = {}
    SCREENER_Q[sym] = {"at": time.time() - (11 * 3600 if not out else 0),
                       "q": out}
    if len(SCREENER_Q) > 300:
        for k in sorted(SCREENER_Q, key=lambda x: SCREENER_Q[x]["at"])[:100]:
            SCREENER_Q.pop(k, None)
    return out


EXPECT_TONE = {"STRONG": 15.0, "MODERATE": 5.0, "MIXED": 0.0, "WEAK": -5.0}


def expected_growth(verdict, why):
    """What the previews expected for profit growth from a year ago, in %:
    the figure they give ("profit seen up 13% YoY") or, without one, a
    rough figure from their tone. (pct, True when it is a real figure)."""
    t = (why or "").lower()
    m = re.search(r"(?:net )?profit[^.;%]{0,40}?\b(up|down|rise|rises|"
                  r"fall|falls|grow|grows|growth|decline|declines|jump|"
                  r"jumps|drop|drops|surge|dip)\b[^%\d-]{0,15}"
                  r"(\d+(?:\.\d+)?)\s*%", t)
    if m:
        v = float(m.group(2))
        neg = m.group(1).startswith(("down", "fall", "decline", "drop",
                                      "dip"))
        return (-v if neg else v), True
    v = EXPECT_TONE.get(str(verdict or "").upper())
    return (v, False) if v is not None else (None, False)


def results_figures(sym, iso, verdict="", why=""):
    """The quarter a results meeting on `iso` reported, with profit, sales,
    the change from the same quarter a year earlier and how that compares
    with what was expected."""
    q = screener_quarters(sym)
    if not q:
        return {}
    try:
        d0 = datetime.date.fromisoformat(iso)
    except ValueError:
        return {}
    ends = [k for k in q if k < iso and
            (d0 - datetime.date.fromisoformat(k)).days <= 120]
    if not ends:
        return {}
    k = max(ends)
    f = q[k]
    kd = datetime.date.fromisoformat(k)
    prev = None
    for p in q:
        pd = datetime.date.fromisoformat(p)
        if abs((kd - pd).days - 365) <= 6:
            prev = q[p]
            break

    def pct(a, b):
        if a is None or b is None or not b:
            return None
        return round((a - b) / abs(b) * 100, 1)
    out = {"qtr": kd.strftime("%b %Y"), "np": f.get("np"),
           "sales": f.get("sales"), "eps": f.get("eps"),
           "npYoY": pct(f.get("np"), prev and prev.get("np")),
           "salesYoY": pct(f.get("sales"), prev and prev.get("sales"))}
    exp, real = expected_growth(verdict, why)
    if exp is not None and out["npYoY"] is not None:
        gap = out["npYoY"] - exp
        band = 3 if real else 6
        out["expPct"] = exp
        out["expReal"] = real
        out["vsExp"] = ("better" if gap > band else
                        "worse" if gap < -band else "in line")
    return out


def _chart_kind(text):
    t = (text or "").lower()
    for w, k in (("demerger", "Demerger"), ("amalgamation", "Merger"),
                 ("merger", "Merger"), ("scheme of arrangement", "Merger")):
        if w in t:
            return k
    return _corp_kind(text)


def chart_events(sym):
    """Marks for a share's chart: dividends, bonuses, splits, buybacks,
    rights, mergers (NSE's list, Yahoo's when NSE does not answer), results
    (with what was expected, when the dashboard read it) and the last
    week's news."""
    sym = re.sub(r"[^A-Z0-9&-]", "", str(sym or "").upper())
    hit = CHART_EVENTS.get(sym)
    if hit and time.time() - hit["at"] < 6 * 3600:
        return hit["data"]
    out, notes = [], []
    ref = "https://www.nseindia.com/get-quotes/equity?symbol=" + Q(sym)
    nse_acts = False
    try:
        data, err = SESSION.fetch(
            "https://www.nseindia.com/api/corporates-corporateActions"
            "?index=equities&symbol=" + Q(sym), ref, sym, timeout=20)
        for r in (data if isinstance(data, list) else []):
            subj = re.sub(r"\s+", " ", str(r.get("subject") or "")).strip()
            kind = _chart_kind(subj)
            iso = _isodate(r.get("exDate") or "")
            if kind and iso:
                nse_acts = True
                title = subj
                if kind == "Dividend":
                    # 20.13: the amount a share and nothing else
                    amt = re.findall(r"(?:rs|re|inr|\u20b9)\.?\s*"
                                     r"(\d+(?:\.\d+)?)", subj, re.I)
                    if amt:
                        title = "Dividend \u20b9%g a share" % sum(
                            float(a) for a in amt)
                out.append({"date": iso, "kind": kind, "title": title,
                            "text": "", "link": ""})
        if not nse_acts and err:
            notes.append("NSE: %s" % str(err)[:60])
    except Exception as e:
        notes.append("NSE: %s" % str(e)[:60])
    if not nse_acts:
        try:
            _b, _m, ev = yahoo_ohlc(sym + ".NS", "10y", "1mo", events=True)
            for d in (ev.get("dividends") or {}).values():
                iso = datetime.datetime.fromtimestamp(
                    int(d["date"]) + IST_SHIFT,
                    datetime.timezone.utc).date().isoformat()
                out.append({"date": iso, "kind": "Dividend",
                            "title": "Dividend ₹%s a share" %
                            ("%g" % round(float(d.get("amount") or 0), 2)),
                            "text": "", "link": ""})
            for d in (ev.get("splits") or {}).values():
                iso = datetime.datetime.fromtimestamp(
                    int(d["date"]) + IST_SHIFT,
                    datetime.timezone.utc).date().isoformat()
                out.append({"date": iso, "kind": "Split",
                            "title": "Split / bonus %s" %
                            (d.get("splitRatio") or ""),
                            "text": "Ex-date %s (Yahoo Finance)" %
                            _corp_day(iso), "link": ""})
        except Exception as e:
            notes.append("Yahoo: %s" % str(e)[:60])
    # results: the board meetings that approved them, each linked to the
    # results the company filed that day (the PDF in its "Outcome of Board
    # Meeting" filing)
    pv = previews()
    seen = set()
    pdfs = {}
    try:
        data, _e = SESSION.fetch(
            "https://www.nseindia.com/api/corporate-announcements?index="
            "equities&symbol=" + Q(sym) + "&subject=" +
            Q("Outcome of Board Meeting"), ref, sym, timeout=20)
        for r in (data if isinstance(data, list) else []):
            f = str(r.get("attchmntFile") or "")
            txt = (str(r.get("attchmntText") or "") + " " + f).lower()
            iso = _isodate(r.get("an_dt") or "")
            if iso and f.lower().endswith(".pdf") and "result" in txt:
                pdfs.setdefault(iso, f)
    except Exception:
        pass

    def results_pdf(iso):
        d0 = datetime.date.fromisoformat(iso)
        for k in range(0, 3):
            hit = pdfs.get((d0 + datetime.timedelta(days=k)).isoformat())
            if hit:
                return hit
        return ""
    try:
        data, err = SESSION.fetch(
            "https://www.nseindia.com/api/corporate-board-meetings"
            "?index=equities&symbol=" + Q(sym), ref, sym, timeout=20)
        for r in (data if isinstance(data, list) else []):
            text = str(r.get("bm_purpose") or "") + " " + \
                str(r.get("bm_desc") or "")
            if "financial result" not in text.lower():
                continue
            iso = _isodate(r.get("bm_date") or "")
            if not iso or iso in seen:
                continue
            seen.add(iso)
            p = pv.get(sym + "|" + iso) or {}
            v = p.get("verdict")
            v = v if v not in (None, "NONE", "UNCLEAR") else ""
            item = {"date": iso, "kind": "Results", "title": "Results",
                    "text": (p.get("why") or "")[:200] if v else "",
                    "expected": v,
                    "link": results_pdf(iso) or (
                        "https://news.google.com/search?q=" +
                        Q("%s results %s" % (sym, iso[:7])))}
            if iso <= datetime.datetime.utcfromtimestamp(
                    time.time() + IST_SHIFT).date().isoformat():
                try:
                    item.update(results_figures(sym, iso, v,
                                                p.get("why") or ""))
                except Exception:
                    pass
            out.append(item)
    except Exception as e:
        notes.append("results: %s" % str(e)[:60])
    for r in CORP_CACHE.get("rows") or []:
        if r.get("symbol") == sym and r.get("kind") == "Results" and \
                r.get("exIso") and r["exIso"] not in seen:
            p = pv.get(sym + "|" + r["exIso"]) or {}
            v = p.get("verdict")
            out.append({"date": r["exIso"], "kind": "Results",
                        "title": "Results due" + (
                            " - expected %s" % v if v and v not in
                            ("NONE", "UNCLEAR") else ""),
                        "text": (p.get("why") or r.get("value") or "")[:200],
                        "expected": v if v not in ("NONE", "UNCLEAR") else "",
                        "link": r.get("link") or ""})
    # the week's news
    try:
        terms, name = share_terms(sym)
        # 20.14: asked for in quotes, and only headlines that name the share
        # itself are kept (BHARTIHEXA showed Bharti Airtel's news)
        names = [t for t in terms if " " in t] or [t for t in terms if t != sym]
        q = '"%s"' % names[0] if names else (
            " ".join(name.split()[:3]) if name else sym)
        rx = [re.compile(r"(?<![A-Za-z])" + re.escape(t) + r"(?![A-Za-z])",
                         0 if t == sym else re.I) for t in terms]
        for it in google_news(q, 20):
            a = it.get("age")
            if a is None or a > 7 * 24:
                continue
            if rx and not any(r.search(it.get("title") or "") for r in rx):
                continue
            out.append({"ts": int(time.time() - a * 3600), "kind": "News",
                        "title": it["title"][:160],
                        "text": it.get("source", ""), "link": it["link"]})
            if sum(1 for x in out if x["kind"] == "News") >= 8:
                break
    except Exception:
        pass
    data = {"ok": True, "items": out, "notes": notes, "sym": sym}
    CHART_EVENTS[sym] = {"at": time.time() - (5 * 3600 if notes else 0),
                         "data": data}
    if len(CHART_EVENTS) > 80:
        for k in sorted(CHART_EVENTS, key=lambda k: CHART_EVENTS[k]["at"])[:40]:
            CHART_EVENTS.pop(k, None)
    return data


# ---------------------------------------------------------------------------
# LONG-TERM GAINS DATES (20.10) - from the workbook (read only): the shares
# still held, parcel by parcel, oldest sold first as in the workbook's P&L.
# A parcel becomes long-term once held more than 365 days; the hover box of
# a share warns in the last five days.
# ---------------------------------------------------------------------------

LTCG_CACHE = {"at": 0, "mtime": 0, "data": {}}


def ltcg_soon():
    """{SYMBOL: [{"date", "qty", "days"}]} for parcels that turn long-term
    within 30 days (the box shows those within 5)."""
    use_acc = acc_load() is not None
    p = acc_path() if use_acc else ""
    try:
        mt = os.path.getmtime(p) if p else 0
    except OSError:
        mt = 0
    if LTCG_CACHE["mtime"] == mt and time.time() - LTCG_CACHE["at"] < 3600:
        return LTCG_CACHE["data"]
    out = {}
    try:
        today = datetime.date.today()
        held = (acc_view()[1] or {}).get("parcels", {}) if use_acc else {}
        for sym, lots in held.items():
            for lot in lots:
                d, q = lot[0], lot[1]
                bought = datetime.date.fromisoformat(d)
                days = (bought + datetime.timedelta(days=366) - today).days
                if 0 <= days <= 30:
                    out.setdefault(sym, []).append(
                        {"date": d, "qty": round(q, 4), "days": days})
        LTCG_CACHE.update(at=time.time(), mtime=mt, data=out, error="")
    except Exception as e:
        LTCG_CACHE.update(at=time.time(), mtime=mt, data={},
                          error=str(e)[:120])
    return LTCG_CACHE["data"]


# ---------------------------------------------------------------------------
# ACCOUNTS (20.13, 20.14) - the accounts inside the dashboard: Summary,
# Transactions, P&L, Capital gains, Holdings, Passive Income, Charges,
# Reconciliation and a User Manual, worked out on this computer: FIFO cost,
# the charges engine with its day-wise STT and stamp rounding, intraday
# matching, the tax label. Rows are typed here, or built from the broker's
# own statements (20.14), which never leave the computer. Kept per profile
# in accounts.json (the year running) and accounts-YYYY-YY.json (past
# years), with copies of the last versions in Backups.
# ---------------------------------------------------------------------------

ACC_LOCK = threading.RLock()
ACC_CACHE = {"key": None, "data": None}
ACC_TYPES = ("BUY", "SELL", "OPENING_CASH", "OPENING_SHARES", "FUND_ADD",
             "FUND_WITHDRAWAL", "EXPENSE", "BONUS", "SPLIT", "RIGHTS_ISSUE",
             "DEMERGER", "BUYBACK")
ACC_LOT_TYPES = ("OPENING_SHARES", "BONUS", "SPLIT", "RIGHTS_ISSUE",
                 "DEMERGER")
ACC_MONEY_TYPES = ("OPENING_CASH", "FUND_ADD", "FUND_WITHDRAWAL", "EXPENSE")
ACC_EXPENSES = ["AMC", "PAYMENT_GATEWAY", "BUYBACK_FEE", "CHARGES_ADJ"]
ACC_PASSIVE = ["DIVIDEND", "INTEREST"]
# 20.16: what a BUY / SELL row is - (name, Profile kind, taxed like shares).
# Charges are worked out for shares only (the broker's rates for equity);
# for the others they are whatever is typed from the contract note.
ACC_INST = {"": ("Shares", "equity", True),
            "ipo": ("IPO allotment", "equity", True),
            "etf_eq": ("Equity ETF", "equity", True),
            "reit": ("REIT / InvIT units", "equity", True),
            "mf_eq": ("Equity mutual fund", "fund", True),
            "mf_debt": ("Debt / other mutual fund", "fund", False),
            "bond": ("Bond / NCD", "bond", False),
            "gsec": ("G-sec / T-bill / SDL", "bond", False),
            "sgb": ("Sovereign Gold Bond", "gold", False),
            "etf_gold": ("Gold / silver ETF", "gold", False)}
# brokerage and DP of each broker (as in the dashboard's Profile -> Broker)
ACC_BROKERS = {
    "zerodha": {"del": {"pct": 0}, "intra": {"pct": 0.03, "cap": 20},
                "dp": 15.34, "zerodha": True},
    "groww": {"del": {"pct": 0.1, "cap": 20, "min": 5},
              "intra": {"pct": 0.1, "cap": 20, "min": 5}, "dp": 23.6},
    "angel": {"del": {"pct": 0.1, "cap": 20, "min": 5},
              "intra": {"pct": 0.1, "cap": 20, "min": 5}, "dp": 23.6},
    "upstox": {"del": {"flat": 20}, "intra": {"pct": 0.1, "cap": 20},
               "dp": 23.6},
    "dhan": {"del": {"pct": 0}, "intra": {"pct": 0.03, "cap": 20},
             "dp": 14.75},
}


def xround(x, n=0):
    """Excel's ROUND: halves away from zero (Python's round() goes to the
    even number), done on the decimal text so 2.675 is 2.68 as in Excel."""
    import decimal
    q = decimal.Decimal(1).scaleb(-n)
    d = decimal.Decimal(repr(float(x))).quantize(
        q, rounding=decimal.ROUND_HALF_UP)
    return float(d)


# 20.19: the rates of the charges, by name, so a contract note can correct
# one (with his yes) from the note's date onward - trades before that date
# keep the rate they were made at. Defaults are the rates in force when
# 20.19 was made (Zerodha's charges page and NSE/BSE circulars).
CHG_RATES = {
    "stt_del": (0.001, "STT on delivery buys and sales", "% of the value"),
    "stt_intra": (0.00025, "STT on intraday sales", "% of the value"),
    "exch_nse": (0.0000307, "NSE transaction charge (with the IPF "
                 "contribution)", "% of the value"),
    "exch_bse": (0.0000375, "BSE transaction charge", "% of the value"),
    "sebi": (0.000001, "SEBI turnover fee (Rs 10 a crore)",
             "% of the value"),
    "gst": (0.18, "GST on brokerage, exchange and SEBI charges",
            "% of those charges"),
    "stamp_del": (0.00015, "Stamp duty on delivery buys", "% of the value"),
    "stamp_intra": (0.00003, "Stamp duty on intraday buys",
                    "% of the value"),
}
_RATE_CACHE = {"at": None, "hist": []}
_RATE_TL = threading.local()   # 20.19: a rate tried on a contract note,
                               # in this thread only, never saved


def _rate_try():
    if not hasattr(_RATE_TL, "d"):
        _RATE_TL.d = {}
    return _RATE_TL.d


def chg_rate_hist():
    """[{key, v, from, note, at}] - the rates changed from contract notes,
    oldest first. Kept in the Accounts settings file (accounts_ui.json)."""
    try:
        mt = os.path.getmtime(acc_ui_path())
    except OSError:
        mt = 0
    if _RATE_CACHE["at"] != mt:
        h = [x for x in (acc_ui().get("rates") or [])
             if isinstance(x, dict) and x.get("key") in CHG_RATES]
        h.sort(key=lambda x: str(x.get("from") or ""))
        _RATE_CACHE.update(at=mt, hist=h)
    return _RATE_CACHE["hist"]


def chg_rate(key, d=""):
    """The rate in force on day d (iso): the newest change made from a
    date on or before d, else the default."""
    tr = _rate_try()
    if key in tr:
        return tr[key]
    v = CHG_RATES[key][0]
    for x in chg_rate_hist():
        if x["key"] == key and str(x.get("from") or "") <= str(d or "9"):
            try:
                v = float(x["v"])
            except (TypeError, ValueError):
                pass
    return v


def acc_broker():
    st = load_state()
    p = st.get("prefs") or {}
    k = p.get("broker") or "zerodha"
    if k == "other":
        o = p.get("brokerOwn") or {}

        def n(v, d):
            try:
                return float(v) if v not in (None, "") else d
            except (TypeError, ValueError):
                return d
        return {"del": {"pct": n(o.get("delPct"), 0),
                        "cap": n(o.get("delCap"), 0)},
                "intra": {"pct": n(o.get("intraPct"), 0.03),
                          "cap": n(o.get("intraCap"), 20)},
                "dp": n(o.get("dp"), 15.34)}
    return ACC_BROKERS.get(k) or ACC_BROKERS["zerodha"]


def _brokerage(rule, val):
    if not val or val <= 0 or not rule:
        return 0.0
    if rule.get("flat"):
        return float(rule["flat"])
    b = val * float(rule.get("pct") or 0) / 100
    if rule.get("cap"):
        b = min(b, float(rule["cap"]))
    if rule.get("min") and b > 0:
        b = max(b, float(rule["min"]))
    return b


def _anum(v):
    if v in (None, ""):
        return None
    try:
        f = float(v)
        return f if math.isfinite(f) else None
    except (TypeError, ValueError):
        return None


def acc_compute(acc, broker=None, today=None, upto=None):
    """Every sheet worked out from the typed rows - the workbook's formulas
    one by one. Returns plain lists and figures for the box. upto (an iso
    date) leaves out the rows after it (the broker check compares up to the
    last day of the broker's statements)."""
    broker = broker or ACC_BROKERS["zerodha"]
    today = today or datetime.date.today()
    tx = []
    for i, r in enumerate(acc.get("tx") or []):
        if upto and str(r.get("date") or "") > upto:
            continue
        t = dict(r)
        t["i"] = i
        t["type"] = str(t.get("type") or "").strip().upper()
        t["sym"] = str(t.get("sym") or "").strip().upper()
        t["qty"] = _anum(t.get("qty"))
        t["price"] = _anum(t.get("price"))
        t["override"] = _anum(t.get("override"))
        t["yes"] = bool(t.get("intra"))
        t["d"] = t.get("date") or ""
        t["inst"] = t.get("inst") if t.get("inst") in ACC_INST else ""
        # H: GROSS VALUE
        if t["qty"] is None or t["price"] is None:
            t["gross"] = None
        else:
            t["gross"] = t["override"] if t["override"] is not None \
                else t["qty"] * t["price"]
        tx.append(t)
    by_i = {t["i"]: t for t in tx}
    # ---- Charges: one row per BUY / SELL, in the order typed ----
    trades = [t for t in tx if t["type"] in ("BUY", "SELL")]
    first = {}
    for t in tx:          # XLOOKUP finds the first row with the same key
        if t["gross"] is None:
            continue
        k = (t["d"], t["type"], t["sym"], round(abs(t["gross"]), 6))
        first.setdefault(k, t)
    ch = []
    for t in trades:
        e = abs(t["gross"]) if t["gross"] is not None else 0.0
        k = (t["d"], t["type"], t["sym"], round(e, 6))
        src = first.get(k, t)
        ch.append({"d": t["d"], "type": t["type"], "sym": t["sym"], "e": e,
                   "yes": src["yes"], "inst": t["inst"],
                   "exch": "BSE" if str(src.get("exch") or "").upper()
                   .startswith("B") else "NSE", "tx": t["i"]})
    yes_days = {}
    for c in ch:
        if c["yes"]:
            yes_days.setdefault(c["d"], 0)
            yes_days[c["d"]] += 1
    yes_sym_type = set((c["d"], c["sym"], c["type"]) for c in ch if c["yes"])
    seen_day = {}
    cum_stt, cum_stamp, sells_seen = {}, {}, {}
    for c in ch:
        e, d = c["e"], c["d"]
        seen_day[d] = seen_day.get(d, 0) + 1
        # F: DP - the first delivery sale of a share on a day
        dp = None
        if not c["yes"] and c["type"] == "SELL":
            key = (d, c["sym"])
            sells_seen[key] = sells_seen.get(key, 0) + 1
            if sells_seen[key] == 1:
                dp = broker["dp"]
        # G: brokerage
        if c["yes"] or (d, c["sym"], c["type"]) in yes_sym_type:
            if broker.get("zerodha"):
                brk = xround(min(e * 0.0003, 20), 4)
            else:
                brk = xround(_brokerage(broker["intra"], e), 4)
        elif broker.get("zerodha"):
            # Zerodha's paisa on the first row of a delivery-only day
            brk = 0.01 if seen_day[d] == 1 and not yes_days.get(d) else None
        else:
            brk = xround(_brokerage(broker["del"], e), 4) or None
        # H: STT, for the whole day, rounded to the rupee
        stt = None
        if not (c["yes"] and c["type"] == "BUY"):
            r_in = chg_rate("stt_intra", d)
            r_del = chg_rate("stt_del", d)
            rate = (r_in if c["type"] == "SELL" else 0) if c["yes"] \
                else r_del
            row = e * (r_in if c["yes"] else r_del)
            cum = cum_stt.get(d, 0.0) + e * rate
            cum_stt[d] = cum
            stt = xround(cum, 0) - xround(cum - row, 0)
        else:
            cum_stt[d] = cum_stt.get(d, 0.0)
        # I: exchange
        exch = xround(e * chg_rate("exch_bse" if c["exch"] == "BSE"
                                   else "exch_nse", d), 6)
        # L: SEBI
        sebi = xround(e * chg_rate("sebi", d), 6)
        # J: GST
        gst = xround(chg_rate("gst", d) * ((brk or 0) + exch + sebi), 4)
        # K: stamp, for the whole day, rounded to the rupee
        stamp = None
        if c["type"] != "SELL":
            rate = chg_rate("stamp_intra" if c["yes"] else "stamp_del", d)
            cum = cum_stamp.get(d, 0.0) + e * rate
            cum_stamp[d] = cum
            stamp = xround(cum, 0) - xround(cum - e * rate, 0)
        c.update(dp=dp, brk=brk, stt=stt, exchg=exch, gst=gst, stamp=stamp,
                 sebi=sebi)
        if c.get("inst"):
            # 20.16: not a share bought or sold on the exchange (an IPO
            # allotment, a bond, a fund...) - the charges are only what he
            # types from the contract note; the equity rates would be wrong
            c.update(dp=None, brk=None, stt=None, exchg=None, gst=None,
                     stamp=None, sebi=None)
        # a figure he set by hand (to match the contract note) wins
        fix = by_i[c["tx"]].get("chgFix") or {}
        for k2, v2 in fix.items():
            if k2 in ("dp", "brk", "stt", "exchg", "gst", "stamp", "sebi"):
                c[k2] = _anum(v2)
                c["fixed"] = True
        if "brk" in fix or "exchg" in fix or "sebi" in fix:
            if "gst" not in fix:
                c["gst"] = xround(chg_rate("gst", d) * (
                    (c["brk"] or 0) + (c["exchg"] or 0)
                    + (c["sebi"] or 0)), 4)
        c["total"] = xround(sum(c[k2] or 0 for k2 in (
            "dp", "brk", "stt", "exchg", "gst", "stamp", "sebi")), 4)
    by_key = {}
    for c in ch:
        k = (c["d"], c["type"], c["sym"], round(c["e"], 6))
        by_key[k] = by_key.get(k, 0.0) + c["total"]
    # ---- Transactions: I, J, K ----
    bal = 0.0
    for t in tx:
        if t["type"] in ("BUY", "SELL") and t["gross"] is not None:
            t["chg"] = by_key.get((t["d"], t["type"], t["sym"],
                                   round(abs(t["gross"]), 6)), 0.0)
            t["net"] = t["gross"] - t["chg"]
        else:
            t["chg"] = _anum(t.get("charges"))
            if t["chg"] is None and t["type"] == "OPENING_SHARES":
                t["chg"] = 0.0
            t["net"] = _anum(t.get("netIn"))
        if t["net"] is not None:
            bal += t["net"]
        t["bal"] = bal if (t["net"] is not None or t["d"]) else None
    # ---- P&L: one row per SELL / BUYBACK ----
    lots_of = {}
    for t in tx:
        lot = (t["type"] == "BUY" and not t["yes"]) or \
            t["type"] in ACC_LOT_TYPES
        if lot and t["sym"]:
            lots_of.setdefault(t["sym"], []).append(t)
    chg_by = {}
    for c in ch:
        chg_by.setdefault((c["d"], c["type"], c["sym"]), []).append(c)
    pl, prior = [], {}
    for t in tx:
        if t["type"] not in ("SELL", "BUYBACK"):
            continue
        sym, qty, sd = t["sym"], t["qty"] or 0, t["d"]
        f = t["gross"]
        r = {"d": sd, "sym": sym, "qty": t["qty"], "price": t["price"],
             "sale": f, "yes": t["yes"], "tx": t["i"], "inst": t["inst"]}
        lots = [x for x in lots_of.get(sym, []) if x["d"] < sd]
        pq = prior.get(sym, 0.0)
        cum, cost, buychg, used, pieces = 0.0, 0.0, 0.0, [], []
        for x in lots:
            lq = abs(x["qty"] or 0)
            lg = abs(x["gross"] or 0)
            hi = min(max(pq + qty - cum, 0), lq)
            lo = min(max(pq - cum, 0), lq)
            if lq:
                cost += (hi - lo) * lg / lq
                if hi - lo > 0:
                    cs = [c for c in chg_by.get((x["d"], "BUY", sym), [])
                          if abs(c["e"] - lg) < 1e-6]
                    lc = sum(c["total"] for c in cs)
                    lstt = sum(c.get("stt") or 0 for c in cs)
                    buychg += (hi - lo) / lq * lc
                    # 20.14: each parcel the sale used, for Capital gains
                    # (20.15: with its STT apart - STT is not an expense the
                    # income-tax rules allow against a capital gain)
                    pieces.append({"d": x["d"], "q": hi - lo,
                                   "cost": (hi - lo) * lg / lq,
                                   "chg": (hi - lo) / lq * lc,
                                   "stt": (hi - lo) / lq * lstt})
            if hi - lo > 0:
                used.append(x["d"])
            cum += lq
        scs = [c for c in chg_by.get((sd, "SELL", sym), [])
               if f is not None and abs(c["e"] - f) < 1e-6]
        sellchg = sum(c["total"] for c in scs)
        sellstt = sum(c.get("stt") or 0 for c in scs)
        if t["yes"]:
            ib = [x for x in tx if x["sym"] == sym and x["d"] == sd and
                  x["type"] == "BUY" and x["yes"]]
            r["cost"] = abs(ib[-1]["gross"]) if ib and \
                ib[-1]["gross"] is not None else None
            r["chg"] = sellchg + sum(c["total"] for c in chg_by.get(
                (sd, "BUY", sym), []) if c["yes"])
            r["from"] = r["to"] = r["buyDate"] = sd
            r["tax"] = "INTRADAY"
        else:
            prior[sym] = pq + qty
            r["cost"] = xround(cost, 4)
            r["chg"] = sellchg + buychg
            r["from"] = min(used) if used else ""
            r["to"] = max(used) if used else ""
            r["buyDate"] = r["from"]
            if not r["from"]:
                r["tax"] = ""
            else:
                d0 = datetime.date.fromisoformat(sd)
                if (d0 - datetime.date.fromisoformat(r["to"])).days > 365:
                    r["tax"] = "LTCG"
                elif (d0 - datetime.date.fromisoformat(r["from"])).days \
                        <= 365:
                    r["tax"] = "STCG"
                else:
                    r["tax"] = "SPLIT REQUIRED"
        r["gp"] = (f - r["cost"]) if f is not None and \
            r["cost"] is not None else None
        r["np"] = (r["gp"] - r["chg"]) if r["gp"] is not None else None
        r["pct"] = (r["np"] / abs(r["cost"])) if r["np"] is not None and \
            r["cost"] else None
        r["days"] = (datetime.date.fromisoformat(sd) -
                     datetime.date.fromisoformat(r["buyDate"])).days \
            if r.get("buyDate") else None
        r["noCost"] = not r["cost"]
        r["pieces"] = [] if t["yes"] else pieces
        r["sellChg"] = sellchg
        r["sellStt"] = sellstt
        pl.append(r)
    # ---- Holdings ----
    syms = []
    for s in (acc.get("symbols") or []):
        s = str(s).strip().upper()
        if s and s not in syms:
            syms.append(s)
    for t in tx:
        if t["sym"] and t["type"] not in ACC_MONEY_TYPES and \
                t["sym"] not in syms:
            syms.append(t["sym"])
    hold = []
    for s in syms:
        inq = sum(t["qty"] or 0 for t in tx if t["sym"] == s and
                  t["type"] in ACC_LOT_TYPES)
        buyq = sum(t["qty"] or 0 for t in tx if t["sym"] == s and
                   t["type"] == "BUY")
        outq = sum(t["qty"] or 0 for t in tx if t["sym"] == s and
                   t["type"] in ("SELL", "BUYBACK"))
        q = inq - buyq - outq
        cin = sum(abs(t["gross"] or 0) for t in lots_of.get(s, []))
        cout = sum(r["cost"] or 0 for r in pl if r["sym"] == s and
                   not r["yes"])
        lots = lots_of.get(s, [])
        h = {"sym": s, "qty": q if abs(q) > 1e-9 else None}
        if h["qty"] is not None:
            h["invested"] = cin - cout
            h["avg"] = xround(h["invested"] / q, 2)
            h["date"] = lots[-1]["d"] if lots else ""
            h["age"] = (today - datetime.date.fromisoformat(h["date"])).days \
                if h["date"] else None
        hold.append(h)
    # the parcels still held (oldest sold first), for the long-term dates
    parcels = {}
    for s, lots in lots_of.items():
        # [date, quantity still held, price paid per share]
        left = [[x["d"], abs(x["qty"] or 0),
                 abs(x["gross"] or 0) / abs(x["qty"]) if x["qty"] else 0.0]
                for x in lots]
        sold = sum((r["qty"] or 0) for r in pl if r["sym"] == s and
                   not r["yes"])
        for lp in left:
            take = min(sold, lp[1])
            lp[1] -= take
            sold -= take
        left = [lp for lp in left if lp[1] > 1e-9]
        if left:
            parcels[s] = left
    # ---- Passive income ----
    pas = [dict(p, amount=_anum(p.get("amount")), i=i) for i, p in
           enumerate(acc.get("passive") or [])
           if not upto or str(p.get("date") or "") <= upto]
    pas_by = {}
    for p in pas:
        s = str(p.get("sym") or "").upper()
        if s:
            a = pas_by.setdefault(s, [0, 0.0])
            a[0] += 1
            a[1] += p["amount"] or 0
    # ---- Dashboard and reconciliation ----

    def sumtx(field, kind, sym=None):
        return sum((t[field] or 0) for t in tx if t["type"] == kind and
                   (sym is None or t["sym"] == sym))
    gp = {k: sum(r["gp"] or 0 for r in pl if r["tax"] == k)
          for k in ("STCG", "LTCG", "INTRADAY")}
    realised = sum(r["gp"] or 0 for r in pl)
    purchases = -sumtx("gross", "BUY")
    sales = sumtx("gross", "SELL")
    charges = sum(t["chg"] or 0 for t in tx)
    other_exp = abs(sumtx("net", "EXPENSE"))
    cash = next((t["bal"] for t in reversed(tx) if t["bal"] is not None),
                0.0)
    invested = sum(h.get("invested") or 0 for h in hold)
    dash = {
        "netWorth": cash + invested, "invested": invested, "cash": cash,
        "active": sum(1 for h in hold if (h["qty"] or 0) > 0),
        "stcg": gp["STCG"], "ltcg": gp["LTCG"], "intraday": gp["INTRADAY"],
        "realised": realised, "netProfit": realised - charges - other_exp,
        "purchases": purchases, "sales": sales, "charges": charges,
        "netTradingCash": sales - purchases - charges,
        "unrealisedCharges": charges - sum(r["chg"] or 0 for r in pl),
        "fundsAdded": sumtx("net", "FUND_ADD"),
        "fundsWithdrawn": -sumtx("net", "FUND_WITHDRAWAL"),
        "dividends": sum(p["amount"] or 0 for p in pas
                         if str(p.get("type")).upper() == "DIVIDEND"),
        "interest": sum(p["amount"] or 0 for p in pas
                        if str(p.get("type")).upper() == "INTEREST"),
        "amc": abs(sumtx("net", "EXPENSE", "AMC")),
        "gateway": abs(sumtx("net", "EXPENSE", "PAYMENT_GATEWAY")),
        "otherExp": abs(sumtx("net", "EXPENSE", "BUYBACK_FEE")) +
        abs(sumtx("net", "EXPENSE", "CHARGES_ADJ")),
        "totalOtherExp": other_exp}
    dash["fundsNet"] = dash["fundsAdded"] - dash["fundsWithdrawn"]
    dash["passive"] = dash["dividends"] + dash["interest"]
    opening = next((t["net"] or 0 for t in tx
                    if t["type"] == "OPENING_CASH"), 0.0)
    rec = {"opening": opening, "sales": sales, "purchases": purchases,
           "charges": sum(c["total"] for c in ch) + other_exp,
           "fundsAdded": dash["fundsAdded"],
           "fundsWithdrawn": abs(sumtx("net", "FUND_WITHDRAWAL"))}
    rec["expected"] = rec["opening"] + rec["sales"] - rec["purchases"] - \
        rec["charges"] + rec["fundsAdded"] - rec["fundsWithdrawn"]
    rec["actual"] = cash
    rec["difference"] = rec["actual"] - rec["expected"]
    # ---- the warnings the workbook's colours gave ----
    alerts = []
    for t in tx:
        if t["type"] in ("BUY", "SELL") and not t["yes"]:
            other = "SELL" if t["type"] == "BUY" else "BUY"
            twin = any(x["d"] == t["d"] and x["sym"] == t["sym"] and
                       x["type"] == other for x in tx)
            flagged = any(x["d"] == t["d"] and x["sym"] == t["sym"] and
                          x["type"] == t["type"] and x["yes"] for x in tx)
            if twin and not flagged:
                t["warn"] = "Bought and sold the same day: tick INTRADAY " \
                    "on both rows (split the bigger one if they differ)"
                key = (t["d"], t["sym"])
                if key not in [x.get("key") for x in alerts]:
                    alerts.append({"tab": "tx", "row": t["i"], "key": key,
                                   "text": "%s %s bought and sold the same "
                                   "day: tick INTRADAY on both rows" % (
                                       t["d"], t["sym"])})
    for r in pl:
        if r["noCost"]:
            r["warn"] = "No purchase cost found for this sale"
            alerts.append({"tab": "pl", "row": r["tx"], "text": "%s %s: %s" %
                           (r["d"], r["sym"], r["warn"])})
        elif r["tax"] == "SPLIT REQUIRED":
            alerts.append({"tab": "pl", "row": r["tx"], "text": "%s %s: "
                           "split the sale row by parcel (%s and %s)" % (
                               r["d"], r["sym"], r["from"], r["to"])})
    if abs(rec["difference"]) >= 0.005:
        alerts.append({"tab": "rec", "row": -1, "text": "Reconciliation is "
                       "%.2f out" % rec["difference"]})
    out_tx = [{k: t.get(k) for k in (
        "i", "date", "type", "sym", "exch", "qty", "price", "gross", "chg",
        "net", "bal", "intra", "override", "warn", "id", "note", "inst")}
        for t in tx]
    cg = acc_capital_gains(pl, acc.get("fy") or acc_fy_of(today))
    for r in pl:
        r.pop("pieces", None)
    return {"tx": out_tx, "charges": ch, "pl": pl, "holdings": hold,
            "passive": pas,
            "passiveBy": [{"sym": s, "count": v[0], "amount": v[1]}
                          for s, v in sorted(pas_by.items())],
            "dash": dash, "rec": rec, "alerts": alerts, "parcels": parcels,
            "cg": cg}


def _xlsx_sheets(path, want=None):
    """{sheet name: {row: {col: (value, has_formula)}}} for the sheets in
    want (every sheet when want is None), read with the standard library
    (no Excel, no add-ons). Numbers come as floats, text as text, dates as
    Excel serial numbers."""
    import zipfile
    from xml.etree import ElementTree as XT
    M = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
    R = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
    out = {}
    with zipfile.ZipFile(path) as z:
        wb = XT.fromstring(z.read("xl/workbook.xml"))
        pr = wb.find("{%s}workbookPr" % M)
        base = datetime.date(1904, 1, 1) if pr is not None and str(
            pr.get("date1904", "")).lower() in ("1", "true") \
            else datetime.date(1899, 12, 30)
        rels = XT.fromstring(z.read("xl/_rels/workbook.xml.rels"))
        rmap = {r.get("Id"): r.get("Target") for r in rels}
        shared = []
        if "xl/sharedStrings.xml" in z.namelist():
            for _ev, si in XT.iterparse(z.open("xl/sharedStrings.xml")):
                if si.tag == "{%s}si" % M:
                    shared.append("".join(t.text or "" for t in
                                          si.iter("{%s}t" % M)))
                    si.clear()
        for sh in wb.iter("{%s}sheet" % M):
            name = (sh.get("name") or "").strip()
            if want is not None and \
                    name.lower() not in [w.lower() for w in want]:
                continue
            target = rmap.get(sh.get("{%s}id" % R), "").lstrip("/")
            if not target.startswith("xl/"):
                target = "xl/" + target
            rows = {}
            for _ev, el in XT.iterparse(z.open(target)):
                if el.tag != "{%s}row" % M:
                    continue
                rn = int(el.get("r") or 0)
                cells = {}
                for c in el:
                    ref = c.get("r") or ""
                    col = re.sub(r"\d", "", ref)
                    v = c.find("{%s}v" % M)
                    t = c.get("t")
                    f = c.find("{%s}f" % M) is not None
                    val = None
                    if t == "s" and v is not None:
                        try:
                            val = shared[int(v.text)]
                        except (ValueError, IndexError, TypeError):
                            val = None
                    elif t == "inlineStr":
                        val = "".join(x.text or "" for x in
                                      c.iter("{%s}t" % M))
                    elif t in ("str", "e"):
                        val = v.text if v is not None else None
                    elif t == "b":
                        val = (v.text == "1") if v is not None else None
                    elif v is not None:
                        try:
                            val = float(v.text)
                        except (TypeError, ValueError):
                            val = v.text
                    cells[col] = (val, f)
                rows[rn] = cells
                el.clear()
            out[name.lower()] = rows
    return out, base



def acc_fy_of(d):
    """'2026-27' for any date from 1 April 2026 to 31 March 2027."""
    if isinstance(d, str):
        try:
            d = datetime.date.fromisoformat(d[:10])
        except ValueError:
            d = datetime.date.today()
    y = d.year if d.month >= 4 else d.year - 1
    return "%d-%02d" % (y, (y + 1) % 100)


def acc_fy_range(fy):
    """(1 April, 31 March) of a year written '2026-27'."""
    m = re.match(r"(\d{4})-(\d{2})$", str(fy or ""))
    y = int(m.group(1)) if m else datetime.date.today().year
    return datetime.date(y, 4, 1), datetime.date(y + 1, 3, 31)


def acc_fy_next(fy):
    s, _e = acc_fy_range(fy)
    return "%d-%02d" % (s.year + 1, (s.year + 2) % 100)


def acc_capital_gains(pl, fy):
    """20.14: the year's gains split the way the advance-tax dates split
    the year (15 June, 15 September, 15 December, 15 March), short-term and
    long-term parcel by parcel (one sale can be both), intraday apart.
    Gross gain = sale value - purchase value; net = after every charge."""
    start, end = acc_fy_range(fy)
    y = start.year
    bounds = [("1 Apr - 15 Jun", datetime.date(y, 4, 1),
               datetime.date(y, 6, 15), "15 Jun %d" % y),
              ("16 Jun - 15 Sep", datetime.date(y, 6, 16),
               datetime.date(y, 9, 15), "15 Sep %d" % y),
              ("16 Sep - 15 Dec", datetime.date(y, 9, 16),
               datetime.date(y, 12, 15), "15 Dec %d" % y),
              ("16 Dec - 15 Mar", datetime.date(y, 12, 16),
               datetime.date(y + 1, 3, 15), "15 Mar %d" % (y + 1)),
              ("16 Mar - 31 Mar", datetime.date(y + 1, 3, 16),
               datetime.date(y + 1, 3, 31), "15 Mar %d (or with the "
               "return)" % (y + 1))]
    rows = []
    for r in pl:
        f, qty = r.get("sale"), r.get("qty") or 0
        if f is None or not qty:
            continue
        if r.get("inst") and not ACC_INST.get(r["inst"], ("", "", True))[2]:
            # 20.16: a bond, a debt fund, gold... - not taxed like shares:
            # shown, kept out of the share totals, and typed in Taxes
            rows.append({"d": r["d"], "sym": r["sym"], "tax": "OTHER",
                         "q": qty, "sale": f, "cost": r.get("cost") or 0,
                         "gp": r.get("gp") or 0, "chg": r.get("chg") or 0,
                         "np": r.get("np") or 0, "buy": "", "tx": r["tx"],
                         "inst": ACC_INST[r["inst"]][0]})
            continue
        if r.get("yes"):
            rows.append({"d": r["d"], "sym": r["sym"], "tax": "INTRADAY",
                         "q": qty, "sale": f, "cost": r.get("cost") or 0,
                         "gp": r.get("gp") or 0, "chg": r.get("chg") or 0,
                         "np": r.get("np") or 0, "buy": r["d"], "tx": r["tx"]})
            continue
        pieces = r.get("pieces") or []
        sale_chg = r.get("sellChg") or 0
        sale_stt = r.get("sellStt") or 0
        for p in pieces:
            share = p["q"] / qty
            sale = f * share
            days = (datetime.date.fromisoformat(r["d"]) -
                    datetime.date.fromisoformat(p["d"])).days
            chg = p["chg"] + sale_chg * share
            stt = (p.get("stt") or 0) + sale_stt * share
            rows.append({"d": r["d"], "sym": r["sym"],
                         "tax": "LTCG" if days > 365 else "STCG",
                         "q": p["q"], "sale": sale, "cost": p["cost"],
                         "gp": sale - p["cost"], "chg": chg,
                         "np": sale - p["cost"] - chg, "buy": p["d"],
                         "days": days, "tx": r["tx"],
                         # what the income-tax rules count: every charge
                         # except STT comes off the gain
                         "taxable": sale - p["cost"] - (chg - stt),
                         "stt": stt})
        if not pieces:
            rows.append({"d": r["d"], "sym": r["sym"], "tax": "NO COST",
                         "q": qty, "sale": f, "cost": 0, "gp": f,
                         "chg": r.get("chg") or 0, "np": r.get("np") or 0,
                         "buy": "", "tx": r["tx"]})
    periods, cum = [], {"STCG": 0.0, "LTCG": 0.0, "INTRADAY": 0.0}
    for label, a, b, due in bounds:
        p = {"label": label, "from": a.isoformat(), "to": b.isoformat(),
             "due": due}
        for k in ("STCG", "LTCG", "INTRADAY"):
            g = [x for x in rows if x["tax"] == k and
                 a.isoformat() <= x["d"] <= b.isoformat()]
            p[k.lower()] = sum(x["gp"] for x in g)
            p[k.lower() + "Net"] = sum(x["np"] for x in g)
            cum[k] += p[k.lower()]
            p[k.lower() + "Cum"] = cum[k]
        periods.append(p)
    tot = {k.lower(): sum(x["gp"] for x in rows if x["tax"] == k)
           for k in ("STCG", "LTCG", "INTRADAY")}
    tot.update({k.lower() + "Net": sum(x["np"] for x in rows
                                       if x["tax"] == k)
                for k in ("STCG", "LTCG", "INTRADAY")})
    # the tax rates of the year (Finance Act 2024, unchanged by Budget 2026:
    # short-term 20%, long-term 12.5% above Rs 1.25 lakh a year; intraday is
    # business income at the slab rate)
    # 20.15: worked out the way the return is - gain = sale - cost - every
    # charge except STT (STT is never allowed); short-term losses can be set
    # off against short- or long-term gains, long-term losses only against
    # long-term gains (the rest is carried forward 8 years); short-term at
    # 20% from the first rupee, long-term at 12.5% above Rs 1.25 lakh;
    # 4% cess on the tax. Intraday is speculative business income, at the
    # slab rate, and its loss is set off only against speculative income.
    st = sum(x.get("taxable", x["np"]) for x in rows if x["tax"] == "STCG")
    lt = sum(x.get("taxable", x["np"]) for x in rows if x["tax"] == "LTCG")
    tot["stcgTaxableGain"], tot["ltcgTaxableGain"] = st, lt
    tot["stt"] = sum(x.get("stt") or 0 for x in rows if x["tax"] in ("STCG", "LTCG"))
    st_left, lt_left = st, lt
    if st_left < 0 and lt_left > 0:              # short-term loss eats long-term gain
        use = min(-st_left, lt_left)
        lt_left -= use
        st_left += use
    tot["stcgAfterSetoff"] = max(0.0, st_left)
    tot["ltcgAfterSetoff"] = max(0.0, lt_left)
    tot["stclCarry"] = -st_left if st_left < 0 else 0.0
    tot["ltclCarry"] = -lt_left if lt_left < 0 else 0.0
    tot["ltcgFree"] = 125000.0
    tot["ltcgTaxable"] = max(0.0, tot["ltcgAfterSetoff"] - 125000.0)
    tot["stcgTax"] = tot["stcgAfterSetoff"] * 0.20
    tot["ltcgTax"] = tot["ltcgTaxable"] * 0.125
    tot["cess"] = (tot["stcgTax"] + tot["ltcgTax"]) * 0.04
    tot["taxTotal"] = tot["stcgTax"] + tot["ltcgTax"] + tot["cess"]
    return {"periods": periods, "rows": rows, "totals": tot, "fy": fy}


# ---- where each year is kept ---------------------------------------------

def acc_dir():
    return os.path.dirname(PATHS["state"])


def acc_path(fy=None):
    """The year running: accounts.json; a past year: accounts-2025-26.json"""
    if fy and re.fullmatch(r"\d{4}-\d{2}", str(fy)):
        return os.path.join(acc_dir(), "accounts-%s.json" % fy)
    return os.path.join(acc_dir(), "accounts.json")


def acc_past_list():
    try:
        names = os.listdir(acc_dir())
    except OSError:
        return []
    out = [m.group(1) for m in (re.fullmatch(r"accounts-(\d{4}-\d{2})\.json",
                                             n) for n in names) if m]
    return sorted(out, reverse=True)


def acc_load(fy=None):
    p = acc_path(fy)
    if not os.path.exists(p):
        return None
    d = _read_json(p, None)
    return d if isinstance(d, dict) and isinstance(d.get("tx"), list) \
        else None


def acc_save(acc, note=""):
    """Saved at once, with the version before kept in Backups (the last
    forty), so a slip can be undone."""
    with ACC_LOCK:
        p = acc_path()
        if os.path.exists(p):
            bdir = os.path.join(os.path.dirname(p), "Backups")
            os.makedirs(bdir, exist_ok=True)
            try:
                import shutil
                stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S-%f")
                shutil.copy2(p, os.path.join(bdir, "accounts-%s.json" %
                                             stamp))
                old = sorted(f for f in os.listdir(bdir)
                             if f.startswith("accounts-"))
                for f in old[:-40]:
                    os.remove(os.path.join(bdir, f))
            except Exception:
                pass
        acc["saved"] = time.strftime("%d %b %Y %H:%M")
        acc["note"] = note[:80]
        acc.setdefault("fy", acc_fy_of(datetime.date.today()))
        _write_json(p, acc)
        ACC_CACHE["key"] = None
        ACC_CHECK["key"] = None


def acc_ui_path():
    return os.path.join(acc_dir(), "accounts_ui.json")


def acc_ui():
    """How the box looks (his settings), whether the assistant may read the
    accounts, and the new-year question - kept apart from the rows, so
    changing a colour makes no backup and every year shares them."""
    d = _read_json(acc_ui_path(), {})
    return d if isinstance(d, dict) else {}


def acc_ui_save(d):
    _write_json(acc_ui_path(), d)
    _RATE_CACHE["at"] = None      # 20.19: a rate may have changed


def acc_view(fy=None):
    """The worked-out sheets, kept until the rows or the broker change."""
    acc = acc_load(fy)
    if not acc:
        return None, None
    try:
        mt = os.path.getmtime(acc_path(fy))
    except OSError:
        mt = 0
    br = acc_broker()
    key = (acc_path(fy), mt, json.dumps(br, sort_keys=True),
           datetime.date.today().isoformat(),
           json.dumps(chg_rate_hist(), sort_keys=True))
    with ACC_LOCK:
        if fy:
            hit = ACC_PAST.get(key)
            if not hit:
                ACC_PAST.clear()
                hit = ACC_PAST[key] = acc_compute(acc, br)
            return acc, hit
        if ACC_CACHE["key"] != key:
            ACC_CACHE["data"] = acc_compute(acc, br)
            ACC_CACHE["key"] = key
        return acc, ACC_CACHE["data"]


ACC_PAST = {}
ACC_CHECK = {"key": None, "data": None}


def acc_cash():
    """The cash figures for the funds box: the balance before today
    (Kite's opening balance), money added or taken out today, and the
    balance after every row typed so far (latest)."""
    acc, v = acc_view()
    if not v:
        raise ValueError("no accounts in the dashboard yet")
    today = datetime.date.today().isoformat()
    best = latest = None
    funds = 0.0
    for t in v["tx"]:
        if t.get("bal") is None or not t.get("date"):
            continue
        latest = (round(t["bal"], 2), t["date"])
        if t["date"] < today:
            best = latest
        if t["date"] == today and t["type"] in ("FUND_ADD",
                                                 "FUND_WITHDRAWAL"):
            funds += t.get("net") or 0
    if not best:
        best = latest
    if not best:
        raise ValueError("no cash balance in the Accounts yet")
    return {"opening": best[0], "day": best[1], "fundsToday": round(funds, 2),
            "available": round(best[0] + funds, 2),
            "latest": latest[0], "latestDay": latest[1],
            "saved": acc.get("saved") or "", "source": "accounts"}


def _acc_row(data):
    """A row as typed in the box, made the way the accounts keep it: BUY
    quantities negative, SELL and the share-in events positive; money taken
    out negative."""
    r = data if isinstance(data, dict) else {}
    kind = str(r.get("type") or "").strip().upper().replace(" ", "_")
    if kind not in ACC_TYPES:
        raise ValueError("Choose the type of row.")
    d = str(r.get("date") or "")[:10]
    try:
        datetime.date.fromisoformat(d)
    except ValueError:
        raise ValueError("The date is not right.")
    row = {"id": str(r.get("id") or secrets.token_hex(5))[:12], "date": d,
           "type": kind}
    note = re.sub(r"[\x00-\x1f]", " ", str(r.get("note") or ""))[:200].strip()
    if note:
        row["note"] = note
    sym = re.sub(r"[^A-Z0-9&_.-]", "", str(r.get("sym") or "").upper())[:30]
    if kind in ACC_MONEY_TYPES:
        amt = _anum(r.get("netIn"))
        if amt is None:
            raise ValueError("Type the amount.")
        if kind in ("FUND_WITHDRAWAL", "EXPENSE"):
            amt = -abs(amt)
        elif kind == "FUND_ADD":
            amt = abs(amt)
        row["netIn"] = amt
        if kind == "EXPENSE":
            if not sym:
                raise ValueError("Choose what the expense is.")
            row["sym"] = sym
        return row
    if not sym:
        raise ValueError("Type the share's NSE symbol.")
    row["sym"] = sym
    q = _anum(r.get("qty"))
    if q is None or q == 0:
        raise ValueError("Type the quantity.")
    row["qty"] = -abs(q) if kind == "BUY" else abs(q)
    pr = _anum(r.get("price"))
    if kind in ("BUY", "SELL", "OPENING_SHARES", "RIGHTS_ISSUE",
                "DEMERGER", "BUYBACK"):
        if pr is None:
            raise ValueError("Type the price.")
    if kind in ("BONUS", "SPLIT"):
        pr = 0.0 if pr is None else pr
    if pr is not None:
        row["price"] = abs(pr)
    if kind in ("BUY", "SELL"):
        ex = str(r.get("exch") or "NSE").upper()
        row["exch"] = "BSE" if ex.startswith("B") else "NSE"
        inst = str(r.get("inst") or "")
        if inst in ACC_INST and inst:
            row["inst"] = inst
        if r.get("intra"):
            row["intra"] = True
        ov = _anum(r.get("override"))
        if ov is not None:
            row["override"] = -abs(ov) if kind == "BUY" else abs(ov)
        fix = r.get("chgFix") if isinstance(r.get("chgFix"), dict) else {}
        fix = {k: _anum(v) for k, v in fix.items() if k in (
            "dp", "brk", "stt", "exchg", "gst", "stamp", "sebi")
            and _anum(v) is not None}
        if fix:
            row["chgFix"] = fix
    else:
        # events and opening parcels move no money in the ledger
        row["charges"] = 0.0
        row["netIn"] = 0.0
        if kind == "OPENING_SHARES":
            row["exch"] = "NSE"
    return row


def _acc_place(tx, row):
    """In date order: after the last row on or before its date."""
    at = len(tx)
    for i in range(len(tx) - 1, -1, -1):
        if (tx[i].get("date") or "") <= row["date"]:
            at = i + 1
            break
    else:
        at = 0
    tx.insert(at, row)
    return at


def acc_mark_intraday(tx, days=None):
    """20.14: a share bought and sold on the same day is intraday on both
    rows (the exchange nets them). Where the quantities differ the bigger
    side is split, as the workbook asked: 95 sold and 94 bought gives a
    94-share intraday sale and a 1-share delivery sale. Only days and
    shares with no Intraday tick at all are touched. Returns how many rows
    were marked."""
    groups = {}
    for t in tx:
        if t.get("type") in ("BUY", "SELL") and t.get("sym") and \
                (days is None or t.get("date") in days):
            groups.setdefault((t["date"], t["sym"]), []).append(t)
    marked = 0
    for (_d, _sym), rows in sorted(groups.items()):
        if any(r.get("intra") for r in rows):
            continue
        buys = [r for r in rows if r["type"] == "BUY"]
        sells = [r for r in rows if r["type"] == "SELL"]
        if not buys or not sells:
            continue
        want = min(sum(abs(r.get("qty") or 0) for r in buys),
                   sum(abs(r.get("qty") or 0) for r in sells))
        for side in (buys, sells):
            left = want
            for r in side:
                if left <= 1e-9:
                    break
                q = abs(r.get("qty") or 0)
                if q <= left + 1e-9:
                    r["intra"] = True
                    left -= q
                    marked += 1
                    continue
                # split this row: the intraday part, then the rest
                sign = -1 if r["type"] == "BUY" else 1
                rest = dict(r, id=secrets.token_hex(5), qty=sign * (q - left))
                r["qty"] = sign * left
                r["intra"] = True
                if r.get("override") is not None:
                    ov = abs(r["override"])
                    r["override"] = sign * round(ov * left / q, 2)
                    rest["override"] = sign * round(ov * (q - left) / q, 2)
                rest.pop("intra", None)
                rest.pop("chgFix", None)
                at = next(k for k, t in enumerate(tx) if t is r)
                tx.insert(at + 1, rest)
                left = 0
                marked += 1
    return marked


