def asset_search(q, types=None, countries=None, limit=40):
    """Instruments for the picker: the built-in list, the NSE shares, Yahoo's
    search and the Indian mutual funds, filtered by kind and country."""
    q = str(q or "").strip()
    ql = q.lower()
    types = set(types or [])
    countries = set(countries or [])
    out, seen = [], set()

    def ok(t, c):
        # crypto, gold, crude and currencies belong to no one country
        return (not types or t in types) and (not countries or c in
                                              countries or c == "Global")

    def add(d):
        k = (d.get("y") or d.get("mf") or d.get("key"), d.get("type"))
        if k in seen or not ok(d["type"], d["country"]):
            return
        seen.add(k)
        out.append(d)
    for key, ys, name, t, c in ASSET_CATALOG:
        if not ql or ql in key.lower() or ql in name.lower() or \
                ql in ys.lower():
            add({"key": key, "y": ys, "name": name, "type": t, "country": c})
    for t, name in ASSET_PLAIN:
        if not ql or ql in name.lower():
            add({"key": "", "y": "", "name": name, "type": t,
                 "country": "India", "plain": True})
    if ql and (not types or types & {"equity", "etf", "sgb", "bond"}) and \
            (not countries or "India" in countries):
        try:
            for r in chart_search(q, 10):
                if r.get("kind") == "share":
                    sym = r.get("sym") or r.get("name")
                    t = "sgb" if str(sym).startswith("SGB") else "equity"
                    add({"key": sym, "y": sym + ".NS", "name":
                         r.get("label") or r.get("name") or sym, "type": t,
                         "country": "India", "nse": True})
        except Exception:
            pass
    if len(ql) >= 2 and (not types or types - {"fd", "rd", "ppf", "epf",
                                                "nps", "nsc", "kvp", "scss",
                                                "pomis", "ssy", "ulip",
                                                "zcb", "other"}):
        try:
            raw = urllib.request.urlopen(urllib.request.Request(
                "https://query2.finance.yahoo.com/v1/finance/search?q=" +
                urllib.parse.quote(q) + "&quotesCount=15&newsCount=0",
                headers={"User-Agent": "Mozilla/5.0"}), timeout=10).read()
            for r in json.loads(raw.decode("utf-8", "replace")).get(
                    "quotes") or []:
                ys = r.get("symbol")
                t = YAHOO_TYPE.get(r.get("quoteType"))
                if not ys or not t:
                    continue
                c = YAHOO_COUNTRY.get(r.get("exchange"), "Global" if t in (
                    "crypto", "currency", "commodity") else
                    r.get("exchDisp") or "Other")
                nm = r.get("longname") or r.get("shortname") or ys
                if t == "equity" and re.search(r"\b(bond|treasury)\b",
                                               nm, re.I):
                    t = "bond"
                if t == "commodity" and re.search(r"\bgold\b", nm, re.I):
                    t = "gold"
                elif t == "commodity" and re.search(r"\bsilver\b", nm, re.I):
                    t = "silver"
                if c == "India" and t in ("equity", "etf"):
                    continue            # the NSE list gives these, live
                add({"key": asset_key_of(ys), "y": ys, "name": nm,
                     "type": t, "country": c, "exch": r.get("exchDisp")})
        except Exception:
            pass
    # 20.16: a code Yahoo's search does not know - tried on the main foreign
    # exchanges one by one (005930 -> 005930.KS, 7203 -> 7203.T...)
    if ql and re.match(r"^[A-Za-z0-9&-]{1,12}$", q) and \
            not (types and "equity" not in types) and \
            not any(x.get("exch") or x.get("nse") for x in out):
        sufs = (".KS", ".KQ", ".T", ".HK", ".L", ".DE", ".PA", ".TO", ".AX",
                ".SI", ".SS", ".SZ", ".TW", ".KL", ".JK", ".BK", ".SA", ".MX")
        found = []

        def probe(sf):
            try:
                bars, meta, _e = yahoo_ohlc(q.upper() + sf, "5d", "1d")
                if bars:
                    found.append((sufs.index(sf), q.upper() + sf, meta))
            except Exception:
                pass
        ths = [threading.Thread(target=probe, args=(sf,), daemon=True)
               for sf in sufs]
        for t in ths:
            t.start()
        for t in ths:
            t.join(8)
        for _i, ys, meta in sorted(found)[:5]:
            add({"key": asset_key_of(ys), "y": ys, "name": meta.get(
                "longName") or meta.get("shortName") or ys, "type": "equity",
                "country": YAHOO_COUNTRY.get(meta.get("exchangeName"),
                                             "Other"),
                "exch": meta.get("fullExchangeName") or
                meta.get("exchangeName") or ""})
    if len(ql) >= 3 and (not types or "fund" in types) and \
            (not countries or "India" in countries):
        try:
            raw = urllib.request.urlopen(urllib.request.Request(
                "https://api.mfapi.in/mf/search?q=" + urllib.parse.quote(q),
                headers={"User-Agent": "Mozilla/5.0"}), timeout=10).read()
            for r in (json.loads(raw.decode("utf-8", "replace")) or [])[:25]:
                add({"key": "MF%s" % r.get("schemeCode"), "y": "",
                     "mf": str(r.get("schemeCode")), "name":
                     r.get("schemeName"), "type": "fund",
                     "country": "India"})
        except Exception:
            pass
    return out[:limit]


def asset_key_of(ys):
    """A short name for the table: BTC-INR -> BTC, GC=F -> GOLD, ^TNX ->
    US10Y, VOD.L -> VOD.L."""
    for key, y, _n, _t, _c in ASSET_CATALOG:
        if y == ys:
            return key
    s = str(ys or "").upper()
    m = re.match(r"^([A-Z0-9]+)-(INR|USD|USDT)$", s)
    if m:
        return m.group(1)
    return re.sub(r"[^A-Z0-9.&-]", "", s.replace("=X", "").replace("=F", ""))


def fx_inr(cur):
    """Rupees for one unit of a currency (Yahoo, kept ten minutes). London
    prices in pence (GBp) are a hundredth of a pound."""
    cur = str(cur or "INR")
    if cur in ("GBp", "GBX"):
        g = fx_inr("GBP")
        return g / 100.0 if g else None
    cur = cur.upper()
    if cur in ("INR", ""):
        return 1.0
    hit = FX.get(cur)
    if hit and time.time() - hit[0] < 600:
        return hit[1]
    try:
        pts, _c = yahoo_history(cur + "INR=X", "5d", "1d")
        v = pts[-1][1] if pts else None
    except Exception:
        v = None
    if v:
        FX[cur] = (time.time(), v)
    return v or (hit[1] if hit else None)


def mcx_quote(sym):
    """20.16: gold and silver as traded in India (MCX, the near contract) -
    from the Economic Times commodity page; when it does not answer,
    Gemini with Google Search, said so. None when neither is sure."""
    sym = re.sub(r"[^A-Z]", "", str(sym or "").upper())[:12]
    try:
        raw = _tt_get("https://economictimes.indiatimes.com/"
                      "commoditysummary/symbol-%s.cms" % sym, timeout=12)
        m = re.search(r'commodityPrice">\s*([0-9.,]+)', raw)
        if m:
            txt = re.sub(r"\s+", " ", re.sub(r"<[^>]+>", " | ", raw))
            last = to_number(m.group(1))
            unit = re.search(r"Per(?:&nbsp;|\s)+([0-9]*\s*[A-Za-z]+)", raw)
            chg = re.search(r"Change \|[ |]*(-?[0-9.,]+) \((-?[0-9.]+)%\)",
                            txt)
            prev = re.search(r"Prv\. Close \|[ |]*([0-9.,]+)", txt)
            exp = re.search(r"Expiry: ([0-9]{2}-[A-Za-z]{3}-[0-9]{4})", txt)
            if last:
                return {"ltpNum": last, "cur": "INR",
                        "close": to_number(prev.group(1)) if prev else None,
                        "pchange": to_number(chg.group(2)) if chg else None,
                        "unit": unit.group(1).replace("GRMS", "g").replace("KGS", "kg").strip()
                        if unit else "", "expiry": exp.group(1) if exp
                        else "", "src": "Economic Times (MCX)",
                        "at": time.time(), "other": True}
    except Exception:
        pass
    text, src, _e = ask_gemini_web(
        "What is the latest MCX %s futures price in India (near-month "
        "contract), in rupees per %s? Answer ONLY the number, e.g. 138419, "
        "or UNKNOWN." % (sym.lower(), "10 grams" if sym == "GOLD" else "kg"),
        timeout=30)
    n = to_number(re.sub(r"[^0-9.]", "", str(text or "").split()[0])) \
        if text and "UNKNOWN" not in text.upper() else None
    if n:
        return {"ltpNum": n, "cur": "INR", "close": None, "pchange": None,
                "src": "Gemini with Google Search (the ET page did not "
                       "answer)", "sources": src, "at": time.time(),
                "other": True}
    return None


def asset_quote(ys, life=60):
    """The price, the day's move, the 52-week range and the beta of one
    instrument (Yahoo; a year of daily bars, kept a minute)."""
    if str(ys).startswith("et:"):
        with ASSET_LOCK:
            hit = ASSET_Q.get(ys)
        if hit and time.time() - hit["at"] < max(life, 120):
            return hit["q"]
        q = mcx_quote(ys[3:])
        if not q:
            return hit["q"] if hit else {"symbol": ys, "error": "no price"}
        q["symbol"] = ys
        with ASSET_LOCK:
            ASSET_Q[ys] = {"at": time.time(), "q": q}
        return q
    with ASSET_LOCK:
        hit = ASSET_Q.get(ys)
    if hit and time.time() - hit["at"] < life:
        return hit["q"]
    try:
        bars, meta, _ev = yahoo_ohlc(ys, "1y", "1d")
    except Exception as e:
        if hit:
            return hit["q"]
        return {"symbol": ys, "error": str(e)[:80]}
    if not bars:
        return hit["q"] if hit else {"symbol": ys, "error": "no prices"}
    ltp = meta.get("regularMarketPrice") or bars[-1][4]
    prev = bars[-2][4] if len(bars) > 1 else None
    if meta.get("regularMarketTime") and len(bars) > 1 and \
            int(meta["regularMarketTime"]) - bars[-1][0] > 86400:
        prev = bars[-1][4]
    closes = [b[4] for b in bars]
    q = {"symbol": ys, "ltpNum": round(float(ltp), 4),
         "close": prev, "cur": meta.get("currency") or "",
         "pchange": round((ltp / prev - 1) * 100, 2) if prev else None,
         "yearHigh": max(b[2] for b in bars),
         "yearLow": min(b[3] for b in bars),
         "dayHigh": meta.get("regularMarketDayHigh"),
         "dayLow": meta.get("regularMarketDayLow"),
         "at": time.time(), "other": True}
    try:
        ref = "^GSPC" if q["cur"] == "USD" and not ys.endswith("-USD") and \
            not ys.endswith("=F") and not ys.startswith("^") else "^NSEI"
        hitr = ASSET_REF.get(ref)
        if hitr and time.time() - hitr[0] < 3600:
            rp = hitr[1]
        else:
            rp, _c = yahoo_history(ref, "1y", "1d")
            ASSET_REF[ref] = (time.time(), rp)
        rd = {time.strftime("%Y-%m-%d", time.gmtime(t + 19800)): c
              for t, c in rp}
        sd = {time.strftime("%Y-%m-%d", time.gmtime(b[0] + 19800)): b[4]
              for b in bars}
        days = sorted(set(rd) & set(sd))
        ir, sr = [], []
        for i in range(1, len(days)):
            a, b = days[i - 1], days[i]
            if rd[a] and sd[a]:
                ir.append(rd[b] / rd[a] - 1)
                sr.append(sd[b] / sd[a] - 1)
        n = len(ir)
        if n >= 60:
            mi, ms = sum(ir) / n, sum(sr) / n
            var = sum((x - mi) ** 2 for x in ir) / n
            cov = sum((ir[i] - mi) * (sr[i] - ms) for i in range(n)) / n
            q["beta"] = round(cov / var, 2) if var else None
            q["betaVs"] = "S&P 500" if ref == "^GSPC" else "Nifty 50"
        rets = [closes[i] / closes[i - 1] - 1 for i in range(1, len(closes))
                if closes[i - 1]]
        if len(rets) > 30:
            m = sum(rets) / len(rets)
            per = 365 if ys.endswith(("-INR", "-USD")) else 252
            q["vol"] = round((sum((x - m) ** 2 for x in rets) / len(rets)) **
                             0.5 * per ** 0.5 * 100, 1)
    except Exception:
        pass
    q["hist"] = [[b[0], b[4]] for b in bars[-260:]]
    with ASSET_LOCK:
        ASSET_Q[ys] = {"at": time.time(), "q": q}
    return q


def mf_nav(code):
    """An Indian mutual fund's latest NAV and the one before (mfapi.in)."""
    ys = "MF" + str(code)
    with ASSET_LOCK:
        hit = ASSET_Q.get(ys)
    if hit and time.time() - hit["at"] < 3 * 3600:
        return hit["q"]
    try:
        raw = urllib.request.urlopen(urllib.request.Request(
            "https://api.mfapi.in/mf/%s" % urllib.parse.quote(str(code)),
            headers={"User-Agent": "Mozilla/5.0"}), timeout=12).read()
        d = json.loads(raw.decode("utf-8", "replace"))
        data = d.get("data") or []
        nav = float(data[0]["nav"])
        prev = float(data[1]["nav"]) if len(data) > 1 else None
        hist = []
        for r in data[:260][::-1]:
            try:
                dd = datetime.datetime.strptime(r["date"], "%d-%m-%Y")
                hist.append([int(dd.timestamp()), float(r["nav"])])
            except Exception:
                continue
        q = {"symbol": ys, "ltpNum": nav, "close": prev, "cur": "INR",
             "pchange": round((nav / prev - 1) * 100, 2) if prev else None,
             "navDate": data[0].get("date"), "hist": hist,
             "name": (d.get("meta") or {}).get("scheme_name"),
             "at": time.time(), "other": True}
    except Exception as e:
        return hit["q"] if hit else {"symbol": ys, "error": str(e)[:80]}
    with ASSET_LOCK:
        ASSET_Q[ys] = {"at": time.time(), "q": q}
    return q


def asset_list(st=None):
    """The other-market rows of the main table, in their sections."""
    st = st or load_state()
    a = [x for x in (st.get("assets") or []) if isinstance(x, dict) and
         x.get("key")]
    rank = {t: i for i, t in enumerate(ASSET_ORDER)}
    crank = lambda c: 0 if c == "India" else 1 if c == "United States" \
        else 2
    return sorted(a, key=lambda x: (rank.get(x.get("type"), 99),
                                    crank(x.get("country")),
                                    (st.get("assets") or []).index(x)))


def asset_quotes(st=None):
    """The other-market rows with their prices, for /api/quotes."""
    out = []
    for a in asset_list(st):
        try:
            q = mf_nav(a["mf"]) if a.get("mf") else asset_quote(a["y"], 300)
        except Exception:
            continue
        if not q or q.get("error"):
            continue
        q = {k: v for k, v in q.items() if k != "hist"}
        q["symbol"] = a["key"]
        q["section"] = a.get("type")
        q["assetName"] = a.get("name")
        out.append(q)
    return out


def asset_loop():
    """Keeps the other-market prices fresh (every minute while the page is
    used; crypto trades all day and night)."""
    time.sleep(20)
    while STATS["running"]:
        try:
            st = load_state()
            for a in asset_list(st):
                if a.get("mf"):
                    mf_nav(a["mf"])
                elif a.get("y"):
                    asset_quote(a["y"], 55)
                time.sleep(0.4)
            for it in portfolio_load().get("items") or []:
                if it.get("mf"):
                    mf_nav(it["mf"])
                elif it.get("y"):
                    asset_quote(it["y"], 280)
            day = datetime.date.today().isoformat()
            if STATS.get("pfMark") != day and datetime.datetime.now().hour \
                    >= 16:
                STATS["pfMark"] = day
                portfolio_day_mark()
        except Exception:
            pass
        time.sleep(60)


