def _inr0(v):
    """12,34,567 - Indian grouping, whole rupees."""
    try:
        v = float(v)
    except (TypeError, ValueError):
        return str(v)
    neg, v = v < 0, int(round(abs(v)))
    s = str(v)
    if len(s) > 3:
        head, tail = s[:-3], s[-3:]
        head = ",".join(re.findall(r"\d{1,2}(?=(?:\d{2})*$)", head))
        s = head + "," + tail
    return ("-" if neg else "") + s


def _tn(x, neg=False):
    """A typed figure: '1,25,000' -> 125000.0; blank -> 0; minus only
    where a loss can be typed."""
    try:
        v = float(str(x if x is not None else "").replace(",", "")
                  .replace("₹", "").strip() or 0)
    except (TypeError, ValueError):
        return 0.0
    if v != v or abs(v) > 1e13:
        return 0.0
    return v if neg else max(0.0, v)


def _r10(v):
    """Rounded to the nearest ten rupees (the Act rounds total income and
    the tax this way)."""
    return float(int(math.floor(v / 10.0 + 0.5)) * 10) if v >= 0 \
        else -float(int(math.floor(-v / 10.0 + 0.5)) * 10)


def _fy_year(fy):
    m = re.match(r"(\d{4})-(\d{2})$", str(fy or ""))
    return int(m.group(1)) if m else None


def tax_sec(fy, old, new=None):
    """The section as the year's Act numbers it."""
    y = _fy_year(fy) or 0
    if y >= 2026 and new:
        return "s.%s (old %s)" % (new, old)
    return "s.%s" % old


def tax_rates(fy):
    y = _fy_year(fy) or 0
    if y < 2025:
        return None
    r = {"y": y,
         "newSlabs": [(400000, 0), (800000, .05), (1200000, .10),
                      (1600000, .15), (2000000, .20), (2400000, .25),
                      (None, .30)],
         "newStd": 75000, "oldStd": 50000,
         "newRebate": (1200000, 60000), "oldRebate": (500000, 12500),
         "famPen": {"new": 25000, "old": 15000},
         "stEq": .20, "ltEq": .125, "ltEqFree": 125000, "lt": .125,
         "ltIdx": .20, "flat30": .30, "amt": .185,
         "mat": .14 if y >= 2026 else .15, "matFinal": y >= 2026,
         "nps2": {"new": .14, "old": .10}}
    if y > 2026:
        r["assumed"] = ("The rates of tax year 2026-27 are used: the "
                        "Finance Act for %d-%02d is not in this version "
                        "yet." % (y, (y + 1) % 100))
    return r


def _slab_tax(inc, slabs):
    tax, lo = 0.0, 0.0
    for top, rate in slabs:
        hi = inc if top is None else min(inc, top)
        if hi > lo:
            tax += (hi - lo) * rate
        if top is None or inc <= top:
            break
        lo = top
    return tax


def _slab_rate(inc, slabs):
    lo = 0.0
    for top, rate in slabs:
        if top is None or inc <= top:
            return rate if inc > lo else 0.0
        lo = top
    return 0.0


def _old_slabs(entity, age, resident):
    if entity == "individual" and resident and age == "80plus":
        return [(500000, 0), (1000000, .20), (None, .30)]
    if entity == "individual" and resident and age == "60to80":
        return [(300000, 0), (500000, .05), (1000000, .20), (None, .30)]
    return [(250000, 0), (500000, .05), (1000000, .20), (None, .30)]


def tax_load():
    return _read_json(tax_path(), {}) or {}


def tax_input(fy):
    d = tax_load()
    return (d.get(fy) or {}) if isinstance(d.get(fy), dict) else {}


def tax_save(fy, inp):
    if not _fy_year(fy):
        raise ValueError("Which financial year?")
    if not isinstance(inp, dict):
        raise ValueError("Nothing to save")
    s = json.dumps(inp)
    if len(s) > 400000:
        raise ValueError("Too much to keep")
    with TAX_LOCK:
        d = tax_load()
        old = d.get(fy)
        if old is not None:
            d.setdefault("_undo", {})[fy] = old
        inp["saved"] = time.strftime("%Y-%m-%d %H:%M")
        d[fy] = inp
        _write_json(tax_path(), d)
    return {"ok": True}


def tax_undo(fy):
    with TAX_LOCK:
        d = tax_load()
        u = (d.get("_undo") or {}).pop(fy, None)
        if u is None:
            return {"ok": False, "error": "Nothing to undo"}
        d[fy] = u
        _write_json(tax_path(), d)
    return {"ok": True}


def tax_auto(fy):
    """What the Accounts already know for the year: the gains on shares
    (sale - cost - every charge except STT), intraday (net of every
    charge - STT is allowed against business income), dividends and
    interest as entered in Passive Income."""
    out = {"have": False, "stEq": 0.0, "ltEq": 0.0, "intraday": 0.0,
           "dividend": 0.0, "interest": 0.0, "warn": []}
    try:
        cur = (acc_load() or {}).get("fy")
        _a, v = acc_view(None if (not fy or fy == cur) else fy)
    except Exception:
        v = None
    if not v:
        return out
    out["have"] = True
    tot = (v.get("cg") or {}).get("totals") or {}
    out["stEq"] = float(tot.get("stcgTaxableGain") or 0)
    out["ltEq"] = float(tot.get("ltcgTaxableGain") or 0)
    out["intraday"] = float(tot.get("intradayNet") or 0)
    dash = v.get("dash") or {}
    out["dividend"] = float(dash.get("dividends") or 0)
    out["interest"] = float(dash.get("interest") or 0)
    rows = (v.get("cg") or {}).get("rows") or []
    if any(r.get("tax") == "LTCG" and str(r.get("buy") or "") < "2018-02-01"
           for r in rows):
        out["warn"].append(
            "Some long-term parcels were bought before 1 Feb 2018: their "
            "cost for tax can be the 31 Jan 2018 price (grandfathering). "
            "The gain here uses the actual cost, so it may be higher than "
            "the return's - enter the difference as a manual capital-gain "
            "row (a negative gain) if you have the 31 Jan 2018 prices.")
    oth = [r for r in rows if r.get("tax") == "OTHER"]
    if oth:
        out["warn"].append(
            "Sales in Transactions that are not taxed like shares (%s): "
            "they are not in the share gains above - add each in Capital "
            "gains with its type and dates." % ", ".join(sorted(set(
                "%s (%s)" % (r["sym"], r.get("inst") or "") for r in oth)))[
                :300])
    if any(r.get("tax") == "NO COST" for r in rows):
        out["warn"].append("Some sales have no purchase cost in the "
                           "Accounts: their gain is not included. Fix them "
                           "in Transactions first.")
    if out["dividend"]:
        out["warn"].append(
            "Dividends come from Passive Income as entered. If tax was cut "
            "(TDS), the gross dividend is what is taxed - check it against "
            "the AIS / Form 26AS and type the gross figure in Other "
            "sources if it differs.")
    return out


def _cg_rows(inp, fy, entity, resident, warn):
    """The capital-gain rows typed by hand, sorted into the rate they are
    taxed at."""
    b = {"stSlab": 0.0, "stEq": 0.0, "ltEq": 0.0, "lt125": 0.0,
         "lt20": 0.0, "vda": 0.0, "exempt": 0.0, "detail": []}
    for i, r in enumerate(inp.get("cg") or []):
        if not isinstance(r, dict):
            continue
        typ = r.get("type") if r.get("type") in TAX_CG_TYPES else "gold"
        try:
            bd = datetime.date.fromisoformat(str(r.get("bought"))[:10])
            sd = datetime.date.fromisoformat(str(r.get("sold"))[:10])
        except ValueError:
            warn.append("Capital gain row %d (%s) needs both dates - left "
                        "out." % (i + 1, r.get("what") or "no name"))
            continue
        if sd < bd:
            warn.append("Capital gain row %d: sold before it was bought - "
                        "left out." % (i + 1))
            continue
        sale, cost = _tn(r.get("sale")), _tn(r.get("cost"))
        imp, exp = _tn(r.get("improve")), _tn(r.get("exp"))
        stamp, exm = _tn(r.get("stamp")), _tn(r.get("exempt"))
        full = sale
        note = ""
        if typ == "property" and stamp > sale * 1.10:
            full = stamp
            note = "stamp value used (more than 110% of the price - %s)" % \
                tax_sec(fy, "50C", "78")
        months = (sd.year - bd.year) * 12 + (sd.month - bd.month) - \
            (1 if sd.day < bd.day else 0)
        lim = 12 if typ in ("listed_equity", "other_listed") else 24
        long_ = months >= lim and not (months == lim and sd.day == bd.day)
        gain = full - cost - imp - exp
        name = r.get("what") or TAX_CG_TYPES[typ]
        if typ == "sgb":
            b["exempt"] += max(0.0, gain)
            b["detail"].append({"what": name, "gain": gain,
                                "bucket": "exempt", "note": "exempt"})
            continue
        if typ == "vda":
            # a crypto loss is ignored: no set-off, no carry forward
            b["vda"] += max(0.0, gain)
            b["detail"].append({"what": name, "gain": gain, "bucket": "vda",
                                "note": "a loss counts as nil" if gain < 0
                                else ""})
            continue
        if exm:
            cap = 5000000 if r.get("exemptSec") == "54EC" else 100000000
            if exm > cap:
                warn.append("Row %d: the exemption claimed is above the "
                            "limit of Rs %s - only the limit is used." %
                            (i + 1, _inr0(cap)))
                exm = cap
            exm = min(exm, max(0.0, gain))
        if typ == "debt_new":
            bucket = "stSlab"
        elif not long_:
            bucket = "stEq" if typ == "listed_equity" else "stSlab"
        elif typ == "listed_equity":
            bucket = "ltEq"
        else:
            bucket = "lt125"
        taxed = gain - exm
        if bucket == "lt125" and typ == "property" and bd < \
                datetime.date(2024, 7, 23) and resident and \
                entity in ("individual", "huf"):
            # bought before 23 July 2024: the lower of 12.5% without
            # indexation and 20% with it
            ci_b = TAX_CII.get(bd.year if bd.month >= 4 else bd.year - 1)
            ci_s = TAX_CII.get(sd.year if sd.month >= 4 else sd.year - 1)
            if bd < datetime.date(2001, 4, 1):
                ci_b = 100
                note += ("; bought before 1 Apr 2001 - the cost should be "
                         "the fair market value on 1 Apr 2001")
            if ci_b and ci_s:
                idx = full - cost * ci_s / ci_b - imp - exp - exm
                if imp:
                    note += ("; the improvement cost is not indexed (its "
                             "year is not known), which can only make the "
                             "indexed option look worse")
                if idx * 0.20 < taxed * 0.125:
                    bucket, taxed = "lt20", idx
                    note += "; 20% with indexation is lower - used"
                else:
                    note += "; 12.5% without indexation is lower - used"
            else:
                note += ("; the indexed option was not worked out (the "
                         "cost inflation index of the year of sale is not "
                         "known yet)")
        b[bucket] += taxed
        b["detail"].append({"what": name, "gain": taxed, "bucket": bucket,
                            "long": long_, "months": months,
                            "note": note.strip("; ")})
    return b


def _setoff(loss, pools, order):
    """Takes a loss (positive figure) off the pools in order; returns what
    is left of the loss."""
    for k in order:
        if loss <= 0:
            break
        if pools.get(k, 0) > 0:
            use = min(loss, pools[k])
            pools[k] -= use
            loss -= use
    return loss


def _surcharge_rate(entity, regime, inc, rest, scheme):
    """(rate on the income at normal rates, rate on dividends and the
    capped capital gains)."""
    if entity in ("firm", "llp"):
        r = .12 if inc > 1e7 else 0.0
        return r, r
    if entity in ("company", "opc"):
        if scheme in ("22", "15"):
            return .10, .10
        r = .12 if inc > 1e8 else .07 if inc > 1e7 else 0.0
        return r, r
    if inc <= 5e6:
        return 0.0, 0.0
    if inc <= 1e7:
        return .10, .10
    if inc <= 2e7 or rest <= 2e7:
        return .15, .15
    if rest <= 5e7 or regime == "new":
        return .25, .15
    return .37, .15


def _sc_thresholds(entity, regime, scheme):
    if entity in ("firm", "llp"):
        return [1e7]
    if entity in ("company", "opc"):
        return [] if scheme in ("22", "15") else [1e7, 1e8]
    return [5e6, 1e7, 2e7] + ([] if regime == "new" else [5e7])


def _regime_calc(inp, auto, fy, regime, R):
    ent = inp.get("entity") if inp.get("entity") in TAX_ENTITIES \
        else "individual"
    resident = inp.get("resident", True) is not False
    age = inp.get("age") if inp.get("age") in ("below60", "60to80",
                                               "80plus") else "below60"
    co = inp.get("company") or {}
    scheme = co.get("scheme") if co.get("scheme") in ("normal", "22", "15") \
        else "normal"
    indiv = ent == "individual"
    slabbed = ent in ("individual", "huf", "aop")
    new = regime == "new"
    lines, notes, warn = [], [], []

    def L(label, amt, kind="row", help_=""):
        lines.append({"label": label, "amt": round(amt, 2), "kind": kind,
                      "help": help_})

    # ---- 1. Salary
    sal = inp.get("salary") or {}
    s_gross = _tn(sal.get("gross")) + _tn(sal.get("perq"))
    sal_inc = 0.0
    if s_gross and indiv:
        ex = 0.0 if new else _tn(sal.get("exempt"))
        std = min(s_gross - ex, R["newStd"] if new else R["oldStd"])
        pt = 0.0 if new else min(_tn(sal.get("profTax")), 2500)
        sal_inc = max(0.0, s_gross - ex - std - pt)
        L("Income from salary", sal_inc, "head",
          "Gross salary and perquisites %s, less %sstandard deduction %s%s."
          % (_inr0(s_gross), ("exempt allowances %s, " % _inr0(ex))
             if ex else "", _inr0(std),
             (", professional tax %s" % _inr0(pt)) if pt else ""))
        if new and (_tn(sal.get("exempt")) or _tn(sal.get("profTax"))):
            notes.append("New regime: HRA, LTA and the other exempt "
                         "allowances, and professional tax, are not "
                         "allowed.")
    elif s_gross:
        warn.append("Salary is entered but only an individual has salary "
                    "income - it is left out.")

    # ---- 2. House property
    hp_inc, so_int = 0.0, 0.0
    for h in inp.get("hp") or []:
        if not isinstance(h, dict):
            continue
        intr = _tn(h.get("interest"))
        if h.get("kind") == "let":
            nav = max(0.0, _tn(h.get("rent")) - _tn(h.get("munTax")))
            hp_inc += nav - nav * 0.30 - intr
        else:
            so_int += intr
    if so_int:
        if new:
            notes.append("New regime: interest on a self-occupied house is "
                         "not allowed.")
        else:
            use = min(so_int, 200000.0)
            hp_inc -= use
            if so_int > use:
                notes.append("Interest on self-occupied houses is allowed "
                             "only up to Rs 2,00,000 in all.")
    if inp.get("hp"):
        L("Income from house property", hp_inc, "head",
          "Let-out: rent less municipal tax, less 30% standard deduction, "
          "less interest on the loan. Self-occupied: nil, less interest (old "
          "regime, up to Rs 2 lakh).")

    # ---- 3. Business or profession
    bz = inp.get("biz") or {}
    p44ad = _tn(bz.get("ad_digital")) * 0.06 + _tn(bz.get("ad_cash")) * 0.08
    p44ada = _tn(bz.get("ada")) * 0.50
    nonspec = _tn(bz.get("business"), True) + _tn(bz.get("fno"), True) + \
        p44ad + p44ada
    spec = (auto.get("intraday", 0.0) if inp.get("useAuto", True) is not
            False else 0.0) + _tn(bz.get("speculative"), True)
    if p44ad or p44ada:
        notes.append("Presumptive income: 6%% of turnover received through "
                     "banks / digital means and 8%% of cash turnover (%s), "
                     "50%% of a profession's receipts (%s)." %
                     (tax_sec(fy, "44AD"), tax_sec(fy, "44ADA")))
    c_f = {"hp": 0.0, "biz": 0.0, "spec": 0.0, "stcl": 0.0, "ltcl": 0.0}
    if nonspec < 0 and spec > 0:          # a business loss may eat
        u = min(-nonspec, spec)          # speculative profit
        nonspec += u
        spec -= u
    if spec < 0:
        c_f["spec"] = -spec
        spec = 0.0

    # ---- 4. Capital gains
    cgb = _cg_rows(inp, fy, ent, resident, warn)
    use_auto = inp.get("useAuto", True) is not False
    pools = {"stSlab": cgb["stSlab"],
             "stEq": cgb["stEq"] + (auto.get("stEq", 0.0) if use_auto else 0),
             "lt20": cgb["lt20"], "lt125": cgb["lt125"],
             "ltEq": cgb["ltEq"] + (auto.get("ltEq", 0.0) if use_auto else 0)}
    stl = sum(-pools[k] for k in ("stSlab", "stEq") if pools[k] < 0)
    ltl = sum(-pools[k] for k in ("lt20", "lt125", "ltEq") if pools[k] < 0)
    for k in pools:
        pools[k] = max(0.0, pools[k])
    order_st = ["stSlab", "stEq", "lt20", "lt125", "ltEq"]
    order_lt = ["lt20", "lt125", "ltEq"]
    stl = _setoff(stl, pools, order_st)
    ltl = _setoff(ltl, pools, order_lt)
    bf = inp.get("bf") or {}
    bf_st = _setoff(_tn(bf.get("stcl")), pools, order_st)
    bf_lt = _setoff(_tn(bf.get("ltcl")), pools, order_lt)
    c_f["stcl"] = stl + bf_st
    c_f["ltcl"] = ltl + bf_lt
    cg_total = sum(pools.values()) + cgb["vda"]
    if cg_total or c_f["stcl"] or c_f["ltcl"] or cgb["detail"] or \
            (use_auto and (auto.get("stEq") or auto.get("ltEq"))):
        L("Capital gains (after setting off capital losses)", cg_total,
          "head", "Short-term losses are set off against short- or "
          "long-term gains, long-term losses only against long-term gains "
          "(%s); crypto gains are taxed alone and their losses ignored."
          % tax_sec(fy, "70 / 74", "108 / 111"))
        for k, lab in (("stSlab", "Short-term, at slab rates"),
                       ("stEq", "Short-term on listed shares / equity funds "
                        "(%s, 20%%)" % tax_sec(fy, "111A", "196")),
                       ("ltEq", "Long-term on listed shares / equity funds "
                        "(%s, 12.5%% above Rs 1.25 lakh)" %
                        tax_sec(fy, "112A", "198")),
                       ("lt125", "Long-term, other assets (%s, 12.5%%)" %
                        tax_sec(fy, "112", "197")),
                       ("lt20", "Long-term, property with indexation "
                        "(20%)"),
                       ("vda", "Crypto / VDA (30%)")):
            v = cgb["vda"] if k == "vda" else pools[k]
            if v:
                L(lab, v, "sub")
    if cgb["exempt"]:
        notes.append("Sovereign Gold Bonds held to maturity: gain of Rs %s "
                     "is exempt." % _inr0(cgb["exempt"]))

    # ---- 5. Other sources
    os_ = inp.get("os") or {}
    div = _tn(os_.get("dividend")) if os_.get("dividend") not in (
        None, "") else (auto.get("dividend", 0.0) if use_auto else 0.0)
    intr = _tn(os_.get("savings")) + _tn(os_.get("fd")) + \
        _tn(os_.get("otherInt")) + (
            auto.get("interest", 0.0) if use_auto and
            os_.get("dividend") in (None, "") else 0.0)
    fp = _tn(os_.get("famPension"))
    fp_ded = min(fp / 3.0, R["famPen"]["new" if new else "old"]) if fp else 0
    other = _tn(os_.get("other"), True)
    os_inc = div + intr + fp - fp_ded + other
    lottery = _tn(os_.get("lottery"))
    if os_inc or lottery or div:
        L("Income from other sources", os_inc + lottery, "head",
          "Dividends %s, interest %s%s%s%s." % (
              _inr0(div), _inr0(intr),
              (", family pension %s less 1/3 (up to %s)" % (
                  _inr0(fp), _inr0(R["famPen"]["new" if new
                                                   else "old"]))) if fp
              else "", (", other %s" % _inr0(other)) if other else "",
              (", winnings from lotteries / games %s (30%%, no "
               "deduction)" % _inr0(lottery)) if lottery else ""))

    # ---- set-off between heads (current year)
    norm = {"sal": sal_inc, "hp": max(0.0, hp_inc), "biz": max(0.0, nonspec),
            "spec": spec, "os": max(0.0, os_inc)}
    hp_loss = max(0.0, -hp_inc)
    if hp_loss:
        cap = 0.0 if new else 200000.0
        use = min(hp_loss, cap)
        rest = hp_loss - use
        pool = dict(norm, **pools)
        left = _setoff(use, pool, ["sal", "os", "biz", "spec", "stSlab",
                                   "stEq", "lt20", "lt125", "ltEq"])
        for k in norm:
            norm[k] = pool[k]
        for k in pools:
            pools[k] = pool[k]
        c_f["hp"] = rest + left
        if hp_loss:
            L("Less: house property loss set off against other income",
              -(use - left), "sub", "Up to Rs 2 lakh a year against other "
              "heads (old regime only - the new regime allows none); the "
              "rest is carried forward 8 years against house property "
              "income.")
    biz_loss = max(0.0, -nonspec)
    if biz_loss:
        pool = dict(norm, **pools)
        left = _setoff(biz_loss, pool, ["os", "hp", "stSlab", "stEq",
                                        "lt20", "lt125", "ltEq"])
        for k in norm:
            norm[k] = pool[k]
        for k in pools:
            pools[k] = pool[k]
        c_f["biz"] += left
        L("Less: business loss set off against other income",
          -(biz_loss - left), "sub", "A business loss may be set off "
          "against any income except salary; the rest is carried forward 8 "
          "years against business income.")
    os_neg = max(0.0, -os_inc)
    if os_neg:
        warn.append("A loss under Other sources is not set off here - "
                    "check it with your CA.")
    # ---- losses of earlier years
    u = _setoff(_tn(bf.get("hp")), norm, ["hp"])
    c_f["hp"] += u
    u = _setoff(_tn(bf.get("spec")), norm, ["spec"])
    c_f["spec"] += u
    u = _setoff(_tn(bf.get("biz")), norm, ["biz", "spec"])
    c_f["biz"] += u
    if any(_tn(bf.get(k)) for k in ("hp", "spec", "biz", "stcl", "ltcl")):
        notes.append("Losses of earlier years were set off as the Act "
                     "allows (house property against house property, "
                     "speculative against speculative, business against "
                     "business, capital against capital gains).")

    spec_rate_inc = pools["stEq"] + pools["ltEq"] + pools["lt125"] + \
        pools["lt20"] + cgb["vda"] + lottery
    gti = sum(norm.values()) + spec_rate_inc
    L("Gross total income", gti, "total")

    # ---- Chapter VI-A deductions
    dd = inp.get("ded") or {}
    ded, dlines = 0.0, []
    senior = indiv and age != "below60"
    if indiv and not new:
        c80c = min(_tn(dd.get("c80")), 150000.0)
        c1b = min(_tn(dd.get("ccd1b")), 50000.0)
        d_self = min(_tn(dd.get("d80self")), 50000.0 if senior else 25000.0)
        d_par = min(_tn(dd.get("d80par")), 50000.0 if dd.get("parSenior")
                    else 25000.0)
        e80 = _tn(dd.get("e80"))
        g80 = _tn(dd.get("g80"))
        oth = _tn(dd.get("other"))
        if senior and resident:
            tt = min(intr, 50000.0)
            ttl = "Interest of a senior citizen (%s)" % tax_sec(
                fy, "80TTB", "153")
        else:
            tt = min(_tn(os_.get("savings")), 10000.0)
            ttl = "Savings bank interest (%s)" % tax_sec(fy, "80TTA", "153")
        for lab, v in (("%s - PF, PPF, ELSS, insurance, home-loan principal "
                        "(up to Rs 1.5 lakh)" % tax_sec(fy, "80C", "123"),
                        c80c),
                       ("%s - own NPS (up to Rs 50,000)" %
                        tax_sec(fy, "80CCD(1B)", "124"), c1b),
                       ("%s - health insurance, self and family" %
                        tax_sec(fy, "80D", "126"), d_self),
                       ("%s - health insurance, parents" %
                        tax_sec(fy, "80D", "126"), d_par),
                       ("%s - education-loan interest" %
                        tax_sec(fy, "80E", "129"), e80),
                       ("%s - donations (the eligible amount)" %
                        tax_sec(fy, "80G", "133"), g80),
                       (ttl, tt), ("Other deductions (as typed)", oth)):
            if v:
                dlines.append((lab, v))
    elif not new and ent in ("huf",):
        for lab, k, cap in (("80C (up to Rs 1.5 lakh)", "c80", 150000.0),
                            ("80D", "d80self", 25000.0),
                            ("Other deductions", "other", None)):
            v = _tn(dd.get(k))
            v = min(v, cap) if cap else v
            if v:
                dlines.append((tax_sec(fy, lab), v) if lab[0].isdigit()
                              else (lab, v))
    elif not new:
        v = _tn(dd.get("other"))
        if v:
            dlines.append(("Chapter VI-A deductions (as typed)", v))
    if indiv:
        nps = _tn(sal.get("employerNps"))
        if nps:
            bd = _tn(sal.get("basicDa"))
            cap = bd * R["nps2"]["new" if new else "old"] if bd else nps
            if not bd:
                warn.append("Employer's NPS: type the basic pay + DA too, "
                            "so the %d%% limit can be checked." %
                            (R["nps2"]["new" if new else "old"] * 100))
            dlines.append(("%s - employer's NPS contribution" %
                           tax_sec(fy, "80CCD(2)", "124"), min(nps, cap)))
    if new and _tn(dd.get("newOk")):
        dlines.append(("Deductions the new regime allows (Agniveer fund, "
                       "new employees' wages)", _tn(dd.get("newOk"))))
    ded = sum(v for _l, v in dlines)
    # never more than the income at normal rates
    room = max(0.0, gti - spec_rate_inc)
    if ded > room:
        notes.append("Deductions are limited to the income taxed at normal "
                     "rates (they never reduce capital gains at special "
                     "rates, crypto or lottery winnings).")
        ded = room
    if dlines:
        L("Less: deductions under Chapter VI-A", -ded, "head")
        for lab, v in dlines:
            L(lab, v, "sub")
    elif new and indiv:
        notes.append("New regime: 80C, 80D and most other deductions are "
                     "not allowed; employer's NPS is.")
    ti_exact = gti - ded
    ti = _r10(ti_exact)
    L("Total income (rounded to the nearest Rs 10)", ti, "total")

    # ---- tax at normal and special rates
    normal = max(0.0, ti - spec_rate_inc)
    if ent in ("firm", "llp"):
        slabs = [(None, R["flat30"])]
    elif ent in ("company", "opc"):
        rate = {"22": .22, "15": .15}.get(scheme) or (
            .25 if co.get("small", True) is not False else .30)
        slabs = [(None, rate)]
    elif new:
        slabs = R["newSlabs"]
    else:
        slabs = _old_slabs(ent, age, resident)
    bel = slabs[0][0] if slabs[0][1] == 0 else 0.0
    sp = {"stEq": pools["stEq"], "ltEq": max(0.0, pools["ltEq"] -
                                             R["ltEqFree"]),
          "lt125": pools["lt125"], "lt20": pools["lt20"]}
    short = 0.0
    if slabbed and resident and bel and normal < bel:
        short = bel - normal
        rem = _setoff(short, sp, ["lt20", "stEq", "lt125", "ltEq"])
        if short - rem:
            notes.append("The income at normal rates is below the basic "
                         "exemption limit (Rs %s): the gap of Rs %s comes off "
                         "the capital gains taxed at special rates (allowed "
                         "to resident individuals and HUFs)." %
                         (_inr0(bel), _inr0(short - rem)))
    t_norm = _slab_tax(normal, slabs)
    t_sp = {"stEq": sp["stEq"] * R["stEq"], "ltEq": sp["ltEq"] * R["ltEq"],
            "lt125": sp["lt125"] * R["lt"], "lt20": sp["lt20"] * R["ltIdx"],
            "vda": cgb["vda"] * R["flat30"], "lot": lottery * R["flat30"]}
    L("Tax on income at normal rates (Rs %s)" % _inr0(normal), t_norm,
      "tax", "Slab rates of the %s" % (
          "new regime (%s)" % tax_sec(fy, "115BAC", "202") if new and slabbed
          else "old regime" if slabbed else
          "flat rate of %d%%" % round(slabs[0][1] * 100)))
    for k, lab in (("stEq", "Tax on short-term gains on shares at 20%"),
                   ("ltEq", "Tax on long-term gains on shares above Rs 1.25 "
                    "lakh at 12.5%"),
                   ("lt125", "Tax on other long-term gains at 12.5%"),
                   ("lt20", "Tax on property gains with indexation at 20%"),
                   ("vda", "Tax on crypto / VDA at 30%"),
                   ("lot", "Tax on lottery / game winnings at 30%")):
        if t_sp[k]:
            L(lab, t_sp[k], "tax")
    tax = t_norm + sum(t_sp.values())
    L("Tax before rebate", tax, "total")

    # ---- rebate (resident individuals)
    rebate = 0.0
    if indiv and resident:
        lim, mx = R["newRebate"] if new else R["oldRebate"]
        base = t_norm if new else t_norm + t_sp["stEq"] + t_sp["lt125"] + \
            t_sp["lt20"]
        if ti <= lim:
            rebate = min(base, mx)
        elif new and ti - lim < base:
            # marginal relief: the tax never more than the income above
            # Rs 12 lakh
            rebate = base - (ti - lim)
            if spec_rate_inc:
                notes.append("Marginal relief above Rs 12 lakh is worked "
                             "out on the tax at slab rates only - with "
                             "capital gains in the income, confirm it with "
                             "your CA.")
        if rebate:
            L("Less: rebate (%s)%s" % (tax_sec(fy, "87A", "156"),
                                       " with marginal relief" if ti > lim
                                       else ""), -rebate, "tax",
              ("New regime: nil tax up to Rs 12 lakh of total income; not "
               "available on the tax on special-rate income (capital gains "
               "on shares and property, crypto, lottery).") if new else
              ("Old regime: up to Rs 12,500 when total income is Rs 5 lakh "
               "or less; not available on long-term gains on shares (112A)."))
    tax_ar = max(0.0, tax - rebate)

    # ---- surcharge
    capped_inc = pools["stEq"] + pools["ltEq"] + pools["lt125"] + \
        pools["lt20"] + div
    rest_inc = ti - capped_inc
    r_full, r_cap = _surcharge_rate(ent, regime, ti, rest_inc, scheme)
    top = _slab_rate(normal, slabs)
    t_div = min(t_norm, div * top)
    t_cap = t_sp["stEq"] + t_sp["ltEq"] + t_sp["lt125"] + t_sp["lt20"] + \
        t_div
    t_cap = min(t_cap, tax_ar)
    sc = (tax_ar - t_cap) * r_full + t_cap * r_cap
    mr = 0.0
    if sc:
        thr = max([t for t in _sc_thresholds(ent, regime, scheme)
                   if t < ti] or [0])
        if thr and normal >= ti - thr:
            n2 = normal - (ti - thr)
            t2 = _slab_tax(n2, slabs) + sum(t_sp.values())
            rf2, rc2 = _surcharge_rate(ent, regime, thr, thr - capped_inc,
                                       scheme)
            t2cap = min(t2, t_cap)
            at_thr = t2 + (t2 - t2cap) * rf2 + t2cap * rc2
            over = tax_ar + sc - (at_thr + (ti - thr))
            if over > 0:
                mr = min(over, sc)
        elif thr:
            notes.append("Marginal relief on the surcharge was not worked "
                         "out (most of the income is at special rates) - "
                         "check it with your CA.")
        L("Add: surcharge%s" % (" (%d%%, 15%% on dividends and capital "
                                 "gains)" % round(r_full * 100)
                                 if r_full != r_cap else " (%d%%)" %
                                 round(r_full * 100)), sc, "tax",
          "Surcharge on the tax when the income crosses Rs 50 lakh / 1 / 2 "
          "/ 5 crore (individuals), Rs 1 crore (firms), Rs 1 / 10 crore "
          "(companies). On dividends and capital gains on shares and "
          "property it is never more than 15%.")
        if mr:
            L("Less: marginal relief on the surcharge", -mr, "tax",
              "The extra tax from crossing a surcharge limit may not be "
              "more than the income above that limit.")
    sc_net = sc - mr
    cess = (tax_ar + sc_net) * 0.04
    L("Add: health and education cess at 4%", cess, "tax")
    total = tax_ar + sc_net + cess

    # ---- AMT (non-corporate, old regime, profit-linked deductions)
    amt_info = None
    amt_d = _tn(dd.get("amtDed"))
    if amt_d and ent not in ("company", "opc") and not new:
        ati = ti + amt_d
        if ent in ("firm", "llp") or ati > 2000000:
            a_tax = ati * R["amt"]
            ar, _ac = _surcharge_rate(ent, regime, ati, ati, scheme)
            a_tot = (a_tax + a_tax * ar) * 1.04
            amt_info = {"ati": ati, "amt": a_tot}
            L("Alternate minimum tax: 18.5%% of adjusted total income "
              "Rs %s, with surcharge and cess" % _inr0(ati), a_tot,
              "sub", "AMT applies when profit-linked deductions (80-IA to "
              "80RRB, 10AA, 35AD) are claimed; the higher of the two is "
              "paid and the excess is a credit for later years.")
            if a_tot > total:
                notes.append("AMT is higher than the regular tax: AMT is "
                             "payable, and the difference (Rs %s) is a "
                             "credit for later years." %
                             _inr0(a_tot - total))
                total = a_tot
    # ---- MAT (companies on the normal rates)
    mat_info = None
    if ent in ("company", "opc") and scheme == "normal" and \
            _tn(co.get("bookProfit")):
        bp = _tn(co.get("bookProfit"))
        m_tax = bp * R["mat"]
        mrr = .12 if bp > 1e8 else .07 if bp > 1e7 else 0.0
        m_tot = (m_tax + m_tax * mrr) * 1.04
        mat_info = {"bookProfit": bp, "mat": m_tot}
        L("Minimum alternate tax: %g%% of book profit Rs %s, with surcharge "
          "and cess" % (R["mat"] * 100, _inr0(bp)), m_tot, "sub",
          "A company on the normal rates pays the higher of the regular "
          "tax and MAT. %s" % ("From tax year 2026-27 MAT is a final tax - "
                               "no new MAT credit." if R["matFinal"] else
                               "The excess is a credit for 15 years."))
        if m_tot > total:
            total = m_tot
            notes.append("MAT is higher than the regular tax and is "
                         "payable.")
    total = _r10(total)
    L("Total tax for the year (rounded to the nearest Rs 10)", total, "grand")
    pd = inp.get("paid") or {}
    tds = _tn(pd.get("tds")) + _tn(pd.get("tcs"))
    adv = _tn(pd.get("advance")) + _tn(pd.get("self"))
    if tds or adv:
        L("Less: TDS and TCS", -tds, "sub")
        L("Less: advance tax and self-assessment tax paid", -adv, "sub")
    bal = total - tds - adv
    L("Tax still to pay" if bal > 0 else "Refund due" if bal < 0 else
      "Nothing more to pay", abs(bal), "grand",
      "Before interest for late payment (234B / 234C), which is not worked "
      "out here.")
    if R.get("assumed"):
        notes.append(R["assumed"])
    cfl = {k: round(v, 2) for k, v in c_f.items() if v > 0.5}
    if cfl:
        notes.append("Losses carried forward: " + ", ".join(
            "%s Rs %s" % ({"hp": "house property (8 years)",
                           "biz": "business (8 years)",
                           "spec": "speculative (4 years)",
                           "stcl": "short-term capital (8 years)",
                           "ltcl": "long-term capital (8 years)"}[k],
                          _inr0(v)) for k, v in cfl.items()) +
            ". Only if the return is filed by its due date.")
    return {"regime": regime, "lines": lines, "notes": notes, "warn": warn,
            "gti": round(gti, 2), "ded": round(ded, 2), "ti": ti,
            "tax": round(tax, 2), "rebate": round(rebate, 2),
            "surcharge": round(sc_net, 2), "cess": round(cess, 2),
            "total": total, "tds": tds, "paid": adv, "balance": round(bal, 2),
            "liability": max(0.0, total - tds),
            "marginal": _slab_rate(normal, slabs), "carry": cfl,
            "amt": amt_info, "mat": mat_info,
            "heads": {"salary": sal_inc, "hp": hp_inc,
                      "biz": nonspec, "spec": spec,
                      "cg": sum(pools.values()) + cgb["vda"],
                      "os": os_inc + lottery},
            "cgDetail": cgb["detail"]}


def tax_compute(fy=None):
    """The year's computation: {ok, fy, filled, totalTax, regimes...}."""
    if not fy:
        try:
            fy = (acc_load() or {}).get("fy") or acc_fy_of(
                datetime.date.today().isoformat())
        except Exception:
            fy = acc_fy_of(datetime.date.today().isoformat())
    R = tax_rates(fy)
    inp = tax_input(fy)
    if not R:
        return {"ok": True, "fy": fy, "supported": False, "filled": False,
                "inp": inp, "error": "The Taxes section works out FY 2025-26 "
                "and later. Earlier years had other rates and are not worked "
                "out here."}
    auto = tax_auto(fy)
    ent = inp.get("entity") if inp.get("entity") in TAX_ENTITIES \
        else "individual"
    if ent in ("individual", "huf", "aop"):
        res = {"new": _regime_calc(inp, auto, fy, "new", R),
               "old": _regime_calc(inp, auto, fy, "old", R)}
        best = "new" if res["new"]["total"] <= res["old"]["total"] else "old"
    else:
        res = {"normal": _regime_calc(inp, auto, fy, "normal", R)}
        best = "normal"
    chosen = inp.get("regime") if inp.get("regime") in res else best
    filled = bool(inp.get("saved"))
    return {"ok": True, "fy": fy, "supported": True, "inp": inp,
            "auto": auto, "res": res, "best": best, "chosen": chosen,
            "filled": filled, "totalTax": res[chosen]["liability"],
            "marginal": res[chosen]["marginal"],
            "entities": TAX_ENTITIES, "cgTypes": TAX_CG_TYPES,
            "newAct": (_fy_year(fy) or 0) >= 2026,
            "aiOK": bool(acc_ui().get("aiOK"))}


