def _scaled(r):
    k = INDEX_SCALE.get(r.get("name"))
    if k:
        r = dict(r)
        for f in ("last", "chg"):
            if isinstance(r.get(f), (int, float)):
                r[f] = round(r[f] * k, 6)
    return r


def ticker_prefs(st=None):
    """(ticked labels in order, rise-is-bad by label, threshold by group).
    A tick can carry an end date ("until"): after it, it is unticked."""
    st = st if st is not None else load_state()
    tp = st.get("tickerPrefs") if isinstance(st.get("tickerPrefs"),
                                             dict) else {}
    today = datetime.date.today().isoformat()
    pins = tp.get("pins")
    if not isinstance(pins, dict):
        pins = {c[0]: True for c in INDEX_CATALOG if c[4]}
        if profile_read().get("admin"):
            pins.update(TRIP_PINS)
    elif "JPY/INR" in pins:              # renamed in 20.7: one yen in rupees
        pins = dict(pins)
        pins["\u00a51 = \u20b9"] = pins.pop("JPY/INR")
    if isinstance(tp.get("pins"), dict) and "INDIA VIX" not in pins:
        # 20.10: India's VIX joins the strip in place of the US one (an
        # untick saved after this is kept as false, so it stays off)
        pins = dict(pins)
        pins["INDIA VIX"] = True
    on = [c[0] for c in INDEX_CATALOG
          if pins.get(c[0]) is True or (isinstance(pins.get(c[0]), str)
                                         and today < pins[c[0]])]
    tb = tp.get("bad") if isinstance(tp.get("bad"), dict) else {}
    if "JPY/INR" in tb:
        tb = dict(tb)
        tb.setdefault("\u00a51 = \u20b9", tb.pop("JPY/INR"))
    tm = tp.get("move") if isinstance(tp.get("move"), dict) else {}
    bad = {c[0]: bool(tb.get(c[0], c[5])) for c in INDEX_CATALOG}
    move = {}
    for g, pct in INDEX_GROUPS:
        try:
            move[g] = max(0.1, float(tm.get(g, pct)))
        except (TypeError, ValueError):
            move[g] = pct
    return on, bad, move, pins


