def _why_now(tzname):
    try:
        from zoneinfo import ZoneInfo
        return datetime.datetime.now(ZoneInfo(tzname))
    except Exception:
        off = WHY_TZ_FALLBACK.get(tzname, 0)
        return datetime.datetime.now(datetime.timezone(
            datetime.timedelta(hours=off)))


def why_session(label):
    """20.18: (trading now?, the date of its latest session) in the
    market's own time. Before the open, the latest session is the previous
    weekday's - so a US session that runs past midnight in India keeps
    one date from start to finish."""
    c = INDEX_BY.get(label)
    s = WHY_SESSIONS.get(label) or WHY_GROUP_SESSIONS.get(
        c[2] if c else "") or ("Asia/Kolkata", "09:15", "15:15")
    every_day = len(s) > 3 and s[3] == "all"
    now = _why_now(s[0])
    if s[1] == "fx":
        # a session starts at 6 pm New York time: moved six hours on, each
        # session falls on one weekday, and the daily break is 11 pm-midnight
        sh = now + datetime.timedelta(hours=6)
        trading_day = sh.weekday() < 5
        d = sh.date()
        while d.weekday() >= 5:
            d -= datetime.timedelta(days=1)
        return trading_day and sh.hour != 23, d.isoformat()
    hm = now.strftime("%H:%M")
    trading_day = every_day or now.weekday() < 5
    if label in INDIA_INDICES and not is_trading_day():
        trading_day = False
    open_now = trading_day and s[1] <= hm < s[2]
    d = now.date()
    if not (trading_day and hm >= s[1]):
        d -= datetime.timedelta(days=1)
        while not every_day and d.weekday() >= 5:
            d -= datetime.timedelta(days=1)
    return open_now, d.isoformat()


def why_due(label, pct, stale=False):
    """20.17: whether Gemini is asked (again) why this index moved. 2 Nov:
    152 questions for 22 different moves, because the Nasdaq going -3.98%,
    -4.02%, -3.99% changed the old key every time. Now asked on the first
    move of the day, again only when the move reaches a NEW whole % (never
    for going back), or turns round by at least 1%; when Gemini was busy,
    again after 15 minutes; never more than WHY_MAX_ASKS a day."""
    w = INDEX_WHY.get(label) or {}
    now = time.time()
    open_now, sday = why_session(label)
    if w.get("pending") and now - w.get("at", 0) < 300:
        return False
    if w.get("day") != sday:
        # 20.18: nothing asked yet for this session. While it trades: its
        # first real move. After the close: ONCE, for the finished session
        # (when the dashboard was not open while it traded) - never again
        if w.get("why") and label in INDIA_INDICES and \
                not is_trading_day():
            return False             # an Indian holiday: last session holds
        return True
    if not open_now:
        # closed: only a failed question is tried again, at most once more
        return bool(w.get("fail")) and (w.get("asks") or 0) < 2 and \
            now - w.get("at", 0) > 900
    if (w.get("asks") or 0) >= WHY_MAX_ASKS:
        return False
    if w.get("fail"):
        return now - w.get("at", 0) > 900
    b, s = int(abs(pct)), ("+" if pct >= 0 else "-")
    if s != w.get("sign") and b >= 1:
        return True
    return b > (w.get("maxb") or 0)


def index_reason(label, pct, claimed=False):
    key = why_key(pct)
    old = INDEX_WHY.get(label) or {}
    if not claimed and not why_due(label, pct):
        return
    INDEX_WHY[label] = dict(old, key=key, at=time.time(), pending=True)
    c = INDEX_BY.get(label) or (label, "", "", "", False, False)
    group, what = c[2], c[3]
    if label == "\u00a51 = \u20b9":
        term = "JPY INR yen rupee exchange rate"
    elif group in ("Currencies",):
        term = "%s rupee %s" % (label.replace("/", " "), "exchange rate")
    elif group in ("Commodities", "Crypto"):
        term = "%s price %s" % (label.title(), "today")
    elif group == "Bonds":
        term = "%s bond yield" % what.split(",")[0]
    else:
        term = "%s %s stocks market" % (label, what)
    heads = []
    try:
        url = ("https://news.google.com/rss/search?q=" + Q(term + " when:1d")
               + "&hl=en-IN&gl=IN&ceid=IN:en")
        raw = urllib.request.urlopen(urllib.request.Request(
            url, headers={"User-Agent": UA}), timeout=10).read()
        for it in ET.fromstring(raw).iter("item"):
            t = re.sub(r"\s+-\s+[^-]+$", "", (it.findtext("title") or "")
                       .strip())
            if t:
                heads.append(t)
            if len(heads) >= 8:
                break
    except Exception:
        pass
    why, answered = "", not heads      # no headlines: nothing to ask
    if heads:
        with WHY_SEM:
            ans, _e = ask_gemini("Why did %s (%s) %s %.1f%% %s? Headlines:"
                                 "\n- " % (label, what, "rise" if pct >= 0
                                           else "fall", abs(pct),
                                           "today" if why_session(label)[0]
                                           else "in its last session") +
                                 "\n- ".join(heads), WHY_STYLE)
        answered = ans is not None
        ans = re.sub(r"\s+", " ", str(ans or "")).strip()
        if ans and "UNKNOWN" not in ans.upper() and len(ans) < 260:
            why = ans
    # 20.14: said plainly when the news does not explain it - 20.17: but
    # ONLY when Gemini answered; a busy Gemini is not "no reason"
    today = why_session(label)[1]          # 20.18: the session's own date
    same = old.get("day") == today
    INDEX_WHY[label] = {
        "key": key, "day": today, "at": time.time(),
        "why": why or ("No particular reason found in today's news."
                       if answered else (old.get("why") if same else "")),
        "fail": not answered,
        "asks": ((old.get("asks") or 0) + 1) if same else 1,
        "maxb": max(int(abs(pct)), ((old.get("maxb") or 0) if same else 0)),
        "sign": "+" if pct >= 0 else "-"}
    try:
        _write_json(os.path.join(os.path.dirname(PATHS["state"]),
                                 "index_why.json"), INDEX_WHY)
    except Exception:
        pass


def index_quote(label):
    """Take the freshest CNBC batch if it is recent, else ask directly.
    Nothing here touches the NSE session, so the ticker can never be blocked
    by the 125-symbol stock sweep."""
    if label == "BRENT":
        # Brent is taken from Moneycontrol and shown in US dollars. CNBC's
        # @LCO.1 is only used if Moneycontrol will not answer at all.
        try:
            r = brent_spot()
        except Exception:
            r = None
        if r and r.get("last"):
            r["stale"] = False
            r["when"] = time.time()
            r["whenText"] = time.strftime("%d %b %H:%M:%S")
            TICKER["last"][label] = dict(r)
            return r
    # The Indian indices never take the CNBC shortcut. CNBC republishes them
    # with a lag, and his 19 Aug capture showed the dashboard drifting away
    # from both NSE and Moneycontrol all afternoon because of this line.
    fresh = None
    if label not in INDIA_INDICES:
        fresh = CNBC_CACHE["data"].get(label) \
            if time.time() - CNBC_CACHE["at"] < 15 else None
    if fresh:
        r = dict(fresh)
    else:
        r = None
        for fn in (lambda: mc_index_quote(label),
                   lambda: cnbc_quotes([label]).get(label)):
            try:
                got = fn()
                if got and got.get("last"):
                    r = got
                    break
            except Exception:
                continue
    if r and r.get("last"):
        r["stale"] = False
        r["when"] = time.time()
        r["whenText"] = time.strftime("%d %b %H:%M:%S")
        TICKER["last"][label] = dict(r)
        return r
    old = TICKER["last"].get(label)
    if old:
        out = dict(old, stale=True)
        if old.get("when"):
            out["whenText"] = time.strftime("%d %b %H:%M:%S",
                                            time.localtime(old["when"]))
        return out
    return None


def fetch_indices(with_guests=None):
    """Fetch every index in parallel. The ticked ones every cycle; the rest
    only every ten minutes, to see whether one has moved a lot."""
    if not TICKER_FILE_LOADED["v"]:
        load_ticker_cache()
        index_why_load()
    pins, bad, move, _p = ticker_prefs()
    if with_guests is None:
        with_guests = time.time() - GUEST_CHECK["at"] > 600
    others = [c[0] for c in INDEX_CATALOG if c[0] not in pins]
    labels = list(pins) + (others if with_guests else [])
    if with_guests:
        GUEST_CHECK["at"] = time.time()
    try:
        CNBC_CACHE["data"] = cnbc_batch(labels)   # one call covers nearly all
        CNBC_CACHE["at"] = time.time()
    except Exception as e:
        TICKER["error"] = "CNBC: %s" % str(e)[:80]

    got = {}
    threads = []

    def work(lbl):
        try:
            got[lbl] = index_quote(lbl)
        except Exception:
            got[lbl] = None

    for lbl in labels:
        t = threading.Thread(target=work, args=(lbl,), daemon=True)
        t.start()
        threads.append(t)
    for t in threads:
        t.join(timeout=25)

    rows = []
    for label in pins:
        r = got.get(label) or TICKER["last"].get(label)
        if r and r.get("last"):
            rows.append(dict(r))
    for label in others:
        limit = move.get((INDEX_BY.get(label) or ("", "", ""))[2],
                         BIG_MOVE_PCT)
        r = got.get(label)
        if with_guests:
            if r and r.get("last") and not r.get("stale") \
                    and abs(r.get("pct") or 0) >= limit:
                rows.append(dict(r, alert=True))
        else:
            old = TICKER["last"].get(label)
            if old and old.get("guest") and abs(old.get("pct") or 0) >= limit:
                rows.append(dict(old, alert=True))
    for label in others:
        if with_guests and label in TICKER["last"]:
            TICKER["last"][label]["guest"] = any(
                x["name"] == label for x in rows)
    for r in rows:
        if "mktOpen" in r:
            r["open"] = r["mktOpen"]
        else:
            # no flag from the source: for the Indian names fall back to our
            # own trading calendar, and leave the rest unknown
            r["open"] = (in_market_hours() if r["name"] in INDIA_INDICES
                         else None)
        c = INDEX_BY.get(r["name"]) or ("", "", "", "", False, False)
        r["country"] = c[3]
        r["group"] = c[2]
        r["bad"] = bad.get(r["name"], False)
        r["sym"] = c[1]
        # 20.14: a reason for every index, not only the big moves
        pct = r.get("pct")
        if pct is not None and abs(pct) < QUIET_MOVE and not r.get("alert"):
            r["why"] = "No particular reason - a quiet day (%+.2f%%)." % pct
        elif pct is not None:
            # 20.16: stale figures and holidays get a reason too (NIFTY,
            # SENSEX and VIX had none on the phone after a weekend restart):
            # the move of the last session, asked once a day
            # 20.17: asked only for the indices on his strip (or with an
            # alert), and only when why_due says so - see there
            w = INDEX_WHY.get(r["name"]) or {}
            today = why_session(r["name"])[1]
            # 20.18: a reason is shown ONLY for the session the figure is
            # from - never an older session's reason under a newer move
            if w.get("why") and w.get("day") == today:
                r["why"] = w["why"]
            elif w.get("fail") and w.get("day") == today:
                r["why"] = ("Reason not found yet - Gemini was busy; it is "
                            "asked again in a few minutes.")
            if (r["name"] in pins or r.get("alert")) and \
                    why_due(r["name"], pct, bool(r.get("stale"))):
                # marked at once, so the next cycle does not start another
                INDEX_WHY[r["name"]] = dict(w, at=time.time(), pending=True)
                threading.Thread(target=index_reason, daemon=True,
                                 args=(r["name"], r.get("pct") or 0,
                                       True)).start()
    TICKER["rows"] = [_scaled(r) for r in rows]
    try:
        hist_record(TICKER["rows"])      # kept for the charts in the hover box
    except Exception:
        pass
    TICKER["error"] = "" if rows else "no index source reachable"
    TICKER["at"] = time.time()
    save_ticker_cache()


def indices_info():
    """Diagnostics -> Indices: every market, ticked or not, with its latest
    figure."""
    pins, bad, move, raw = ticker_prefs()
    out = []
    for c in INDEX_CATALOG:
        r = TICKER["last"].get(c[0]) or {}
        until = raw.get(c[0]) if isinstance(raw.get(c[0]), str) else ""
        r = _scaled(dict(r, name=c[0]))
        out.append({"label": c[0], "group": c[2], "what": c[3],
                    "on": c[0] in pins, "until": until if c[0] in pins
                    else "", "bad": bad.get(c[0], False),
                    "last": r.get("last"), "pct": r.get("pct"),
                    "whenText": r.get("whenText", "")})
    return {"rows": out, "move": move,
            "groups": [g for g, _p in INDEX_GROUPS]}


def ticker_watcher():
    while STATS["running"]:
        # every 10 seconds while the market is open, so the strip keeps pace
        # with Kite and NSE; his side-by-side screenshot showed the gap was
        # simply the age of the reading (ours 41 seconds older), not a
        # different figure - the previous close matched to the paisa
        gap = 10 if in_market_hours() else 45
        # sector index PEs for the VALUATION column, every two minutes
        if time.time() - INDEX_PE_AT["t"] > 120:
            INDEX_PE_AT["t"] = time.time()
            try:
                nse_indices()
            except Exception:
                pass
        if time.time() - TICKER["at"] > gap:
            try:
                fetch_indices()
                TICKER["lastOk"] = time.strftime("%H:%M:%S")
                TICKER["fails"] = 0
            except Exception as e:
                TICKER["fails"] = TICKER.get("fails", 0) + 1
                TICKER["error"] = str(e)[:120]
        time.sleep(5)



