TL_MAP = {}


def tl_map():
    global TL_MAP
    if not TL_MAP:
        try:
            raw = zlib.decompress(base64.b64decode(
                TL_MAP_B64.replace("\n", "")))
            TL_MAP = json.loads(raw.decode("utf-8"))
        except Exception:
            TL_MAP = {}
    return TL_MAP


def trendlyne_url(symbol):
    """The real Trendlyne page for a symbol, or "" if it is not listed."""
    key = re.sub(r"[^A-Z0-9]", "", (symbol or "").upper())
    tail = tl_map().get(key)
    return ("https://trendlyne.com/equity/" + tail + "/") if tail else ""


def screener_url(symbol):
    return ("https://www.screener.in/company/"
            + re.sub(r"[^A-Z0-9]", "", (symbol or "").upper()) + "/")


RECO = {"map": {}, "at": 0, "error": "", "fetched": ""}


def reco_file():
    return os.path.join(DATA_DIR, "recos.json")


def load_recos_disk():
    try:
        with open(reco_file()) as f:
            d = json.load(f)
        RECO["map"] = d.get("map") or {}
        RECO["fetched"] = d.get("fetched") or ""
    except Exception:
        pass


def save_recos_disk():
    try:
        with open(reco_file(), "w") as f:
            json.dump({"map": RECO["map"], "fetched": RECO["fetched"]}, f)
    except Exception:
        pass
# Each list page carries roughly 20 reports, so crawl deep enough to cover
# a watchlist of 125. Runs once a day in the background.
RECO_PAGES_BASE = (
    [("trendlyne", "https://trendlyne.com/research-reports/")]
    + [("trendlyne", "https://trendlyne.com/research-reports/?page=%d" % p)
       for p in range(2, 150)]
    + [("trendlyne", "https://trendlyne.com/research-reports/buy/")]
    + [("trendlyne", "https://trendlyne.com/research-reports/buy/?page=%d" % p)
       for p in range(2, 40)]
    + [("trendlyne", "https://trendlyne.com/research-reports/sell/"),
       ("trendlyne", "https://trendlyne.com/research-reports/sell/?page=2")]
)
RECO_PAGES = RECO_PAGES_BASE


def _clean(t):
    t = re.sub(r"<[^>]+>", " ", t or "")
    t = t.replace("&amp;", "&").replace("&#039;", "'").replace("&nbsp;", " ")
    return re.sub(r"\s+", " ", t).strip()


def load_recos_cache():
    try:
        with open(os.path.join(DATA_DIR, "recos.json")) as f:
            d = json.load(f)
        RECO["map"] = d.get("map") or {}
        RECO["savedAt"] = d.get("savedAt") or ""
    except Exception:
        pass


def save_recos_cache():
    try:
        with open(os.path.join(DATA_DIR, "recos.json"), "w") as f:
            json.dump({"map": RECO["map"],
                       "savedAt": time.strftime("%d-%b-%Y %H:%M")}, f)
    except Exception:
        pass


RECO_PAGES_PER_RUN = 30


def reco_pages():
    """Recent report pages only. Calls already on file are kept until their
    horizon ends, so there is nothing to gain from the deep archive."""
    pages = []
    for kind in ("", "buy/", "sell/", "hold/"):
        pages.append(("trendlyne",
                      "https://trendlyne.com/research-reports/" + kind))
        for n in range(2, 9):
            pages.append(("trendlyne",
                          "https://trendlyne.com/research-reports/%s?page=%d"
                          % (kind, n)))
    return pages


TL_CALLS = ("BUY", "SELL", "HOLD", "ACCUMULATE", "REDUCE", "ADD", "NEUTRAL",
            "OUTPERFORM", "UNDERPERFORM", "OVERWEIGHT", "UNDERWEIGHT")


def trendlyne_rows(html):
    """Each <tr class='Ltop'> is one report. Read the Type / Target / LTP
    cells directly, which the JSON-LD sometimes omits."""
    out = {}
    for block in re.split(r"""<tr class=['"]Ltop['"]>""", html)[1:]:
        m = re.search(r"/equity/(\d+)/([A-Z0-9&\-]+)/([a-z0-9\-]+)/", block)
        if not m:
            continue
        sym = re.sub(r"[^A-Z0-9]", "", m.group(2).upper())
        cells = [_clean(c) for c in re.findall(r"<td[^>]*>(.*?)</td>",
                                               block, re.S)]
        call = ""
        for c in cells:
            up = c.strip().upper()
            if up in TL_CALLS:
                call = up
                break
        if not call:
            for c in cells:
                for w in TL_CALLS:
                    if re.fullmatch(w + r"\b.*", c.strip().upper()):
                        call = w
                        break
                if call:
                    break
        nums = [c for c in cells if re.fullmatch(r"[0-9][0-9,]*\.?[0-9]*", c)]
        date = ""
        dm = re.search(r"(\d{1,2} [A-Za-z]{3} \d{4})", block)
        if dm:
            date = dm.group(1)
        author = ""
        am = re.search(r"research-reports/author/[^>]*>([^<]{3,40})<", block)
        if am:
            author = _clean(am.group(1))
        out[sym] = {"call": call, "nums": nums, "on": date, "house": author,
                    "url": "https://trendlyne.com" + m.group(0)}
    return out


def parse_trendlyne(html):
    """Trendlyne embeds every research report as JSON-LD. Far more reliable
    than reading the table, which is drawn by JavaScript."""
    out = {}
    table = trendlyne_rows(html)          # richer: call, target, author, date
    blocks = re.findall(
        r'<script[^>]*type\s*=\s*"application/ld\+json"[^>]*>(.*?)</script>',
        html, re.S)
    for b in blocks:
        try:
            d = json.loads(b.strip())
        except Exception:
            continue
        if not isinstance(d, dict) or d.get("@type") != "Review":
            continue
        item = d.get("itemReviewed") or {}
        same = item.get("sameAs") or ""
        m = re.search(r"/equity/(\d+)/([A-Z0-9&\-]+)/", same)
        if not m:
            continue
        sym = m.group(2)
        desc = d.get("description") or ""
        call = ""
        for word in ("Accumulate", "Reduce", "Buy", "Sell", "Hold", "Add"):
            if re.search(r"\b" + word + r"\b", desc, re.I):
                call = word.upper()
                break
        # 20.14: the number must follow "target ... to/of/at" (with or
        # without Rs/₹); a bare "to 1.3" could be a percentage (HCLTECH
        # showed a target of ₹1.3 at ₹1,393)
        tgt = re.search(r"(?i)target(?:\s+price)?[^0-9%]{0,25}?(?:to|of|at)"
                        r"\s*(?:rs\.?|₹|inr)?\s*([0-9][0-9,]*(?:\.[0-9]+)?)"
                        r"(?![0-9.,]*\s*%)(?![0-9])",
                        desc)
        move = ""
        if re.search(r"\bincreased\b", desc, re.I):
            move = "target raised"
        elif re.search(r"\bdecreased\b", desc, re.I):
            move = "target cut"
        elif re.search(r"\bmaintain", desc, re.I):
            move = "maintained"
        author = ((d.get("author") or {}).get("name") or "").strip()
        when = (d.get("datePublished") or "").split(",")[0].strip()
        key = re.sub(r"[^A-Z0-9]", "", sym.upper())
        if len(key) < 3:
            continue
        extra = table.get(key) or {}
        if not call:
            call = extra.get("call") or ""
        if not tgt and extra.get("nums"):
            # the Target column sits just after LTP in the row
            nums = extra["nums"]
            tgt = type("m", (), {"group": lambda self, i, v=nums[1] if len(nums) > 1 else nums[0]: v})()
        out[key] = {
            "name": item.get("name") or sym,
            "call": call,
            "target": tgt.group(1) if tgt else "",
            "reco": "",
            "house": author or extra.get("house", ""),
            "on": when or extra.get("on", ""),
            "note": move,
            "url": same,
            "horizon": reco_horizon(desc),
            "hv": RECO_HORIZON_V,
            "report": d.get("url") or "",
            "src": "Trendlyne",
        }
    for sym, ex in table.items():
        if sym in out or not ex.get("call"):
            continue
        out[sym] = {"name": sym, "call": ex["call"],
                    "target": (ex["nums"][1] if len(ex.get("nums") or []) > 1
                               else ""),
                    "reco": "", "house": ex.get("house", ""),
                    "on": ex.get("on", ""), "note": "",
                    "url": ex.get("url", ""), "report": "",
                    "src": "Trendlyne"}
    return out


def parse_moneycontrol(html):
    out = {}
    chunks = re.split(r'(?i)<li[^>]*class="[^"]*(?:clearfix|idea)', html)
    for ch in chunks[1:]:
        text = _clean(ch)
        m_call = re.search(r"\b(BUY|HOLD|SELL|ACCUMULATE|REDUCE|ADD)\b",
                           text, re.I)
        if not m_call:
            continue
        m_name = (re.search(r'title="([^"]{3,60})"', ch)
                  or re.search(r">([A-Za-z][A-Za-z&.\- ]{2,50})<", ch))
        if not m_name:
            continue
        name = _clean(m_name.group(1))
        tgt = re.search(r"Target[^0-9]{0,20}([0-9][0-9,\.]*)", text, re.I)
        reco_px = re.search(r"Reco Price[^0-9]{0,20}([0-9][0-9,\.]*)", text, re.I)
        house = re.search(r"Research by\s+([A-Za-z&.,\- ]{3,45})", text, re.I)
        when = re.search(r"Reco on\s*:?\s*([A-Za-z]+ \d{1,2},? \d{4})", text)
        key = re.sub(r"[^A-Z]", "", name.upper())
        if len(key) < 3:
            continue
        out[key] = {"name": name, "call": m_call.group(1).upper(),
                    "target": tgt.group(1) if tgt else "",
                    "reco": reco_px.group(1) if reco_px else "",
                    "house": _clean(house.group(1)) if house else "",
                    "on": when.group(1) if when else "",
                    "src": "Moneycontrol"}
    return out


# A call stays on screen until the date its own report gives ("12-month
# target", "3 months") and, where the report gives none, for 21 days - his
# choice in October 2026, replacing the old flat two weeks, which removed
# calls that were still running.
RECO_DEFAULT_DAYS = 21
RECO_MAX_AGE_DAYS = RECO_DEFAULT_DAYS        # kept for older callers


RECO_HORIZON_V = 2


def reco_horizon(text):
    """Most brokers do not publish a time horizon. Where the report states
    one, show it; otherwise the popup says 'not stated' rather than inventing
    the usual 12 months.

    Only a period tied to the call itself counts ("12-month target", "target
    ... over the next 9 months", "investment horizon of 2 years", "short-term
    pick"). The old test took ANY period in the text, so Kotak's "RBI approves
    Mr. Anup Saha as MD&CEO for 3 years" became a three-year call, and "long-
    term visibility" a one-year one - checked against Trendlyne's 72 reports
    on 9 Oct 2026, every match the old test made was of that kind."""
    t = html_lib.unescape(text or "")
    unit = r"(months?|years?|weeks?)"
    pats = [
        r"\b(\d{1,2})\s*[- ]?\s*" + unit + r"\s*(?:target|horizon|time ?frame"
        r"|price target|tp)\b",
        r"\b(?:horizon|time ?frame|holding period)\s+of\s+(\d{1,2})\s*[- ]?\s*"
        + unit,
        r"\btarget(?: price)?\b[^.]{0,60}?\b(?:in|over|within)\s+(?:the\s+)?"
        r"(?:next\s+)?(\d{1,2})\s*[- ]?\s*" + unit,
    ]
    for rx in pats:
        m = re.search(rx, t, re.I)
        if m:
            n, u = int(m.group(1)), m.group(2).lower().rstrip("s")
            if u == "year" and n > 1:
                n, u = 12, "month"       # never longer than a year on screen
            return "%d %s%s" % (n, u, "" if n == 1 else "s")
    if re.search(r"\bshort[- ]term\s+(?:call|trade|target|pick|view|horizon"
                 r"|buy|sell)\b", t, re.I):
        return "short term"
    if re.search(r"\blong[- ]term\s+(?:call|target|pick|investment|horizon"
                 r"|buy|view)\b", t, re.I):
        return "long term"
    return ""


def reco_date(text):
    """Trendlyne dates come as '12 Aug 2026' or 'Aug. 12'. Return a date."""
    t = (text or "").strip().replace(".", "")
    if not t:
        return None
    today = datetime.date.today()
    m = re.match(r"^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\s+(\d{4})$", t)
    if m:
        try:
            return datetime.date(int(m.group(3)),
                                 _MON[m.group(2)[:3].upper()], int(m.group(1)))
        except Exception:
            return None
    m = re.match(r"^([A-Za-z]{3})[a-z]*\s+(\d{1,2})$", t)
    if m:
        try:
            mo = _MON[m.group(1)[:3].upper()]
            d = datetime.date(today.year, mo, int(m.group(2)))
            if d > today + datetime.timedelta(days=2):
                d = datetime.date(today.year - 1, mo, int(m.group(2)))
            return d
        except Exception:
            return None
    return None


def reco_until(r):
    """(last day the call is shown, why). The report's own horizon when it
    states one; otherwise RECO_DEFAULT_DAYS after it was published."""
    r = r or {}
    d = reco_date(r.get("on"))
    if not d:
        return None, ""
    # a horizon read by the old, loose test (no "hv") is not trusted
    h = (str(r.get("horizon") or "").lower()
         if r.get("hv") == RECO_HORIZON_V else "")
    m = re.match(r"(\d{1,2})\s*(week|month|year)", h)
    if m:
        n = int(m.group(1))
        days = {"week": 7 * n, "month": round(30.44 * n),
                "year": 365 * n}[m.group(2)]
        why = "the report's own horizon (%s)" % h
    elif "short term" in h:
        days, why = 60, "a short-term call (two months)"
    elif "long term" in h:
        days, why = 365, "a long-term call (one year)"
    else:
        days = RECO_DEFAULT_DAYS
        why = "no horizon in the report - shown for %d days" % days
    return d + datetime.timedelta(days=days), why


def reco_is_recent(r):
    """A call must be dated, still inside its horizon, and actually
    attributable to someone. Anything without a research house is a
    market-wide summary, not a call."""
    r = r or {}
    if not str(r.get("house") or "").strip():
        return False
    d = reco_date(r.get("on"))
    if not d:
        return False
    until, _why = reco_until(r)
    return d <= datetime.date.today() <= until


def prune_recos():
    """A call is shown until its horizon ends (21 days when the report
    gives none). An old BUY that was never formally withdrawn is worse than
    no call at all."""
    keep = {k: v for k, v in RECO["map"].items() if reco_is_recent(v)}
    dropped = len(RECO["map"]) - len(keep)
    RECO["map"] = keep
    return dropped


def fetch_recos():
    """Broker calls (BUY / HOLD / SELL) with target and research house."""
    found = {}
    pages_read = 0
    for site, url in reco_pages():
        pages_read += 1
        try:
            raw = urllib.request.urlopen(
                urllib.request.Request(url, headers={
                    "User-Agent": UA, "Accept-Language": "en-US,en;q=0.9",
                    "Accept": "text/html,application/xhtml+xml"}),
                timeout=25).read()
            if raw[:2] == b"\x1f\x8b":
                raw = gzip.GzipFile(fileobj=io.BytesIO(raw)).read()
            html = raw.decode("utf-8", "replace")
        except Exception as e:
            RECO["error"] = str(e)
            continue

        got = parse_trendlyne(html) if site == "trendlyne" \
            else parse_moneycontrol(html)
        for k, v in got.items():
            found.setdefault(k, v)      # keep the NEWEST report for a stock
        RECO["progress"] = "%d pages, %d stocks" % (len(found), len(found))
        time.sleep(0.4)
        want = {re.sub(r"[^A-Z0-9]", "", x.upper())
                for x in (load_state().get("watchlist") or [])}
        if want and want.issubset(set(found) | set(RECO["map"])):
            break
        # v16.1: this used to `break` as soon as ONE page returned anything,
        # so only page 1 of Trendlyne was ever read - about twenty reports
        # market-wide, of which perhaps one was in the watchlist. Under a
        # two-week window there is no point crawling the deep archive either,
        # so read a sensible number of recent pages and stop.
        if pages_read >= RECO_PAGES_PER_RUN:
            break
    if found:
        # keep older calls too, and never let an older Trendlyne report
        # replace a newer call taken from the news
        for k, v in found.items():
            od = reco_date((RECO["map"].get(k) or {}).get("on"))
            nd = reco_date(v.get("on"))
            if not (od and nd and od > nd):
                RECO["map"][k] = v
        RECO["error"] = ""
        RECO["fetched"] = time.strftime("%d-%b %H:%M")
    prune_recos()
    save_recos_disk()
    RECO["at"] = time.time()


def reco_for(symbol):
    """The call filed under this exact symbol. (Until 20.7 a call could also
    be borrowed from any company whose ticker began with the same five
    letters - BAJAJFINSV could have shown BAJAJ-AUTO's call. Never again.)"""
    m = RECO["map"]
    for key in (re.sub(r"[^A-Z0-9]", "", symbol.upper()),
                re.sub(r"[^A-Z]", "", symbol.upper())):
        if key in m:
            return reco_sane(symbol, m[key])
    return None


def reco_sane(symbol, r):
    """20.15: every target the source gives is shown, however far from
    today's price (a call can be for a year ahead). Only a figure that cannot
    be a price for this share at all - under a tenth or over ten times
    today's price, which is a percentage or a page number read as a price
    (HCLTECH: "target 1.3" from "cut target by 1.3%" at Rs 1,393) - is
    replaced by a note pointing to the report, never silently dropped."""
    if not isinstance(r, dict):
        return r
    with CACHE_LOCK:
        q = CACHE.get(re.sub(r"[^A-Z0-9&-]", "", symbol.upper())) or {}
    ltp = to_number(q.get("ltpNum") or q.get("ltp"))
    if not ltp:
        return r
    out = dict(r)
    for k in ("target", "reco"):
        v = to_number(out.get(k))
        if v and not (0.1 * ltp <= v <= 10 * ltp):
            out[k] = ""
            out["dropped"] = ("%s gave a figure (%s) that cannot be a price "
                              "for this share beside today's ₹%s - it is "
                              "probably a percentage; open the report for "
                              "the target" % (out.get("src") or "the source",
                                              r.get(k),
                                              "{:,.2f}".format(ltp)))
    return out


MC_IDS = {}          # symbol -> Moneycontrol scrip id, learned as we go


def mc_search_id(symbol):
    if symbol in MC_IDS:
        return MC_IDS[symbol]
    try:
        url = ("https://www.moneycontrol.com/mccode/common/autosuggestion_solr.php"
               "?classic=true&query=" + urllib.parse.quote(symbol)
               + "&type=1&format=json")
        raw = urllib.request.urlopen(
            urllib.request.Request(url, headers={
                "User-Agent": UA,
                "Referer": "https://www.moneycontrol.com/"}), timeout=8).read()
        d = json.loads(raw.decode("utf-8", "replace"))
        rows = d if isinstance(d, list) else (d.get("data") or [])
        for r in rows:
            sc = r.get("sc_id") or r.get("scid") or r.get("id")
            if sc:
                MC_IDS[symbol] = sc
                return sc
    except Exception:
        pass
    MC_IDS[symbol] = None
    return None


def mc_reco(symbol):
    """Moneycontrol's per-stock broker consensus."""
    sc = mc_search_id(symbol)
    if not sc:
        return None
    for url in (
        "https://api.moneycontrol.com/mcapi/v1/stock/estimates/analyst-rating"
        "?scId=" + urllib.parse.quote(str(sc)) + "&ex=N&deviceType=W",
        "https://api.moneycontrol.com/mcapi/v1/stock/estimates/price-forecast"
        "?scId=" + urllib.parse.quote(str(sc)) + "&ex=N&deviceType=W",
    ):
        try:
            raw = urllib.request.urlopen(
                urllib.request.Request(url, headers={
                    "User-Agent": UA,
                    "Referer": "https://www.moneycontrol.com/"}),
                timeout=8).read()
            d = json.loads(raw.decode("utf-8", "replace"))
            data = d.get("data") or {}
            blob = json.dumps(data).upper()
            call = ""
            for w in ("STRONG BUY", "BUY", "OUTPERFORM", "HOLD", "NEUTRAL",
                      "UNDERPERFORM", "SELL"):
                if '"' + w + '"' in blob or "'" + w + "'" in blob:
                    call = "BUY" if "BUY" in w or "OUTPERFORM" in w else (
                        "SELL" if "SELL" in w or "UNDERPERFORM" in w else "HOLD")
                    break
            tgt = ""
            for k in ("targetPrice", "target", "avgTarget", "priceTarget"):
                v = data.get(k) if isinstance(data, dict) else None
                if v:
                    tgt = str(v)
                    break
            if call:
                return {"name": symbol, "call": call, "target": tgt,
                        "reco": "", "house": "Moneycontrol consensus",
                        "on": datetime.date.today().strftime("%d %b %Y"),
                        "note": "", "url": "", "report": "",
                        "src": "Moneycontrol"}
        except Exception:
            continue
    return None


def fill_missing_recos(limit=25):
    """Retired in v16. Moneycontrol's consensus carried no target, no research
    house and no working link, which is exactly the low-quality filler the
    two-week rule is meant to keep out. Kept as a no-op so nothing breaks."""
    return 0


def _fill_missing_recos_retired(limit=25):
    """Anything Trendlyne has not covered, ask other sources - a few each
    cycle so we never hammer one site."""
    st = load_state()
    done = 0
    for sym in (st.get("watchlist") or []):
        key = re.sub(r"[^A-Z0-9]", "", sym.upper())
        if key in RECO["map"]:
            continue
        r = mc_reco(sym)
        if r:
            r["seen"] = datetime.date.today().isoformat()
            RECO["map"][key] = r
            done += 1
        time.sleep(0.8)
        if done >= limit:
            break
    if done:
        save_recos_cache()
    return done


# ---------------------------------------------------------------------------
# CALLS FROM THE NEWS (20.7)
#
# Trendlyne carries the reports of Indian brokers (Motilal Oswal, ICICI
# Securities ...). Foreign houses - Nomura, Citi, Goldman Sachs, Jefferies,
# Morgan Stanley, HSBC - do not publish there: their calls reach him only
# as headlines ("Paytm share price target Rs 2,250: Nomura initiates
# coverage at Buy"), which is how the Paytm call of 15 Oct was missed. So
# every hour the headlines that announce a call are read too: the news the
# dashboard already has (Moneycontrol's "Buy X; target of Rs Y: Broker"),
# plus a few searches.
# ---------------------------------------------------------------------------

NEWS_CALL_QUERIES = [
    '"target of Rs" buy',
    '"share price target" brokerage',
    '"initiates coverage" "target price"',
    '"maintains buy" OR "retains buy" "target"',
    '"upgrades" "target price" shares India',
    '"downgrades" "target price" shares India',
    '"sell rating" "target price" India shares',
    'brokerage calls today target',
]
NEWS_CALLS = {"seen": {}, "at": 0, "found": 0, "error": ""}
CALL_STYLE = (
    "Each numbered headline may report a broker's or research house's call "
    "on ONE Indian listed company. For each headline write one line: "
    "'<n>|<company as named>|<BUY or SELL or HOLD>|<target price, digits "
    "only, or ->|<broker or research house>' when the headline itself names "
    "the company, the rating or a target, and who gave it. Accumulate, Add, "
    "Outperform and Overweight are BUY; Reduce, Underperform and Underweight "
    "are SELL; Neutral, Equal-weight and Hold are HOLD. Write '<n>|NO' for "
    "anything else (several companies at once, market views, results, an "
    "analyst's chart levels without a house).\n\n")
_CALL_RX = [
    # Moneycontrol: "Buy Indian Bank; target of Rs 1000: Prabhudas Lilladher"
    re.compile(r"^(Buy|Sell|Hold|Accumulate|Add|Reduce|Neutral)\s+(.+?)\s*[;:,]"
               r"\s*target of Rs\.?\s*([\d,]+(?:\.\d+)?)\s*:\s*(.+?)\s*$", re.I),
    # "Paytm share price target Rs 2,250: Nomura initiates coverage at Buy"
    re.compile(r"^(.+?) share price target (?:Rs\.?|\u20b9)\s*([\d,]+(?:\.\d+)?)"
               r"\s*:\s*(.+?)\s+(?:initiates coverage at|initiates with|"
               r"maintains|retains|reiterates|stays|keeps|upgrades to|"
               r"downgrades to|at)\s+(Buy|Sell|Hold|Neutral|Overweight|"
               r"Underweight|Outperform|Underperform|Equal[- ]weight|Add|"
               r"Reduce|Accumulate)\b", re.I),
]
_CALL_WORD = {"BUY": "BUY", "ACCUMULATE": "BUY", "ADD": "BUY",
              "OUTPERFORM": "BUY", "OVERWEIGHT": "BUY", "SELL": "SELL",
              "REDUCE": "SELL", "UNDERPERFORM": "SELL", "UNDERWEIGHT": "SELL",
              "HOLD": "HOLD", "NEUTRAL": "HOLD", "EQUALWEIGHT": "HOLD",
              "EQUAL-WEIGHT": "HOLD", "EQUAL WEIGHT": "HOLD"}
_CO_STOP = {"ltd", "limited", "the", "of", "and", "co", "company", "corp",
            "corporation", "india", "industries", "shares", "share", "stock",
            "&"}


def _co_norm(t):
    return " ".join(w for w in re.split(r"[^a-z0-9&]+", (t or "").lower())
                    if w and w not in _CO_STOP)


_CO_DROP = {"ltd", "limited", "the", "co", "company", "corp",
            "corporation", "&", "and", "shares", "share", "stock", "inc"}
_CO_TAIL = {"industries", "enterprises", "india", "ltd", "limited"}


def _co_full(t):
    return " ".join(w for w in re.split(r"[^a-z0-9&]+", (t or "").lower())
                    if w and w not in _CO_DROP)


def call_symbol(company, symbols):
    """The watchlist symbol a company named in a headline stands for, or
    None. Only a sure match: the ticker, a well-known alias or brand, the
    company's full name, or its first word when everything after it is
    "Industries", "India", "Enterprises" ("Reliance" for Reliance
    Industries). A short name never swallows a longer one - Reliance Power
    is not RELIANCE, Bank of Baroda is not BANKINDIA, ITC Hotels is not
    ITC."""
    c = _co_full(company)
    if not c:
        return None
    flat = re.sub(r"[^A-Z0-9&]", "", company.upper())
    alias = NAME_ALIASES.get(re.sub(r"[^A-Z0-9]", "", company.upper()))
    for s in symbols:
        if s.upper() in (flat, alias or ""):
            return s
        if any(c == _co_full(b) for b in BRAND_TERMS.get(s, [])):
            return s
    exact, loose = [], []
    for s in symbols:
        _t, name = share_terms(s)
        n = _co_full(name)
        if not n:
            continue
        if n == c:
            exact.append(s)
            continue
        nw = n.split()
        if " " not in c and len(c) >= 5 and nw[0] == c and \
                all(w in _CO_TAIL for w in nw[1:]):
            loose.append(s)
    if len(exact) == 1:
        return exact[0]
    if not exact and len(loose) == 1:
        return loose[0]
    return None


def _call_parse(items):
    """[(item, company, call, target, house)] from headlines."""
    out, ask = [], []
    for it in items:
        t = re.sub(r"\s+-\s+[^-]{2,40}$", "", it["title"]).strip()
        # the whole title: "target of Rs 180" and a later "Rs 200" are two
        # different calls (title_key drops numbers and short words)
        k = re.sub(r"[^a-z0-9]+", " ", t.lower()).strip()
        if k in NEWS_CALLS["seen"]:
            r = NEWS_CALLS["seen"][k]
            if r:
                out.append((it,) + tuple(r))
            continue
        m = _CALL_RX[0].match(t)
        if m:
            r = [m.group(2), m.group(1), m.group(3), m.group(4)]
        else:
            m = _CALL_RX[1].match(t)
            r = [m.group(1), m.group(4), m.group(2), m.group(3)] if m else None
        if r:
            r[1] = _CALL_WORD.get(r[1].upper(), "")
            r[2] = r[2].replace(",", "")
            NEWS_CALLS["seen"][k] = r if r[1] else None
            if r[1]:
                out.append((it,) + tuple(r))
            continue
        if re.search(r"\b(target|buy|sell|hold|neutral|overweight|underweight|"
                     r"outperform|underperform|coverage|upgrade|downgrade)",
                     t, re.I):
            ask.append((it, t, k))
        else:
            NEWS_CALLS["seen"][k] = None
    if ask and GEMINI["key"]:
        for i in range(0, len(ask), 40):
            part = ask[i:i + 40]
            ans, _e = ask_gemini("\n".join("%d. %s" % (n + 1, x[1])
                                           for n, x in enumerate(part)),
                                 CALL_STYLE)
            if not ans:
                break                    # tried again next hour
            got = set()
            for ln in str(ans).splitlines():
                p = [x.strip(" *") for x in ln.split("|")]
                m = re.match(r"\D*(\d+)", p[0]) if p else None
                if not m:
                    continue
                n = int(m.group(1)) - 1
                if not 0 <= n < len(part):
                    continue
                w = re.sub(r"[^A-Z-]", "", p[2].upper()) if len(p) >= 5 else ""
                if len(p) >= 5 and w in _CALL_WORD:
                    r = [p[1], _CALL_WORD[w], re.sub(r"[^\d.]", "", p[3]), p[4]]
                    NEWS_CALLS["seen"][part[n][2]] = r
                    out.append((part[n][0],) + tuple(r))
                got.add(n)
            for n in got:
                NEWS_CALLS["seen"].setdefault(part[n][2], None)
    if len(NEWS_CALLS["seen"]) > 5000:
        NEWS_CALLS["seen"] = dict(list(NEWS_CALLS["seen"].items())[-3000:])
    return out


def news_calls():
    """Read the call headlines and put them in the CALL column: a newer call
    from the news replaces an older one from Trendlyne."""
    st = load_state()
    symbols = [s for s in (st.get("watchlist") or []) if s]
    items = []
    for it in (NEWS.get("items") or []) + (NEWS.get("globalAll") or []):
        # an undated headline cannot be dated - it would look new every hour
        if it.get("age") is not None and it["age"] <= 72 and it.get("title"):
            items.append({"title": it["title"], "link": it.get("link", ""),
                          "source": it.get("source", ""), "age": it.get("age")})
    for q in NEWS_CALL_QUERIES:
        try:
            url = ("https://news.google.com/rss/search?q=" + Q(q + " when:3d")
                   + "&hl=en-IN&gl=IN&ceid=IN:en")
            raw = urllib.request.urlopen(urllib.request.Request(
                url, headers={"User-Agent": UA}), timeout=12).read()
            for it in list(ET.fromstring(raw).iter("item"))[:30]:
                t = (it.findtext("title") or "").strip()
                l = (it.findtext("link") or "").strip()
                a = age_hours(it.findtext("pubDate") or "")
                if t and l and a is not None:
                    items.append({"title": t, "link": l,
                                  "source": it.findtext("source") or "News",
                                  "age": a})
        except Exception as e:
            NEWS_CALLS["error"] = str(e)[:80]
    seen_t, uniq = set(), []
    for it in items:
        k = re.sub(r"[^a-z0-9]+", " ", it["title"].lower()).strip()
        if k not in seen_t:
            seen_t.add(k)
            uniq.append(it)
    found = 0
    for it, company, call, target, house in _call_parse(uniq):
        house = (house or "").strip(" -")
        sym = call_symbol(company, symbols)
        if not sym or not call or len(house) < 2:
            continue
        a = it.get("age")
        key = re.sub(r"[^A-Z0-9]", "", sym.upper())
        old = RECO["map"].get(key) or {}
        od = reco_date(old.get("on"))
        nd = (datetime.datetime.now() - datetime.timedelta(hours=a or 0)).date()
        if od and (od > nd or (od == nd and old.get("target")
                               and not target)):
            continue                     # what is on file is newer / fuller
        RECO["map"][key] = {
            "name": company, "call": call, "target": target or "",
            "reco": "", "house": house.strip()[:60], "on":
            nd.strftime("%d %b %Y"), "note": "from the news", "url":
            it["link"], "horizon": "", "hv": RECO_HORIZON_V,
            "report": it["link"], "src": "News (" + it["source"] + ")",
            "headline": it["title"][:200]}
        found += 1
    NEWS_CALLS["at"] = time.time()
    NEWS_CALLS["found"] = found
    if found:
        save_recos_disk()
    return found


# ---------------------------------------------------------------------------
# RECOMMENDATIONS (News picks in 20.7) - the strip at the bottom
#
# Once each morning (on the first look at the dashboard after 7, or when he
# presses READ AGAIN) Gemini reads the last 24 hours of headlines about each
# share and says, only where the news is clear:
#   - for the BLANK rows of the table: BUY, or nothing;
#   - for what he holds (OLD, YESTERDAY, MISSED, and Out of list): SELL when
#     the news is bad enough that it may fall further, HOLD when it is good
#     enough that it may rise further;
#   - and up to five shares outside his list that the news makes look
#     strong.
# A rough reading of the news and nothing more: each line names the
# headline it rests on, and clicking it opens that article.
# ---------------------------------------------------------------------------

PICKS_FILE = os.path.join(DATA_DIR, "picks.json")
PICKS = {"running": False, "step": "", "error": "", "tried": 0}
PICK_STYLE = (
    "You read Indian stock-market headlines for a trader. For each share "
    "below you get the headlines about it from the last 24 hours, numbered. "
    "Judge only from those headlines how the news may move the share in "
    "the next day or two. Write one line per share: "
    "'<SYMBOL>|<CALL>|<reason in at most 8 words>|<number of the headline it "
    "rests on>|<KIND>'. KIND is RESULTS when the reason is the company's "
    "quarterly results (out, due, or what is expected of them), otherwise "
    "NEWS. Each share comes with its company name: a headline about another "
    "company of the same group (Aditya Birla AMC for Aditya Birla Capital, "
    "Tata Motors for Tata Steel) is NOT about it - treat it as no news. CALL for a share marked [BLANK] is BUY (clearly good news: "
    "strong results, big order, upgrade, approval, buyback, a broker's buy "
    "call with upside) or NONE. CALL for a share marked [HELD] is SELL "
    "(clearly bad news that may push it lower: weak results, downgrade, "
    "penalty, raid, loss of a big client, promoter selling) or HOLD (clearly "
    "good news that may push it higher) or NONE. Use NONE whenever the "
    "headlines are routine, mixed, old, about the whole market, or not "
    "really about this company. Nothing else in the answer.\n\n")
PICK_OUT_STYLE = (
    "Below are today's Indian market headlines, numbered. Name up to eight "
    "shares listed on the NSE that are NOT in this list: %s - whose own "
    "news in these headlines is clearly and strongly positive for the next "
    "day or two (results well above expectations, a large order, a broker "
    "upgrade or buy call with big upside, an approval, a buyback). Prefer "
    "large and mid-sized companies; skip penny stocks and SME listings. "
    "One line each: "
    "'<NSE SYMBOL>|<company name exactly as the headline writes it>|<reason "
    "in at most 8 words>|<headline number>'. If none stands out, write "
    "NONE. Nothing else.\n\n")


OPP_QUERIES = ["stocks to buy today when:1d",
               "buy call target price brokerage when:1d",
               "rating upgrade target price when:1d",
               "bags order worth crore when:1d",
               "results beat estimates profit jumps when:1d"]


def _corp_result(sym):
    """'Results 24 Oct - expected MODERATE' when Corporate actions has this
    share's results in the next two weeks (or the last two days)."""
    for r in (CORP_CACHE.get("rows") or []):
        if r.get("symbol") != sym or r.get("kind") != "Results":
            continue
        d = r.get("daysTo")
        if d is None or not (-2 <= d <= 14):
            continue
        pv = (previews().get(sym + "|" + str(r.get("exIso") or "")) or {})
        v = pv.get("verdict")
        return "Results %s%s" % (r.get("date") or r.get("exIso") or "",
                                 " - expected %s" % v if v and v not in
                                 ("NONE", "UNCLEAR") else "")
    return ""


def picks_read():
    return _read_json(PICKS_FILE, {})


def _pick_groups():
    """(blank symbols, held names) from his table and Out of list."""
    st = load_state()
    notes = st.get("notes") or {}
    blank, held = [], []
    for s in st.get("watchlist") or []:
        n = notes.get(s) or {}
        # 20.12: MISSED is a share he did NOT buy - it is not held
        if any(str(n.get(k) or "").strip() for k in ("old", "yesterday")):
            held.append(s)
        elif not any(str(v or "").strip() for v in n.values()):
            blank.append(s)
    for s in extra_symbols(st):           # Out of list, as the dashboard reads it
        s = str(s or "").strip().upper()
        if s and s not in held:
            held.append(s)
    return blank, held


def _pick_news(sym, pool):
    """Headlines of the last 24 hours about one share, with their links."""
    terms, name = share_terms(sym)
    if not terms and not name:
        terms = [sym]
    out, seen = [], set()

    def hit(t):
        return any(re.search(r"(?<![A-Za-z])" + re.escape(x) +
                             r"(?![A-Za-z])", t, re.I if (
                                 " " in x or x != sym or (
                                     len(sym) >= 5 and sym.isalpha()
                                     and sym not in ("ETERNAL",))) else 0)
                   for x in terms)
    for it in pool:
        t = it.get("title") or ""
        if (it.get("age") if it.get("age") is not None else 99) > 24:
            continue
        if hit(t) and title_key(t) not in seen:
            seen.add(title_key(t))
            out.append(it)
    q = " ".join(name.split()[:3]) if name else (terms[0] if terms else sym)
    for it in google_news(q, limit=10):
        a = it.get("age")
        if a is None or a > 24 or title_key(it["title"]) in seen:
            continue
        # the company's own full name, as whole words - "bank" alone or
        # "itc" inside "switch" is someone else's story
        full = _co_full(name)
        if hit(it["title"]) or (full and len(full) >= 6 and re.search(
                r"(?<![a-z0-9])" + re.escape(full) + r"(?![a-z0-9])",
                _co_full(it["title"]))):
            seen.add(title_key(it["title"]))
            out.append(it)
    return out[:6]


def _pick_outside(pool, mine):
    """Up to eight shares outside his lists that today's news makes look
    strong - each checked to be a real NSE share, with its price."""
    rows = []
    mine = set(mine)
    recent = [it for it in pool if (it.get("age") if it.get("age")
                                    is not None else 99) <= 24]
    recent = recent[:100]
    # and the searches that bring up what brokers and the news rate
    # highly today, across the whole market
    seen_t = set(title_key(it["title"]) for it in recent)
    for term in OPP_QUERIES:
        try:
            for it in google_news(term, 12):
                if (it.get("age") if it.get("age") is not None else 99) \
                        <= 24 and title_key(it["title"]) not in seen_t:
                    seen_t.add(title_key(it["title"]))
                    recent.append(it)
        except Exception:
            pass
        time.sleep(0.4)
    recent = recent[:180]
    if recent:
        ans, _e = ask_gemini("\n".join("%d. %s" % (n + 1, it["title"])
                                       for n, it in enumerate(recent)),
                             PICK_OUT_STYLE % ", ".join(sorted(mine)),
                             timeout=60)
        for ln in str(ans or "").splitlines():
            p = [x.strip() for x in ln.split("|")]
            if len(p) < 4:
                continue
            s = re.sub(r"[^A-Z0-9&-]", "", p[0].upper())
            if not s or s in mine or s == "NONE":
                continue
            try:                      # must be a real NSE share
                q = fetch_symbol(s, light=True)
                if to_number(q.get("ltp")) is None:
                    continue
            except Exception:
                continue
            n = re.sub(r"\D", "", p[3])
            it = recent[int(n) - 1] if n and 0 < int(n) <= len(recent) \
                else {}
            # the headline must really be about that company: its ticker, or
            # its name - two words when the first is a group's (Adani Energy
            # is not Adani Enterprises)
            tl = (it.get("title") or "").lower()
            words = _co_norm(p[1]).split()
            need = " ".join(words[:2] if len(words) > 1 and
                            words[0] in NAME_GENERIC else words[:1])
            if not ((len(need) >= 3 and re.search(
                    r"(?<![a-z])" + re.escape(need) + r"(?![a-z])", tl))
                    or re.search(r"(?<![A-Za-z])" + re.escape(s) +
                                 r"(?![A-Za-z])", it.get("title") or "")):
                continue
            rows.append({"sym": s, "call": "BUY", "why": p[2][:80],
                         "title": it.get("title", ""),
                         "link": it.get("link", ""),
                         "source": it.get("source", ""),
                         "group": "outside", "kind": "news",
                         "price": to_number(q.get("ltp"))})
            mine.add(s)
            if sum(1 for r in rows if r["group"] == "outside") >= 8:
                break
    PICKS["oppNote"] = "%d candidates read, %d kept" % (len(recent), len(rows))
    return rows


# "when:1d": Google sorts by relevance, so without it most results are old
FNO_QUERIES = ["futures buy target stop loss when:1d",
               "Nifty options strategy call put when:1d",
               "Bank Nifty option buy target when:1d",
               "F&O derivative trading ideas when:1d",
               "sell futures target stop loss when:1d"]
FNO_STYLE = (
    "Below are Indian market headlines from the last 24 hours, numbered. Pick "
    "out up to six that give a concrete F&O trade idea from a broker or "
    "analyst - buying or selling a stock or index FUTURE, or a call/put "
    "OPTION or an option strategy. One line each: '<UNDERLYING as on NSE, "
    "e.g. NIFTY, BANKNIFTY, RELIANCE>|<instrument, e.g. NIFTY 26000 CE, "
    "RELIANCE NOV FUT, BANKNIFTY bull call spread>|<BUY or SELL>|<target "
    "and stop-loss if given, else the reason - at most 12 words>|<headline "
    "number>'. Only ideas the headline itself states; no general market "
    "views. If none, write NONE. Nothing else.\n\n")


def _pick_fno():
    """Futures and options ideas from brokers in today's news (20.9)."""
    heads, seen = [], set()
    for term in FNO_QUERIES:
        try:
            for it in google_news(term, 12):
                if (it.get("age") if it.get("age") is not None else 99) \
                        <= 24 and title_key(it["title"]) not in seen:
                    seen.add(title_key(it["title"]))
                    heads.append(it)
        except Exception:
            pass
        time.sleep(0.4)
    heads = heads[:70]
    if not heads:
        return []
    ans, _e = ask_gemini("\n".join("%d. %s" % (n + 1, it["title"])
                                   for n, it in enumerate(heads)),
                         FNO_STYLE, timeout=60)
    rows = []
    for ln in str(ans or "").splitlines():
        p = [x.strip(" *") for x in ln.split("|")]
        if len(p) < 5 or p[2].upper() not in ("BUY", "SELL"):
            continue
        n = re.sub(r"\D", "", p[4])
        if not n or not 0 < int(n) <= len(heads):
            continue
        it = heads[int(n) - 1]
        und = re.sub(r"[^A-Z0-9&-]", "", p[0].upper())
        # the underlying must be named in the headline it came from
        t = (it.get("title") or "").upper().replace(" ", "")
        if not und or und not in t:        # "BANK NIFTY" counts as BANKNIFTY
            continue
        rows.append({"sym": p[1][:40] or und, "call": p[2].upper(),
                     "why": p[3][:90], "title": it.get("title", ""),
                     "link": it.get("link", ""), "source": it.get("source", ""),
                     "group": "fno", "kind": "fno"})
        if len(rows) >= 6:
            break
    return rows


MARKET_QUERIES = {
    "crypto": ["bitcoin price outlook", "crypto market rally analysts"],
    "gold": ["gold price outlook India MCX", "silver price outlook"],
    "foreign": ["US stocks to buy analysts", "Wall Street stocks upgrade"],
    "commodity": ["crude oil price outlook", "MCX commodity outlook"],
    "bond": ["India bond yields outlook RBI", "best corporate bonds NCD issue"],
    "fund": ["mutual fund to invest analysts India", "ETF inflows India"],
    "currency": ["rupee outlook dollar forex"]}
MARKET_NAMES = {"crypto": "crypto", "gold": "gold / silver",
                "foreign": "foreign share", "commodity": "commodity",
                "bond": "bond", "fund": "fund / ETF",
                "currency": "currency"}


def _pick_markets():
    """20.16: for someone who invests in more than Indian shares (Profile ->
    What you invest in), up to five ideas from today's news in those
    markets - each named in the headline it came from."""
    st = load_state()
    kinds = ((st.get("prefs") or {}).get("invest") or {}).get("types") or []
    want = [k for k in MARKET_QUERIES if k in kinds]
    if not want:
        return []
    heads, seen = [], set()
    for k in want:
        for term in MARKET_QUERIES[k]:
            try:
                for it in google_news(term, 8):
                    if (it.get("age") if it.get("age") is not None else 99) \
                            <= 36 and title_key(it["title"]) not in seen:
                        seen.add(title_key(it["title"]))
                        heads.append(dict(it, _k=k))
            except Exception:
                pass
            time.sleep(0.4)
    heads = heads[:60]
    if not heads:
        return []
    ans, _e = ask_gemini(
        "Headlines:\n" + "\n".join("%d. %s" % (n + 1, it["title"])
                                    for n, it in enumerate(heads)),
        "You pick investment ideas from news headlines for an Indian investor "
        "in these markets only: %s. Answer ONLY lines in the form NAME | "
        "BUY | reason in under 12 words | headline number - the NAME exactly "
        "as the headline writes it (Bitcoin, Gold, Apple, Brent...). Only "
        "where the headline itself is clearly positive (analysts raise "
        "targets, a breakout, strong inflows); at most five lines; NONE if "
        "nothing is clear. Never invent." % ", ".join(
            MARKET_NAMES[k] for k in want), timeout=60)
    rows = []
    for ln in str(ans or "").splitlines():
        p = [x.strip(" *") for x in ln.split("|")]
        if len(p) < 4 or p[1].upper() != "BUY":
            continue
        n = re.sub(r"\D", "", p[3])
        if not n or not 0 < int(n) <= len(heads):
            continue
        it = heads[int(n) - 1]
        name = p[0][:30]
        if len(name) < 2 or name.lower() not in (it.get("title") or "").lower():
            continue                          # named in its own headline
        rows.append({"sym": name, "call": "BUY", "why": p[2][:90],
                     "title": it.get("title", ""), "link": it.get("link", ""),
                     "source": it.get("source", ""), "group": "outside",
                     "kind": "market", "market": MARKET_NAMES[it["_k"]]})
        if len(rows) >= 5:
            break
    return rows


def picks_run(force=False):
    """Read the news and write the picks. Runs once at a time."""
    if PICKS["running"]:
        return
    today = datetime.date.today().isoformat()
    old = picks_read()
    if not force and old.get("day") == today:
        return
    if not force and time.time() - PICKS["tried"] < 1800:
        return                            # a failed try waits half an hour
    PICKS["tried"] = time.time()
    if not GEMINI["key"]:
        PICKS["error"] = "This needs Gemini (Ask panel -> key)."
        return
    PICKS["running"] = True
    PICKS["error"] = ""
    try:
        blank, held = _pick_groups()
        pool = [it for it in (NEWS.get("items") or []) +
                (NEWS.get("globalAll") or []) if it.get("title")]
        news = {}
        allsyms = held + blank
        for i, s in enumerate(allsyms):
            PICKS["step"] = "reading the news of %d of %d shares" % (
                i + 1, len(allsyms))
            items = _pick_news(s, pool)
            if items:
                news[s] = items
            time.sleep(0.25)
        rows = []
        syms = [s for s in allsyms if s in news]
        heads = []                         # every numbered headline
        answered = 0
        for i in range(0, len(syms), 20):
            part = syms[i:i + 20]
            PICKS["step"] = "Gemini is reading (%d of %d)" % (
                min(i + 20, len(syms)), len(syms))
            q = []
            for s in part:
                tag = "[HELD]" if s in held else "[BLANK]"
                nm = short_company(s)
                if nm and nm.upper() != s:
                    tag = "(%s) %s" % (nm, tag)
                lines = []
                for it in news[s]:
                    heads.append(it)
                    lines.append("  %d. %s" % (len(heads), it["title"]))
                q.append("%s %s\n%s" % (s, tag, "\n".join(lines)))
            ans, err = ask_gemini("\n\n".join(q), PICK_STYLE, timeout=60)
            if not ans:
                PICKS["error"] = "Gemini did not answer: %s" % str(err)[:100]
                if "quota" in str(err).lower():
                    break                 # the rest would fail the same way
                continue
            answered += 1
            for ln in str(ans).splitlines():
                p = [x.strip() for x in ln.strip().split("|")]
                if len(p) < 3 or p[0].upper() not in part:
                    continue
                s, call = p[0].upper(), p[1].upper()
                ok = (call == "BUY" and s in blank) or \
                    (call in ("SELL", "HOLD") and s in held)
                if not ok:
                    continue
                n = re.sub(r"\D", "", p[3]) if len(p) > 3 else ""
                it = heads[int(n) - 1] if n and 0 < int(n) <= len(heads) \
                    else news[s][0]
                if it not in news[s]:     # a number from another share
                    it = news[s][0]
                kind = "results" if (len(p) > 4 and "RESULT" in p[4].upper()) \
                    or _corp_result(s) else "news"
                rows.append({"sym": s, "call": call, "why": p[2][:80],
                             "title": it.get("title", ""),
                             "link": it.get("link", ""),
                             "source": it.get("source", ""),
                             "group": "held" if s in held else "blank",
                             "kind": kind, "corp": _corp_result(s)})
        # shares outside his lists
        PICKS["step"] = "looking beyond your list"
        st = load_state()
        mine = set(str(s).upper() for s in allsyms)
        mine |= set(str(s).upper() for s in (st.get("watchlist") or []))
        if syms and not answered:
            # nothing came back - keep yesterday's stamp so it tries again
            return
        rows += _pick_outside(pool, mine)
        PICKS["step"] = "reading futures and options ideas"
        try:
            rows += _pick_fno()
        except Exception as e:
            PICKS["error"] = "F&O ideas: %s" % str(e)[:80]
        PICKS["step"] = "reading the other markets you invest in"
        try:
            rows += _pick_markets()
        except Exception as e:
            PICKS["error"] = "Other markets: %s" % str(e)[:80]
        order = {"SELL": 0, "HOLD": 1, "BUY": 2}
        rows.sort(key=lambda r: (r["group"] == "outside", order.get(
            r["call"], 3), r["sym"]))
        _write_json(PICKS_FILE, {"day": today, "at": time.strftime("%H:%M"),
                                 "rows": rows, "read": len(syms),
                                 "blank": len(blank), "held": len(held)})
        try:
            picks_archive(picks_read())
        except Exception:
            pass
        PICKS["step"] = ""
    except Exception as e:
        PICKS["error"] = str(e)[:120]
    finally:
        PICKS["running"] = False
        PICKS["step"] = ""


# ---------------------------------------------------------------------------
# HOW THE RECOMMENDATIONS TURNED OUT (20.12) - every day's picks are kept
# (picks_history.json, a year), with the price when they were made: the
# close before, for picks made before the market opened, otherwise the live
# price. The Past tab compares that with the price since; the report counts
# how often each kind of call was right.
#   BUY is counted right when the price has risen since, SELL when it has
#   fallen, HOLD when it has not fallen more than 2%.
# ---------------------------------------------------------------------------
PICKHIST_FILE = os.path.join(DATA_DIR, "picks_history.json")
PICK_BARS = {}


def picks_archive(d):
    day = d.get("day")
    if not day or not d.get("rows"):
        return
    h = _read_json(PICKHIST_FILE, {})
    if not isinstance(h, dict):
        h = {}
    old = {(r.get("sym"), r.get("call")): r for r in
           (h.get(day) or {}).get("rows") or []}
    before = time.strftime("%H:%M") < "09:15" and day == \
        datetime.date.today().isoformat()
    rows = []
    for r in d.get("rows") or []:
        sym = str(r.get("sym") or "").upper()
        keep = old.get((sym, r.get("call")))
        if keep and keep.get("px"):
            px = keep["px"]               # the first price stays
        else:
            with CACHE_LOCK:
                q = dict(CACHE.get(sym) or {})
            px = (to_number(q.get("prevclose")) if before else None) or \
                q.get("ltpNum") or to_number(r.get("price")) or None
        rows.append({"sym": sym, "call": r.get("call"),
                     "why": str(r.get("why") or "")[:100],
                     "group": r.get("group"), "kind": r.get("kind"),
                     "title": str(r.get("title") or "")[:200],
                     "link": r.get("link") or "", "source": r.get("source")
                     or "", "px": px})
    h[day] = {"at": d.get("at", ""), "rows": rows}
    cut = (datetime.date.today() - datetime.timedelta(days=400)).isoformat()
    h = {k: v for k, v in h.items() if k >= cut}
    _write_json(PICKHIST_FILE, h)


def _pick_closes(sym):
    hit = PICK_BARS.get(sym)
    if hit and time.time() - hit[0] < 3600:
        return hit[1]
    try:
        bars, _m, _e = yahoo_ohlc(sym + ".NS", "2y", "1d")
        out = [(datetime.datetime.fromtimestamp(b[0] + IST_SHIFT,
                                                datetime.timezone.utc)
                .date().isoformat(), b[4]) for b in bars]
    except Exception:
        out = []
    PICK_BARS[sym] = (time.time() if out else time.time() - 3300, out)
    return out


def picks_history(days=7):
    days = max(1, min(400, int(days or 7)))
    h = _read_json(PICKHIST_FILE, {})
    if not isinstance(h, dict):
        h = {}
    today = datetime.date.today()
    cut = (today - datetime.timedelta(days=days)).isoformat()
    picked = sorted([k for k in h if cut <= k < today.isoformat()],
                    reverse=True)
    syms = sorted({r["sym"] for k in picked for r in h[k].get("rows") or []
                   if re.fullmatch(r"[A-Z0-9&-]{1,20}", r.get("sym") or "")})
    closes = {}

    def one(sym):
        closes[sym] = _pick_closes(sym)
    ts = []
    for sym in syms[:150]:
        t = threading.Thread(target=one, args=(sym,), daemon=True)
        t.start()
        ts.append(t)
        if len(ts) >= 8:
            ts.pop(0).join(30)
    for t in ts:
        t.join(30)
    out_days, scored = [], []
    for k in picked:
        rows = []
        for r in h[k].get("rows") or []:
            x = dict(r)
            cl = closes.get(r["sym"]) or []
            frm = r.get("px")
            if not frm:
                prior = [c for d, c in cl if d < k]
                frm = prior[-1] if prior else None
            that = [c for d, c in cl if d >= k]
            with CACHE_LOCK:
                q = CACHE.get(r["sym"]) or {}
                now = q.get("ltpNum") if time.time() - (q.get("at") or 0) \
                    < 600 else None
            now = now or (cl[-1][1] if cl else None)
            x["from"] = round(frm, 2) if frm else None
            x["now"] = round(now, 2) if now else None
            x["day1"] = round((that[0] / frm - 1) * 100, 2) \
                if that and frm else None
            x["since"] = round((now / frm - 1) * 100, 2) if now and frm \
                else None
            if x["since"] is not None and r.get("call") in ("BUY", "SELL",
                                                            "HOLD"):
                x["right"] = (x["since"] > 0 if r["call"] == "BUY" else
                              x["since"] < 0 if r["call"] == "SELL" else
                              x["since"] > -2)
                scored.append(x)
            rows.append(x)
        out_days.append({"day": k, "at": h[k].get("at", ""), "rows": rows})
    summ = {}
    for x in scored:
        g = "outside" if x.get("group") == "outside" else \
            "fno" if x.get("group") == "fno" else "mine"
        for key in (x["call"], g + ":" + x["call"]):
            s = summ.setdefault(key, {"n": 0, "right": 0, "sum": 0.0})
            s["n"] += 1
            s["right"] += 1 if x["right"] else 0
            s["sum"] += x["since"]
    for s in summ.values():
        s["avg"] = round(s["sum"] / s["n"], 2) if s["n"] else None
        s.pop("sum", None)
    best = sorted([x for x in scored if x["call"] == "BUY"],
                  key=lambda x: -x["since"])[:3]
    worst = sorted([x for x in scored if x["call"] == "BUY"],
                   key=lambda x: x["since"])[:3]
    return {"ok": True, "days": out_days, "summary": summ, "since": cut,
            "first": min(h) if h else "", "best": best, "worst": worst,
            "scored": len(scored),
            "right": sum(1 for x in scored if x["right"])}


def picks_payload():
    d = picks_read()
    return {"day": d.get("day", ""), "at": d.get("at", ""),
            "today": d.get("day") == datetime.date.today().isoformat(),
            "rows": d.get("rows") or [], "read": d.get("read", 0),
            "running": PICKS["running"], "step": PICKS["step"],
            "error": PICKS["error"]}


