NEWSPUSH_FILE = os.path.join(DATA_DIR, "newspush.json")
NEWSPUSH = {"at": 0, "error": ""}


# ---------------------------------------------------------------------------
# NEWS ON THE PHONE WITHOUT THE MAC (20.8)
#
# The Mac sleeps, so the news cannot come from it. A small program
# (Backend/newsbot/notify.py) runs instead on GitHub's free computers every
# ten minutes, reads the news sites, and sends each new headline about his
# shares - and the few that move the whole market - to his ntfy app, one
# notification per article; tapping it opens the article in Safari.
# Setting it up needs a free GitHub account and one token pasted into
# Diagnostics -> Phone news; this server then creates the repository, puts
# the program there, stores the settings as encrypted secrets (GitHub
# requires libsodium's "sealed box", done below in plain Python), and from
# then on keeps the list of shares there up to date whenever it runs.
# Nothing in it can read or change anything in his Zerodha account.
# ---------------------------------------------------------------------------
# --- libsodium sealed box in pure Python (GitHub secrets need it) --------

_P25519 = 2 ** 255 - 19


def _x25519(k, u):
    k = bytearray(k)
    k[0] &= 248; k[31] &= 127; k[31] |= 64
    k = int.from_bytes(k, "little")
    u = int.from_bytes(u, "little") & ((1 << 255) - 1)
    x1, x2, z2, x3, z3, swap = u, 1, 0, u, 1, 0
    p = _P25519
    for t in reversed(range(255)):
        kt = (k >> t) & 1
        swap ^= kt
        if swap:
            x2, x3, z2, z3 = x3, x2, z3, z2
        swap = kt
        a, b = (x2 + z2) % p, (x2 - z2) % p
        aa, bb = a * a % p, b * b % p
        e = (aa - bb) % p
        c, d = (x3 + z3) % p, (x3 - z3) % p
        da, cb = d * a % p, c * b % p
        x3 = (da + cb) ** 2 % p
        z3 = x1 * (da - cb) ** 2 % p
        x2 = aa * bb % p
        z2 = e * (aa + 121665 * e) % p
    if swap:
        x2, x3, z2, z3 = x3, x2, z3, z2
    return (x2 * pow(z2, p - 2, p) % p).to_bytes(32, "little")


def _rotl(v, c):
    return ((v << c) & 0xffffffff) | (v >> (32 - c))


def _salsa_rounds(x):
    x = list(x)
    for _ in range(10):
        for a, b, c, d in ((0, 4, 8, 12), (5, 9, 13, 1), (10, 14, 2, 6),
                           (15, 3, 7, 11)):
            x[b] ^= _rotl((x[a] + x[d]) & 0xffffffff, 7)
            x[c] ^= _rotl((x[b] + x[a]) & 0xffffffff, 9)
            x[d] ^= _rotl((x[c] + x[b]) & 0xffffffff, 13)
            x[a] ^= _rotl((x[d] + x[c]) & 0xffffffff, 18)
        for a, b, c, d in ((0, 1, 2, 3), (5, 6, 7, 4), (10, 11, 8, 9),
                           (15, 12, 13, 14)):
            x[b] ^= _rotl((x[a] + x[d]) & 0xffffffff, 7)
            x[c] ^= _rotl((x[b] + x[a]) & 0xffffffff, 9)
            x[d] ^= _rotl((x[c] + x[b]) & 0xffffffff, 13)
            x[a] ^= _rotl((x[d] + x[c]) & 0xffffffff, 18)
    return x


_SIGMA = struct.unpack("<4I", b"expand 32-byte k")


def _salsa_state(key, n16):
    k = struct.unpack("<8I", key)
    n = struct.unpack("<4I", n16)
    return [_SIGMA[0], k[0], k[1], k[2], k[3], _SIGMA[1], n[0], n[1], n[2],
            n[3], _SIGMA[2], k[4], k[5], k[6], k[7], _SIGMA[3]]


def _hsalsa20(key, n16):
    x = _salsa_rounds(_salsa_state(key, n16))
    return struct.pack("<8I", *[x[i] for i in (0, 5, 10, 15, 6, 7, 8, 9)])


def _salsa20_stream(key, n8, length):
    out = bytearray()
    ctr = 0
    while len(out) < length:
        st = _salsa_state(key, n8 + struct.pack("<Q", ctr))
        x = _salsa_rounds(st)
        out += struct.pack("<16I", *[(x[i] + st[i]) & 0xffffffff
                                     for i in range(16)])
        ctr += 1
    return bytes(out[:length])


def _poly1305(key, msg):
    r = int.from_bytes(key[:16], "little") & 0x0ffffffc0ffffffc0ffffffc0fffffff
    s = int.from_bytes(key[16:], "little")
    p, acc = (1 << 130) - 5, 0
    for i in range(0, len(msg), 16):
        n = int.from_bytes(msg[i:i + 16] + b"\x01", "little")
        acc = (acc + n) * r % p
    return ((acc + s) & ((1 << 128) - 1)).to_bytes(16, "little")


def seal(msg, pk):
    """crypto_box_seal(msg, pk) - what GitHub expects for a secret."""
    esk = secrets.token_bytes(32)
    epk = _x25519(esk, (9).to_bytes(32, "little"))
    nonce = hashlib.blake2b(epk + pk, digest_size=24).digest()
    shared = _x25519(esk, pk)
    k = _hsalsa20(shared, b"\x00" * 16)          # crypto_box_beforenm
    sk = _hsalsa20(k, nonce[:16])                # xsalsa20 subkey
    stream = _salsa20_stream(sk, nonce[16:], 32 + len(msg))
    c = bytes(a ^ b for a, b in zip(msg, stream[32:]))
    return epk + _poly1305(stream[:32], c) + c


CLOUD_FILE = os.path.join(DATA_DIR, "cloudnews.json")   # the first profile's
CLOUD = {"lock": threading.Lock(), "at": 0, "error": ""}
CLOUD_REPO = "cas-news"

# 20.10 - the administrator's own GitHub token, so the copies he gives to family and
# close friends need no GitHub account of their own: each such copy gets its
# own schedule (.github/workflows/news-<id>.yml) and its own secrets in his
# cas-news repository, next to his. It is kept scrambled so that no scanner
# (GitHub's own included) takes it for a token and has it cancelled if this
# folder is ever put online. It is never written into the repository.
_SHARED_GH = ("b0xnWnpoS0pZUUdONTRFRkxEM3JsRkZPYWZYdXBIcEtJd2lkMW9jQkFtZVkzSTF6VzhEMWxFRDBaTFdfZzQwdjNlc3ZONDBnMEFSQzZVU0MxMV90YXBfYnVodGln")


def shared_token():
    try:
        return base64.b64decode(_SHARED_GH).decode()[::-1]
    except Exception:
        return ""


def cloud_path():
    """Each profile its own phone-news settings (the first profile's are
    where they always were, Data/cloudnews.json)."""
    return os.path.join(os.path.dirname(PATHS["state"]), "cloudnews.json")


def shared_flow(cid):
    """The schedule for one shared copy: the same program, its own secrets,
    its own queue (so copies never wait for one another)."""
    try:
        flow = open(os.path.join(NEWSBOT_DIR, "news.yml"), encoding="utf-8").read()
    except OSError:
        return ""
    flow = flow.replace("name: CAS news to the phone",
                        "name: CAS news to the phone (copy %s)" % cid)
    flow = flow.replace("group: news\n", "group: news-%s\n" % cid.lower())
    for k in ("NTFY_TOPIC", "WATCH", "GEMINI_KEY"):
        flow = flow.replace("secrets.%s }}" % k, "secrets.%s_%s }}" % (k, cid))
    return flow
# a fine-grained token cannot make a repository unless it covers "All
