GH_API = "https://api.github.com"
NEWSBOT_DIR = os.path.join(HERE, "newsbot")


def gh_api(method, path, token, body=None, timeout=25):
    """(status, json, headers) from api.github.com."""
    req = urllib.request.Request(
        GH_API + path, method=method,
        data=None if body is None else json.dumps(body).encode(),
        headers={"Authorization": "Bearer " + token,
                 "Accept": "application/vnd.github+json",
                 "X-GitHub-Api-Version": "2022-11-28",
                 "User-Agent": "cas-dashboard"})
    try:
        r = urllib.request.urlopen(req, timeout=timeout)
        raw = r.read()
        return r.status, (json.loads(raw) if raw.strip() else {}), r.headers
    except urllib.error.HTTPError as e:
        raw = e.read()
        try:
            j = json.loads(raw)
        except Exception:
            j = {"message": raw[:200].decode("utf-8", "replace")}
        return e.code, j, e.headers


def cloud_read():
    return _read_json(cloud_path(), {})


def cloud_token(d):
    return d.get("token") or (shared_token() if d.get("shared") else "")


def cloud_flow_path(d):
    return ".github/workflows/news-%s.yml" % d["id"].lower() \
        if d.get("shared") else ".github/workflows/news.yml"


def cloud_shared_ok():
    """A copy may use the administrator's account for phone news: any profile but the
    administrator's own (his has its own repository settings)."""
    return bool(shared_token()) and not profile_read().get("admin")


def cloud_setup_shared():
    """One press, no account: this profile's own schedule and secrets in
    the administrator's cas-news repository."""
    token = shared_token()
    if not token:
        return {"ok": False, "error": "This copy has no shared GitHub account."}
    topic = news_topic(profile_read())
    if not topic:
        return {"ok": False, "error": "This profile has no ntfy name yet "
                "(Diagnostics -> Profile)."}
    with CLOUD["lock"]:
        c, me, _h = gh_api("GET", "/user", token)
        if c != 200:
            return {"ok": False, "error": "GitHub did not accept the shared "
                    "account (%s). Ask whoever gave you this copy for a "
                    "newer one." % me.get("message", c)}
        repo = "%s/%s" % (me["login"], CLOUD_REPO)
        cid = hashlib.sha1(topic.encode()).hexdigest()[:10].upper()
        d = {"shared": True, "id": cid, "repo": repo}
        flow = shared_flow(cid)
        if not flow:
            return {"ok": False, "error": "Backend/newsbot is missing."}
        ok, err = _cloud_file(token, repo, cloud_flow_path(d), flow,
                              "CAS news: schedule for copy " + cid)
        if not ok:
            return {"ok": False, "error": "Could not save the schedule: " + err}
        c, key, _h = gh_api("GET", "/repos/%s/actions/secrets/public-key"
                            % repo, token)
        if c != 200:
            return {"ok": False, "error": "Could not read the repository's "
                    "key (%s)." % key.get("message", c)}
        watch = json.dumps(cloud_watch(), separators=(",", ":"))
        for name, value in (("NTFY_TOPIC", topic), ("WATCH", watch),
                            ("GEMINI_KEY", GEMINI.get("key") or "")):
            if not value:
                continue
            ok, err = _cloud_secret(token, repo, "%s_%s" % (name, cid), value,
                                    key)
            if not ok:
                return {"ok": False, "error": "Could not store the " + err}
        wf = os.path.basename(cloud_flow_path(d))
        gh_api("PUT", "/repos/%s/actions/workflows/%s/enable" % (repo, wf),
               token)
        c, _j, _h = gh_api("POST", "/repos/%s/actions/workflows/%s/dispatches"
                          % (repo, wf), token, {"ref": "main"})
        if c == 404:                  # GitHub needs a moment for a new file
            time.sleep(4)
            c, _j, _h = gh_api("POST", "/repos/%s/actions/workflows/%s/"
                              "dispatches" % (repo, wf), token, {"ref": "main"})
        d.update(on=True, made=time.strftime("%d %b %Y %H:%M"), topic=topic,
                 watch=hashlib.sha1(watch.encode()).hexdigest(),
                 flow=hashlib.sha1(flow.encode()).hexdigest())
        _write_json(cloud_path(), d)
        CLOUD["error"] = ""
    return {"ok": True, "repo": repo, "started": c == 204, "shared": True,
            "topic": topic}


# tickers that are also everyday words in market news ("BSE Sensex", "an
# idea"): on the phone they count only in these forms
CLOUD_STRICT = {
    "BSE": ["BSE Ltd", "BSE Limited", "BSE share", "BSE shares", "BSE stock"],
    "NSE": ["NSE IPO", "NSE share", "NSE shares"],
    "IDEA": ["Vodafone Idea"],
    "MCX": ["MCX Ltd", "MCX share", "MCX shares", "MCX stock",
            "Multi Commodity Exchange"],
    "IEX": ["Indian Energy Exchange", "IEX share", "IEX shares", "IEX stock"],
    "CAMS": ["Computer Age Management", "CAMS share", "CAMS shares"],
    "STAR": ["Strides Pharma"],
    "LT": ["Larsen & Toubro", "L&T"],
    "M&M": ["Mahindra & Mahindra", "M&M"],
}


def cloud_watch():
    """The shares the cloud looks for: what he holds (OLD, YESTERDAY,
    Out of list) first, then the rows he is working on today (QTY, PRICE,
    TARGET or MISSED filled in)."""
    st = load_state()
    notes = st.get("notes") or {}
    _blank, held = _pick_groups()

    def names(sym):
        if sym in CLOUD_STRICT:
            return [sym] + CLOUD_STRICT[sym]
        terms, full = share_terms(sym)
        words = [w for w in re.split(r"\s+", re.sub(
            r"\((?:india|i)\)|\b(?:limited|ltd\.?|company)\b", " ", str(full or ""),
            flags=re.I)) if w.strip(" .,")]
        t = []
        for x in terms:
            if x == sym:
                # the ticker itself only when it is short (TCS, ITC): a long
                # one like RELIANCE would also catch Reliance Power
                if len(sym) <= 4:
                    t.append(x)
                continue
            # 20.10: one word of a longer name is not enough on the phone -
            # "Ashok" was Ashok Leyland in a story about someone else
            if " " not in x and len(words) >= 2 and words[0].lower() == x.lower():
                n = 3 if words[1] in ("&", "and") and len(words) >= 3 else 2
                x = " ".join(words[:n])
            if x not in t:
                t.append(x)
        return [sym] + (t or [sym])
    working = [s for s in (st.get("watchlist") or []) if s not in held and
               any(str((notes.get(s) or {}).get(k) or "").strip()
                   for k in ("buy", "purchase", "target", "missed"))]
    full = {}
    for s in list(held)[:120] + working[:60]:
        try:
            nm = share_terms(s)[1]
        except Exception:
            nm = ""
        full[s] = re.sub(r"\s+(limited|ltd\.?)$", "", str(nm or s),
                         flags=re.I).strip() or s
    # the company names let Gemini tell "Trent Ltd" from Trent Williams
    try:
        alerts = [[a["sym"], a["price"], a["until"], a.get("ref"),
                   a.get("note", "")] for a in palerts_active()][:40]
    except Exception:
        alerts = []
    city, region = local_place()
    # 20.15: his F&O list, for the figures the phone reads with the laptop
    # off (public figures; he agreed the names he follows may be public)
    fno = [str(x.get("sym") or "").upper() for x in (st.get("fnoWatch") or [])
           if isinstance(x, dict) and x.get("sym")][:8]
    # 20.17: every share of the table and Out of list - their prices go into
    # the phone's laptop-off copy (snapshot.json), refreshed every half hour
    every = list(dict.fromkeys(list(st.get("watchlist") or []) +
                               [s for _n, s in extra_names(st)]))[:300]
    return {"held": [names(s) for s in held][:120],
            "watch": [names(s) for s in working][:60], "names": full,
            "fno": fno, "all": every,
            "quiet": [22, 7], "alerts": alerts,
            "city": city, "region": region}


def _cloud_secret(token, repo, name, value, key=None):
    if key is None:
        c, key, _h = gh_api("GET", "/repos/%s/actions/secrets/public-key"
                            % repo, token)
        if c != 200:
            return False, "could not read the repository's key (%s)" % c
    ct = seal(value.encode("utf-8"), base64.b64decode(key["key"]))
    c, j, _h = gh_api("PUT", "/repos/%s/actions/secrets/%s" % (repo, name),
                      token, {"encrypted_value": base64.b64encode(ct)
                              .decode(), "key_id": key["key_id"]})
    return c in (201, 204), "secret %s: %s" % (name, j.get("message", c))


def _cloud_file(token, repo, path, content, msg):
    c, cur, _h = gh_api("GET", "/repos/%s/contents/%s" % (repo, path), token)
    body = {"message": msg, "content": base64.b64encode(
        content.encode("utf-8")).decode()}
    if c == 200 and isinstance(cur, dict):
        if base64.b64decode(cur.get("content") or "") == content.encode():
            return True, ""
        body["sha"] = cur.get("sha")
    c, j, _h = gh_api("PUT", "/repos/%s/contents/%s" % (repo, path), token,
                      body)
    return c in (200, 201), "%s: %s" % (path, j.get("message", c))


def cloud_setup(token):
    """Everything on GitHub, from one token. Safe to run again."""
    token = re.sub(r"\s", "", str(token or ""))
    if not re.fullmatch(r"(ghp_|github_pat_)[A-Za-z0-9_]{20,}", token):
        return {"ok": False, "error": "That does not look like a GitHub "
                "token (it starts with ghp_)."}
    with CLOUD["lock"]:
        c, me, hdr = gh_api("GET", "/user", token)
        if c != 200:
            return {"ok": False, "error": "GitHub did not accept the token "
                    "(%s)." % me.get("message", c)}
        scopes = (hdr.get("X-OAuth-Scopes") or "") if hdr else ""
        if scopes and not ("workflow" in scopes and "repo" in scopes):
            return {"ok": False, "error": "The token needs the boxes 'repo' "
                    "and 'workflow' ticked (it has: %s)." % scopes}
        owner = me["login"]
        repo = "%s/%s" % (owner, CLOUD_REPO)
        c, j, _h = gh_api("GET", "/repos/" + repo, token)
        fine = token.startswith("github_pat_")
        if c == 404:
            c, j, _h = gh_api("POST", "/user/repos", token, {
                "name": CLOUD_REPO, "private": False, "auto_init": True,
                "description": "News headlines to my phone (Capital Compass)"})
            if c not in (201,):
                if fine:
                    return {"ok": False, "fine": True, "error": FINE_HELP}
                return {"ok": False, "error": "Could not make the "
                        "repository: %s" % j.get("message", c)}
            time.sleep(3)
        try:
            prog = open(os.path.join(NEWSBOT_DIR, "notify.py"),
                        encoding="utf-8").read()
            flow = open(os.path.join(NEWSBOT_DIR, "news.yml"),
                        encoding="utf-8").read()
        except OSError as e:
            return {"ok": False, "error": "Backend/newsbot is missing (%s)"
                    % e}
        extra = cloud_extra_files()
        for path, text in [("notify.py", prog),
                           (".github/workflows/news.yml", flow)] + extra:
            ok, err = _cloud_file(token, repo, path, text, "CAS news: " + path)
            if not ok:
                return {"ok": False, "fine": fine, "error": "Could not save " +
                        err + (" - the token needs Contents and Workflows: "
                               "Read and write" if fine else "")}
        c, key, _h = gh_api("GET", "/repos/%s/actions/secrets/public-key"
                            % repo, token)
        if c != 200:
            return {"ok": False, "fine": fine, "error": "Could not read the "
                    "repository's key (%s)%s." % (key.get("message", c),
                    " - the token needs Secrets: Read and write" if fine
                    else "")}
        topic = news_topic(admin_profile() if is_admin_copy()
                           else profile_read())
        watch = json.dumps(cloud_watch(), separators=(",", ":"))
        for name, value in (("NTFY_TOPIC", topic), ("WATCH", watch),
                            ("GEMINI_KEY", GEMINI.get("key") or "")):
            if not value:
                continue
            ok, err = _cloud_secret(token, repo, name, value, key)
            if not ok:
                return {"ok": False, "error": "Could not store the " + err}
        gh_api("PUT", "/repos/%s/actions/workflows/news.yml/enable" % repo,
               token)
        c, j, _h = gh_api("POST", "/repos/%s/actions/workflows/news.yml/"
                          "dispatches" % repo, token, {"ref": "main"})
        d = {"token": token, "repo": repo, "on": True,
             "made": time.strftime("%d %b %Y %H:%M"),
             "watch": hashlib.sha1(watch.encode()).hexdigest(),
             "prog": hashlib.sha1((prog + flow + "".join(
                 t for _p, t in extra)).encode()).hexdigest(),
             "topic": topic}
        _write_json(cloud_path(), d)
        CLOUD["error"] = ""
    return {"ok": True, "repo": repo, "started": c == 204}


def cloud_extra_files():
    """20.15: the program that writes the phone's laptop-off figures, and
    the dashboard's own program it reads them with (code only - nothing
    about him is in either)."""
    out = []
    for path, src in (("snapshot.py", os.path.join(NEWSBOT_DIR,
                                                    "snapshot.py")),
                      ("cas_server.py", os.path.join(HERE, "cas_server.py"))):
        try:
            txt = open(src, encoding="utf-8").read()
            # 20.16: the repository is public - the Gemini key that comes
            # with the program never goes into it (the laptop-off programs
            # do not use Gemini)
            txt = re.sub(r'(?m)^GEMINI_SHIPPED = "[^"]*"',
                         'GEMINI_SHIPPED = ""', txt)
            out.append((path, txt))
        except OSError:
            pass
    return out


def cloud_snapshot_url():
    d = cloud_read()
    repo = d.get("repo") or ""
    if not repo or d.get("shared"):
        return ""
    return "https://raw.githubusercontent.com/%s/main/snapshot.json" % repo


def cloud_sync(force=False):
    """Hourly while the dashboard runs: the share list (and the program, if
    a new version of it came with an update) sent to GitHub when changed."""
    d = cloud_read()
    token = cloud_token(d)
    if not d.get("on") or not token:
        return
    if not force and time.time() - CLOUD["at"] < 3600:
        return
    cw = cloud_watch()
    # just after starting, the company names are not read yet: a list of
    # bare tickers would catch far less news - wait for them
    # (counted by whether NSE has given the company's name yet - a short
    # ticker like ITC is its own name, which the old count missed)
    with CACHE_LOCK:
        named = sum(1 for g in cw["held"] if (CACHE.get(g[0]) or {}).get(
            "companyFull") or (CACHE.get(g[0]) or {}).get("company"))
    if not force and cw["held"] and named < 0.6 * len(cw["held"]):
        return
    CLOUD["at"] = time.time()
    watch = json.dumps(cw, separators=(",", ":"))
    h = hashlib.sha1(watch.encode()).hexdigest()
    try:
        prog = open(os.path.join(NEWSBOT_DIR, "notify.py"),
                    encoding="utf-8").read()
        flow = open(os.path.join(NEWSBOT_DIR, "news.yml"),
                    encoding="utf-8").read()
        extra = cloud_extra_files()
        ph = hashlib.sha1((prog + flow + "".join(
            t for _p, t in extra)).encode()).hexdigest()
    except OSError:
        prog = flow = None
        extra = []
        ph = d.get("prog")
    with CLOUD["lock"]:
        if h != d.get("watch"):
            ok, err = _cloud_secret(token, d["repo"], "WATCH_" + d["id"]
                                    if d.get("shared") else "WATCH", watch)
            if ok:
                d["watch"] = h
            else:
                CLOUD["error"] = err[:120]
        if d.get("shared"):
            # a shared copy keeps only its own schedule up to date - the
            # program itself is the administrator's copy's to update
            flow = shared_flow(d["id"])
            fh = hashlib.sha1(flow.encode()).hexdigest() if flow else None
            if fh and fh != d.get("flow"):
                ok, err = _cloud_file(token, d["repo"], cloud_flow_path(d),
                                      flow, "CAS news: update copy " + d["id"])
                if ok:
                    d["flow"] = fh
                else:
                    CLOUD["error"] = err[:120]
        elif prog and ph != d.get("prog"):
            for path, text in [("notify.py", prog),
                               (".github/workflows/news.yml", flow)] + extra:
                ok, err = _cloud_file(token, d["repo"], path, text,
                                      "CAS news: update " + path)
                if not ok:
                    CLOUD["error"] = err[:120]
                    break
            else:
                d["prog"] = ph
        d["synced"] = time.strftime("%d %b %H:%M")
        _write_json(cloud_path(), d)


# ---------------------------------------------------------------------------
# PRICE ALERTS (20.12) - "tell me when ITC touches 260", for as long as he
# chose (a week to a year). Checked every ten seconds while the market is
# open, from the dashboard's own NSE prices; each touch rings in the
# dashboard and comes to the phone (the news channel in ntfy). While the Mac
# is off, the GitHub news program checks them every five minutes instead.
# A price going back and forth across the line rings at most once in half
# an hour.
# ---------------------------------------------------------------------------
PALERT_LOCK = threading.Lock()
PALERT_LAST = {}
PALERT_SEEN = {}
PALERT_SPANS = {"1w": 7, "1m": 31, "3m": 92, "6m": 183, "1y": 366}


def palert_path():
    return os.path.join(os.path.dirname(PATHS["state"]), "price_alerts.json")


def palerts_read():
    d = _read_json(palert_path(), {})
    return list(d.get("items") or []) if isinstance(d, dict) else []


def palerts_write(items):
    _write_json(palert_path(), {"items": items[-200:]})


def palerts_active(items=None):
    today = datetime.date.today().isoformat()
    return [a for a in (palerts_read() if items is None else items)
            if a.get("until", "") >= today and not a.get("off")]


def palert_add(data):
    sym = re.sub(r"[^A-Z0-9&-]", "", str(data.get("sym") or "").upper())[:20]
    try:
        price = round(float(str(data.get("price") or "").replace(",", "")
                            .replace("\u20b9", "")), 2)
    except ValueError:
        price = 0
    if not sym or not price > 0:
        return {"ok": False, "error": "A share and a price are needed."}
    span = str(data.get("span") or "3m")
    until = str(data.get("until") or "")
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", until):
        until = (datetime.date.today() + datetime.timedelta(
            days=PALERT_SPANS.get(span, 92))).isoformat()
    live = chart_live("share", sym)
    if not live.get("ok"):
        return {"ok": False, "error": "No price could be read for %s - is "
                "it an NSE symbol?" % sym}
    a = {"id": "a%d" % int(time.time() * 1000), "sym": sym, "price": price,
         "until": until, "made": time.strftime("%Y-%m-%d %H:%M"),
         "ref": live["ltp"], "note": str(data.get("note") or "")[:80],
         "hits": 0, "hitAt": 0}
    # 20.19: a trend line from the chart - its level moves with time
    ln = data.get("line")
    if isinstance(ln, dict):
        try:
            line = {k: float(ln[k]) for k in ("t1", "p1", "t2", "p2")}
            line["shift"] = float(ln.get("shift") or 0)
        except (KeyError, TypeError, ValueError):
            return {"ok": False, "error": "The line could not be read."}
        if line["t1"] == line["t2"]:
            return {"ok": False, "error": "That line has no slope to follow."}
        a["line"] = line
        a["price"] = round(palert_level(a), 2)
    with PALERT_LOCK:
        items = palerts_read()
        items.append(a)
        palerts_write(items)
    PALERT_LAST[a["id"]] = live["ltp"]
    threading.Thread(target=cloud_sync, kwargs={"force": True},
                     daemon=True).start()
    return {"ok": True, "item": a, "now": live["ltp"]}


def palert_del(aid):
    with PALERT_LOCK:
        items = [a for a in palerts_read() if a.get("id") != aid]
        palerts_write(items)
    threading.Thread(target=cloud_sync, kwargs={"force": True},
                     daemon=True).start()
    return {"ok": True}


def palert_level(a):
    """The alert's price now: fixed, or where its trend line stands."""
    ln = a.get("line")
    if not isinstance(ln, dict):
        return float(a["price"])
    now = time.time() + float(ln.get("shift") or 0)
    return ln["p1"] + (ln["p2"] - ln["p1"]) * (now - ln["t1"]) / \
        (ln["t2"] - ln["t1"])


def palert_tick(anytime=False):
    """One look at every live alert's price; returns how many rang.
    (anytime: also outside market hours - for the tests)"""
    if not anytime:
        if not is_trading_day():
            return 0
        m = datetime.datetime.now().hour * 60 + datetime.datetime.now().minute
        if not (9 * 60 + 15 <= m <= cas_times()["shut"]):
            return 0
    rang = 0
    for a in palerts_active():
        with CACHE_LOCK:
            q = CACHE.get(a["sym"]) or {}
            fresh = q.get("ltpNum") and time.time() - (q.get("at") or 0) < 30
        # a share outside the table is read from NSE at most twice a minute
        if not fresh and time.time() - PALERT_SEEN.get(a["sym"], 0) < 30:
            continue
        PALERT_SEEN[a["sym"]] = time.time()
        live = chart_live("share", a["sym"])
        if not live.get("ok") or not live.get("ltp"):
            continue
        if live.get("at") and time.time() - live["at"] > 120:
            continue                       # an old price is not a touch
        px, lvl = float(live["ltp"]), palert_level(a)
        prev = PALERT_LAST.get(a["id"])
        if prev is None:
            prev = float(a.get("ref") or px)
        PALERT_LAST[a["id"]] = px
        touched = px == lvl or (prev < lvl <= px) or (prev > lvl >= px)
        if not touched or time.time() - float(a.get("hitAt") or 0) < 1800:
            continue
        rang += 1
        up = px >= prev
        text = "PRICE ALERT: %s %s \u20b9%s (now \u20b9%s)" % (
            a["sym"], "rose to" if up else "fell to", fmt_inr(lvl),
            fmt_inr(px))
        push_event("warn", text + (" - " + a["note"] if a.get("note")
                                   else ""), gap=600)
        topic = news_topic(profile_read())
        if topic:
            threading.Thread(target=ntfy_send, daemon=True, args=(
                topic, "PRICE ALERT - %s Rs %s" % (a["sym"], fmt_inr(lvl)),
                "%s %s \u20b9%s at %s - now \u20b9%s.%s\nAlert set %s, "
                "until %s." % (a["sym"], "rose to" if up else "fell to",
                               fmt_inr(lvl), time.strftime("%H:%M"),
                               fmt_inr(px), (" " + a["note"]) if
                               a.get("note") else "", a.get("made", "")[:10],
                               a["until"])),
                kwargs={"priority": 4, "tags": "bell",
                        "click": "https://www.nseindia.com/get-quotes/"
                                 "equity?symbol=" + Q(a["sym"])}).start()
        with PALERT_LOCK:
            items = palerts_read()
            for x in items:
                if x.get("id") == a["id"]:
                    x["hits"] = int(x.get("hits") or 0) + 1
                    x["hitAt"] = time.time()
                    x["lastHit"] = time.strftime("%d %b %H:%M")
            palerts_write(items)
    return rang


def palert_test(aid):
    """What a touch looks like - the banner, the sound and the phone - for
    trying it out when the market is shut (20.13)."""
    a = next((x for x in palerts_read() if x.get("id") == aid), None)
    if not a:
        return {"ok": False, "error": "No such alert."}
    push_event("warn", "PRICE ALERT (TEST): %s at \u20b9%s - this is how a "
               "real one looks" % (a["sym"], fmt_inr(a["price"])), gap=5)
    topic = news_topic(profile_read())
    if not topic:
        return {"ok": True, "phone": False}
    ok, _e = ntfy_send(topic, "PRICE ALERT (TEST) - %s Rs %s" % (
        a["sym"], fmt_inr(a["price"])), "A test of your price alert for %s "
        "at Rs %s. A real one comes like this when the price touches it." % (
            a["sym"], fmt_inr(a["price"])), priority=4, tags="bell")
    return {"ok": True, "phone": bool(ok)}


def palert_loop():
    while STATS["running"]:
        try:
            palert_tick()
        except Exception as e:
            STATS["lastError"] = "price alerts: %s" % str(e)[:80]
        time.sleep(10)


def fmt_inr(v):
    try:
        return "{:,.2f}".format(float(v))
    except (TypeError, ValueError):
        return str(v)


CLOUD_RUNS = {"at": 0, "last": 0, "stalled": False}


def cloud_stalled():
    """20.12 safety net: GitHub has not run the news program for two hours
    in the day (it stopped the schedule, or is badly behind) - then this Mac
    sends the news itself until GitHub runs again. Asked every 20 minutes."""
    d = cloud_read()
    token = cloud_token(d)
    if not (d.get("on") and token and d.get("repo")):
        return False
    now = datetime.datetime.now()
    if not (8 <= now.hour < 22):
        return False
    if time.time() - CLOUD_RUNS["at"] < 1200:
        return CLOUD_RUNS["stalled"]
    CLOUD_RUNS["at"] = time.time()
    try:
        c, j, _h = gh_api("GET", "/repos/%s/actions/workflows/%s/runs"
                          "?per_page=3" % (d["repo"], os.path.basename(
                              cloud_flow_path(d))), token, timeout=15)
        if c != 200:
            return CLOUD_RUNS["stalled"]
        last = 0
        for r in j.get("workflow_runs") or []:
            try:
                t = datetime.datetime.strptime(
                    r.get("updated_at") or r.get("created_at"),
                    "%Y-%m-%dT%H:%M:%SZ").replace(
                        tzinfo=datetime.timezone.utc).timestamp()
            except (TypeError, ValueError):
                continue
            last = max(last, t)
        CLOUD_RUNS["last"] = last
        wake = now.replace(hour=7, minute=30, second=0).timestamp()
        CLOUD_RUNS["stalled"] = bool(last) and time.time() - max(
            last, wake) > 2 * 3600
    except Exception:
        pass
    return CLOUD_RUNS["stalled"]


def cloud_status():
    d = cloud_read()
    out = {"on": bool(d.get("on")), "repo": d.get("repo", ""),
           "made": d.get("made", ""), "synced": d.get("synced", ""),
           "topic": d.get("topic") or news_topic(
               admin_profile() if is_admin_copy() else profile_read()),
           "shared": bool(d.get("shared")), "canShare": cloud_shared_ok(),
           "error": CLOUD["error"]}
    if out["on"] and not d.get("shared"):
        # his own: the ntfy name of the profile that set it up
        out["topic"] = d.get("topic") or out["topic"]
    token = cloud_token(d)
    if d.get("on") and token:
        c, j, _h = gh_api("GET", "/repos/%s/actions/workflows/%s/runs"
                          "?per_page=5" % (d["repo"], os.path.basename(
                              cloud_flow_path(d))), token)
        if c == 200:
            out["runs"] = [{"at": r.get("created_at", ""),
                            "status": r.get("status", ""),
                            "result": r.get("conclusion") or ""}
                           for r in (j.get("workflow_runs") or [])][:5]
        else:
            out["error"] = out["error"] or "GitHub: %s" % j.get("message", c)
    return out


# ---------------------------------------------------------------------------
# DAILY BACKUP TO GITHUB (20.18) - everything he has typed (the table, the
# Accounts of every year, the Portfolio, alerts, today's buys, profiles,
# messages) goes once a day, after the market, into his GitHub repository,
# so even a lost or dead laptop loses nothing. The repository is PUBLIC (it
# has to be, for the phone's copy and the free running time), so the files
# are locked with a long random key - xsalsa20-poly1305, the same lock as
# GitHub's own secrets above - never with his password, which is a short
# PIN anyone could try out offline. The key is a RECOVERY CODE he keeps off
# the laptop (Diagnostics -> GitHub backup shows it); on a new computer that
# code alone opens the backups. Thirty days are kept.
# ---------------------------------------------------------------------------
GHB = {"error": "", "running": False}
GHB_FILES = ("cas_state.json", "accounts.json", "accounts_ui.json",
             "portfolio.json", "alerts.json", "todays_buys.json",
             "profiles.json", "users.json", "users.json.k", "users.json.m",
             "picks_history.json", "ai_calls.json", "Messages/messages.json")
GHB_KEEP_DAYS = 30
_B32 = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"        # no 0/O or 1/I to mistake


def ghb_key_path():
    return os.path.join(acc_dir(), "backupkey.json")


def ghb_state_path():
    return os.path.join(acc_dir(), "ghbackup.json")


def ghb_code():
    """His recovery code (made once: 160 random bits, 32 letters/digits)."""
    d = _read_json(ghb_key_path(), {})
    c = d.get("code") if isinstance(d, dict) else None
    if not c:
        n = int.from_bytes(secrets.token_bytes(20), "big")
        s = ""
        for _ in range(32):
            s = _B32[n % 32] + s
            n //= 32
        c = "-".join(s[i:i + 4] for i in range(0, 32, 4))
        _write_json(ghb_key_path(), {"code": c,
                                     "made": time.strftime("%d %b %Y")})
    return c


def _ghb_derive(code, salt):
    clean = re.sub(r"[^A-Z0-9]", "", str(code or "").upper())
    return hashlib.scrypt(clean.encode(), salt=salt, n=2 ** 14, r=8, p=1,
                          dklen=32)


def _secretbox(key, msg):
    nonce = secrets.token_bytes(24)
    sk = _hsalsa20(key, nonce[:16])
    stream = _salsa20_stream(sk, nonce[16:], 32 + len(msg))
    c = bytes(a ^ b for a, b in zip(msg, stream[32:]))
    return nonce + _poly1305(stream[:32], c) + c


def _secretbox_open(key, box):
    if len(box) < 40:
        return None
    nonce, tag, c = box[:24], box[24:40], box[40:]
    sk = _hsalsa20(key, nonce[:16])
    stream = _salsa20_stream(sk, nonce[16:], 32 + len(c))
    if not _hmac.compare_digest(_poly1305(stream[:32], c), tag):
        return None                       # wrong code, or the file damaged
    return bytes(a ^ b for a, b in zip(c, stream[32:]))


def ghb_pack():
    base = acc_dir()
    names = list(GHB_FILES) + sorted(
        f for f in os.listdir(base)
        if re.fullmatch(r"accounts-\d{4}-\d{2}\.json", f))
    files = {}
    for n in names:
        p = os.path.join(base, n)
        if os.path.isfile(p) and os.path.getsize(p) < 8000000:
            with open(p, "rb") as f:
                files[n] = base64.b64encode(f.read()).decode()
    body = gzip.compress(json.dumps({
        "v": 1, "made": time.strftime("%Y-%m-%d %H:%M"), "version": VERSION,
        "files": files}).encode())
    salt = secrets.token_bytes(16)
    return (b"CCB1" + salt + _secretbox(_ghb_derive(ghb_code(), salt), body),
            sorted(files))


def ghb_unpack(blob, code):
    if blob[:4] != b"CCB1":
        return None
    plain = _secretbox_open(_ghb_derive(code, blob[4:20]), blob[20:])
    if plain is None:
        return None
    return json.loads(gzip.decompress(plain).decode("utf-8"))


def ghb_dir(d):
    return "backups/" + ("copy-%s" % d["id"] if d.get("shared") else "main")


def ghb_run(force=False):
    """Once a day after 15:35 (or at the first chance when the last copy is
    more than 30 hours old); `force` - now. True when a copy was sent."""
    d = cloud_read()
    token = cloud_token(d)
    if not d.get("on") or not token:
        GHB["error"] = "GitHub is not set up (Diagnostics -> Phone news)"
        return False
    st = _read_json(ghb_state_path(), {})
    st = st if isinstance(st, dict) else {}
    today = datetime.date.today().isoformat()
    if not force:
        due = (st.get("day") != today and time.strftime("%H:%M") >= "15:35") \
            or time.time() - (st.get("at") or 0) > 30 * 3600
        if not due or time.time() - (st.get("tried") or 0) < 1800:
            return False
    if GHB["running"]:
        return False
    GHB["running"] = True
    try:
        st["tried"] = time.time()
        _write_json(ghb_state_path(), st)
        blob, names = ghb_pack()
        path = "%s/%s.ccb" % (ghb_dir(d), today)
        ok, err = _cloud_file(token, d["repo"], path,
                              base64.b64encode(blob).decode(),
                              "Capital Compass backup " + today)
        if not ok:
            GHB["error"] = err[:120]
            return False
        GHB["error"] = ""
        st.update(day=today, at=time.time(), size=len(blob), files=names,
                  when=time.strftime("%d %b %Y, %H:%M"))
        _write_json(ghb_state_path(), st)
        # thirty days are kept
        c, lst, _h = gh_api("GET", "/repos/%s/contents/%s" % (
            d["repo"], ghb_dir(d)), token)
        if c == 200 and isinstance(lst, list):
            cut = (datetime.date.today() - datetime.timedelta(
                days=GHB_KEEP_DAYS)).isoformat()
            for f in lst:
                m = re.fullmatch(r"(\d{4}-\d{2}-\d{2})\.ccb", f.get("name", ""))
                if m and m.group(1) < cut:
                    gh_api("DELETE", "/repos/%s/contents/%s" % (
                        d["repo"], f["path"]), token,
                        {"message": "old backup", "sha": f["sha"]})
        return True
    except Exception as e:
        GHB["error"] = str(e)[:120]
        return False
    finally:
        GHB["running"] = False


def ghb_list():
    d = cloud_read()
    token = cloud_token(d)
    if not d.get("on") or not token:
        return {"ok": False, "error": "GitHub is not set up"}
    c, lst, _h = gh_api("GET", "/repos/%s/contents/%s" % (d["repo"],
                                                         ghb_dir(d)), token)
    if c == 404:
        return {"ok": True, "days": []}
    if c != 200 or not isinstance(lst, list):
        return {"ok": False, "error": "GitHub: %s" % (lst or {}).get(
            "message", c)}
    days = sorted((re.sub(r"\.ccb$", "", f["name"]) for f in lst
                   if f.get("name", "").endswith(".ccb")), reverse=True)
    return {"ok": True, "days": days}


def ghb_restore(day, code):
    """Puts the files of one day's GitHub backup back, after setting aside
    every file it replaces (Backups/before_github_restore_<time>/)."""
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", str(day or "")):
        return {"ok": False, "error": "Pick a day"}
    d = cloud_read()
    token = cloud_token(d)
    if not d.get("on") or not token:
        return {"ok": False, "error": "GitHub is not set up"}
    c, f, _h = gh_api("GET", "/repos/%s/contents/%s/%s.ccb" % (
        d["repo"], ghb_dir(d), day), token, timeout=60)
    if c != 200:
        return {"ok": False, "error": "GitHub: %s" % (f or {}).get(
            "message", c)}
    try:
        blob = base64.b64decode(base64.b64decode(f.get("content") or ""))
        pack = ghb_unpack(blob, code or ghb_code())
    except Exception:
        pack = None
    if not pack:
        return {"ok": False, "error": "That recovery code does not open this "
                "backup - check the code (letters and digits; dashes do not "
                "matter)."}
    base = acc_dir()
    aside = os.path.join(base, "Backups", "before_github_restore_" +
                         time.strftime("%Y-%m-%d_%H%M%S"))
    with NOTE_LOCK:
        for name, b64 in (pack.get("files") or {}).items():
            if ".." in name or name.startswith("/"):
                continue
            dest = os.path.join(base, name)
            if os.path.exists(dest):
                os.makedirs(os.path.dirname(os.path.join(aside, name)),
                            exist_ok=True)
                with open(dest, "rb") as a, open(os.path.join(aside, name),
                                                 "wb") as b:
                    b.write(a.read())
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            with open(dest + ".tmp", "wb") as w:
                w.write(base64.b64decode(b64))
            os.replace(dest + ".tmp", dest)
        PHONE_REV["rev"] += 1000
    return {"ok": True, "files": sorted(pack.get("files") or {}),
            "made": pack.get("made"), "aside": os.path.basename(aside)}


def ghb_status(reveal=False):
    st = _read_json(ghb_state_path(), {})
    st = st if isinstance(st, dict) else {}
    k = _read_json(ghb_key_path(), {})
    out = {"last": st.get("when") or "", "files": st.get("files") or [],
           "size": st.get("size") or 0, "error": GHB["error"],
           "codeMade": (k or {}).get("made", "") if isinstance(k, dict) else "",
           "on": bool(cloud_read().get("on"))}
    if reveal:
        out["code"] = ghb_code()
    return out


