def extra_names(state):
    """Each line of Out of list is ONE share, spaces and all.

    The old version split on every space, so "INOX WIND" became two shares,
    INOX and WIND - which is why Holdings showed 75 against his 72. The
    name is kept as he typed it for display; the symbol used for NSE
    lookups is the same name with the spaces taken out (INOX WIND ->
    INOXWIND, PVR INOX -> PVRINOX), which is how NSE writes them."""
    out, seen = [], set()
    for line in re.split(r"[\n,;]+", state.get("outOfList") or ""):
        name = re.sub(r"\s+", " ", line).strip().upper()
        sym = re.sub(r"[^A-Z0-9&-]", "", name)
        if len(sym) < 2 or len(sym) > 24 or sym in seen:
            continue
        seen.add(sym)
        out.append((name, sym))
    return out


def extra_symbols(state):
    """Symbols typed into the Out of list panel also count as 'your shares'."""
    return [sym for _name, sym in extra_names(state)]


def split_news(watchlist):
    mine, macro = [], []
    words = {}
    for s in watchlist:
        b = re.sub(r"[^A-Z]", "", s.upper())
        if len(b) >= 3:
            words[b] = s
    for it in NEWS["items"]:
        up = re.sub(r"[^A-Za-z ]", " ", it["title"]).upper()
        # Back to the wider net he preferred: it lets through the occasional
        # wrong tag but brings in far more, and more varied, headlines.
        # The one guard kept is that a loose match needs six characters, so
        # OIL can no longer be found inside "turmoil".
        squashed = up.replace(" ", "")
        hits = [sym for b, sym in words.items()
                if re.search(r"\b" + b + r"\b", up)
                or (len(b) >= 6 and b in squashed)]
        if hits:
            mine.append({**it, "symbols": sorted(set(hits))[:3]})
        else:
            low = it["title"].lower()
            if any(n in low for n in INDEX_NOISE):
                continue
            if any(w in low for w in MACRO_WORDS):
                macro.append(it)
    return mine[:30], macro[:25]


