def market_hours():
    if not is_trading_day():
        return False
    return "09:00" <= datetime.datetime.now().strftime("%H:%M") <= \
        hm_text(cas_times()["late"])


def bulk_poller():
    time.sleep(3)
    if not BULK_OK:
        discover_bulk()
    last_discover = time.time()
    while STATS["running"]:
        try:
            if not BULK_OK and time.time() - last_discover > 300:
                discover_bulk()
                last_discover = time.time()
            bulk_pass()
        except Exception as e:
            STATS["lastError"] = "bulk: %s" % e
        wait = BULK_EVERY_MARKET if market_hours() else BULK_EVERY_IDLE
        w = 0.0
        while w < wait and STATS["running"] and not FORCE["bulk"]:
            time.sleep(0.25)
            w += 0.25
        FORCE["bulk"] = False


def sweep_poller():
    """Never idles: keeps walking every symbol the bulk lists don't cover."""
    i = 0
    hurry_until = 0
    while STATS["running"]:
        state = load_state()
        watch = [s.upper() for s in (state.get("watchlist") or [])]
        # shares the bulk lists do not cover, plus - once a day - every share
        # whose P/E and sector have not been read yet (the bulk lists carry
        # prices only, and the VALUATION column needs the full quote)
        today = datetime.date.today().isoformat()
        with CACHE_LOCK:
            no_pe = {s for s in watch
                     if (CACHE.get(s) or {}).get("peDay") != today}
        todo = [s for s in watch if s not in BULK_SEEN or s in no_pe]
        if not todo:
            time.sleep(2.0)
            continue
        if FORCE["sweep"]:            # Refresh now -> start again from the top
            FORCE["sweep"] = False
            i = 0
            hurry_until = time.time() + 120
            STATS["sweepRound"] = STATS.get("sweepRound", 0) + 1
        if i >= len(todo):
            i = 0
            STATS["lastSweep"] = time.strftime("%H:%M:%S")
        sym = todo[i]
        i += 1
        STATS["sweepPos"] = i
        try:
            q = merge_symbol(fetch_symbol(sym, light=True))
            if q.get("error"):
                STATS["lastError"] = "%s: %s" % (sym, q["error"])
                RECENT_FAILS.append((time.time(), sym, q["error"]))
            else:
                STATS["okCount"] = STATS.get("okCount", 0) + 1
        except Exception as e:
            STATS["lastError"] = "%s: %s" % (sym, e)
        time.sleep(0.12 if time.time() < hurry_until else GAP_SWEEP)


def in_auction_window(now=None):
    """The auction's order entry, plus a minute either side: 15:19-15:31
    (from 7 Dec 2026, 15:30-15:41)."""
    now = now or datetime.datetime.now()
    if not is_trading_day(now.date()):
        return False
    t = cas_times(now)
    mins = now.hour * 60 + now.minute
    return t["entry"] - 1 <= mins <= t["shut"] + 1




def active_poller():
    while STATS["running"]:
        syms = active_symbols(load_state())
        if not syms:
            FORCE["active"] = False
            time.sleep(1.0)
            continue
        auction = in_auction_window()
        started, any_cas = time.time(), False
        for s in syms:
            if not STATS["running"]:
                return
            try:
                q = merge_symbol(fetch_symbol(s))
                record_series(s, q.get("icp"), (load_state().get("notes") or {}))
                if q.get("casStatus") in (True, "true", "True", 1):
                    any_cas = True
            except Exception as e:
                STATS["lastError"] = str(e)
            time.sleep(0 if (FORCE["active"] or auction) else GAP_ACTIVE)
        FORCE["active"] = False
        STATS["auction"] = auction
        STATS["activePass"] = round(time.time() - started, 1)
        STATS["lastActive"] = time.strftime("%H:%M:%S")
        STATS["casOn"] = any_cas
        note_cas(any_cas)


