BODY_CAP = 25 * 1024 * 1024     # the whole table with every notepad fits


# the dashboard's own names. cas.localhost is the short address (20.8): every
# Chromium browser sends *.localhost to this computer by itself, and treats
# it as a secure page, so Touch ID works there too
LOCAL_NAMES = ("localhost", "127.0.0.1", "::1", "cas.localhost")
SHORT_URL = {"url": ""}


def _host_name(h):
    h = str(h or "").strip().lower()
    m = re.match(r"^\[([0-9a-f:]+)\](?::\d+)?$", h)     # [::1]:8765
    if m:
        return m.group(1)
    return h.rsplit(":", 1)[0] if h.count(":") == 1 else h


class Handler(BaseHTTPRequestHandler):
    timeout = 120           # a page that stops half way does not hold a thread

    def log_message(self, *a):
        pass

    def _send(self, code, body, ctype="application/json"):
        if isinstance(body, (dict, list)):
            body = json.dumps(body)
        data = body.encode("utf-8") if isinstance(body, str) else body
        self.send_response(code)
        self.send_header("Content-Type", ctype + "; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control",
                         "no-store, no-cache, must-revalidate, max-age=0")
        self.send_header("Pragma", "no-cache")
        self.end_headers()
        try:
            self.wfile.write(data)
        except (BrokenPipeError, ConnectionResetError):
            pass            # the page was closed or reloaded mid-reply

    def _gate(self, path):
        """The page itself, the manual and sounds are always served; every
        figure (/api/...) only with an open session once a profile exists."""
        # only this computer's own names: a web page elsewhere cannot point
        # a look-alike name at it to read it
        host = _host_name(self.headers.get("Host"))
        if host not in LOCAL_NAMES:
            self._send(403, {"error": "unknown address"})
            return False
        REQ.pid = None
        self._spid = None
        if auth_route(self, self.command, path):
            return False
        if path.startswith("/api/") and path != "/api/ping" and \
                locked_for(self):
            self._send(401, {"locked": True})
            return False
        REQ.pid = getattr(self, "_spid", None) or ACTIVE["pid"]
        return True

    def handle_one_request(self):
        try:
            BaseHTTPRequestHandler.handle_one_request(self)
        except ProfileMoved:
            # another profile was opened while this request was under way
            try:
                self._send(401, {"locked": True})
            except Exception:
                pass

    def do_GET(self):
        p = urllib.parse.urlparse(self.path)
        path, qs = p.path, urllib.parse.parse_qs(p.query)
        if not self._gate(path):
            return
        # anything that changes his data or opens a program on the Mac only
        # for the dashboard's own page: another web site can make the browser
        # fetch an address, but it cannot add this header
        if path in SIDE_EFFECT_GETS and self.headers.get("X-CAS") != "1" \
                and not (path == "/api/kite" and not qs.get("path")) \
                and not (path == "/api/askkey" and "set" not in qs and
                         "shipped" not in qs):
            self._send(403, {"error": "only from the dashboard itself"})
            return

        if path in ("/m", "/m/"):
            # the phone page, from the Mac's own address (to look at it on
            # the Mac)
            try:
                with open(os.path.join(HERE, "phone.html"), "rb") as f:
                    self._send(200, f.read(), "text/html")
            except Exception:
                self._send(404, "phone.html is missing", "text/plain")
            return
        if path == "/api/m":
            self._send(200, phone_data())
            return
        if path == "/api/m/news":
            self._send(200, phone_news())
            return

        if path in ("/", "/index.html"):
            try:
                with open(os.path.join(HERE, "dashboard.html"), "rb") as f:
                    html = f.read()
            except Exception:
                self._send(500, "dashboard.html must sit next to cas_server.py",
                           "text/plain")
                return
            self._send(200, html, "text/html")
            return

        if path in ("/vendor/icon-64.png", "/vendor/icon-180.png",
                    "/vendor/icon-512.png"):
            try:
                with open(os.path.join(HERE, path.lstrip("/")), "rb") as f:
                    self._send(200, f.read(), "image/png")
            except Exception:
                self._send(404, "no icon", "text/plain")
            return

        if path in ("/chart.js", "/voice.js", "/accounts.js", "/messages.js",
                    "/portfolio.js", "/lang.js", "/taxes.js",
                    "/vendor/lightweight-charts.js"):
            # the full chart (20.12): its own script, and TradingView's free
            # chart library (Apache 2.0 licence, kept beside it in vendor/)
            try:
                with open(os.path.join(HERE, path.lstrip("/")), "rb") as f:
                    self._send(200, f.read(), "text/javascript")
            except Exception:
                self._send(404, "// %s is missing" % path, "text/javascript")
            return

        if path == "/api/kite":
            self._send(200, open_kite_v16(qs.get("path", [""])[0] or None))
            return

        if path == "/api/kite_old":
            st = load_state()
            saved = tidy_app_path(st.get("kiteApp") or st.get("kitePath") or "")
            if saved:
                import subprocess
                try:
                    if saved.startswith("http"):
                        cmd = ["open", "-a", "Google Chrome", saved]
                    elif saved.endswith(".app"):
                        cmd = ["open", "-a", saved]
                    else:                       # .webloc, alias, anything else
                        cmd = ["open", saved]
                    r = subprocess.run(cmd, timeout=8, capture_output=True)
                    if r.returncode == 0:
                        self._send(200, {"ok": True, "how": "saved",
                                         "app": os.path.basename(saved) or saved})
                        return
                except Exception:
                    pass
            self._send(200, open_kite_browser())
            return

        if path == "/api/kiteset":
            p = (qs.get("path", [""])[0] or "").strip()
            with NOTE_LOCK:
                st = load_state()
                st["kiteApp"] = tidy_app_path(p)
                save_state(st)
            self._send(200, {"ok": True, "kiteApp": st["kiteApp"]})
            return

        if path == "/api/checksources":
            sym = (qs.get("symbol", ["RELIANCE"])[0] or "RELIANCE").upper()
            out = []

            def probe(name, fn):
                t0 = time.time()
                try:
                    n = fn()
                    out.append({"source": name, "ok": bool(n),
                                "detail": ("%s rows" % n) if isinstance(n, int)
                                else str(n),
                                "secs": round(time.time() - t0, 1)})
                except Exception as e:
                    out.append({"source": name, "ok": False,
                                "detail": str(e)[:140],
                                "secs": round(time.time() - t0, 1)})

            # the three history sources were removed in v16 when the LT chart
            # moved to NSE's 52-week report; this button was still calling them
            probe("52-week report (NSE)",
                  lambda: len(wk52_for(wk52_fetch_latest() or
                                       datetime.date.today()) or {}))
            for name, url, lang in LOCAL_FEEDS:
                probe("Kolkata: " + name,
                      lambda n=name, u=url: len(read_rss(n, u)))
            for site, url in RECO_PAGES[:4]:
                probe("Reco: " + url.split("/")[-2] + " (" + site + ")",
                      lambda u=url: len(urllib.request.urlopen(
                          urllib.request.Request(u, headers={
                              "User-Agent": UA,
                              "Accept": "text/html"}), timeout=12).read()))
            probe("Index: NSE allIndices", lambda: len(nse_indices()))
            # (stooq, a spare source for the world indices, closed its free
