            if not re.fullmatch(r"[A-Z0-9&._-]{1,24}", sym):
                self._send(400, {"error": "not an NSE symbol"})
                return
            url, how = tickertape_url(sym)
            if url:
                self.send_response(302)
                self.send_header("Location", url)
                self.send_header("Cache-Control", "no-store")
                self.end_headers()
                return
            # never another site: ask him for the link once, then it is
            # remembered for this share for good
            esc = html_lib.escape(sym)
            page = TT_ASK_PAGE.replace("{SYMJS}", json.dumps(sym).replace(
                "<", "\\u003c")).replace("{SYM}", esc)
            body = page.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
