    def do_POST(self):
        # every POST the page makes is JSON; a plain form on another web page
        # cannot send that without the browser asking first, so this keeps
        # other sites from changing anything here
        ctype = (self.headers.get("Content-Type") or "").lower()
        if not ctype.startswith("application/json"):
            self._send(415, {"error": "JSON only"})
            return
        if not self._gate(urllib.parse.urlparse(self.path).path):
            return
        ppath = urllib.parse.urlparse(self.path).path
        if ppath in ("/api/m/note", "/api/m/outlist", "/api/m/eod"):
            try:
                n = max(0, int(self.headers.get("Content-Length", 0) or 0))
                data = json.loads(self.rfile.read(min(n, 20000))
                                  .decode("utf-8"))
            except Exception:
                data = None
            code, body = phone_post(ppath, data)
            self._send(code, body)
            return
        if urllib.parse.urlparse(self.path).path == "/api/eod":
            try:
                n = max(0, int(self.headers.get("Content-Length", 0) or 0))
                payload = json.loads(self.rfile.read(min(n, BODY_CAP))
                                     .decode("utf-8"))
                if not isinstance(payload, dict):
                    raise ValueError("expected an object")
            except Exception as e:
                self._send(400, {"error": str(e)[:200]})
                return
            with EOD_LOCK:
                d = eod_read()
                if d.get("date") == payload.get("date"):
                    how = str(payload.get("how") or "")[:40]
                    if how == "undo":
                        # 20.14: the box's UNDO - the day is asked about again
                        d["done"] = False
                        d.pop("how", None)
                        d.pop("accAdded", None)
                    elif how == "accounts":
                        # put into the Accounts once: the button stays off
                        d["accAdded"] = time.strftime("%d %b %H:%M")
                    else:
                        d["done"] = True
                        d["how"] = how
                        d["doneAt"] = time.strftime("%d %b %H:%M")
                    eod_write(d)
            self._send(200, eod_status())
            return
        if urllib.parse.urlparse(self.path).path == "/api/tickertape-link":
            try:
                n = max(0, int(self.headers.get("Content-Length", 0) or 0))
                payload = json.loads(self.rfile.read(min(n, BODY_CAP))
                                     .decode("utf-8"))
                if not isinstance(payload, dict):
                    raise ValueError("expected an object")
            except Exception as e:
                self._send(400, {"error": str(e)[:200]})
