ZERODHA_URL = "https://zerodha.com/charges/"
# what the dashboard's own PROFIT and BREAKEVEN assume, as Zerodha words it
ZERODHA_EXPECT = [
    ("STT on intraday sells 0.025%", "0.025% on the sell side"),
    ("NSE transaction charges 0.00307%", "NSE: 0.00307%"),
    ("stamp duty on intraday buys 0.003%",
     "0.003% or \u20b9300 / crore on buy side"),
    ("brokerage 0.03% or Rs 20 an order", "0.03% or Rs. 20/executed order"),
    ("GST 18% on brokerage and fees", "18% on (brokerage"),
    ("SEBI fee Rs 10 a crore", "\u20b910 / crore"),
]


def rules_read():
    d = _read_json(RULES_FILE, {})
    d.setdefault("items", [])
    d.setdefault("seen", [])
    return d


def rules_write(d):
    d["items"] = d["items"][-120:]
    d["seen"] = d["seen"][-1500:]
    _write_json(RULES_FILE, d)


def _rule_id(*parts):
    return hashlib.sha1("|".join(parts).encode("utf-8")).hexdigest()[:12]


def _rule_news():
    """Candidate headlines: SEBI's own feed, then the news searches."""
    out = []
    try:
        raw = urllib.request.urlopen(urllib.request.Request(
            "https://www.sebi.gov.in/sebirss.xml",
            headers={"User-Agent": UA}), timeout=20).read()
        for it in ET.fromstring(raw).iter("item"):
            t = (it.findtext("title") or "").strip()
            l = (it.findtext("link") or "").strip()
            if not t or not l:
                continue
            # circulars, press releases and consultation papers - not
            # the daily orders against individual companies
            if not re.search(r"/(legal/circulars|media-and-notifications/"
                             r"press-releases)", l):
                continue
            out.append({"title": t, "link": l, "source": "SEBI",
                        "sebi": True})
    except Exception as e:
        RULES["error"] = "SEBI feed: %s" % str(e)[:80]
    for q in RULE_QUERIES:
        try:
            url = ("https://news.google.com/rss/search?q=" + Q(q + " when:10d")
                   + "&hl=en-IN&gl=IN&ceid=IN:en")
            raw = urllib.request.urlopen(urllib.request.Request(
                url, headers={"User-Agent": UA}), timeout=12).read()
            for it in list(ET.fromstring(raw).iter("item"))[:12]:
                t = (it.findtext("title") or "").strip()
                l = (it.findtext("link") or "").strip()
                src = it.findtext("source") or "News"
                t = re.sub(r"\s+-\s+" + re.escape(src) + r"$", "", t)
                age = age_hours(it.findtext("pubDate") or "")
                if t and l and age is not None and age < 24 * 10:
                    out.append({"title": t, "link": l, "source": src,
                                "age": age})
        except Exception:
            continue
    return out


def _rule_screen(cands):
    """Which of the candidates are real changes: Gemini if it answers, a
    strict word test if not. Returns [(cand, why)]."""
    RULES["byWords"] = False
    if not cands:
        return []
    keep = []
    if GEMINI["key"]:
        for i in range(0, len(cands), 25):
            part = cands[i:i + 25]
            # a SEBI circular is a decision already taken, whatever its
            # title sounds like ("Review of certain aspects of ...")
            q = "\n".join("%d. %s%s" % (n + 1, "[SEBI CIRCULAR - issued] "
                                         if c.get("sebi") else "", c["title"])
                          for n, c in enumerate(part))
            ans, _e = ask_gemini(q, RULE_STYLE)
            if not ans or not re.search(r"^\W*\d+\W*\|.*\b(YES|NO)\b",
                                        str(ans), re.I | re.M):
                keep = None              # no answer in the form asked for
                break
            for ln in str(ans).splitlines():
                # "5|YES|AUCTION|..." - also "5|1|YES|..." or "**5**|YES"
                m = re.match(r"\W*(\d+)\W*\|(?:\s*\d+\s*\|)?\s*(YES|NO)\s*"
                             r"\|?\s*(?:([A-Z]+)\s*\|)?\s*(.*)", ln, re.I)
                if m and m.group(2).upper() == "YES":
                    n = int(m.group(1)) - 1
                    topic = (m.group(3) or "").upper()
                    # only the topics that touch his accounts or the
                    # dashboard (F&O-only or "OTHER" are dropped)
                    if 0 <= n < len(part) and topic in RULE_TOPICS:
                        part[n]["topic"] = topic
                        keep.append((part[n], m.group(4).strip(" |*")[:140]))
        if keep is not None:
            return keep
    # no Gemini: nothing from the news (a word test let too much through);
    # these are asked about again next time. Zerodha's own page still counts.
    RULES["byWords"] = True
    return []


def _zerodha_check(d):
    """New alerts from Zerodha's charges page: when it no longer says what
    the dashboard assumes, or when the charges part of it changes."""
    out = []
    try:
        raw = urllib.request.urlopen(urllib.request.Request(
            ZERODHA_URL, headers={"User-Agent": UA}), timeout=20).read()
        page = raw.decode("utf-8", "replace")
    except Exception as e:
        RULES["error"] = "Zerodha page: %s" % str(e)[:80]
        return out
    page = re.sub(r"<script.*?</script>|<style.*?</style>", " ", page,
                  flags=re.S | re.I)
    text = re.sub(r"\s+", " ", html_lib.unescape(re.sub(r"<[^>]+>", " ",
                                                         page)))
    i = text.find("Equity delivery")
    j = text.find("Currency", i + 1) if i >= 0 else -1
    part = text[i:j] if i >= 0 and j > i else ""
    if len(part) < 300:
        RULES["error"] = "Zerodha page: charges table not found"
        return out
    for label, token in ZERODHA_EXPECT:
        if token not in part:
            out.append({"id": _rule_id("zx", label),
                        "title": "Zerodha's charges page no longer shows %s"
                                 % label,
                        "why": "The dashboard's PROFIT and BREAKEVEN use it "
                               "- they may need changing.",
                        "link": ZERODHA_URL, "source": "Zerodha"})
    z = d.get("zerodha") or {}
    # only the figures count - new wording or layout is not a change
    figs = re.findall(r"[\d.]+%|\u20b9\s?[\d,.]+|Rs\.?\s?[\d,.]+", part)
    h = hashlib.sha1("|".join(figs).encode("utf-8")).hexdigest()
    if z.get("hash") and z["hash"] != h:
        old = set(re.findall(r"[\d.]+%|\u20b9\s?[\d,.]+|Rs\.?\s?[\d,.]+",
                             z.get("text") or ""))
        new = [x for x in dict.fromkeys(
            re.findall(r"[\d.]+%|\u20b9\s?[\d,.]+|Rs\.?\s?[\d,.]+", part))
            if x not in old]
        out.append({"id": _rule_id("zc", h),
                    "title": "Zerodha has changed its charges page",
                    "why": ("New figures on it: " + ", ".join(new[:6]))
                    if new else "Some figures were removed or moved.",
                    "link": ZERODHA_URL, "source": "Zerodha"})
    d["zerodha"] = {"hash": h, "text": part[:6000],
                    "checked": time.strftime("%d %b %H:%M")}
    return out


_STOP = set("this that with from have will after over into their about "
             "says said sebi india indian market markets news check here "
             "what more rules rule".split())


def _story_words(x):
    return {w for w in re.findall(r"[a-z0-9]+", (x.get("title", "") + " " +
                                                  x.get("why", "")).lower())
            if len(w) > 3 and w not in _STOP}


def _rule_quiet():
    """22:00 to 08:00 on the Mac's clock: notices wait for the morning."""
    h = time.localtime().tm_hour
    return h >= 22 or h < 8


RULE_SAME_STYLE = (
    "You keep a list of changes to Indian trading rules and charges so that "
    "a trader is told about each change ONCE, however many papers report "
    "it. Below are the KNOWN changes and some NEW headlines. For each new "
    "headline write exactly one line: 'N<i>|K<j>' if it reports the same "
    "change as known change K<j> (the same decision or proposal, even if it "
    "is worded differently, gives more detail, or is a later or follow-up "
    "report about it); 'N<i>|N<k>' if it is the same change as an EARLIER "
    "new headline N<k>; otherwise 'N<i>|NEW'. Nothing else.\n\n")


def _rule_match(news, known):
    """For each new item: the id of the known item it repeats, the index of
    an earlier new item it repeats, or None when it is a new change."""
    out = [None] * len(news)
    if not news:
        return out
    ok = False
    if GEMINI["key"] and known is not None:
        q = "KNOWN:\n" + ("\n".join(
            "K%d. [%s] %s - %s" % (n + 1, k.get("topic") or "OTHER",
                                   k["title"], k.get("why") or "")
            for n, k in enumerate(known)) or "(none)") + "\n\nNEW:\n" + \
            "\n".join("N%d. [%s] %s - %s" % (n + 1, f.get("topic") or "OTHER",
                                             f["title"], f.get("why") or "")
                      for n, f in enumerate(news))
        ans, _e = ask_gemini(q, RULE_SAME_STYLE)
        lines = re.findall(r"N(\d+)\s*\|\s*(K\d+|N\d+|NEW)", str(ans or ""),
                           re.I)
        if len(lines) >= len(news):
            ok = True
            for a, b in lines:
                i = int(a) - 1
                if not 0 <= i < len(news):
                    continue
                b = b.upper()
                if b == "NEW":
                    continue
                if b.startswith("K"):
                    j = int(b[1:]) - 1
                    if 0 <= j < len(known):
                        out[i] = ("K", known[j]["id"])
                elif b.startswith("N"):
                    j = int(b[1:]) - 1
                    if 0 <= j < i:
                        out[i] = ("N", j)
    if not ok:
        # no Gemini: the same subject within the month counts as the same
        # change - better one notice too few than the same one ten times
        for i, f in enumerate(news):
            k = next((k for k in known if _same_story(k, f)), None)
            if k:
                out[i] = ("K", k["id"])
                continue
            j = next((j for j in range(i) if _same_story(news[j], f)), None)
            if j is not None:
                out[i] = ("N", j)
    return out


def _same_story(a, b):
    ta, tb = a.get("topic") or "", b.get("topic") or ""
    if ta and tb and ta != "OTHER" and ta == tb:
        return True
    wa, wb = _story_words(a), _story_words(b)
    if not wa or not wb:
        return False
    return len(wa & wb) / float(min(len(wa), len(wb))) >= 0.5


def rules_push(force=False):
    """Send what is waiting - as ONE notification, never at night, at most
    four a day."""
    with RULES["lock"]:
        d = rules_read()
        wait = [x for x in d["items"] if x["id"] in (d.get("pending") or [])
                and not x.get("done")]
        if not wait:
            if d.get("pending"):
                d["pending"] = []
                rules_write(d)
            return
        if _rule_quiet() and not force:
            return
        today = time.strftime("%Y-%m-%d")
        sent = d.get("sent") if isinstance(d.get("sent"), dict) else {}
        if sent.get("day") != today:
            sent = {"day": today, "n": 0}
        if sent["n"] >= 4 and not force:
            return
        sent["n"] += 1
        d["sent"] = sent
        d["pending"] = []
        rules_write(d)
    p = admin_profile() if is_admin_copy() else profile_read()
    if len(wait) == 1:
        f = wait[0]
        body = "%s\n%s\n\nSource: %s - tap to open." % (
            f["title"], f.get("why") or "", f["source"])
    else:
        body = "\n\n".join("%d. %s\n%s" % (n + 1, f.get("why") or f["title"],
                                            f["source"])
                            for n, f in enumerate(wait[:6])) + \
            "\n\nAll of them are on the dashboard."
    ntfy_send(code_channel(p), "Rule / charges change" +
              ("s (%d)" % len(wait) if len(wait) > 1 else ""), body,
              priority=4, tags="scales",
              click=wait[0]["link"] if len(wait) == 1 else None)


def rules_check():
    """One full check. Safe to call from a request (runs once at a time).

    Every report is compared with EVERY change already known from the last
    60 days - including those he marked Done - so a change is announced
    once, however many papers write about it, whatever their headline."""
    with RULES["lock"]:
        if RULES["running"]:
            return
        RULES["running"] = True
    try:
        RULES["error"] = ""
        d = rules_read()
        zero = _zerodha_check(d)
        seen = set(d["seen"])
        have = {x["id"] for x in d["items"]}
        cands, ids = [], set()
        for c in _rule_news():
            key = re.sub(r"[^a-z0-9]", "", c["title"].lower())[:90]
            cid = _rule_id("n", key)
            if cid in seen or cid in have or cid in ids:
                continue
            ids.add(cid)
            if c.get("sebi") or RULE_WORDS.search(c["title"]):
                c["id"] = cid
                cands.append(c)
            else:
                seen.add(cid)
        cands = cands[:60]
        news = []
        for c, why in _rule_screen(cands):
            news.append({"id": c["id"], "title": c["title"], "why": why,
                         "link": c["link"], "source": c["source"],
                         "topic": c.get("topic", ""), "age": c.get("age")})
        # SEBI's own words first, so they become the banner
        news.sort(key=lambda f: f["source"] != "SEBI")
        now = time.time()
        known = [x for x in d["items"] if x["source"] != "Zerodha"
                 and now - (x.get("ts") or now) < 60 * 86400]
        match = _rule_match(news, known)
        fresh, links = [], []
        head = {}                        # index of a new item -> its banner
        for i, f in enumerate(news):
            m = match[i]
            if m and m[0] == "K":
                links.append((m[1], f))
                head[i] = m[1]           # a later N pointing here joins it too
            elif m and m[0] == "N" and m[1] in head:
                links.append((head[m[1]], f))
                head[i] = head[m[1]]
            else:
                fresh.append(f)
                head[i] = f["id"]
        fresh += zero
        if RULES.get("byWords"):
            # Gemini did not answer: what the word test let through is seen,
            # the rest is asked about again when Gemini is back
            kept = {f["id"] for f in news}
            new_seen = [c["id"] for c in cands if c["id"] in kept]
        else:
            new_seen = [c["id"] for c in cands]
        first = not d.get("lastRun")
        added = []
        # written under the lock onto the file as it is NOW, so a Done
        # pressed while this check was reading the web is kept
        with RULES["lock"]:
            cur = rules_read()
            have = {x["id"] for x in cur["items"]}
            for f in fresh:
                if f["id"] in have:
                    continue
                f.update(at=time.strftime("%d %b %Y %H:%M"), ts=now,
                         done=False)
                f.setdefault("more", [])
                cur["items"].append(f)
                have.add(f["id"])
                added.append(f)
            for tid, f in links:
                for x in cur["items"]:
                    if x["id"] == tid and len(x.setdefault("more", [])) < 8 \
                            and f["link"] not in [m.get("link")
                                                  for m in x["more"]] \
                            and f["link"] != x.get("link"):
                        x["more"].append({"source": f["source"],
                                          "link": f["link"]})
            cur["seen"] = list(dict.fromkeys(cur["seen"] + new_seen
                                             + [i for i in seen
                                                if i not in cur["seen"]]))
            cur["zerodha"] = d.get("zerodha") or cur.get("zerodha")
            cur["lastRun"] = time.strftime("%d %b %H:%M")
            cur["lastTs"] = time.time()
            # a notice only for a change reported in the last day (the very
            # first check finds two weeks of news: banners, no notices)
            push = [f["id"] for f in added
                    if (f.get("age") is None and not first)
                    or (f.get("age") is not None and f["age"] < 24)]
            cur["pending"] = list(dict.fromkeys((cur.get("pending") or [])
                                                + push))
            rules_write(cur)
        rules_push()
    except Exception as e:
        RULES["error"] = str(e)[:120]
    finally:
        RULES["running"] = False


def rules_payload(all_too=False):
    d = rules_read()
    items = [x for x in d["items"] if not x.get("done")]
    out = {"items": items[::-1], "lastRun": d.get("lastRun", ""),
           "zerodhaChecked": (d.get("zerodha") or {}).get("checked", ""),
           "running": RULES["running"], "error": RULES["error"]}
    if all_too:
        out["all"] = d["items"][::-1][:40]
    return out


def _page_words(url, limit=7000):
    """The readable words of a web page (for Gemini to read an article)."""
    try:
        raw = urllib.request.urlopen(urllib.request.Request(
            url, headers={"User-Agent": "Mozilla/5.0"}), timeout=15).read(
                900000).decode("utf-8", "replace")
    except Exception:
        return ""
    raw = re.sub(r"(?is)<(script|style|noscript|svg|header|footer|nav)"
                 r".*?</\1>", " ", raw)
    txt = html_lib.unescape(re.sub(r"<[^>]+>", " ", raw))
    return re.sub(r"\s+", " ", txt).strip()[:limit]


def rules_explain(rid, me=False):
    """20.16: a rule or charges change in plain words (10-15 lines), and -
    when asked - whether it touches him: his trading as Profile describes
    it, what he invests in, and what the dashboard would need. Kept with the
    notice, so Gemini is asked once."""
    d = rules_read()
    x = next((i for i in d["items"] if i.get("id") == rid), None)
    if not x:
        return {"ok": False, "error": "That notice is no longer kept."}
    key = "explainMe" if me else "explain"
    if x.get(key):
        return {"ok": True, "text": x[key]}
    words = _page_words(x.get("link") or "") if x.get("link") else ""
    base = ("A notice about a change in Indian market rules or charges:\n"
            "Title: %s\nSummary: %s\nSource: %s\nArticle text (may be "
            "partial): %s\n\n" % (x.get("title"), x.get("why") or "",
                                    x.get("source"), words))
    if not me:
        prompt = base + (
            "Explain it in simple English for a retail investor in 10 to 15 "
            "short lines: what changes, from when, who it applies to, and "
            "what (if anything) an investor has to do. Plain text, no "
            "markdown headings, no jargon without explaining it. If the "
            "article does not say something, say it is not stated - never "
            "guess dates or numbers.")
    else:
        st = load_state()
        pr = st.get("prefs") or {}
        style = (pr.get("style") or {}).get("text") or ""
        inv = (pr.get("invest") or {}).get("types") or ["equity"]
        try:
            brk = (profile_read().get("broker") or {}).get("name") or ""
        except Exception:
            brk = ""
        prompt = base + (
            "The user: invests in %s; broker %s; trading style in his own "
            "words: %s.\nThe dashboard he uses tracks NSE prices, the "
            "closing auction (ICP/IEP), charges and capital-gains tax in his "
            "accounts, F&O figures and a portfolio; it never places orders.\n"
            "Answer in plain English, at most 12 lines: 1) does this change "
            "affect him at all (yes / no / only if ...)? 2) if yes, how, "
            "with a short example; 3) should he change his way of trading; "
            "4) does the dashboard need a change (say which part: charges, "
            "auction times, tax, margins) or nothing. Do not invent facts "
            "the article does not give; say what is uncertain."
            % (", ".join(inv), brk or "not stated",
               style or "not described yet (Profile -> Your trading style)"))
    txt, err = ask_gemini(prompt, timeout=40)
    if not txt:
        return {"ok": False, "error": "Gemini did not answer (%s)." % err}
    with RULES["lock"]:
        d = rules_read()
        for i in d["items"]:
            if i.get("id") == rid:
                i[key] = txt.strip()[:4000]
        rules_write(d)
    return {"ok": True, "text": txt.strip()}


def rules_done(rid):
    with RULES["lock"]:
        d = rules_read()
        for x in d["items"]:
            if x["id"] == rid:
                x["done"] = True
                x["doneAt"] = time.strftime("%d %b %H:%M")
        rules_write(d)
    return True


def rules_watcher():
    time.sleep(90)
    n = 0
    while STATS["running"]:
        if n % 3600 == 0:
            # once a week, counted from the last full check (kept on disk,
            # so a restart does not bring the check forward)
            last = rules_read().get("lastTs") or 0
            if time.time() - last >= RULE_EVERY:
                rules_check()
        if n % 300 == 299:
            rules_push()                 # what waited overnight goes at 8
            try:
                auth_held_push()
            except Exception:
                pass
        n += 1
        time.sleep(1)


# ---------------------------------------------------------------------------
# PHONE VIEW
#
# A page for his iPhone on the same Wi-Fi: indices, the gauge, the rows he
# is buying today with the auction figures, and his holdings; he can change
# the six number boxes of any watchlist share and write today's buys into
# YESTERDAY from it (nothing else can be changed from the phone). It is
# served by a SECOND, separate little server that answers only that page and
# its figures, and only with the secret key in the address - the main
# dashboard stays reachable from this Mac alone. Off until he turns it on in
# Diagnostics -> Phone.
# ---------------------------------------------------------------------------

PHONE_PORT = 8766                 # plain http: the setup page, and a fallback
PHONE_TLS_PORT = 8767             # https, with the dashboard's own certificate
PHONE_FILE = os.path.join(DATA_DIR, "phone.json")
PHONE = {"srv": None, "tls": None, "err": "", "tlsErr": ""}
CERT_DIR = os.path.join(DATA_DIR, "PhoneCertificate")


def phone_cfg():
    try:
        with open(PHONE_FILE, encoding="utf-8") as f:
            d = json.load(f)
    except Exception:
        d = {}
    if not d.get("key"):
        import secrets
        d["key"] = secrets.token_urlsafe(9)
        d.setdefault("on", False)
        phone_save(d)
    return d


def phone_save(d):
    try:
        tmp = PHONE_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(d, f)
        os.replace(tmp, PHONE_FILE)
    except Exception:
        pass


def lan_addresses():
    """This Mac's address on the home network, and its Bonjour name."""
    ip = ""
    try:
        import socket
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("10.255.255.255", 1))     # no packet is actually sent
        ip = s.getsockname()[0]
        s.close()
    except Exception:
        ip = ""
    host = ""
    try:
        # the Mac's own Bonjour name, as the iPhone will look it up
        r = subprocess.run(["scutil", "--get", "LocalHostName"], timeout=3,
                           capture_output=True, text=True)
        if r.returncode == 0 and r.stdout.strip():
            host = r.stdout.strip() + ".local"
    except Exception:
        host = ""
    return ip, host


def phone_info():
    d = phone_cfg()
    ip, host = lan_addresses()
    urls = []
    for h in (host, ip):
        if h:
            urls.append("http://%s:%d/?k=%s" % (h, PHONE_PORT, d["key"]))
    c = cert_info()
    names = c.get("names") or []
    secure = ["https://%s:%d/?k=%s" % (h, PHONE_TLS_PORT, d["key"])
              for h in (host, ip) if h and h in names]
    return {"on": bool(d.get("on")), "running": PHONE["srv"] is not None,
            "urls": urls, "secure": secure, "error": PHONE["err"],
            "tlsRunning": PHONE["tls"] is not None, "tlsError": PHONE["tlsErr"],
            "cert": {"made": c.get("made", ""), "until": c.get("until", ""),
                     "names": names, "name": c.get("cn", ""),
                     "stale": bool(c and host and host not in names)}}


# ---------------------------------------------------------------------------
# THE PHONE'S OWN CERTIFICATE (https on the home Wi-Fi)
#
# Safari shows "Not secure" on a plain http page, will not keep the page for
# use away from home, and allows no Face ID. So the dashboard makes its own
# little certificate authority, installed on his iPhone once (Settings ->
# Profile Downloaded -> Install, then Certificate Trust Settings). It signs
# ONE certificate - for this Mac's name on the home network - and its
# signing key is then deleted, so it can never vouch for any other site.
# Made with the openssl that comes with macOS; nothing is fetched or paid.
# ---------------------------------------------------------------------------

def cert_info():
    try:
        with open(os.path.join(CERT_DIR, "info.json")) as f:
            d = json.load(f)
        if all(os.path.exists(os.path.join(CERT_DIR, n))
               for n in ("server.crt", "server.key", "ca.der")):
            return d
    except Exception:
        pass
    return {}


def cert_make():
    """Makes (or makes again) the certificate. Returns (ok, error)."""
    import shutil
    import tempfile
    ossl = shutil.which("openssl") or "/usr/bin/openssl"
    if not os.path.exists(ossl):
        return False, "openssl was not found on this computer"
    ip, host = lan_addresses()
    if not (ip or host):
        return False, "this computer is not on a network right now"
    who = (profile_read().get("name") or "").strip()
    cn = ("Capital Compass on %s" % (host or ip))[:60]
    alt = []
    if host:
        alt.append("DNS:" + host)
    if ip:
        alt.append("IP:" + ip)
    work = tempfile.mkdtemp(prefix="cascert")
    j = lambda n: os.path.join(work, n)

    def run(*args):
        r = subprocess.run([ossl] + list(args), cwd=work, timeout=60,
                           capture_output=True, text=True)
        if r.returncode != 0:
            raise RuntimeError((r.stderr or r.stdout or "openssl failed")
                               .strip().splitlines()[-1][:200])
    clean = lambda t: re.sub(r"[^A-Za-z0-9 .\-]", "", t)
    try:
        with open(j("ca.cnf"), "w") as f:
            f.write("[req]\ndistinguished_name=dn\nprompt=no\n"
                    "x509_extensions=v3_ca\n[dn]\nCN=%s\nO=%s\n"
                    "[v3_ca]\nbasicConstraints=critical,CA:TRUE,pathlen:0\n"
                    "keyUsage=critical,keyCertSign,cRLSign\n"
                    "subjectKeyIdentifier=hash\n"
                    % (clean(cn), clean("Capital Compass - " + (who or "home"))
                       [:60]))
        with open(j("srv.cnf"), "w") as f:
            f.write("[req]\ndistinguished_name=dn\nprompt=no\n[dn]\nCN=%s\n"
                    "[srv]\nbasicConstraints=critical,CA:FALSE\n"
                    "keyUsage=critical,digitalSignature,keyEncipherment\n"
                    "extendedKeyUsage=serverAuth\nsubjectAltName=%s\n"
                    "subjectKeyIdentifier=hash\n"
                    "authorityKeyIdentifier=keyid\n"
                    % (clean(host or ip), ",".join(alt)))
        run("req", "-x509", "-new", "-nodes", "-newkey", "rsa:2048",
            "-sha256", "-days", "3650", "-set_serial",
            "0x" + secrets.token_hex(8), "-keyout", "ca.key", "-out", "ca.crt",
            "-config", "ca.cnf")
        run("req", "-new", "-nodes", "-newkey", "rsa:2048", "-sha256",
            "-keyout", "server.key", "-out", "server.csr", "-config",
            "srv.cnf")
        # 820 days: Apple accepts no https certificate valid for longer
        run("x509", "-req", "-in", "server.csr", "-CA", "ca.crt", "-CAkey",
            "ca.key", "-set_serial", "0x" + secrets.token_hex(8), "-out",
            "server.crt", "-days", "820", "-sha256", "-extfile", "srv.cnf",
            "-extensions", "srv")
        run("x509", "-in", "ca.crt", "-outform", "DER", "-out", "ca.der")
        os.makedirs(CERT_DIR, exist_ok=True)
        for n in ("server.crt", "server.key", "ca.der", "ca.crt"):
            shutil.copyfile(j(n), os.path.join(CERT_DIR, n + ".new"))
        for n in ("server.crt", "server.key", "ca.der", "ca.crt"):
            os.replace(os.path.join(CERT_DIR, n + ".new"),
                       os.path.join(CERT_DIR, n))
        try:
            os.chmod(os.path.join(CERT_DIR, "server.key"), 0o600)
        except Exception:
            pass
        until = (datetime.date.today() + datetime.timedelta(days=819))
        _write_json(os.path.join(CERT_DIR, "info.json"), {
            "names": [x for x in (host, ip) if x], "cn": cn,
            "made": time.strftime("%d %b %Y"),
            "until": until.strftime("%d %b %Y")})
    except Exception as e:
        return False, str(e)[:200]
    finally:
        # the signing key goes: this authority can never sign anything else
        shutil.rmtree(work, ignore_errors=True)
    return True, ""


def intraday_charges(buy_val, sell_val):
    """The same Zerodha figures as the page's PROFIT column."""
    d = datetime.date.today().isoformat()
    brk = min(buy_val * 0.0003, 20) + min(sell_val * 0.0003, 20)
    stt = sell_val * chg_rate("stt_intra", d)
    exch = (buy_val + sell_val) * chg_rate("exch_nse", d)
    sebi = (buy_val + sell_val) * chg_rate("sebi", d)
    stamp = buy_val * chg_rate("stamp_intra", d)
    gst = (brk + exch + sebi) * chg_rate("gst", d)
    return brk + stt + exch + sebi + stamp + gst


def phone_data():
    st = load_state()
    notes = st.get("notes") or {}
    labels = st.get("headings") or {}

    live = in_market_hours()

    def quote(sym):
        with CACHE_LOCK:
            q = dict(CACHE.get(sym) or {})
        # 20.19: in market hours a price not read for five minutes is not
        # sent as if current - the phone shows "could not fetch"
        if live and q and time.time() - (q.get("at") or 0) > 300:
            for k in ("ltp", "ltpNum", "pchange", "icp", "iep", "ieq"):
                q[k] = None
            q["_nf"] = True
            return q
        if q.get("pchange") in (None, ""):
            ltp, prev = to_number(q.get("ltpNum") or q.get("ltp")), \
                to_number(q.get("prevclose"))
            if ltp and prev:
                q["pchange"] = round((ltp / prev - 1) * 100, 2)
        return q

    with CACHE_LOCK:
        trust = cas_outside([CACHE.get(x) or {} for x in
                             (st.get("watchlist") or [])]) is not None
    # ACTIVE on the phone: every row with anything typed in it - QTY, PRICE,
    # TARGET, OLD, YESTERDAY, MISSED or a column of his own - whatever the
    # laptop counts as active (so what he holds is always here)
    active = []
    for sym in (st.get("watchlist") or []):
        n = notes.get(sym) or {}
        if not any(str(v or "").strip() for v in n.values()):
            continue
        q = quote(sym)
        qty, price = to_number(n.get("buy")), to_number(n.get("purchase"))
        tgt = to_number(n.get("target"))
        prof = None
        if qty and price and tgt:
            bv, sv = qty * price, qty * tgt
            prof = round((sv - bv - intraday_charges(bv, sv)) / bv * 100, 2)
        active.append({"symbol": sym, "qty": n.get("buy") or "",
                       "price": price, "target": tgt,
                       "ltp": to_number(q.get("ltpNum") or q.get("ltp")), "nf": bool(q.get("_nf")),
                       "pchange": to_number(q.get("pchange")),
                       "icp": to_number(q.get("icp")),
                       "iep": to_number(q.get("iep")),
                       "ieq": to_number(q.get("ieq")), "profit": prof,
                       "outside": bool(trust and q.get("inCas") is False),
                       "old": str(n.get("old") or "").strip(),
                       "yesterday": str(n.get("yesterday") or "").strip()})
    held = []
    for sym in (st.get("watchlist") or []):
        n = notes.get(sym) or {}
        o, y = str(n.get("old") or "").strip(), \
            str(n.get("yesterday") or "").strip()
        if not (o or y):
            continue
        q = quote(sym)
        held.append({"symbol": sym, "old": o, "yesterday": y,
                     "ltp": to_number(q.get("ltpNum") or q.get("ltp")), "nf": bool(q.get("_nf")),
                     "pchange": to_number(q.get("pchange"))})
    # every other list, so all of them can be looked at on the phone: rows
    # with nothing typed in them, and the Out of list shares
    blank = []
    for sym in (st.get("watchlist") or []):
        n = notes.get(sym) or {}
        if any(str(v or "").strip() for v in n.values()):
            continue
        q = quote(sym)
        blank.append({"symbol": sym,
                      "ltp": to_number(q.get("ltpNum") or q.get("ltp")), "nf": bool(q.get("_nf")),
                      "pchange": to_number(q.get("pchange"))})
    outl = []
    for name, sym in extra_names(st):
        q = quote(sym)
        outl.append({"name": name, "symbol": sym,
                     "ltp": to_number(q.get("ltpNum") or q.get("ltp")), "nf": bool(q.get("_nf")),
                     "pchange": to_number(q.get("pchange"))})
    # the same markets as the dashboard's strip, with its colours (a rise in
    # oil or the dollar shows red); CNBC's symbol goes with each, so the
    # phone can read them itself when the Mac is out of reach
    idx = [{"name": r["name"], "last": r.get("last"), "pct": r.get("pct"),
            "bad": bool(r.get("bad")), "alert": bool(r.get("alert")),
            "why": r.get("why", ""), "sym": r.get("sym", ""),
            "scale": INDEX_SCALE.get(r["name"], 1)}
           for r in (TICKER["rows"] or []) if r.get("last")]
    p = market_pulse()
    edit = {s: {f: str((notes.get(s) or {}).get(f) or "")
                for f in PHONE_FIELDS}
            for s in (st.get("watchlist") or [])}
    cols = {"buy": "QTY", "purchase": "PRICE", "target": "TARGET",
            "old": "OLD", "yesterday": "YESTERDAY", "missed": "MISSED"}
    cols.update({k: v for k, v in labels.items() if k in cols and v})
    es = eod_status()
    return {"at": time.strftime("%H:%M:%S"), "version": VERSION,
            "day": time.strftime("%d %b"),
            "notes": edit, "labels": cols,
            "eodRows": es.get("rows") if es.get("pending") else [],
            "eodDate": es.get("date", ""),
            "indices": idx,
            "rules": rules_payload()["items"][:6],
            "gauge": {"label": p.get("label") or "", "value": p.get("value"),
                      "source": p.get("source")},
            "cas": cas_public(),
            "active": active, "held": held, "blank": blank, "out": outl,
            "outText": st.get("outOfList") or "",
            "oldLabel": labels.get("old") or "OLD",
            "yLabel": labels.get("yesterday") or "YESTERDAY",
            "eod": eod_status().get("pending", False),
            "trading": is_trading_day(),
            "lang": (st.get("prefs") or {}).get("lang") or "en",
            "chart": phone_chart_layout(st),
            "snap": cloud_snapshot_url()}


def phone_chart_layout(st):
    """20.15: the laptop chart's layout he uses (the indicators, their
    settings and colours), for the phone's charts."""
    c = st.get("chartCfg") or {}
    lays = c.get("layouts") or []
    cur = next((x for x in lays if x.get("name") == c.get("current")),
               lays[0] if lays else None)
    if not cur:
        return None
    return {"name": cur.get("name"), "type": cur.get("type"),
            "colors": {k: v for k, v in (c.get("colors") or {}).items()
                       if k in ("up", "down", "line")},
            "inds": [{"t": i.get("t"), "p": i.get("p") or {},
                      "s": i.get("s") or {}, "on": i.get("on", True)}
                     for i in (cur.get("inds") or [])[:20]]}


# Changes typed on the iPhone. Each is stamped with a number that only goes
# up; the Mac page picks up everything newer than what it has seen, and the
# server keeps a phone change if the Mac page saves before it has seen it.
PHONE_FIELDS = ("buy", "purchase", "target", "old", "yesterday", "missed")


def phone_news():
    """The dashboard's own news boxes, short: your shares, the market, the
    world and Kolkata - what was already loaded, nothing fetched for it."""
    st = load_state()
    syms = list(dict.fromkeys((st.get("watchlist") or [])
                              + extra_symbols(st)))
    mine, macro = split_news(syms)

    def short(items, n):
        return [{"title": i.get("title", ""), "link": i.get("link", ""),
                 "source": i.get("source", ""), "age": i.get("age"),
                 "symbols": i.get("symbols") or []} for i in items[:n]]
    # the Kolkata test the Mac uses, for the phone to apply by itself when
    # it reads the news sites directly (away from home)
    return {"mine": short(mine, 25), "market": short(macro, 20),
            "world": short(NEWS.get("global") or [], 15),
            "kolkata": short(NEWS.get("local") or [], 15),
            "ready": NEWS.get("at", 0) > 0,
            "rules": {"bengal": list(BENGAL_PLACES) +
                      list(BENGAL_PEOPLE), "elsewhere": list(ELSEWHERE),
                      "border": list(NOT_OUR_BORDER)}}


def phone_set_outlist(text, was):
    """Out of list, changed on the phone. Refused (the Mac's list kept) if
    it was changed on the Mac since the phone last read it."""
    text = "\n".join(re.sub(r"[^A-Za-z0-9&\- ]", "", ln).strip().upper()
                     for ln in re.split(r"[\n,;]+", str(text or "")))
    text = "\n".join(ln for ln in text.split("\n") if ln)[:4000]
    with NOTE_LOCK:
        st = load_state()
        if str(st.get("outOfList") or "") != str(was or ""):
            return "conflict"
        st["outOfList"] = text
        save_state(st)
        PHONE_REV["rev"] += 1
        NOTE_EDITS[("", "outOfList")] = PHONE_REV["rev"]
    return True


def cas_outside(quotes):
    """The shares NSE marks as not in the closing auction - or None when the
    flag looks wrong: if NSE ever sent "not eligible" for (nearly) every
    share, every row would say N/A and the gauge would go blank, so a flag
    claiming that most of the list is outside the auction is ignored."""
    yes = sum(1 for q in quotes if q.get("inCas") is True)
    no = sorted(str(q.get("symbol") or "") for q in quotes
                if q.get("inCas") is False)
    if no and (yes == 0 or len(no) > yes):
        return None
    return no


def phone_set_note(sym, field, value, was=None, anywhere=False):
    """True when written; "conflict" when the phone's change was made on
    old figures (queued while the Mac was out of reach) and the Mac has
    changed that same box since - the Mac's newer value is kept.
    Only watchlist shares, unless `anywhere` (today's buys: a share that has
    left the table is still written, as the Mac's own box does)."""
    sym = str(sym or "").upper().strip()
    if field not in PHONE_FIELDS or not re.fullmatch(r"[A-Z0-9&\-]{1,20}", sym):
        return False
    # what he can type in those boxes on the Mac: figures and a little
    # punctuation ("1,000", "250-260", "100+50"), never markup
    value = re.sub(r"[^0-9.,+\-@/ ]", "", str(value or "")).strip()[:24]
    with NOTE_LOCK:
        st = load_state()
        if not anywhere and sym not in (st.get("watchlist") or []):
            return False
        notes = st.setdefault("notes", {})
        row = dict(notes.get(sym) or {})
        cur = str(row.get(field) or "")
        if was is not None and cur not in (str(was), value):
            return "conflict"
        row[field] = value
        notes[sym] = row
        save_state(st)
        PHONE_REV["rev"] += 1
        NOTE_EDITS[(sym, field)] = PHONE_REV["rev"]
    return True


class PhoneHandler(BaseHTTPRequestHandler):
    """Answers only the phone page, its figures and two kinds of change
    (a number box, today's buys), and only with the key."""
    timeout = 30            # a phone that goes quiet does not hold a thread
    tls = False

    def log_message(self, *a):
        pass

    def handle_one_request(self):
        try:
            BaseHTTPRequestHandler.handle_one_request(self)
        except ProfileMoved:
            try:
                self.send_response(401)
                self.end_headers()
            except Exception:
                pass

    def do_GET(self):
        import hmac
        p = urllib.parse.urlparse(self.path)
        qs = urllib.parse.parse_qs(p.query)
        key = qs.get("k", [""])[0]
        cfg = phone_cfg()
        if not hmac.compare_digest(key.encode("utf-8", "replace"),
                                   str(cfg.get("key", "x")).encode()) or \
                not cfg.get("on"):
            self.send_response(403)
            self.end_headers()
            return
        REQ.pid = None
        self._spid = None
        if auth_route(self, "GET", p.path):
            return
        if p.path.startswith("/api/") and locked_for(self):
            self.send_response(401)
            self.end_headers()
            return
        REQ.pid = getattr(self, "_spid", None) or ACTIVE["pid"]
        tls = getattr(self, "tls", False)
        if p.path == "/" and not tls and cert_info():
            # plain http with a certificate made: the page that installs it
            # and leads on to the secure address
            body = phone_setup_page(key).encode("utf-8")
            ctype = "text/html; charset=utf-8"
        elif p.path in ("/", "/m"):
            try:
                with open(os.path.join(HERE, "phone.html"), "rb") as f:
                    body = f.read()
            except Exception:
                body = b"phone.html is missing from the Backend folder"
            ctype = "text/html; charset=utf-8"
        elif p.path == "/ca.crt":
            try:
                with open(os.path.join(CERT_DIR, "ca.der"), "rb") as f:
                    body = f.read()
            except Exception:
                self.send_response(404)
                self.end_headers()
                return
            ctype = "application/x-x509-ca-cert"
        elif p.path == "/sw.js" and tls:
            body = PHONE_SW.encode("utf-8")
            ctype = "text/javascript; charset=utf-8"
        elif p.path in ("/icon-180.png", "/icon-512.png"):
            try:
                with open(os.path.join(HERE, "vendor", p.path.lstrip("/")),
                          "rb") as f:
                    body = f.read()
            except Exception:
                body = b""
            ctype = "image/png"
        elif p.path == "/lang.js":
            try:
                with open(os.path.join(HERE, "lang.js"), "rb") as f:
                    body = f.read()
            except Exception:
                body = b""
            ctype = "text/javascript; charset=utf-8"
        elif p.path == "/ping":
            body, ctype = b'{"ok": true}', "application/json"
        elif p.path == "/api/m/extra":
            body = json.dumps(phone_extra()).encode("utf-8")
            ctype = "application/json; charset=utf-8"
        elif p.path == "/api/m/fno":
            body = json.dumps(phone_fno(qs.get("symbol", ["NIFTY"])[0])) \
                .encode("utf-8")
            ctype = "application/json; charset=utf-8"
        elif p.path == "/api/m":
            body = json.dumps(phone_data()).encode("utf-8")
            ctype = "application/json; charset=utf-8"
        elif p.path == "/api/m/news":
            body = json.dumps(phone_news()).encode("utf-8")
            ctype = "application/json; charset=utf-8"
        elif p.path == "/api/m/company":
            body = json.dumps(phone_company(qs.get("sym", [""])[0])) \
                .encode("utf-8")
            ctype = "application/json; charset=utf-8"
        else:
            self.send_response(404)
            self.end_headers()
            return
        self.send_response(200)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        try:
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError):
            pass

    def do_POST(self):
        """Edits from the phone: one note, or today's buys into YESTERDAY."""
        import hmac
        p = urllib.parse.urlparse(self.path)
        key = urllib.parse.parse_qs(p.query).get("k", [""])[0]
        cfg = phone_cfg()
        ctype = (self.headers.get("Content-Type") or "").lower()
        if not cfg.get("on") or not ctype.startswith("application/json") or \
                not hmac.compare_digest(key.encode("utf-8", "replace"),
                                        str(cfg.get("key", "x")).encode()):
            self.send_response(403)
            self.end_headers()
            return
        REQ.pid = None
        self._spid = None
        if auth_route(self, "POST", p.path):
            return
        if locked_for(self):
            body = b'{"locked": true}'
            self.send_response(401)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return
        REQ.pid = getattr(self, "_spid", None) or ACTIVE["pid"]
        try:
            n = max(0, int(self.headers.get("Content-Length", 0) or 0))
            data = json.loads(self.rfile.read(min(n, 20000)).decode("utf-8"))
        except Exception:
            data = None
        code, out = phone_post(p.path, data)
        body = json.dumps(out).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        try:
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError):
            pass


class PhoneTLSHandler(PhoneHandler):
    """The same, on the secure (https) address."""
    tls = True


def phone_company(sym):
    """20.16: the company box in short, for the phone's chart sheet."""
    d = company_info(sym)
    if not d.get("ok"):
        return d
    scr, nse = d.get("scr") or {}, d.get("nse") or {}
    shp = scr.get("shareholding") or {}
    last = [[r[0], r[-1]] for r in (shp.get("rows") or [])[:5]]
    return {"ok": True, "sym": d["sym"], "name": d.get("name"),
            "top": (scr.get("top") or [])[:9], "shp": last,
            "shpAt": (shp.get("heads") or [""])[-1],
            "meeting": (nse.get("meeting") or {}).get("next"),
            "news": (d.get("news") or [])[:4]}


PHONE_CHART_FILE = "phone_chart.json"


def phone_chart_save(data):
    """20.16: the phone's chart settings saved to the laptop: a layout
    called "From the phone" (the laptop layout's indicators, ticked on or
    off on the phone, line or candles) and, if asked, the colours. The
    laptop page takes it in at its next look (/api/staterev)."""
    st = load_state()
    lay = phone_chart_layout(st) or {"inds": []}
    on = data.get("on") if isinstance(data.get("on"), list) else []
    inds = []
    for i, ind in enumerate(lay.get("inds") or []):
        x = dict(ind)
        if i < len(on):
            x["on"] = bool(on[i])
        inds.append(x)
    for k, x in enumerate(inds):
        x["id"] = "p%d%s" % (k, secrets.token_hex(3))
    tf = {"1D": "5m", "5D": "15m", "1M": "1d", "6M": "1d", "1Y": "1d",
          "5Y": "1w"}.get(str(data.get("tf") or ""), "1d")
    hexok = re.compile(r"^#[0-9a-fA-F]{6}$")
    cols = {k: str(v) for k, v in (data.get("colors") or {}).items()
            if k in ("up", "down", "line") and hexok.match(str(v))}
    rec = {"rev": int(time.time() * 1000),
           "layout": {"name": "From the phone",
                      "type": "line" if data.get("type") == "line"
                      else "candle", "inds": inds, "tf": tf},
           "colors": cols if data.get("withColors") else {}}
    _write_json(os.path.join(os.path.dirname(PATHS["state"]),
                             PHONE_CHART_FILE), rec)
    return {"ok": True}


def phone_post(path, data):
    """The phone's changes: one number box, Out of list, or today's buys
    into YESTERDAY. Returns (http status, reply)."""
    if not isinstance(data, dict):
        return 400, {"ok": False}
    if path == "/api/m/translate":
        return 200, {"ok": True, "map": translate_texts(
            (data.get("texts") or [])[:200], str(data.get("lang") or ""))}
    if path in ("/api/m/note", "/api/m/outlist"):
        if path == "/api/m/note":
            ok = phone_set_note(data.get("symbol"), data.get("field"),
                                data.get("value"), data.get("was"))
        else:
            ok = phone_set_outlist(data.get("text"), data.get("was"))
        if ok == "conflict":
            return 409, {"ok": False, "conflict": True}
        return (200 if ok else 400), {"ok": bool(ok)}
    if path == "/api/m/ruledone":
        rules_done(str(data.get("id") or ""))
        return 200, {"ok": True}
    if path == "/api/m/chartlayout":
        return 200, phone_chart_save(data)
    if path == "/api/m/eod":
        ok = False
        with EOD_LOCK:
            d = eod_read()
            rows = data.get("rows")
            if d.get("date") == data.get("date") and not d.get("done") \
                    and isinstance(rows, list) \
                    and all(isinstance(r, dict) for r in rows):
                ok = all([phone_set_note(r.get("symbol"), "yesterday",
                                         r.get("qty"), anywhere=True)
                          is True for r in rows])
                if ok:                   # marked done only if all went in
                    d["done"], d["how"] = True, "written on the phone"
                    d["doneAt"] = time.strftime("%d %b %H:%M")
                    eod_write(d)
        return (200 if ok else 400), {"ok": ok}
    return 404, {"ok": False}


def phone_start():
    if PHONE["srv"] is None:
        try:
            srv = ThreadingHTTPServer(("0.0.0.0", PHONE_PORT), PhoneHandler)
            srv.daemon_threads = True
        except OSError as e:
            PHONE["err"] = "could not open port %d: %s" % (PHONE_PORT, e)
            return False
        PHONE["srv"], PHONE["err"] = srv, ""
        threading.Thread(target=srv.serve_forever, daemon=True).start()
    phone_tls_start()
    return True


def phone_tls_start():
    """The https server, once there is a certificate."""
    if PHONE["tls"] is not None or not cert_info():
        return
    import ssl
    try:
        ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        ctx.load_cert_chain(os.path.join(CERT_DIR, "server.crt"),
                            os.path.join(CERT_DIR, "server.key"))
        srv = ThreadingHTTPServer(("0.0.0.0", PHONE_TLS_PORT), PhoneTLSHandler)
        srv.daemon_threads = True
        # the handshake happens in the request's own thread, so a slow or
        # silent phone cannot hold up everyone else
        srv.socket = ctx.wrap_socket(srv.socket, server_side=True,
                                     do_handshake_on_connect=False)
    except Exception as e:
        PHONE["tlsErr"] = "the secure address could not start: %s" % e
        return
    PHONE["tls"], PHONE["tlsErr"] = srv, ""
    threading.Thread(target=srv.serve_forever, daemon=True).start()


def phone_stop(which=("srv", "tls")):
    for k in which:
        srv = PHONE[k]
        PHONE[k] = None
        if srv is not None:
            try:
                srv.shutdown()
                srv.server_close()
            except Exception:
                pass


def phone_cert_new():
    """Diagnostics -> Phone -> Make the certificate (again)."""
    ok, err = cert_make()
    if ok:
        phone_stop(("tls",))
        if phone_cfg().get("on"):
            phone_tls_start()
    out = phone_info()
    out.update(certOk=ok, certError=err)
    return out


PHONE_FNO = {}


def phone_fno(sym):
    """The F&O panel's figures, short enough for the phone."""
    sym = re.sub(r"[^A-Za-z0-9&\- ]", "", str(sym or "NIFTY"))[:30] or "NIFTY"
    k = sym.upper()
    hit = PHONE_FNO.get(k)
    if hit and time.time() - hit[0] < 55:
        return hit[1]
    # the dashboard's own F&O box keeps its figures: what it had is put back
    keep = dict(FNO_CACHE)
    try:
        if FNO_CACHE.get("data") and (FNO_CACHE.get("key") or ("",))[0] == k \
                and time.time() - FNO_CACHE["at"] < 90:
            d = FNO_CACHE["data"]
        else:
            d = fno_snapshot(sym)
            FNO_CACHE.clear()
            FNO_CACHE.update(keep)
    except Exception as e:
        return {"ok": False, "error": str(e)[:120], "symbol": sym}
    ch = dict(d.get("chain") or {})
    rows = ch.pop("chainRows", None) or []
    atm = ch.get("atm")
    if atm and rows:
        i = min(range(len(rows)), key=lambda n: abs((rows[n].get("strike")
                                                     or 0) - atm))
        rows = rows[max(0, i - 6):i + 7]
    keep = ("strike", "ceOI", "ceChg", "ceLtp", "ceIV", "peOI", "peChg",
            "peLtp", "peIV")
    ch["rows"] = [{k: r.get(k) for k in keep} for r in rows]
    ch.pop("aggregates", None)
    fii = []
    for r in ((d.get("participants") or {}).get("rows") or []):
        try:
            fl = float(r.get("Future Index Long") or 0)
            fs = float(r.get("Future Index Short") or 0)
            fii.append({"who": r.get("Client Type"), "long": fl, "short": fs,
                        "netPct": round((fl - fs) / (fl + fs) * 100, 1)
                        if fl + fs else None})
        except (TypeError, ValueError):
            continue
    fut = dict(d.get("futures") or {})
    fut.pop("contracts", None)
    out = {"ok": bool(ch.get("ok") or fut.get("ok")), "symbol": ch.get("symbol")
           or sym, "chain": ch, "futures": fut, "vix": d.get("vix"),
            "ban": (d.get("ban") or {}).get("names") or [],
            "fii": fii, "fiiDay": (d.get("participants") or {}).get("day", ""),
            "margin": d.get("margin"), "missing": d.get("missing") or [],
            "at": d.get("at"), "date": time.strftime("%d %b")}
    PHONE_FNO[k] = (time.time(), out)
    for old in sorted(PHONE_FNO, key=lambda x: PHONE_FNO[x][0])[:-8]:
        PHONE_FNO.pop(old, None)
    return out


def phone_extra():
    """Corporate actions and IPOs, for the phone (Kite shows neither)."""
    out = {"corp": [], "ipo": [], "at": time.strftime("%d %b %H:%M")}
    try:
        st = load_state()
        mine = set(st.get("watchlist") or []) | set(extra_symbols(st))
        pv = previews()
        for r in fetch_corp_actions():
            if r.get("symbol") not in mine:
                continue
            v = ""
            if r.get("kind") == "Results":
                v = (pv.get(r["symbol"] + "|" + r.get("exIso", "")) or {}) \
                    .get("verdict") or ""
                if v not in ("STRONG", "MODERATE", "WEAK", "MIXED"):
                    v = ""
            out["corp"].append({"symbol": r["symbol"], "kind": r.get("kind"),
                                "purpose": r.get("purpose", "")[:160],
                                "value": r.get("value") or "",
                                "date": r.get("exDate") or "",
                                "daysTo": r.get("daysTo"), "expected": v})
    except Exception:
        pass
    try:
        for r in (fetch_ipos().get("rows") or [])[:30]:
            out["ipo"].append({k: r.get(k, "") for k in (
                "name", "status", "dates", "band", "gmpText", "gainPct",
                "board", "subscription", "listDate", "minAmount")})
    except Exception:
        pass
    return out


# The phone page is kept on the phone by this service worker, so the icon
# opens even with no Mac in reach (on a trip): the page then shows the last
# figures it was sent, after the password.
PHONE_SW = """
const C = 'cas-page-1';
self.addEventListener('install', e => {
  self.skipWaiting();
  // keep the page at once (the key is in this script's own address)
  e.waitUntil(caches.open(C).then(c => fetch('/' + self.location.search,
    { cache: 'no-store', credentials: 'same-origin' })
    .then(r => (r.ok ? c.put('/page', r) : null))).catch(() => null));
});
self.addEventListener('activate', e => e.waitUntil(self.clients.claim()));
self.addEventListener('fetch', e => {
  const u = new URL(e.request.url);
  if (e.request.method !== 'GET' || u.origin !== location.origin) return;
  if (!(e.request.mode === 'navigate' || u.pathname === '/')) return;
  e.respondWith((async () => {
    const c = await caches.open(C);
    try {
      const ctl = new AbortController();
      const t = setTimeout(() => ctl.abort(), 6000);
      const r = await fetch(e.request.url, { signal: ctl.signal,
                                             cache: 'no-store',
                                             credentials: 'same-origin' });
      clearTimeout(t);
      if (r.ok && (r.headers.get('Content-Type') || '').indexOf('html') >= 0)
        await c.put('/page', r.clone());
      return r;
    } catch (err) {
      const k = await c.match('/page');
      return k || new Response('<p style="font:17px -apple-system;padding:30px">' +
        'The dashboard cannot be reached, and this phone has not kept the ' +
        'page yet. Open it once at home first.</p>',
        { headers: { 'Content-Type': 'text/html; charset=utf-8' } });
    }
  })());
});
"""


def phone_setup_page(key):
    """The first page the iPhone opens (plain http): installs the
    certificate, then leads to the secure address."""
    c = cert_info()
    ip, host = lan_addresses()
    names = c.get("names") or []
    h = host if host in names else (ip if ip in names else
                                    (names[0] if names else ""))
    secure = "https://%s:%d/?k=%s" % (h, PHONE_TLS_PORT, key)
    q = urllib.parse.quote(key)
    page = """<!doctype html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Capital Compass - phone set-up</title><style>
body{font:16px -apple-system,sans-serif;background:#f4f6fa;color:#1d2433;
margin:0;padding:24px 16px 40px}.c{background:#fff;border:1px solid #e3e7ee;
border-radius:14px;padding:18px}h1{font-size:21px;color:#1f3864;margin:0 0 6px}
ol{padding-left:20px;line-height:1.5}li{margin:8px 0}
a.b,button{display:block;text-align:center;width:100%%;box-sizing:border-box;
margin:12px 0 4px;padding:13px;font:700 16px -apple-system,sans-serif;
border:0;border-radius:11px;background:#1f3864;color:#fff;text-decoration:none}
a.g{background:#eef1f6;color:#1d2433}.ok{background:#e8f6ec;color:#0a7d32;
border-radius:10px;padding:10px 12px}.s{color:#8a94a6;font-size:13.5px}
</style></head><body><div class="c"><h1>Capital Compass on this phone</h1>
<div id="st" class="s">Checking this phone&hellip;</div>
<div id="ready" style="display:none"><p class="ok">The certificate is
installed - this phone opens the dashboard securely.</p>
<a class="b" href="%(secure)s">OPEN THE DASHBOARD</a>
<p class="s">On the page that opens, tap <b>Share &rarr; Add to Home
Screen</b> and from now on always open it with that icon - it then opens
even away from home, with the last figures.</p></div>
<div id="steps" style="display:none"><p>One-time set-up, about a minute:</p><ol>
<li>Tap <b>Get the certificate</b> below, then <b>Allow</b>.
<a class="b" href="/ca.crt?k=%(q)s">GET THE CERTIFICATE</a></li>
<li>Open <b>Settings</b>: at the top it says <b>Profile Downloaded</b> - tap
it, then <b>Install</b> (top right), your passcode, <b>Install</b> again.</li>
<li>In Settings go to <b>General &rarr; About &rarr; Certificate Trust
Settings</b> and turn on <b>%(cn)s</b>, then <b>Continue</b>.</li>
<li>Come back to this page and tap <b>Check again</b>.
<button onclick="location.reload()">CHECK AGAIN</button></li></ol>
<a class="b g" href="/m?k=%(q)s">Use it without the certificate for now</a>
<p class="s">Without it Safari says "Not secure", Face ID cannot be used,
and the page cannot be kept for use away from home.</p></div></div>
<script>
fetch('%(ping)s', {mode: 'no-cors', cache: 'no-store'})
  .then(function () { document.getElementById('ready').style.display = 'block'; })
  .catch(function () { document.getElementById('steps').style.display = 'block'; })
  .then(function () { document.getElementById('st').style.display = 'none'; });
</script></body></html>"""
    e = html_lib.escape
    return page % {"secure": e(secure), "q": e(q), "cn": e(c.get("cn", "")),
                   "ping": e("https://%s:%d/ping?k=%s" % (h, PHONE_TLS_PORT,
                                                         q))}


def phone_set(on):
    d = phone_cfg()
    d["on"] = bool(on)
    phone_save(d)
    if on:
        phone_start()
    else:
        phone_stop()
    return phone_info()


def main():
    print("=" * 64)
    print("  CAPITAL COMPASS  v%s" % VERSION)
